@publish(data.IMPORTED_PREV_DSA_MATCH_KEYS.schema, cells=data.IMPORTED_PREV_DSA_MATCH_KEYS.cells)
def imported_prev_dsa_match_keys(*, imported_prev_dsa_investment_weo_codes: data.Series[str | None], imported_country_code: int | str, imported_prev_dsa_weo_codes: data.Series[str | int | float | bool | None], imported_selected_vintage_dates: data.Series[str | int | float | bool | None]) -> data.Series[str | int | float | bool | None]:
    """Build PREV_DSA INDEX/MATCH row keys by concatenating country, WEO, vintage, and investment-code coordinates.

    Pin PREV_DSA lookups with fully-formed keys so alias chains cannot leave MATCH unbounded.

    Args:
        imported_prev_dsa_investment_weo_codes: Named-axis series of investment WEO code indicators (for example NGDP_R_PCH, NFIG_R_GDP, NFIP_R_GDP) over catalog coordinates, with optional blanks.
        imported_country_code: Country code scalar supplying the leading key segment; accepts an int or str.
        imported_prev_dsa_weo_codes: Named-axis series of WEO code values over catalog coordinates, carrying str, int, float, bool, or blank entries.
        imported_selected_vintage_dates: Named-axis series of selected vintage dates over catalog coordinates, indexed by vintage labels such as 'The latest vintage' and '5 years ago'.

    Returns:
        Named-axis series of concatenated PREV_DSA INDEX/MATCH row keys formatted as country.WEO.vintage.A, aligned to the catalog coordinates of the key series.
    """
    data.IMPORTED_PREV_DSA_INVESTMENT_WEO_CODES.schema.validate(imported_prev_dsa_investment_weo_codes)
    def formula(parameter: str) -> str | int | float | bool | None:
        PARAMETER_TO_IMPORTED_PREV_DSA_INVESTMENT_WEO_CODES_INDICATOR = {'2024.NGDP_R_PCH': 'NGDP_R_PCH', '2024.NFIG_R_GDP': 'NFIG_R_GDP', '2024.NFIP_R_GDP': 'NFIP_R_GDP'}
        if parameter in ('2024.NGDP_R_PCH', '2024.NFIG_R_GDP', '2024.NFIP_R_GDP'):
            return as_measure(xl_concat(xl_concat(xl_concat(xl_concat(xl_concat(imported_country_code, '.'), imported_prev_dsa_investment_weo_codes[PARAMETER_TO_IMPORTED_PREV_DSA_INVESTMENT_WEO_CODES_INDICATOR[parameter]]), '.'), imported_selected_vintage_dates['The latest vintage']), '.A'), 'str')
        elif parameter in ('2024.NGDPD', '2024.D_PPG_GDP', '2024.NGDP', '2024.DU_GDP'):
            return as_measure(xl_concat(xl_concat(xl_concat(xl_concat(xl_concat(imported_country_code, '.'), imported_prev_dsa_weo_codes[parameter]), '.'), imported_selected_vintage_dates['The latest vintage']), '.A'), 'str')
        return as_measure(xl_concat(xl_concat(xl_concat(xl_concat(xl_concat(imported_country_code, '.'), imported_prev_dsa_weo_codes[parameter]), '.'), imported_selected_vintage_dates['5 years ago']), '.A'), 'str')

    return data.IMPORTED_PREV_DSA_MATCH_KEYS.collect(evaluate(formula, data.IMPORTED_PREV_DSA_MATCH_KEYS.required))

@publish(data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.schema, cells=data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.cells)
def imported_prev_dsa_history_year_headers(*, realism1_external_year_headers: data.Series[int | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[int | str | None]:
    """Derive the Imported PREV_DSA historical year-header series from an anchored Realism 1 year value and the Input 3 time axis.

    Builds the TIME_PERIOD coordinate series used for historical PREV_DSA INDEX/MATCH columns, propagating year headers outward by one-year steps from the anchor position.

    Args:
        realism1_external_year_headers: A typed year-header series from Realism 1 external inputs whose value at the anchor TIME_PERIOD position seeds the historical year-header sequence.
        input3_input_3_macro_current_account: A typed Input 3 macro current-account series whose TIME_PERIOD axis defines the output coordinate grid and anchor position used to propagate year headers.

    Returns:
        A typed integer-or-text year-header series over the Imported PREV_DSA historical TIME_PERIOD coordinates.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 13:
            return as_measure(realism1_external_year_headers[time_period], 'int')
        elif _p_time_period <= 12:
            return as_measure(xl_sub(imported_prev_dsa_history_year_headers[axis_step(_ax_time_period, time_period, 1)], 1), 'int')
        return as_measure(xl_add(imported_prev_dsa_history_year_headers[axis_step(_ax_time_period, time_period, -1)], 1), 'int')

    imported_prev_dsa_history_year_headers = CoordinateReader('imported_prev_dsa_history_year_headers', data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.collect(((coord, imported_prev_dsa_history_year_headers[coord]) for coord in data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.IMPORTED_PREV_DSA_INVESTMENT_YEAR_HEADERS.schema, cells=data.IMPORTED_PREV_DSA_INVESTMENT_YEAR_HEADERS.cells)
def imported_prev_dsa_investment_year_headers(*, realism3_contribution_years: data.Series[int | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[int | str | None]:
    """Builds the Realism 3 investment-growth previous-DSA year-header series over the Input 3 current-account time grid.

    Provides aliased year labels for the PREV_DSA INDEX/MATCH lookup used by the Realism 3 investment-growth block.

    Args:
        realism3_contribution_years: A data.Series of integer, string, or null values holding the Realism 3 contribution-year labels to align and project onto the target time axis.
        input3_input_3_macro_current_account: A data.Input3Input3MacroCurrentAccount series whose TIME_PERIOD coordinate defines the year grid and schema used to validate and evaluate the header mapping.

    Returns:
        A data.Series[int | str | None] of previous-DSA investment year headers aligned to the supplied current-account TIME_PERIOD coordinate.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(realism3_contribution_years[time_period], 'int')

    return data.IMPORTED_PREV_DSA_INVESTMENT_YEAR_HEADERS.collect(evaluate(formula, data.IMPORTED_PREV_DSA_INVESTMENT_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.IMPORTED_PREV_DSA_INVESTMENT_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

