            return as_measure(xl_average(view(dsa_ext_growth_of_exports_of_g_s_us_dollar_terms_in_percent, cols={'SCENARIO': (scenario,), 'TIME_PERIOD': span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[3], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12])})))
