    return data.DSA_EXT_GOVERNMENT_REVENUES_EXCLUDING_GRANTS_IN_PERCENT_OF_GDP.collect(evaluate(formula, data.DSA_EXT_GOVERNMENT_REVENUES_EXCLUDING_GRANTS_IN_PERCENT_OF_GDP.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_EXT_GOVERNMENT_REVENUES_EXCLUDING_GRANTS_IN_PERCENT_OF_GDP.required.bind(TIME_PERIOD=input3_old_debt_service))

