@publish(data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.schema, cells=data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.cells)
def dsa_pub_of_which_external_debt(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_total_public_external_debt: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes the "of which: external debt" public DSA ratio as a percent of nominal GDP.

    Derives the B1_GDP_pub series by dividing total public external debt by nominal GDP in local currency and scaling by 100 over the scenario and year grid.

    Args:
        dsa_pub_nominal_gdp_local_currency: A data.Series of nominal GDP in local currency keyed by scenario and time period, used as the denominator; values may be floats, strings, or None.
        dsa_pub_total_public_external_debt: A data.Series of total public external debt keyed by scenario and time period, used as the numerator; values may be floats, strings, or None.
        input3_old_debt_service: A data.Input3OldDebtService input object whose validated TIME_PERIOD axis supplies the scenario and year coordinates for evaluating and collecting the result.

    Returns:
        A data.Series[float | str | None] of external-debt-to-GDP ratios in percent, keyed by scenario and TIME_PERIOD coordinates.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(dsa_pub_total_public_external_debt[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100))

    return data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.collect(evaluate(formula, data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.schema, cells=data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.cells)
def dsa_pub_pv_of_total_public_debt(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_total_public_domestic_debt: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the PV of total public debt (B1_GDP_pub) as a share of nominal GDP.

    Sums public-sector external debt PV and total public domestic debt, divides by nominal GDP in local currency, and scales to a percent across scenarios and years.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency by scenario and year, used as the denominator of the debt-to-GDP ratio.
        dsa_pub_total_public_domestic_debt: Total public domestic debt stock series by scenario and year, added to external debt PV in the numerator.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: Present value of public-sector external debt at end of period by scenario and year, added to domestic debt in the numerator.
        input3_old_debt_service: Debt service input series supplying the scenario and TIME_PERIOD domain over which the formula is evaluated.

    Returns:
        A data.Series of floats (or string/None blanks) holding the PV of total public debt as a percentage of GDP, keyed by scenario and year.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'A1':
            return as_measure((0 if xl_bool(xl_lt(xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100), 0)) else xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100)))
        return as_measure(xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100))

    return data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.collect(evaluate(formula, data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_PRIMARY_DEFICIT.schema, cells=data.DSA_PUB_PRIMARY_DEFICIT.cells)
def dsa_pub_primary_deficit(*, b6_combo_non_mkt_pub_gdp_shock_label: str, input6_standard_size_threshold_option_historical_average_only: str, input6_standard_size_threshold_option_whichever_is_lower: str, dsa_pub_revenue_and_grants: data.Series[float | str | None], dsa_pub_primary_noninterest_expenditure: data.Series[float | str | None], dsa_pub_standard_test_parameter: data.Series[str | int | float | bool | None], dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter: str | int | float | bool, dsa_pub_standard_test_pb_rule: str | int | float | bool, dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule: str | int | float | bool, a1_hist_pub_historical_statistics: data.Series[float | str | None], baseline_pub_primary_deficit: data.Series[float | str | None], leftover_primary_deficit: data.Series[float | str | None], leftover_revenue_gdp: data.Series[float | str | None], b2_pb_mkt_pub_i_baseline_medium_term_projections: float | str, b2_pb_nonmkt_pub_i_baseline_medium_term_projections: float | str, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derive the public-sector primary deficit (B1_GDP_pub) across scenarios and projection years.

    Produces the public DSA primary-deficit path, applying scenario-specific shock rules for B2/B6 market and non-market tests while falling back to revenue minus non-interest expenditure elsewhere.

    Args:
        b6_combo_non_mkt_pub_gdp_shock_label: Label for the combined non-market public GDP shock applied in the B6_nonmkt rule.
        input6_standard_size_threshold_option_historical_average_only: Sentinel option string selecting the historical-average-only standard-size threshold for shock scaling.
        input6_standard_size_threshold_option_whichever_is_lower: Sentinel option string selecting the whichever-is-lower standard-size threshold for shock scaling.
        dsa_pub_revenue_and_grants: Public revenue and grants series over catalog coordinates, used in the baseline difference against expenditure.
        dsa_pub_primary_noninterest_expenditure: Public primary non-interest expenditure series over catalog coordinates, subtracted from revenue and grants.
        dsa_pub_standard_test_parameter: Standard-test parameter series over catalog coordinates, compared against the threshold options to pick a B2_mkt shock rule.
        dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter: Scalar standard-test parameter for the B2 non-market block, compared against the threshold options to pick a shock rule.
        dsa_pub_standard_test_pb_rule: Scalar standard-test rule selector for the B6 market block, compared against the threshold options to pick a shock rule.
        dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule: Scalar standard-test rule selector for the B6 non-market block, compared against the threshold options to pick a shock rule.
        a1_hist_pub_historical_statistics: Public historical-statistics series over catalog coordinates, supplying the A1 historical-average primary deficit.
        baseline_pub_primary_deficit: Baseline public primary deficit series over catalog coordinates, used as the starting point for shock-adjusted paths.
        leftover_primary_deficit: Leftover primary deficit series over catalog coordinates, scaled by scenario coefficients to build shock adjustments.
        leftover_revenue_gdp: Leftover revenue-to-GDP series over catalog coordinates, providing the scaling factor for B6 shock paths.
        b2_pb_mkt_pub_i_baseline_medium_term_projections: Scalar medium-term baseline projection coefficient applied to leftover primary deficit in the B2 market block.
        b2_pb_nonmkt_pub_i_baseline_medium_term_projections: Scalar medium-term baseline projection coefficient applied to leftover primary deficit in the B2 non-market block.
        input3_input_3_macro_current_account: Macro current-account input dataclass whose time axis anchors the projection periods and historical offsets.
        input3_old_debt_service: Old debt service input dataclass whose time axis defines the output row keys for the deficit series.

    Returns:
        A float, string, or None series of public primary deficits keyed by scenario and time period from row 7.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B2_mkt' and _p_time_period == 1:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_mkt' and _p_time_period == 2:
            return as_measure((xl_add(leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])) if xl_bool(xl_eq(dsa_pub_primary_deficit[scenario, axis_step(_ax_time_period, time_period, -1)], xl_add(leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]))))
        elif scenario == 'B6_mkt' and _p_time_period == 1:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_pb_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_pb_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_nonmkt' and _p_time_period == 1:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter, input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_nonmkt' and _p_time_period == 2:
            return as_measure((xl_add(leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])) if xl_bool(xl_eq(dsa_pub_primary_deficit[scenario, axis_step(_ax_time_period, time_period, -1)], xl_add(leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]))))
        elif scenario == 'B6_nonmkt' and _p_time_period == 1:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b6_combo_non_mkt_pub_gdp_shock_label, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'A1' and _p_time_period == 1:
            return as_measure(a1_hist_pub_historical_statistics['Primary deficit', 'Historical average'])
        elif scenario in ('B6_mkt', 'B6_nonmkt') and _p_time_period == 2:
            return as_measure((xl_add(leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])) if xl_bool(xl_eq(dsa_pub_primary_deficit[scenario, axis_step(_ax_time_period, time_period, -1)], xl_add(leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]))))
        elif scenario == 'A1' and _p_time_period >= 2:
            return as_measure(dsa_pub_primary_deficit[scenario, axis_step(_ax_time_period, time_period, -1)])
        return as_measure(xl_sub(dsa_pub_primary_noninterest_expenditure[scenario, time_period], dsa_pub_revenue_and_grants[scenario, time_period]))

    dsa_pub_primary_deficit = CoordinateReader('dsa_pub_primary_deficit', data.DSA_PUB_PRIMARY_DEFICIT.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.DSA_PUB_PRIMARY_DEFICIT.collect(((coord, dsa_pub_primary_deficit[coord]) for coord in data.DSA_PUB_PRIMARY_DEFICIT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_PRIMARY_DEFICIT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_REVENUE_AND_GRANTS.schema, cells=data.DSA_PUB_REVENUE_AND_GRANTS.cells)
def dsa_pub_revenue_and_grants(*, dsa_pub_of_which_grants: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_revenue_grants: data.Series[float | str | None], baseline_pub_of_which_grants: data.Series[float | str | None], macro_debt_public_sector_revenues_including_grants: data.Series[float | str | None], leftover_real_interest_rate: data.Series[float | str | None], c3_commodity_pub_historical_statistics_key_variables_past_10: int | str, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute public-sector revenue and grants by scenario and projection year.

    Derive the DSA public revenue and grants path from baseline revenue, grants, C3 commodity adjustments, and the initial revenue-to-GDP ratio.

    Args:
        dsa_pub_of_which_grants: Public-sector grants under the DSA scenario as a typed series over scenario and time coordinates, used to replace baseline grants where applicable.
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency as a typed series over scenario and time coordinates, used to form the initial revenue-to-GDP percentage.
        baseline_pub_revenue_grants: Baseline public revenue and grants as a typed series over time coordinates, providing the starting revenue path.
        baseline_pub_of_which_grants: Baseline grants component as a typed series over time coordinates, subtracted from baseline revenue before scenario grants are added.
        macro_debt_public_sector_revenues_including_grants: Public-sector revenues including grants from the macro-debt history as a typed series over time coordinates, used for the initial revenue-to-GDP calculation.
        leftover_real_interest_rate: Leftover real interest rate as a typed series over scenario and time coordinates, used in the C3 tailored-stress adjustment.
        c3_commodity_pub_historical_statistics_key_variables_past_10: Scalar commodity-price historical statistic for the C3 tailored stress, used with the leftover real interest rate in the adjustment formula.
        input3_input_3_macro_current_account: Macro current account input bundle containing validated current-account assumptions used by the calculation context.
        input3_old_debt_service: Old debt service input bundle whose time-period domain defines the projection grid for the returned series.

    Returns:
        A data.Series[float | str | None] of public revenue and grants keyed by scenario and year, including the initial revenue-to-GDP percentage and preserved non-numeric placeholders.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'C3' and _p_time_period == 4:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 3)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and _p_time_period == 5:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 4)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and _p_time_period == 6:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 5)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and 1 <= _p_time_period <= 3:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), leftover_real_interest_rate[scenario]))
        elif _p_time_period == 0:
            return as_measure((xl_div(xl_mul(100, macro_debt_public_sector_revenues_including_grants[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_public_sector_revenues_including_grants[time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]))) else '.'))
        return as_measure(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]))

    return data.DSA_PUB_REVENUE_AND_GRANTS.collect(evaluate(formula, data.DSA_PUB_REVENUE_AND_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_REVENUE_AND_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_OF_WHICH_GRANTS.schema, cells=data.DSA_PUB_OF_WHICH_GRANTS.cells)
def dsa_pub_of_which_grants(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], macro_debt_public_sector_grants: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes the public-sector "of which: grants" ratio as a share of nominal GDP.

    Derives the of-which-grants indicator series for the public DSA by dividing grants by nominal GDP in local currency and expressing the result as a percentage.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency as a data.Series over scenario and time-period coordinates; acts as the denominator of the ratio.
        macro_debt_public_sector_grants: Public-sector grants in local currency as a data.Series indexed by time period; acts as the numerator and yields '...' where non-numeric.
        input3_old_debt_service: Input 3 old debt service container supplying the validated TIME_PERIOD axis that fixes the projection grid for the computed series.

    Returns:
        A data.Series[float | str | None] of the grants-to-GDP percentage, keyed by scenario and the years taken from the Input 3 old debt service grid, with non-numeric grants carrying the '...' placeholder.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_div(macro_debt_public_sector_grants[time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100) if xl_bool(xl_isnumber(lambda: macro_debt_public_sector_grants[time_period])) else '...'))

    return data.DSA_PUB_OF_WHICH_GRANTS.collect(evaluate(formula, data.DSA_PUB_OF_WHICH_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_OF_WHICH_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.schema, cells=data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.cells)
def dsa_pub_primary_noninterest_expenditure(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_primary_noninterest_expenditure: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute public primary noninterest expenditure as a ratio to nominal GDP by scenario and projection year.

    Derives the DSA public primary (noninterest) expenditure path from baseline expenditure and local-currency GDP inputs, using the C3-specific baseline GDP denominator where applicable.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency for the DSA public scenario, keyed by scenario and projection years; used as the denominator, with the B1 series used for C3.
        baseline_pub_primary_noninterest_expenditure: Baseline public primary noninterest expenditure series, keyed by projection year; supplies the numerator before scaling by the baseline GDP ratio.
        baseline_pub_nominal_gdp_lc: Baseline nominal GDP in local currency series, keyed by projection year; used to rescale baseline expenditure into the target GDP denominator.
        input3_input_3_macro_current_account: Macro current-account input container; validated against its schema and used to bind the required TIME_PERIOD axis for evaluation.
        input3_old_debt_service: Old debt-service input container; validated against its schema as part of the authored coordinate-identity inputs.

    Returns:
        Typed data.Series[float | str | None] of public primary noninterest expenditure values keyed by scenario and projection year, preserving string or None placeholders where the underlying computation does not yield numeric data.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'C3':
            return as_measure(xl_div(xl_mul(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency['B1', time_period]))
        return as_measure(xl_div(xl_mul(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.collect(evaluate(formula, data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.schema, cells=data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.cells)
def dsa_pub_contribution_from_real_exchange_rate_depreciation(*, dsa_pub_of_which_external_debt: data.Series[float | str | None], dsa_pub_denominator_1_g: data.Series[float | str | None], dsa_pub_average_real_interest_rate_on_external_debt_in_percent: data.Series[float | str | None], dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes the public DSA contribution from real exchange rate depreciation over scenario and year coordinates.

    Scales prior-period external debt by the depreciation rate and gross-up factor, then divides by the GDP denominator to populate the B1_GDP_pub series.

    Args:
        dsa_pub_of_which_external_debt: Public external debt stock series (of which external debt) indexed by scenario and year; the prior period value is used as the base for the depreciation effect.
        dsa_pub_denominator_1_g: Denominator series (1/GDP in percent terms) used to express the contribution as a share of GDP.
        dsa_pub_average_real_interest_rate_on_external_debt_in_percent: Average real interest rate on external debt in percent, used to build the gross-up factor applied to the depreciated debt stock.
        dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation: Real exchange rate depreciation in percent, where a positive value indicates depreciation, driving the size of the contribution.
        input3_old_debt_service: Input3 old debt service dataclass supplying the scenario and TIME_PERIOD domain over which the formula is evaluated and collected.

    Returns:
        A data.Series of floats or str/None (B1_GDP_pub), the depreciation contribution keyed by scenario and years starting at row 7.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_div(xl_mul(xl_mul(xl_div(dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation[scenario, time_period], 100), dsa_pub_of_which_external_debt[scenario, axis_step(_ax_time_period, time_period, -1)]), xl_add(1, xl_div(dsa_pub_average_real_interest_rate_on_external_debt_in_percent[scenario, time_period], 100))), dsa_pub_denominator_1_g[scenario, time_period]))

    return data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.collect(evaluate(formula, data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_DENOMINATOR_1_G.schema, cells=data.DSA_PUB_DENOMINATOR_1_G.cells)
def dsa_pub_denominator_1_g(*, dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the public DSA denominator 1 + g/100 from real GDP growth.

    Provide the scenario- and year-keyed public-debt denominator used to scale debt ratios.

    Args:
        dsa_pub_real_gdp_growth_in_percent: Real GDP growth in percent as a typed data.Series aligned to scenario and time-period coordinates; values may be numeric, text, or missing.
        input3_old_debt_service: Typed data.Input3OldDebtService providing the scenario and TIME_PERIOD coordinates that define the output grid and validation schema.

    Returns:
        A data.Series[float | str | None] containing the denominator 1 + g/100 keyed by scenario and years, preserving text or missing values where present.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(1, xl_div(dsa_pub_real_gdp_growth_in_percent[scenario, time_period], 100)))

    return data.DSA_PUB_DENOMINATOR_1_G.collect(evaluate(formula, data.DSA_PUB_DENOMINATOR_1_G.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_DENOMINATOR_1_G.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS.schema, cells=data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS.cells)
def dsa_pub_other_identified_debt_creating_flows(*, dsa_pub_privatization_receipts_negative: data.Series[float | str | None], dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization: data.Series[float | str | None], dsa_pub_debt_relief_hipc_and_other: data.Series[float | str | None], dsa_pub_other_debt_creating_or_reducing_flow_please_specify: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Sum the public other identified debt-creating flow components into one series.

    Build the scenario- and year-indexed B1_GDP_pub other identified debt-creating flows series from aligned component inputs.

    Args:
        dsa_pub_privatization_receipts_negative: Negative privatization receipts as a scenario/year-indexed data series; values may be numeric, text, or missing.
        dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization: Recognition of contingent liabilities, including bank recapitalization, as a scenario/year-indexed data series; values may be numeric, text, or missing.
        dsa_pub_debt_relief_hipc_and_other: Debt relief under HIPC and other relief operations as a scenario/year-indexed data series; values may be numeric, text, or missing.
        dsa_pub_other_debt_creating_or_reducing_flow_please_specify: User-specified other debt-creating or debt-reducing flows as a scenario/year-indexed data series; values may be numeric, text, or missing.
        input3_old_debt_service: Input 3 old-debt-service data object whose time-period domain defines the scenario/year grid used for evaluation.

    Returns:
        A scenario/year-indexed data series of other identified debt-creating flows, containing numeric, text, or missing values from the component sum.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_sum((dsa_pub_privatization_receipts_negative[scenario, time_period], dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization[scenario, time_period], dsa_pub_debt_relief_hipc_and_other[scenario, time_period], dsa_pub_other_debt_creating_or_reducing_flow_please_specify[scenario, time_period])))

    return data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS.collect(evaluate(formula, data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE.schema, cells=data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE.cells)
def dsa_pub_privatization_receipts_negative(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_privatization_receipts_negative: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Build the public privatization-receipts (negative) series by rescaling baseline receipts with nominal GDP in local currency across scenarios and years.

    Produces the DSA public privatization-receipts (negative) indicator as a scenario-by-year catalog series from baseline receipts, baseline GDP, and scenario GDP inputs.

    Args:
        dsa_pub_nominal_gdp_local_currency: Public nominal GDP in local-currency series keyed by scenario and time period, used as the scenario-specific denominator when rescaling baseline receipts; entries may be numeric, string, or missing.
        baseline_pub_privatization_receipts_negative: Baseline public privatization-receipts (negative) series keyed by time period, supplying the numerator that is rescaled by the GDP ratio; entries may be numeric, string, or missing.
        baseline_pub_nominal_gdp_lc: Baseline public nominal GDP in local-currency series keyed by time period, forming the baseline denominator of the scaling ratio applied to receipts.
        input3_input_3_macro_current_account: Input 3 macro current-account bundle whose schema is validated and whose catalog coordinates provide scenario context for evaluating the formula.
        input3_old_debt_service: Input 3 old debt-service bundle whose TIME_PERIOD axis is validated and used to define the projection-year grid and period positions of the output series.

    Returns:
        A typed data.Series[float | str | None] of public privatization receipts (negative) keyed by scenario and years, computed as baseline receipts times baseline nominal GDP divided by scenario public nominal GDP in local currency, preserving string or missing placeholders.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_div(xl_mul(baseline_pub_privatization_receipts_negative[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE.collect(evaluate(formula, data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION.schema, cells=data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION.cells)
def dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_recognition_of_contingent_liab_e_g_bank: data.Series[int | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes public recognition of contingent liabilities (e.g., bank recapitalization) as a share of scenario GDP.

    Rescales the baseline contingent-liability recognition amount by baseline nominal GDP and divides by scenario nominal GDP for public DSA outputs.

    Args:
        dsa_pub_nominal_gdp_local_currency: Scenario- and year-keyed nominal GDP in local currency data series used as the denominator when expressing the recognition amount relative to scenario GDP.
        baseline_pub_recognition_of_contingent_liab_e_g_bank: Baseline-year recognition of contingent liabilities (e.g., bank recapitalization) data series; non-numeric values are treated as zero in the rescaling.
        baseline_pub_nominal_gdp_lc: Baseline-year nominal GDP in local currency data series used to convert the baseline recognition amount into local-currency units before scenario rescaling.
        input3_input_3_macro_current_account: Input 3 macro current-account dataclass validated against its schema before computation.
        input3_old_debt_service: Input 3 old debt-service dataclass supplying the TIME_PERIOD axis and scenario/time binding used to evaluate and collect the output series.

    Returns:
        A data.Series[float | str | None] of contingent-liability recognition (e.g., bank recapitalization) relative to scenario nominal GDP, keyed by scenario and TIME_PERIOD, preserving non-numeric or blank results as strings or None.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario in ('B1', 'B2_nonmkt', 'C3', 'A1'):
            return as_measure((xl_div(xl_mul(baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period])) else xl_div(xl_mul(0, baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period])))
        return as_measure((xl_div(xl_mul(baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period])) else 0))

    return data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION.collect(evaluate(formula, data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER.schema, cells=data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER.cells)
def dsa_pub_debt_relief_hipc_and_other(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_debt_relief_hipc_other: data.Series[int | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Express baseline HIPC and other public debt relief as a share of GDP by rescaling it with the baseline-to-DSA nominal GDP ratio.

    Produces the public debt-relief (HIPC and other) series used in the public DSA, aligned to the scenario and year grid of the Input 3 debt-service data.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency for the DSA scenario, keyed by scenario and year; serves as the divisor when converting relief amounts into GDP shares.
        baseline_pub_debt_relief_hipc_other: Baseline public debt relief (HIPC and other) amounts in local currency, keyed by year, taken as the numerator of the relief ratio.
        baseline_pub_nominal_gdp_lc: Baseline nominal GDP in local currency, keyed by year; rescales the baseline relief amount onto the DSA scenario's GDP base before the final division.
        input3_input_3_macro_current_account: Typed Input 3 macro current-account block; validated against its schema before evaluation and supplying macro coordinates for the computation.
        input3_old_debt_service: Typed Input 3 old debt-service block; validated against its schema, and its TIME_PERIOD axis fixes the year domain over which the output series is evaluated.

    Returns:
        A data.Series[float | str | None] of debt relief (HIPC and other) as a share of GDP, keyed by scenario and year on the TIME_PERIOD axis, propagating non-numeric inputs as strings or None.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_div(xl_mul(baseline_pub_debt_relief_hipc_other[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER.collect(evaluate(formula, data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY.schema, cells=data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY.cells)
def dsa_pub_other_debt_creating_or_reducing_flow_please_specify(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_old_new_scenario_total: float | str, baseline_pub_other_debt_creating_reducing_flow_please_specify: data.Series[int | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], c2_natdisaster_historical_statistics_key_variables_past_10: int | str, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derives the public-sector "other debt creating or reducing flow (please specify)" path (B1_GDP_pub) for every scenario in the ladder.

    Rescales the baseline other-flow series into each scenario's local-currency GDP numeraire and applies the C1/C2 first-year scenario adjustments.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency as a named-axis series over catalog coordinates (scenario, time period); values may be blank or text and enter the ratio as the scenario-specific denominator.
        dsa_pub_old_new_scenario_total: Scalar old-to-new scenario total ratio applied only to the first projection year of the C1 shock when dividing the rescaled baseline flow.
        baseline_pub_other_debt_creating_reducing_flow_please_specify: Baseline other debt-creating or reducing flow series over time period; blank or text entries are treated as non-numeric and contribute zero to the scaled flow.
        baseline_pub_nominal_gdp_lc: Baseline nominal GDP in local currency series used to restore the baseline flow to a currency amount before rescaling into the scenario GDP.
        c2_natdisaster_historical_statistics_key_variables_past_10: Scalar natural-disaster historical-statistics add-on (percent of GDP) added to the C2 shock in its first projection year regardless of the baseline flow's numeric status.
        input3_input_3_macro_current_account: Typed dataclass of series carrying the Input 3 macro current-account assumptions; it is schema-validated for structural consistency before evaluation.
        input3_old_debt_service: Typed dataclass of series carrying the Input 3 old debt service grid whose time-period axis fixes the projection domain bound for the returned series.

    Returns:
        A data.Series[float | str | None] of the other debt-creating or reducing flow (B1_GDP_pub), keyed by scenario and by the projection years taken from row 7, with blanks or text propagated where inputs are non-numeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'C1' and _p_time_period == 1:
            return as_measure(xl_add(xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), dsa_pub_old_new_scenario_total))
        elif scenario == 'C2' and _p_time_period == 1:
            return as_measure((xl_add(xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), c2_natdisaster_historical_statistics_key_variables_past_10) if xl_bool(xl_isnumber(lambda: baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period])) else xl_add(xl_div(xl_mul(0, baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), c2_natdisaster_historical_statistics_key_variables_past_10)))
        elif scenario == 'C1' and _p_time_period >= 2:
            return as_measure(xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))
        elif scenario in ('B1', 'B2_nonmkt', 'C3', 'A1'):
            return as_measure((xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period])) else xl_div(xl_mul(0, baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period])))
        return as_measure((xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period])) else 0))

    return data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY.collect(evaluate(formula, data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_RESIDUAL.schema, cells=data.DSA_PUB_RESIDUAL.cells)
def dsa_pub_residual(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_residual: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the public-sector residual (B1_GDP_pub) from baseline residual and GDP deflator ratios.

    Derives the public residual series by scaling the baseline residual with baseline nominal GDP and dividing by scenario-specific nominal GDP in local currency.

    Args:
        dsa_pub_nominal_gdp_local_currency: Scenario- and time-keyed series of nominal GDP in local currency used as the divisor in the residual calculation.
        baseline_pub_residual: Time-keyed series of baseline public residual values used as the numerator input to the scaled residual formula.
        baseline_pub_nominal_gdp_lc: Time-keyed series of baseline nominal GDP in local currency used to rescale the baseline public residual.
        input3_input_3_macro_current_account: Input 3 macro current-account dataclass validated for schema consistency before computation.
        input3_old_debt_service: Input 3 old debt-service dataclass whose TIME_PERIOD axis supplies the evaluation grid for the output series.

    Returns:
        Scenario- and time-keyed series of public residual values (B1_GDP_pub), aligned to years from row 7, with numeric, string, or null entries as computed.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_div(xl_mul(baseline_pub_residual[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_RESIDUAL.collect(evaluate(formula, data.DSA_PUB_RESIDUAL.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_RESIDUAL.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.schema, cells=data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.cells)
def dsa_pub_nominal_gdp_local_currency(*, dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_pub_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None], macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes nominal GDP in local currency from the initial-year USD GDP and exchange rate, then rolls it forward with real growth and GDP-deflator inflation.

    Builds the B1_GDP_pub scenario-and-year series used by the public-sector DSA.

    Args:
        dsa_pub_real_gdp_growth_in_percent: Real GDP growth rate in percent as a typed data.Series[float | str | None] over scenario and TIME_PERIOD coordinates.
        dsa_pub_inflation_rate_gdp_deflator_in_percent: GDP-deflator inflation rate in percent as a typed data.Series[float | str | None] over scenario and TIME_PERIOD coordinates.
        macro_debt_gdp_current_prices_u_s_dollars: GDP at current U.S. dollars as a typed data.Series[float | str | None] supplying the initial-year level for conversion.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Exchange rate in national currency per U.S. dollar as a typed data.Series[float | str | None], used to convert the initial-year GDP level to local currency.
        input3_input_3_macro_current_account: Input 3 macro current-account dataclass carrying related macro projection series; schema-validated before the calculation.
        input3_old_debt_service: Input 3 old-debt-service dataclass whose TIME_PERIOD axis supplies the projection year grid for the output series; schema-validated before the calculation.

    Returns:
        A data.Series[float | str | None] of nominal GDP in local currency (B1_GDP_pub), keyed by scenario and years from row 7.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))
        return as_measure(xl_mul(xl_mul(dsa_pub_nominal_gdp_local_currency[scenario, axis_step(_ax_time_period, time_period, -1)], xl_add(1, xl_div(dsa_pub_real_gdp_growth_in_percent[scenario, time_period], 100))), xl_add(1, xl_div(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))))

    dsa_pub_nominal_gdp_local_currency = CoordinateReader('dsa_pub_nominal_gdp_local_currency', data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.collect(((coord, dsa_pub_nominal_gdp_local_currency[coord]) for coord in data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.schema, cells=data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.cells)
def dsa_pub_real_gdp_growth_in_percent(*, a1_hist_pub_historical_statistics: data.Series[float | str | None], input6_standard_size_threshold_option_historical_average_only: str, input6_standard_size_threshold_option_whichever_is_lower: str, dsa_ext_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_pub_standard_test_parameter: data.Series[str | int | float | bool | None], dsa_pub_standard_test_gdp_growth_rule: str | int | float | bool, dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule: str | int | float | bool, baseline_pub_real_gdp_growth: data.Series[float | str | None], leftover_real_gdp_growth: data.Series[float | str | None], b1_gdp_pub_key_macroeconomic_fiscal_assumptions: float | str, b6_combo_mkt_pub_i_baseline_medium_term_projections: float | str, b6_combo_nonmkt_pub_i_baseline_medium_term_projections: float | str, leftover_nominal_interest_rate: float | str, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derive the public DSA real GDP growth path (in percent) by scenario and year.

    Builds the B1, B6_mkt, B6_nonmkt, C2, C3, and A1 scenario growth paths for the public DSA from baseline growth, leftover growth, and threshold-rule choices.

    Args:
        a1_hist_pub_historical_statistics: Historical statistics series whose 'Real GDP growth (in percent)' historical-average entry supplies the A1 scenario first-period growth rate.
        input6_standard_size_threshold_option_historical_average_only: Threshold-rule option string identifying the 'historical average only' choice, compared against the per-scenario standard test parameter to select the historical-average growth formula.
        input6_standard_size_threshold_option_whichever_is_lower: Threshold-rule option string identifying the 'whichever is lower' choice, selecting the minimum of the historical-average and baseline growth formulas.
        dsa_ext_real_gdp_growth_in_percent: External DSA real GDP growth series (in percent) keyed by scenario and year, copied into the C3 scenario for the first six periods.
        dsa_pub_standard_test_parameter: Per-scenario standard test parameter series holding the selected threshold-rule option used to choose among the growth formula variants.
        dsa_pub_standard_test_gdp_growth_rule: Scalar threshold-rule selector governing which B6_mkt growth formula applies (whichever-is-lower, historical-average-only, or baseline).
        dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule: Scalar threshold-rule selector governing which B6_nonmkt growth formula applies (whichever-is-lower, historical-average-only, or baseline).
        baseline_pub_real_gdp_growth: Baseline public real GDP growth series (in percent) keyed by year, the default path for periods and scenarios without a specific rule.
        leftover_real_gdp_growth: Leftover real GDP growth series keyed by scenario and year, scaled by the B1 or B6 medium-term factor when adjusting the baseline.
        b1_gdp_pub_key_macroeconomic_fiscal_assumptions: B1 GDP key macroeconomic and fiscal assumption multiplier applied to leftover real GDP growth when constructing the B1 path.
        b6_combo_mkt_pub_i_baseline_medium_term_projections: B6 market-financing baseline medium-term projection multiplier applied to leftover real GDP growth for the B6_mkt scenario.
        b6_combo_nonmkt_pub_i_baseline_medium_term_projections: B6 non-market-financing baseline medium-term projection multiplier applied to leftover real GDP growth for the B6_nonmkt scenario.
        leftover_nominal_interest_rate: Nominal interest rate scalar subtracted from baseline real GDP growth to form the C2 scenario first-period value.
        input3_input_3_macro_current_account: Input 3 macro current account dataclass whose TIME_PERIOD axis defines the projection year grid and historical lookback offsets.
        input3_old_debt_service: Input 3 old debt service dataclass whose TIME_PERIOD domain binds the output series coordinate grid.

    Returns:
        Public DSA real GDP growth series (in percent), keyed by scenario and years from row 7, with values as floats or strings, or None where the workbook leaves a blank.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B1' and _p_time_period == 1:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_whichever_is_lower)) else (xl_sub(leftover_real_gdp_growth[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_historical_average_only)) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B1' and _p_time_period == 2:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])) if xl_bool(xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, axis_step(_ax_time_period, time_period, -1)], xl_sub(leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]))))
        elif scenario == 'B6_mkt' and _p_time_period == 1:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_sub(leftover_real_gdp_growth[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B6_mkt' and _p_time_period == 2:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])) if xl_bool(xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, axis_step(_ax_time_period, time_period, -1)], xl_sub(leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]))))
        elif scenario == 'B6_nonmkt' and _p_time_period == 1:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_sub(leftover_real_gdp_growth[scenario, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B6_nonmkt' and _p_time_period == 2:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])) if xl_bool(xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, axis_step(_ax_time_period, time_period, -1)], xl_sub(leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]))))
        elif scenario == 'C2' and _p_time_period == 1:
            return as_measure(xl_sub(baseline_pub_real_gdp_growth[time_period], leftover_nominal_interest_rate))
        elif scenario == 'A1' and _p_time_period == 1:
            return as_measure(a1_hist_pub_historical_statistics['Real GDP growth (in percent)', 'Historical average'])
        elif scenario == 'C3' and _p_time_period <= 6:
            return as_measure(dsa_ext_real_gdp_growth_in_percent[scenario, time_period])
        elif scenario == 'A1' and _p_time_period >= 2:
            return as_measure(dsa_pub_real_gdp_growth_in_percent[scenario, axis_step(_ax_time_period, time_period, -1)])
        return as_measure(baseline_pub_real_gdp_growth[time_period])

    dsa_pub_real_gdp_growth_in_percent = CoordinateReader('dsa_pub_real_gdp_growth_in_percent', data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.collect(((coord, dsa_pub_real_gdp_growth_in_percent[coord]) for coord in data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.schema, cells=data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.cells)
def dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent(*, dsa_pub_total_public_external_debt: data.Series[float | str | None], dsa_pub_external_debt: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the average nominal interest rate on external debt as a percent series (B1_GDP_pub) over scenario and year coordinates.

    Derive the row-7 interest-rate indicator by scaling the external-debt-to-prior-year-total-public-external-debt ratio with the year-over-year exchange-rate movement.

    Args:
        dsa_pub_total_public_external_debt: Total public external debt stock indexed by scenario and year; its prior-year value supplies the base of the ratio.
        dsa_pub_external_debt: External debt stock series on the same scenario and year grid; its current-year value supplies the numerator of the ratio.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: National-currency-per-U.S.-dollar exchange rate series whose prior-year value converts the ratio onto a comparable currency basis.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: The corresponding exchange-rate series on the national-currency basis, whose current-year value divides the converted ratio.
        input3_input_3_macro_current_account: Current-account macro input record whose time-period axis provides the prior-year offset applied in the exchange-rate lookup.
        input3_old_debt_service: Old debt service input record whose scenario and time-period domain defines the coordinate grid the resulting series is collected over.

    Returns:
        A `data.Series[float | str | None]` of the average nominal interest rate on external debt in percent, keyed by scenario and years from row 7, with string and blank values carried through from the underlying inputs.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_div(xl_mul(xl_mul(xl_div(dsa_pub_external_debt[scenario, time_period], dsa_pub_total_public_external_debt[scenario, axis_step(_ax_time_period, time_period, -1)]), 100), macro_debt_exchange_rate_national_currency_per_u_s_dollar[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.schema, cells=data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.cells)
def dsa_pub_average_real_interest_rate_on_external_debt_in_percent(*, dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent: data.Series[float | str | None], dsa_pub_us_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the average real interest rate on external debt (B1_GDP_pub) by deflating the nominal rate with US GDP-deflator inflation.

    Derives the real external-debt interest rate per scenario and year from the nominal rate and US inflation series, returning "..." where the nominal rate is non-numeric.

    Args:
        dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent: Keyword-only `data.Series[float | str | None]` of average nominal interest rate on external debt in percent, keyed by scenario and years; supplies the numerator before deflation and its numeric cells gate the result.
        dsa_pub_us_inflation_rate_gdp_deflator_in_percent: Keyword-only `data.Series[float | str | None]` of the US inflation rate (GDP deflator) in percent, keyed by scenario and years; used as the deflator divisor `(1 + inflation/100)`.
        input3_old_debt_service: Keyword-only `data.Input3OldDebtService` whose `TIME_PERIOD` axis is validated and bound to supply the scenario/time grid the calculation is evaluated over.

    Returns:
        `data.Series[float | str | None]` of the average real interest rate on external debt in percent (B1_GDP_pub), keyed by scenario and years, with "..." where the nominal rate is not numeric.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_div(xl_sub(dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent[scenario, time_period], dsa_pub_us_inflation_rate_gdp_deflator_in_percent[scenario, time_period]), xl_add(1, xl_div(dsa_pub_us_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))) if xl_bool(xl_isnumber(lambda: dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent[scenario, time_period])) else '...'))

    return data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service))

@dataclass(frozen=True, slots=True)
class ScanDsaPubExchangeRateLcPerUsDollarResult:
    """Complete named results of one recurrence group evaluation."""
    dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None]
    dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc: data.Series[float | str | None]

def scan_dsa_pub_exchange_rate_lc_per_us_dollar(*, dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService, baseline_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None]) -> ScanDsaPubExchangeRateLcPerUsDollarResult:
    """Evaluate the recurrence group `dsa_pub_exchange_rate_lc_per_us_dollar`, `dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc` and publish complete tensors."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def dsa_pub_exchange_rate_lc_per_us_dollar_formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B5' and _p_time_period >= 1:
            return as_measure(xl_div(1, dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[scenario, time_period]))
        elif scenario == 'A1':
            return as_measure(macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period])
        return as_measure(baseline_pub_exchange_rate_lc_per_us_dollar[time_period])

    dsa_pub_exchange_rate_lc_per_us_dollar = CoordinateReader('dsa_pub_exchange_rate_lc_per_us_dollar', data.DSA_PUB_EXCHANGE_RATE_LC_PER_US_DOLLAR.required.bind(TIME_PERIOD=input3_old_debt_service), dsa_pub_exchange_rate_lc_per_us_dollar_formula)
    def dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc_formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_div(1, dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        return as_measure(xl_mul(dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[scenario, axis_step(_ax_time_period, time_period, -1)], xl_add(1, xl_div(dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period], 100))))

    dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc = CoordinateReader('dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc', data.DSA_PUB_B5_DEPRECIATION_PUB_EXCHANGE_RATE_US_DOLLAR_PER_LC.required.bind(TIME_PERIOD=input3_old_debt_service), dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc_formula)
    return ScanDsaPubExchangeRateLcPerUsDollarResult(
        dsa_pub_exchange_rate_lc_per_us_dollar=data.DSA_PUB_EXCHANGE_RATE_LC_PER_US_DOLLAR.collect(((coord, dsa_pub_exchange_rate_lc_per_us_dollar[coord]) for coord in data.DSA_PUB_EXCHANGE_RATE_LC_PER_US_DOLLAR.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_EXCHANGE_RATE_LC_PER_US_DOLLAR.required.bind(TIME_PERIOD=input3_old_debt_service)),
        dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc=data.DSA_PUB_B5_DEPRECIATION_PUB_EXCHANGE_RATE_US_DOLLAR_PER_LC.collect(((coord, dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[coord]) for coord in data.DSA_PUB_B5_DEPRECIATION_PUB_EXCHANGE_RATE_US_DOLLAR_PER_LC.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_B5_DEPRECIATION_PUB_EXCHANGE_RATE_US_DOLLAR_PER_LC.required.bind(TIME_PERIOD=input3_old_debt_service)),
    )

@publish(data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR.schema, cells=data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR.cells)
def dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute nominal local-currency depreciation as the percentage change in LC per U.S. dollar.

    Derives the annual percentage depreciation of the local currency from the public DSA exchange-rate path, expressed relative to the prior period.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Public DSA exchange rate (LC per U.S. dollar) as a typed data series over scenario and time-period coordinates.
        input3_old_debt_service: Input 3 old debt service data series supplying the scenario and time-period domain used to align and evaluate the calculation.

    Returns:
        A typed data series of floats, strings, or None holding the nominal depreciation percentages keyed by scenario and projection years.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_sub(xl_div(dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, axis_step(_ax_time_period, time_period, -1)]), 1), 100))

    return data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR.collect(evaluate(formula, data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION.schema, cells=data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION.cells)
def dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation(*, dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar: data.Series[float | str | None], dsa_pub_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None], dsa_pub_us_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes real exchange rate depreciation in percent from nominal local-currency depreciation and domestic/US GDP-deflator inflation.

    Derives the published real exchange rate depreciation series (positive values indicate depreciation) on the scenario and time-period domain supplied by the old debt service input.

    Args:
        dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar: Nominal depreciation of the local currency as percentage change in local currency per dollar, keyed by scenario and time period.
        dsa_pub_inflation_rate_gdp_deflator_in_percent: Domestic inflation rate measured by the GDP deflator in percent, keyed by scenario and time period.
        dsa_pub_us_inflation_rate_gdp_deflator_in_percent: US inflation rate measured by the GDP deflator in percent, keyed by scenario and time period.
        input3_old_debt_service: Old debt service input whose schema is validated and whose TIME_PERIOD domain axis binds the time periods used for the computed series.

    Returns:
        A data.Series[float | str | None] of real exchange rate depreciation in percent (positive indicates depreciation), keyed by scenario and the time periods sourced from the old debt service input.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_sub(xl_div(xl_mul(xl_add(100, dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar[scenario, time_period]), xl_add(1, xl_div(dsa_pub_us_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))), xl_add(1, xl_div(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))), 100))

    return data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION.collect(evaluate(formula, data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.schema, cells=data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.cells)
def dsa_pub_inflation_rate_gdp_deflator_in_percent(*, a1_hist_pub_historical_statistics: data.Series[float | str | None], dsa_ext_exports: data.Series[float | str | None], dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None], dsa_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None], dsa_pub_b6_combo_non_mkt_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None], dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator: float | str, baseline_pub_real_gdp_growth: data.Series[float | str | None], baseline_pub_inflation_rate_gdp_deflator_pct: data.Series[float | str | None], leftover_real_interest_rate: data.Series[float | str | None], b6_combo_mkt_pub_i_baseline_medium_term_nominal_debt: float | str, b6_combo_nonmkt_pub_in_billions_of_lc: float | str, c3_commodity_pub_historical_statistics_key_variables_past_10: int | str, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the public DSA GDP-deflator inflation rate series across baseline and standardized stress scenarios.

    Derives the scenario-and-year inflation path (B1_GDP_pub) by applying scenario-specific adjustments to baseline GDP-deflator inflation.

    Args:
        a1_hist_pub_historical_statistics: Historical statistics series supplying the A1 scenario's historical-average inflation rate (GDP deflator, in percent) lookup.
        dsa_ext_exports: Exports series used by the C3 scenario to scale the commodity-price effect on the GDP deflator.
        dsa_pub_real_gdp_growth_in_percent: Real GDP growth series for the DSA stress scenarios, used to adjust baseline growth in the B1 scenario.
        dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: B5 scenario nominal depreciation series, expressed as the increase in the US-dollar value of the local currency, in percent.
        dsa_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: Nominal appreciation series, expressed as the increase in the US-dollar value of the local currency, in percent, applied in the B6 market-financing scenario.
        dsa_pub_b6_combo_non_mkt_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: B6 non-market scenario nominal appreciation series, expressed as the increase in the US-dollar value of the local currency, in percent.
        dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator: Scalar commodity-price decline applied to the GDP deflator in the C3 scenario, in percent.
        baseline_pub_real_gdp_growth: Baseline real GDP growth series used to derive the B1 scenario growth differential.
        baseline_pub_inflation_rate_gdp_deflator_pct: Baseline GDP-deflator inflation rate series, in percent, from which all scenario paths are adjusted.
        leftover_real_interest_rate: Leftover real interest rate series used as the elasticity factor in the B1 and B5 adjustments.
        b6_combo_mkt_pub_i_baseline_medium_term_nominal_debt: Scalar baseline medium-term nominal debt used as the multiplier in the B6 market-financing inflation adjustment.
        b6_combo_nonmkt_pub_in_billions_of_lc: Scalar non-market public debt in billions of local currency used as the multiplier in the B6 non-market adjustment.
        c3_commodity_pub_historical_statistics_key_variables_past_10: Scalar count of historical key-variable years in the past 10 used to phase the C3 commodity-price decay.
        input3_input_3_macro_current_account: Input 3 macro current-account dataclass providing the TIME_PERIOD axis and reference-year keys for the C3 scenario.
        input3_old_debt_service: Input 3 old debt service dataclass whose TIME_PERIOD axis anchors the returned series and its scenario/year coordinates.

    Returns:
        GDP-deflator inflation rate series (B1_GDP_pub), in percent, keyed by scenario and TIME_PERIOD over the coordinate domain bound from the old debt service axis.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B6_mkt' and _p_time_period == 1:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_nominal_debt, dsa_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'B5' and _p_time_period == 1:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(leftover_real_interest_rate[scenario], dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'B6_nonmkt' and _p_time_period == 1:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(b6_combo_nonmkt_pub_in_billions_of_lc, dsa_pub_b6_combo_non_mkt_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'C3' and _p_time_period == 1:
            return as_measure(xl_mul(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_add(1, xl_div(xl_mul(dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator, dsa_ext_exports[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), 100))))
        elif scenario == 'C3' and _p_time_period == 2:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[15]], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, _ax_time_period.keys[1]]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 1)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and _p_time_period == 3:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[15]], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, _ax_time_period.keys[1]]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and _p_time_period == 4:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[15]], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, _ax_time_period.keys[1]]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 3)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and _p_time_period == 5:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[15]], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, _ax_time_period.keys[1]]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 4)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and _p_time_period == 6:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[15]], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, _ax_time_period.keys[1]]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 5)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'A1' and _p_time_period == 1:
            return as_measure(a1_hist_pub_historical_statistics['Inflation rate (GDP deflator, in percent)', 'Historical average'])
        elif scenario == 'B1' and _p_time_period <= 2:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(xl_sub(baseline_pub_real_gdp_growth[time_period], dsa_pub_real_gdp_growth_in_percent[scenario, time_period]), leftover_real_interest_rate[scenario])))
        elif scenario == 'A1' and _p_time_period >= 2:
            return as_measure(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, axis_step(_ax_time_period, time_period, -1)])
        return as_measure(baseline_pub_inflation_rate_gdp_deflator_pct[time_period])

    dsa_pub_inflation_rate_gdp_deflator_in_percent = CoordinateReader('dsa_pub_inflation_rate_gdp_deflator_in_percent', data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.collect(((coord, dsa_pub_inflation_rate_gdp_deflator_in_percent[coord]) for coord in data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.schema, cells=data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.cells)
def dsa_pub_us_inflation_rate_gdp_deflator_in_percent(*, macro_debt_us_gdp_deflator_percent_change: data.Series[float | str | None], baseline_pub_us_inflation_rate_gdp_deflator_pct: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Return the public US GDP-deflator inflation rate path used by the public DSA.

    Selects the A1 historical GDP-deflator percent-change path and otherwise the baseline public inflation path, aligned to the old-debt-service year grid.

    Args:
        macro_debt_us_gdp_deflator_percent_change: GDP-deflator percent-change series over scenario and time whose values supply the A1 historical inflation path.
        baseline_pub_us_inflation_rate_gdp_deflator_pct: Baseline public US GDP-deflator inflation rate series over scenario and time used for every non-A1 scenario.
        input3_input_3_macro_current_account: Input 3 macro current-account typed data structure, validated for schema conformance and not otherwise read by this helper.
        input3_old_debt_service: Input 3 old-debt-service typed data structure whose TIME_PERIOD axis defines the output year grid.

    Returns:
        Public US inflation rate (GDP deflator, in percent) series keyed by scenario and TIME_PERIOD, taking A1 from the historical change series and other scenarios from the baseline series.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'A1':
            return as_measure(macro_debt_us_gdp_deflator_percent_change[time_period])
        return as_measure(baseline_pub_us_inflation_rate_gdp_deflator_pct[time_period])

    return data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service))

