@publish(data.DSA_PUB_TOTAL_PUBLIC_EXTERNAL_DEBT.schema, cells=data.DSA_PUB_TOTAL_PUBLIC_EXTERNAL_DEBT.cells)
def dsa_pub_total_public_external_debt(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], macro_debt_total_public_ext_debt: data.Series[float | str | None], pv_resfin_pub_output_stock_of_new_forex_debt_in_usd: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the total public external debt (B1_GDP_pub) path in local currency across scenarios and projection years.

    Convert the USD-denominated public external debt stock to local currency and add scenario-specific residual financing to produce the public DSA debt series.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Typed data series of the DSA public exchange rate in local currency per US dollar, keyed by scenario and year and applied to the converted debt stock.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: Typed data series of the macro-debt exchange rate in national currency per US dollar, used to translate the external debt stock before the DSA conversion.
        macro_debt_total_public_ext_debt: Typed data series of total public external debt in US dollars, the base stock carried across projection years.
        pv_resfin_pub_output_stock_of_new_forex_debt_in_usd: Typed data series of the residual-financing stock of new foreign-currency debt in US dollars, indexed by debtor category, scenario, and year.
        input3_input_3_macro_current_account: Typed dataclass of series holding the Input 3 macro current account block; validated against its schema before evaluation.
        input3_old_debt_service: Typed dataclass of series holding the Input 3 old debt service block, whose TIME_PERIOD axis supplies the scenario and year grid for evaluation and domain binding.

    Returns:
        Typed data series of total public external debt (float, str, or None per cell) keyed by scenario and TIME_PERIOD over the projection years from row 7.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_mul(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B1' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 1: Real GDP Growth Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B2_mkt' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B6_mkt' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 6: Combined Shock for Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C1' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Tailored Stress Test 1: Contingent Liability Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B2_nonmkt' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B5' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 5: Exchange Rate Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B6_nonmkt' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C2' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'CL1: Natural disaster', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C3' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Tailored Stress Test 3. Commodity Price shock - Public', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        return as_measure(xl_mul(xl_add(xl_div(macro_debt_total_public_ext_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), pv_resfin_pub_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Key variables at historical average', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))

    return data.DSA_PUB_TOTAL_PUBLIC_EXTERNAL_DEBT.collect(evaluate(formula, data.DSA_PUB_TOTAL_PUBLIC_EXTERNAL_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_TOTAL_PUBLIC_EXTERNAL_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_PRIMARY_DEFICIT_LOCAL_CURRENCY.schema, cells=data.DSA_PUB_PRIMARY_DEFICIT_LOCAL_CURRENCY.cells)
def dsa_pub_primary_deficit_local_currency(*, dsa_pub_primary_deficit: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Convert public primary deficit from percent of GDP to local-currency units.

    Support public DSA calculations by expressing the primary deficit in nominal local currency for each scenario and projection year.

    Args:
        dsa_pub_primary_deficit: Primary deficit (B1_GDP_pub) as a percentage of GDP, provided as a scenario-by-year data series that may contain float, text, or blank values.
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency, provided as a scenario-by-year data series used to scale the percent-of-GDP deficit into currency units.
        input3_old_debt_service: Old debt service input bundle whose TIME_PERIOD coordinate axis supplies the projection-year grid used to align and evaluate the calculation.

    Returns:
        A scenario-by-year data.Series[float | str | None] containing the public primary deficit in local currency, preserving numeric, text, or blank results from the calculation.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(dsa_pub_primary_deficit[scenario, time_period], 100), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_PRIMARY_DEFICIT_LOCAL_CURRENCY.collect(evaluate(formula, data.DSA_PUB_PRIMARY_DEFICIT_LOCAL_CURRENCY.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_PRIMARY_DEFICIT_LOCAL_CURRENCY.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_OTHER_DEBT_CREATING_FLOWS.schema, cells=data.DSA_PUB_OTHER_DEBT_CREATING_FLOWS.cells)
def dsa_pub_other_debt_creating_flows(*, baseline_pub_other_identified_debt_creating_flows: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes public-sector other debt-creating flows (B1_GDP_pub) as a percentage-scaled share of nominal GDP in local currency.

    Derives each scenario-year value by converting the identified debt-creating flows from percent of GDP into local-currency amounts using baseline nominal GDP.

    Args:
        baseline_pub_other_identified_debt_creating_flows: Series of baseline public other identified debt-creating flows expressed in percent of GDP, indexed by scenario and time period.
        baseline_pub_nominal_gdp_lc: Series of baseline nominal GDP in local currency, indexed by scenario and time period, used to scale the percent-of-GDP flows.
        input3_input_3_macro_current_account: Data series for the Input 3 macro current-account block, validated against its schema and aligned to the scenario-year grid.
        input3_old_debt_service: Data series for Input 3 old debt service, validated against its schema and used to supply the time-period axis for evaluation.

    Returns:
        Series of public other debt-creating flows in local currency keyed by scenario and projection years, with float, string, or null values.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(baseline_pub_other_identified_debt_creating_flows[time_period], 100), baseline_pub_nominal_gdp_lc[time_period]))

    return data.DSA_PUB_OTHER_DEBT_CREATING_FLOWS.collect(evaluate(formula, data.DSA_PUB_OTHER_DEBT_CREATING_FLOWS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_OTHER_DEBT_CREATING_FLOWS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_PV_OF_PUBLIC_SECTOR_EXTERNAL_DEBT_END_OF_PERIOD.schema, cells=data.DSA_PUB_PV_OF_PUBLIC_SECTOR_EXTERNAL_DEBT_END_OF_PERIOD.cells)
def dsa_pub_pv_of_public_sector_external_debt_end_of_period(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], baseline_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], macro_debt_pv_of_public_sector_ext_debt_end_of_period: data.Series[float | str | None], pv_resfin_pub_output_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_resfin_pub_output_pv_of_new_forex_debt_in_usd: data.Series[float | str | None], pv_resfin_add_output_pv_of_new_forex_debt_in_usd: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the end-of-period PV of public sector external debt for the public DSA scenario ladder.

    Derives the B1_GDP_pub series by rescaling baseline public external debt PV and adding scenario-specific new forex debt PV under each stress or tailored shock.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Scenario-indexed `data.Series[float | str | None]` of the public DSA exchange rate in local currency per U.S. dollar.
        baseline_pub_exchange_rate_lc_per_us_dollar: Baseline `data.Series[float | str | None]` of the public exchange rate in local currency per U.S. dollar.
        macro_debt_pv_of_public_sector_ext_debt_end_of_period: `data.Series[float | str | None]` of the macro-debt PV of public sector external debt at end of period.
        pv_resfin_pub_output_new_forex_borrowing_gross_usd: `data.Series[float | str | None]` of gross new forex borrowing in USD from the PV residual-financing public output, indexed by debt category, stress case, and time.
        pv_resfin_pub_output_pv_of_new_forex_debt_in_usd: `data.Series[float | str | None]` of the PV of new forex debt in USD from the PV residual-financing public output, indexed by debt category, stress case, and time.
        pv_resfin_add_output_pv_of_new_forex_debt_in_usd: `data.Series[float | str | None]` of additional PV of new forex debt in USD from the PV residual-financing output, indexed by debt category, stress case, and time.
        input3_input_3_macro_current_account: Typed `data.Input3Input3MacroCurrentAccount` input bundle supplying macro current-account coordinates and domain validation.
        input3_old_debt_service: Typed `data.Input3OldDebtService` input bundle supplying the old-debt-service coordinates and the `TIME_PERIOD` axis used to bind the result domain.

    Returns:
        `data.Series[float | str | None]` of the PV of public sector external debt at end of period (`B1_GDP_pub`), keyed by scenario and projection year.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B2_mkt' and _p_time_period == 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif _p_time_period == 0:
            return as_measure(xl_div(xl_mul(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), baseline_pub_exchange_rate_lc_per_us_dollar[time_period]))
        elif scenario == 'B2_mkt' and _p_time_period >= 2:
            return as_measure(xl_mul(xl_add(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), pv_resfin_add_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B1' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 1: Real GDP Growth Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B6_mkt' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 6: Combined Shock for Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C1' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Tailored Stress Test 1: Contingent Liability Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B2_nonmkt' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B5' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 5: Exchange Rate Shock', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'B6_nonmkt' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_new_forex_borrowing_gross_usd['External PPG medium and long-term', 'Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C2' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'CL1: Natural disaster', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        elif scenario == 'C3' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Tailored Stress Test 3. Commodity Price shock - Public', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        return as_measure(xl_mul(xl_add(xl_div(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period]), pv_resfin_pub_output_pv_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Key variables at historical average', time_period]), dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))

    return data.DSA_PUB_PV_OF_PUBLIC_SECTOR_EXTERNAL_DEBT_END_OF_PERIOD.collect(evaluate(formula, data.DSA_PUB_PV_OF_PUBLIC_SECTOR_EXTERNAL_DEBT_END_OF_PERIOD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_PV_OF_PUBLIC_SECTOR_EXTERNAL_DEBT_END_OF_PERIOD.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.schema, cells=data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.cells)
def dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent(*, dsa_pub_revenue_and_grants: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_of_which_short_term: data.Series[float | str | None], dsa_pub_amortization_excluding_st_domestic_debt: data.Series[float | str | None], dsa_pub_interest_expenditure: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes the public debt service-to-revenue-and-grants ratio (B1_GDP_pub) expressed in percent.

    Derive the public DSA debt service burden relative to fiscal revenue and grants for each scenario and projection year, with the A1 scenario floored at zero.

    Args:
        dsa_pub_revenue_and_grants: Revenue and grants series for the public DSA, a named-axis series over scenario and time used as the denominator together with nominal GDP.
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency series over scenario and time, multiplied with revenue and grants to form the denominator.
        dsa_pub_of_which_short_term: Of-which short-term debt series over scenario and time, read at a one-period lag through the macro current account time axis.
        dsa_pub_amortization_excluding_st_domestic_debt: Amortization excluding short-term domestic debt series over scenario and time, added to interest and lagged short-term debt in the numerator.
        dsa_pub_interest_expenditure: Interest expenditure series over scenario and time, added to amortization and lagged short-term debt in the numerator.
        input3_input_3_macro_current_account: Macro current account dataclass whose TIME_PERIOD axis supplies the coordinate used to shift short-term debt by one period.
        input3_old_debt_service: Old debt service dataclass providing the scenario and time domain over which the ratio is evaluated and bound.

    Returns:
        A named-axis series of the debt service-to-revenue-and-grants ratio in percent, keyed by scenario and year, with values that may be numeric, string sentinels, or None.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'A1':
            return as_measure((0 if xl_bool(xl_lt(xl_div(xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), xl_mul(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period])), 0)) else xl_div(xl_mul(10000, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])), xl_mul(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]))))
        return as_measure(xl_div(xl_mul(10000, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])), xl_mul(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period])))

    return data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_DEBT_SERVICE_TO_GDP_RATIO_IN_PERCENT.schema, cells=data.DSA_PUB_DEBT_SERVICE_TO_GDP_RATIO_IN_PERCENT.cells)
def dsa_pub_debt_service_to_gdp_ratio_in_percent(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_of_which_short_term: data.Series[float | str | None], dsa_pub_amortization_excluding_st_domestic_debt: data.Series[float | str | None], dsa_pub_interest_expenditure: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the public debt service-to-GDP ratio in percent by scenario and year.

    Derive the B1_GDP_pub public DSA indicator by summing amortization, interest, and lagged short-term debt and dividing by nominal GDP.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency as a named-axis series over scenarios and years; used as the denominator of the ratio.
        dsa_pub_of_which_short_term: Short-term public debt as a named-axis series over scenarios and years; shifted back one year, or two years for scenario C2, before being added to amortization and interest.
        dsa_pub_amortization_excluding_st_domestic_debt: Public amortization excluding short-term domestic debt as a named-axis series over scenarios and years; contributes directly to the debt-service numerator.
        dsa_pub_interest_expenditure: Public interest expenditure as a named-axis series over scenarios and years; contributes directly to the debt-service numerator.
        input3_input_3_macro_current_account: Macro current-account input dataclass of named-axis series whose TIME_PERIOD axis supplies the lag positions used for short-term debt.
        input3_old_debt_service: Old debt service input dataclass of named-axis series whose TIME_PERIOD domain defines the output scenario-year grid and alignment.

    Returns:
        A data.Series[float | str | None] of public debt service-to-GDP ratios in percent, keyed by scenario and years from row 7 and aligned to the old debt service TIME_PERIOD domain.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'C2':
            return as_measure(xl_div(xl_mul(100, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -2)])), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))
        elif scenario == 'A1':
            return as_measure((0 if xl_bool(xl_lt(xl_div(xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 0)) else xl_div(xl_mul(100, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])), dsa_pub_nominal_gdp_local_currency[scenario, time_period])))
        return as_measure(xl_div(xl_mul(100, xl_add(xl_add(dsa_pub_amortization_excluding_st_domestic_debt[scenario, time_period], dsa_pub_interest_expenditure[scenario, time_period]), dsa_pub_of_which_short_term[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)])), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_DEBT_SERVICE_TO_GDP_RATIO_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_DEBT_SERVICE_TO_GDP_RATIO_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_DEBT_SERVICE_TO_GDP_RATIO_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_PV_OF_PUBLIC_DEBT_TO_REVENUE_AND_GRANTS_RATIO.schema, cells=data.DSA_PUB_PV_OF_PUBLIC_DEBT_TO_REVENUE_AND_GRANTS_RATIO.cells)
def dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio(*, dsa_pub_pv_of_total_public_debt: data.Series[float | str | None], dsa_pub_revenue_and_grants: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the PV of public debt-to-revenue and grants ratio for the public DSA.

    Derive the B1_GDP_pub ratio by dividing PV of total public debt by public revenue and grants, scaling by 100 across scenarios and projection years.

    Args:
        dsa_pub_pv_of_total_public_debt: Series of the present value of total public debt, keyed by scenario and year.
        dsa_pub_revenue_and_grants: Series of public revenue and grants, keyed by scenario and year.
        input3_old_debt_service: Typed Input 3 old-debt-service data container, used to supply the TIME_PERIOD axis for aligning the output series.

    Returns:
        data.Series[float | str | None] containing the PV of public debt-to-revenue and grants ratio, keyed by scenario and TIME_PERIOD.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(dsa_pub_pv_of_total_public_debt[scenario, time_period], dsa_pub_revenue_and_grants[scenario, time_period]), 100))

    return data.DSA_PUB_PV_OF_PUBLIC_DEBT_TO_REVENUE_AND_GRANTS_RATIO.collect(evaluate(formula, data.DSA_PUB_PV_OF_PUBLIC_DEBT_TO_REVENUE_AND_GRANTS_RATIO.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_PV_OF_PUBLIC_DEBT_TO_REVENUE_AND_GRANTS_RATIO.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_STANDARD_TEST_PARAMETER.schema, cells=data.DSA_PUB_STANDARD_TEST_PARAMETER.cells)
def dsa_pub_standard_test_parameter(*, in6opt_standard_historical_average_baseline_projection: str | int | float | bool, lookup_ida_terms_new: str, input6_standard_size_threshold_mode: Literal["New", "Old"], input6_standard_user_defined_threshold: data.Input6StandardUserDefinedThreshold, in6opt_standard_b1_real_gdp_growth_historical_average_baseline_projection: str | int | float | bool) -> data.Series[str | int | float | bool | None]:
    """Compute public standard-test DSA parameters from Input 6 threshold settings.

    Selects each scenario's standard-test threshold value from user-defined Input 6 settings or scalar fallbacks according to the IDA terms mode.

    Args:
        in6opt_standard_historical_average_baseline_projection: Scalar fallback value for the B1 real GDP growth standard-test threshold when the size-threshold mode does not match the IDA terms lookup.
        lookup_ida_terms_new: Scalar IDA terms label compared against the size-threshold mode to choose new versus old threshold handling.
        input6_standard_size_threshold_mode: Scalar literal mode selecting the new or old IDA terms basis for standard-test size thresholds.
        input6_standard_user_defined_threshold: Typed data.Input6StandardUserDefinedThreshold series of user-defined threshold sizes over scenario, indicator, and threshold-component coordinates.
        in6opt_standard_b1_real_gdp_growth_historical_average_baseline_projection: Scalar fallback value for non-B1 standard-test thresholds when the size-threshold mode does not match the IDA terms lookup.

    Returns:
        Typed data.Series[str | int | float | bool | None] of selected standard-test parameter values over the required scenario coordinates.
    """
    data.INPUT6_STANDARD_USER_DEFINED_THRESHOLD.schema.validate(input6_standard_user_defined_threshold)
    def formula(scenario: str) -> str | int | float | bool | None:
        SCENARIO_TO_INPUT6_STANDARD_USER_DEFINED_THRESHOLD_INDICATOR = {'B1': 'Size of real GDP growth shock, # of standard deviations', 'B2_mkt': 'Size of PB/GDP shock, # of standard deviations'}
        SCENARIO_TO_INPUT6_STANDARD_USER_DEFINED_THRESHOLD = {'B1': 'B1. Real GDP growth', 'B2_mkt': 'B2. Primary balance'}
        if scenario == 'B1':
            return as_measure((input6_standard_user_defined_threshold[f'{scenario}. Real GDP growth', SCENARIO_TO_INPUT6_STANDARD_USER_DEFINED_THRESHOLD_INDICATOR[scenario], 'Size'] if xl_bool(xl_eq(input6_standard_size_threshold_mode, lookup_ida_terms_new)) else in6opt_standard_historical_average_baseline_projection), 'str')
        return as_measure((input6_standard_user_defined_threshold[SCENARIO_TO_INPUT6_STANDARD_USER_DEFINED_THRESHOLD[scenario], SCENARIO_TO_INPUT6_STANDARD_USER_DEFINED_THRESHOLD_INDICATOR[scenario], 'Size'] if xl_bool(xl_eq(input6_standard_size_threshold_mode, lookup_ida_terms_new)) else in6opt_standard_b1_real_gdp_growth_historical_average_baseline_projection), 'str')

    return data.DSA_PUB_STANDARD_TEST_PARAMETER.collect(evaluate(formula, data.DSA_PUB_STANDARD_TEST_PARAMETER.required))

@publish(data.DSA_PUB_PV_OF_DEBT_GDP.schema, cells=data.DSA_PUB_PV_OF_DEBT_GDP.cells)
def dsa_pub_pv_of_debt_gdp(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], leftover_exchange_rate_pa: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute public-sector PV of debt-to-GDP ratios from external-debt, exchange-rate, and nominal-GDP series.

    Derives the B2_PB_mkt_pub scenario-by-year output series by converting external debt and GDP into a common currency basis.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency as a data series over scenario and year coordinates, allowing numeric, textual, or blank cells.
        dsa_pub_exchange_rate_lc_per_us_dollar: Local-currency-per-US-dollar exchange-rate series aligned to the same scenario and year coordinates, used to convert external debt into US dollars.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: End-of-period PV of public-sector external debt as a scenario-by-year data series, in the workbook's external-debt currency basis.
        leftover_exchange_rate_pa: Exchange-rate series applied to nominal GDP when expressing it in US dollars for the ratio denominator, aligned by scenario and year.
        input3_old_debt_service: Typed Input 3 old-debt-service dataclass validated against its schema and used for its TIME_PERIOD axis to bind the evaluation domain.

    Returns:
        A data.Series[float | str | None] of public-sector PV of debt-to-GDP values keyed by scenario and years from row 7, containing numeric ratios or source text/blanks.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])), 100))

    return data.DSA_PUB_PV_OF_DEBT_GDP.collect(evaluate(formula, data.DSA_PUB_PV_OF_DEBT_GDP.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_PV_OF_DEBT_GDP.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_PV_OF_DEBT_EXPORTS.schema, cells=data.DSA_PUB_PV_OF_DEBT_EXPORTS.cells)
def dsa_pub_pv_of_debt_exports(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], dsa_pub_exports_us_baseline: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the public-sector PV of external debt-to-exports ratio from exchange-rate, debt-stock, and baseline-export series.

    Derives the B2_PB_mkt_pub indicator series keyed by scenario and projection year for the public DSA output surface.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Typed data series of LC-per-USD exchange rates, indexed by scenario and time period.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: Typed data series of end-of-period public-sector external debt PV, indexed by scenario and time period.
        dsa_pub_exports_us_baseline: Typed data series of baseline exports in USD, indexed by scenario and time period.
        input3_old_debt_service: Typed input data collection whose TIME_PERIOD axis defines the projection-year domain used to evaluate the ratio.

    Returns:
        Typed data series of float, string, or None values containing PV of public debt over exports, keyed by scenario and years from row 7.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), dsa_pub_exports_us_baseline[scenario, time_period]), 100))

    return data.DSA_PUB_PV_OF_DEBT_EXPORTS.collect(evaluate(formula, data.DSA_PUB_PV_OF_DEBT_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_PV_OF_DEBT_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_DEBT_SERVICE_EXPORTS.schema, cells=data.DSA_PUB_DEBT_SERVICE_EXPORTS.cells)
def dsa_pub_debt_service_exports(*, dsa_pub_exports_us_baseline: data.Series[float | str | None], macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], pv_resfin_pub_output_total_debt_service_in_usd: data.Series[float | str | None], pv_resfin_add_output_interest: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the public debt service-to-exports ratio series from interest, scheduled debt service, and baseline export series.

    Produces the DSA public debt service/exports output (B2_PB_mkt_pub) over the scenario and time-period coordinates defined by the old debt service input.

    Args:
        dsa_pub_exports_us_baseline: Baseline public exports in USD as a scenario- and time-indexed series; supplies the denominator for the debt service ratio.
        macro_debt_ppg_interest_due: Macro-debt PPG interest due as a time-indexed scalar-valued series in USD; contributes to the numerator across scenarios.
        macro_debt_main_assumptions_us_dollars_by_year_6: Macro-debt main assumptions in USD by year 6 as a time-indexed series; adds scheduled debt service to the numerator.
        pv_resfin_pub_output_total_debt_service_in_usd: Residual-financing public output total debt service in USD as a multi-coordinate series; contributes external PPG medium- and long-term debt service for scenario-specific stress paths.
        pv_resfin_add_output_interest: Residual-financing additional output interest as a multi-coordinate series; contributes market-access interest in the B2_mkt scenario.
        input3_input_3_macro_current_account: Validated Input 3 macro current account dataclass; provides the macro current-account input context for the calculation.
        input3_old_debt_service: Input 3 old debt service dataclass whose TIME_PERIOD axis and domain define the output evaluation grid and scenario/time binding.

    Returns:
        A data.Series[float | str | None] of debt service-to-exports ratios keyed by scenario and TIME_PERIOD years from row 7, using the coordinate domain bound from the old debt service input.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_exports_us_baseline[scenario, time_period]), 100))
        elif scenario == 'B2_mkt' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_div(xl_add(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), pv_resfin_add_output_interest['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), dsa_pub_exports_us_baseline[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Tailored Stress Test 1: Contingent Liability Shock', time_period]), dsa_pub_exports_us_baseline[scenario, time_period]), 100))

    return data.DSA_PUB_DEBT_SERVICE_EXPORTS.collect(evaluate(formula, data.DSA_PUB_DEBT_SERVICE_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_DEBT_SERVICE_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.schema, cells=data.DSA_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.cells)
def dsa_pub_debt_service_revenue_excl_grants(*, dsa_pub_revenue: data.Series[float | str | None], macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_national_currency_us_dollars: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], pv_resfin_pub_output_total_debt_service_in_usd: data.Series[float | str | None], pv_resfin_add_output_interest: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the public debt service-to-revenue ratio excluding grants (B2_PB_mkt_pub) across scenarios and projection years.

    Combine interest, principal, debt-service, and revenue series under scenario-specific branches to produce the Chart Data debt service-to-revenue indicator.

    Args:
        dsa_pub_revenue: Public revenue series used as the ratio denominator, keyed by scenario and time period; values are floats, strings, or None.
        macro_debt_ppg_interest_due: PPG interest due series from the macro-debt block, aligned to time period; values are floats, strings, or None.
        macro_debt_national_currency_us_dollars: National-currency-to-US-dollar conversion series used as the denominator in the B2_mkt first-period branch; values are floats, strings, or None.
        macro_debt_main_assumptions_us_dollars_by_year_6: Macro-debt main assumptions in US dollars by year 6, added to interest due in the numerator; values are floats, strings, or None.
        pv_resfin_pub_output_total_debt_service_in_usd: PV/resfin public output total debt service in USD, indexed by debt type and scenario, contributing to projected-period numerators; values are floats, strings, or None.
        pv_resfin_add_output_interest: PV/resfin additional output interest series, indexed by debt type and scenario, included in the B2_mkt projected numerator; values are floats, strings, or None.
        input3_input_3_macro_current_account: Typed dataclass of Input 3 macro current-account series, validated against its schema before evaluation.
        input3_old_debt_service: Typed dataclass of Input 3 old debt service series; supplies the TIME_PERIOD axis used to bind and evaluate the output.

    Returns:
        data.Series[float | str | None] of the debt service-to-revenue ratio excluding grants (B2_PB_mkt_pub), keyed by scenario and years from row 7.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B2_mkt' and _p_time_period == 0:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), macro_debt_national_currency_us_dollars[time_period]), 100))
        elif scenario == 'C1' and _p_time_period == 0:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_revenue[scenario, time_period]), 100))
        elif scenario == 'B2_mkt' and _p_time_period >= 1:
            return as_measure(xl_mul(xl_div(xl_add(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), pv_resfin_add_output_interest['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), dsa_pub_revenue[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Tailored Stress Test 1: Contingent Liability Shock', time_period]), dsa_pub_revenue[scenario, time_period]), 100))

    return data.DSA_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.collect(evaluate(formula, data.DSA_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_EXPORTS_US_BASELINE.schema, cells=data.DSA_PUB_EXPORTS_US_BASELINE.cells)
def dsa_pub_exports_us_baseline(*, macro_debt_exports_of_goods_services: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes the baseline public exports of goods and services series in US dollars for the LIC-DSF scenario grid.

    Provides the baseline exports path used to scale public-debt stress indicators over projection years.

    Args:
        macro_debt_exports_of_goods_services: A named-axis data.Series[float | str | None] covering exports of goods and services in US$, aligned to scenario and TIME_PERIOD coordinates and sourced from the baseline B2_PB_mkt_pub row.
        input3_input_3_macro_current_account: A typed data.Input3Input3MacroCurrentAccount input series bundle providing Input 3 macro current-account projections and coordinate schema validation for the calculation.
        input3_old_debt_service: A typed data.Input3OldDebtService input series bundle providing Input 3 old debt-service data; its TIME_PERIOD axis supplies the projection coordinate alignment for the returned baseline series.

    Returns:
        A data.Series[float | str | None] keyed by scenario and TIME_PERIOD containing baseline public exports in US$, preserving string or blank values where present in the source series.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(macro_debt_exports_of_goods_services[time_period])

    return data.DSA_PUB_EXPORTS_US_BASELINE.collect(evaluate(formula, data.DSA_PUB_EXPORTS_US_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_EXPORTS_US_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_REVENUE.schema, cells=data.DSA_PUB_REVENUE.cells)
def dsa_pub_revenue(*, dsa_pub_revenue_and_grants: data.Series[float | str | None], dsa_pub_of_which_grants: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], leftover_exchange_rate_pa: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derive public revenue from grants-inclusive public revenue, grants, nominal GDP, and the exchange rate.

    Computes the DSA public revenue series used when evaluating fiscal (total public debt) risk, converting the grant-free revenue share of GDP into local-currency revenue terms.

    Args:
        dsa_pub_revenue_and_grants: Named-axis series of public revenue and grants (B2_PB_mkt_pub), keyed by scenario and projection year from row 7; may carry blanks or template text.
        dsa_pub_of_which_grants: Named-axis series of the grants component of public revenue, keyed by scenario and projection year; subtracted from the grants-inclusive total.
        dsa_pub_nominal_gdp_local_currency: Named-axis series of nominal GDP in local currency, keyed by scenario and projection year; used as the numerator of the revenue ratio.
        leftover_exchange_rate_pa: Named-axis series of the period-average exchange rate, keyed by scenario and projection year; divides nominal GDP to express the ratio in foreign-currency terms.
        input3_old_debt_service: Typed input bundle providing the old debt service grid whose TIME_PERIOD domain fixes the scenario-year coordinates the output series is bound to.

    Returns:
        Named-axis series of public revenue (B2_PB_mkt_pub) as a float or string-or-None numerator, keyed by scenario and years from row 7, aligned to the TIME_PERIOD domain of the old debt service input.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(xl_sub(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_of_which_grants[scenario, time_period]), 100), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])))

    return data.DSA_PUB_REVENUE.collect(evaluate(formula, data.DSA_PUB_REVENUE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_REVENUE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_GDP.schema, cells=data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_GDP.cells)
def dsa_pub_b2_pb_non_mkt_pub_pv_of_debt_gdp(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], leftover_exchange_rate_pa: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes the non-market public-sector PV of debt-to-GDP ratio for the public DSA.

    Derives the B2_PB_non_mkt_pub PV-of-debt-to-GDP series by converting end-of-period external public debt into local-currency GDP terms and expressing it as a percentage.

    Args:
        dsa_pub_nominal_gdp_local_currency: Scenario- and year-keyed series of nominal GDP in local currency.
        dsa_pub_exchange_rate_lc_per_us_dollar: Scenario- and year-keyed series of the exchange rate in local currency per U.S. dollar.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: Scenario- and year-keyed series of the end-of-period present value of public-sector external debt.
        leftover_exchange_rate_pa: Scenario- and year-keyed series supplying the residual exchange-rate conversion used to scale nominal GDP.
        input3_old_debt_service: Typed input bundle whose validated TIME_PERIOD domain defines the scenario/year grid over which the ratio is evaluated.

    Returns:
        Scenario- and year-keyed series of PV of debt-to-GDP values for non-market public debt, aligned to the input's TIME_PERIOD domain.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])), 100))

    return data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_GDP.collect(evaluate(formula, data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_GDP.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_GDP.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_EXPORTS.schema, cells=data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_EXPORTS.cells)
def dsa_pub_b2_pb_non_mkt_pub_pv_of_debt_exports(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None], dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the non-market public-sector PV of debt-to-exports ratio (B2_PB_non_mkt_pub) across scenarios and years.

    Derive the PV of public-sector external debt as a share of exports by converting end-of-period debt into US dollars and dividing by baseline exports, with results keyed by scenario and TIME_PERIOD from row 7 onward.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Exchange rate in local currency per US dollar, as a scenario- and year-keyed data.Series whose cells are floats, strings, or None; supplies the conversion factor used to express PV debt in US dollars.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: PV of public-sector external debt at end of period, as a scenario- and year-keyed data.Series of floats, strings, or None; provides the numerator before conversion.
        dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline: Non-market public-sector exports (US dollar, baseline) as a scenario- and year-keyed data.Series of floats, strings, or None; supplies the denominator of the ratio.
        input3_old_debt_service: Old debt service input container whose domain defines the TIME_PERIOD axis (scenario and year coordinates) used to align and bound the resulting series.

    Returns:
        A scenario- and year-keyed data.Series of floats, strings, or None containing the non-market public-sector PV of debt-to-exports ratio (percent) aligned to the TIME_PERIOD domain carried by the debt-service input.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(xl_div(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]), dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline[scenario, time_period]), 100))

    return data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_EXPORTS.collect(evaluate(formula, data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_B2_PB_NON_MKT_PUB_PV_OF_DEBT_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_EXPORTS.schema, cells=data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_EXPORTS.cells)
def dsa_pub_b2_pb_non_mkt_pub_debt_service_exports(*, dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline: data.Series[float | str | None], macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], pv_resfin_pub_output_total_debt_service_in_usd: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the non-market public debt service-to-exports ratio (B2_PB_non_mkt_pub) as a scenario- and year-keyed series.

    Derive the debt service-to-exports indicator from PPG interest due, macro-debt assumptions, and baseline exports, with the Bounds Test 2 primary balance shock adjustment applied to non-market access countries.

    Args:
        dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline: Baseline non-market public exports in US dollars, as a named-axis data.Series[float | str | None] over scenario and time period.
        macro_debt_ppg_interest_due: PPG interest due from the Macro-Debt series, as a data.Series[float | str | None] over time periods.
        macro_debt_main_assumptions_us_dollars_by_year_6: Macro-Debt main assumptions in US dollars by year from row 6, as a data.Series[float | str | None] over time periods.
        pv_resfin_pub_output_total_debt_service_in_usd: Total public debt service in US dollars from the PV/residual-financing output, as a data.Series[float | str | None] indexed by debt category, scenario, and time period; the calculation selects external PPG medium- and long-term under Bounds Test 2.
        input3_input_3_macro_current_account: Input 3 macro current-account dataclass containing authored current-account assumptions, validated against its schema before evaluation.
        input3_old_debt_service: Input 3 old debt service dataclass whose TIME_PERIOD axis supplies the target year grid, validated against its schema before evaluation.

    Returns:
        A data.Series[float | str | None] of percentage debt service-to-exports ratios, keyed by scenario and projection years taken from row 7.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline[scenario, time_period]), 100))

    return data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_EXPORTS.collect(evaluate(formula, data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.schema, cells=data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.cells)
def dsa_pub_b2_pb_non_mkt_pub_debt_service_revenue_excl_grants(*, dsa_pub_b2_pb_non_mkt_pub_revenue: data.Series[float | str | None], macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], pv_resfin_pub_output_total_debt_service_in_usd: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the B2 primary-balance-shock non-market public debt service-to-revenue ratio excluding grants.

    Combines PPG interest due and main-assumption debt service, plus residual-financing debt service after the first projection year, and expresses the total as a percentage of non-market public revenue.

    Args:
        dsa_pub_b2_pb_non_mkt_pub_revenue: Non-market public revenue series keyed by scenario and year, used as the denominator of the debt service ratio.
        macro_debt_ppg_interest_due: PPG interest due series over projection years, added to the other debt service components in the numerator.
        macro_debt_main_assumptions_us_dollars_by_year_6: Main-assumptions debt service series in U.S. dollars by year, contributing to the numerator.
        pv_resfin_pub_output_total_debt_service_in_usd: Total public debt service in U.S. dollars keyed by creditor category and scenario, supplying the non-market access bounds-test component used after the first projection year.
        input3_input_3_macro_current_account: Structured macro current-account input group validated against the authored schema before formula evaluation.
        input3_old_debt_service: Old debt service input group whose TIME_PERIOD axis defines the projection-year domain and binding for the evaluated output.

    Returns:
        Series of debt service-to-revenue ratios expressed as percentages, keyed by scenario and projection year, with blanks or text preserved as float | str | None values.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_mul(xl_div(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), dsa_pub_b2_pb_non_mkt_pub_revenue[scenario, time_period]), 100))
        return as_measure(xl_mul(xl_div(xl_add(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), pv_resfin_pub_output_total_debt_service_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]), dsa_pub_b2_pb_non_mkt_pub_revenue[scenario, time_period]), 100))

    return data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.collect(evaluate(formula, data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_B2_PB_NON_MKT_PUB_DEBT_SERVICE_REVENUE_EXCL_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_B2_PB_NON_MKT_PUB_EXPORTS_US_BASELINE.schema, cells=data.DSA_PUB_B2_PB_NON_MKT_PUB_EXPORTS_US_BASELINE.cells)
def dsa_pub_b2_pb_non_mkt_pub_exports_us_baseline(*, macro_debt_exports_of_goods_services: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Build the baseline B2_PB non-market public exports (US$) series from macro-debt exports of goods and services.

    Project the baseline public external-debt export series onto the time grid supplied by the old debt-service input group.

    Args:
        macro_debt_exports_of_goods_services: Time-indexed series of exports of goods and services in US dollars, used as the source values for the baseline exports path.
        input3_input_3_macro_current_account: Macro current-account input group; validated against its schema before the baseline exports series is evaluated.
        input3_old_debt_service: Old debt-service input group whose TIME_PERIOD axis defines the projection years bound for the returned series.

    Returns:
        Data series of baseline non-market public exports in US dollars keyed by scenario and TIME_PERIOD, with float, string, or null values.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(macro_debt_exports_of_goods_services[time_period])

    return data.DSA_PUB_B2_PB_NON_MKT_PUB_EXPORTS_US_BASELINE.collect(evaluate(formula, data.DSA_PUB_B2_PB_NON_MKT_PUB_EXPORTS_US_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_B2_PB_NON_MKT_PUB_EXPORTS_US_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.DSA_PUB_B2_PB_NON_MKT_PUB_REVENUE.schema, cells=data.DSA_PUB_B2_PB_NON_MKT_PUB_REVENUE.cells)
def dsa_pub_b2_pb_non_mkt_pub_revenue(*, dsa_pub_revenue_and_grants: data.Series[float | str | None], dsa_pub_of_which_grants: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], leftover_exchange_rate_pa: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derive non-market public revenue (B2_PB_non_mkt_pub) as a scenario-keyed share of GDP.

    Convert revenue net of grants into a GDP-relative series by deflating nominal local-currency GDP with the period-average exchange rate.

    Args:
        dsa_pub_revenue_and_grants: Scenario-and-year keyed series of total public revenue and grants, in percent of GDP terms as carried on the row 7 projection grid.
        dsa_pub_of_which_grants: Scenario-and-year keyed series giving the grant component included in total revenue and grants, subtracted before the ratio is formed.
        dsa_pub_nominal_gdp_local_currency: Scenario-and-year keyed series of nominal GDP in local currency, the denominator basis before exchange-rate conversion.
        leftover_exchange_rate_pa: Scenario-and-year keyed series of the period-average exchange rate used to translate local-currency GDP into the reporting currency.
        input3_old_debt_service: Typed input-series dataclass whose coordinate axes (notably TIME_PERIOD) supply the evaluation domain and alignment for the computation.

    Returns:
        Scenario-and-year keyed series of non-market public revenue expressed relative to GDP, carrying float values with str or None passthrough for blanks and text cells.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(xl_sub(dsa_pub_revenue_and_grants[scenario, time_period], dsa_pub_of_which_grants[scenario, time_period]), 100), xl_div(dsa_pub_nominal_gdp_local_currency[scenario, time_period], leftover_exchange_rate_pa[scenario, time_period])))

    return data.DSA_PUB_B2_PB_NON_MKT_PUB_REVENUE.collect(evaluate(formula, data.DSA_PUB_B2_PB_NON_MKT_PUB_REVENUE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_B2_PB_NON_MKT_PUB_REVENUE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(key=('SCENARIO',), domain=None, cells=data.DSA_PUB_B2_PB_NON_MKT_PUB_STANDARD_TEST_PARAMETER_CELLS)
def dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter(*, in6opt_standard_b1_real_gdp_growth_historical_average_baseline_projection: str | int | float | bool, lookup_ida_terms_new: str, input6_standard_size_threshold_mode: Literal["New", "Old"], input6_standard_user_defined_threshold: data.Input6StandardUserDefinedThreshold) -> str | int | float | bool:
    """Select the Input 6 standard-test primary-balance shock size or the B1 baseline growth fallback according to the standard size threshold mode.

    Implements the new-vs-old standard-test primary-balance rule for the `B2_PB_non_mkt_pub` threshold parameter (workbook `B2_PB_non_mkt_pub!AA63`).

    Args:
        in6opt_standard_b1_real_gdp_growth_historical_average_baseline_projection: Scalar fallback value for the B1 real GDP growth historical-average baseline projection, returned when the size threshold mode does not match the IDA-terms-new lookup value.
        lookup_ida_terms_new: Scalar string identifier holding the IDA-terms-new lookup value compared against the standard size threshold mode.
        input6_standard_size_threshold_mode: Scalar literal selector indicating whether the standard size threshold rule uses `New` or `Old` IDA terms.
        input6_standard_user_defined_threshold: `data.Input6StandardUserDefinedThreshold` series over catalog coordinates, carrying the Input 6 standard user-defined threshold values keyed by primary-balance measure, shock dimension, and size coordinate; validated before indexing.

    Returns:
        Scalar `str | int | float | bool`; the selected Input 6 standard user-defined threshold size, the B1 baseline growth fallback value, or an `XlError` code string on failure.
    """
    data.INPUT6_STANDARD_USER_DEFINED_THRESHOLD.schema.validate(input6_standard_user_defined_threshold)
    try:
        return as_measure((input6_standard_user_defined_threshold['B2. Primary balance', 'Size of PB/GDP shock, # of standard deviations', 'Size'] if xl_bool(xl_eq(input6_standard_size_threshold_mode, lookup_ida_terms_new)) else in6opt_standard_b1_real_gdp_growth_historical_average_baseline_projection), 'str')
    except XlError as error:
        return error.code

@publish(data.DSA_PUB_B5_DEPRECIATION_PUB_NOMINAL_APPRECIATION_INCREASE_IN_US_DOLLAR_VALUE_OF_LOCAL_CURRENCY_IN_PERCENT.schema, cells=data.DSA_PUB_B5_DEPRECIATION_PUB_NOMINAL_APPRECIATION_INCREASE_IN_US_DOLLAR_VALUE_OF_LOCAL_CURRENCY_IN_PERCENT.cells)
def dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent(*, dsa_pub_b5_depreciation_pub_standard_test_fx_depreciation: float | str, baseline_pub_nominal_appreciation_increase_in_us_dollar: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derive the public DSA B5 nominal local-currency appreciation series from standard-test FX depreciation and baseline appreciation.

    Build the B5 depreciation block's nominal appreciation path by negating standard-test FX depreciation in the first period and using baseline appreciation thereafter.

    Args:
        dsa_pub_b5_depreciation_pub_standard_test_fx_depreciation: Scalar float or string standard-test FX depreciation applied to the initial projection period and negated to express appreciation in percent.
        baseline_pub_nominal_appreciation_increase_in_us_dollar: Typed float, string, or null data series of baseline nominal appreciation in the US dollar value of the local currency, in percent, keyed by scenario and time; supplies values after the first period.
        input3_old_debt_service: Typed `data.Input3OldDebtService` input providing the old debt-service schema and TIME_PERIOD axis used to align and validate scenario periods.

    Returns:
        A typed `data.Series[float | str | None]` of nominal appreciation, expressed as the increase in the US dollar value of the local currency in percent, keyed by scenario and TIME_PERIOD; the first period equals the negated standard-test depreciation and later periods come from the baseline series.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 1:
            return as_measure(xl_neg(dsa_pub_b5_depreciation_pub_standard_test_fx_depreciation))
        return as_measure(baseline_pub_nominal_appreciation_increase_in_us_dollar[time_period])

    return data.DSA_PUB_B5_DEPRECIATION_PUB_NOMINAL_APPRECIATION_INCREASE_IN_US_DOLLAR_VALUE_OF_LOCAL_CURRENCY_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_B5_DEPRECIATION_PUB_NOMINAL_APPRECIATION_INCREASE_IN_US_DOLLAR_VALUE_OF_LOCAL_CURRENCY_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_B5_DEPRECIATION_PUB_NOMINAL_APPRECIATION_INCREASE_IN_US_DOLLAR_VALUE_OF_LOCAL_CURRENCY_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service))

