@publish(data.INPUT5_PROJECTION_YEARS.schema, cells=data.INPUT5_PROJECTION_YEARS.cells)
def input5_projection_years(*, macro_debt_data: int | str, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[int | str | None]:
    """Derive the Input 5 projection-year series over the macro current-account time axis.

    Builds a TIME_PERIOD-aligned projection-year sequence for Input 5 row 5, seeding the pivot period from a scalar anchor and stepping year values forward and backward from it.

    Args:
        macro_debt_data: Scalar anchor value (integer or string) assigned at the pivot time period of the projection-year sequence.
        input3_input_3_macro_current_account: Typed Input 3 macro current-account series whose validated TIME_PERIOD axis defines the output coordinates and alignment.

    Returns:
        A typed TIME_PERIOD-indexed series of projection-year values (int, str, or None), including the pre-projection year.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 12:
            return as_measure(xl_sub(input5_projection_years[axis_step(_ax_time_period, time_period, 1)], 1), 'int')
        elif _p_time_period == 13:
            return as_measure(macro_debt_data, 'int')
        return as_measure(xl_add(input5_projection_years[axis_step(_ax_time_period, time_period, -1)], 1), 'int')

    input5_projection_years = CoordinateReader('input5_projection_years', data.INPUT5_PROJECTION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.INPUT5_PROJECTION_YEARS.collect(((coord, input5_projection_years[coord]) for coord in data.INPUT5_PROJECTION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.INPUT5_PROJECTION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

