@publish(key=(), domain=None, cells=data.INPUT5_INSTRUMENT_TERMS_GRACE_PERIOD_HEADER_CELLS)
def input5_instrument_terms_grace_period_header(*, input4_grace_period_column_header: str | int | float | bool) -> str | int | float | bool:
    """Return the Input 5 grace-period column header derived from the Input 4 header.

    Normalizes the grace-period column header copied from Input 4 into the scalar form expected by the Input 5 instrument-terms layout.

    Args:
        input4_grace_period_column_header: Grace-period column header copied from Input 4; accepts text or scalar numeric and boolean values and is coerced to text.

    Returns:
        The normalized header as a string, or the Excel error code string if normalization fails; numeric and boolean inputs are represented according to the declared scalar return union.
    """
    try:
        return as_measure(input4_grace_period_column_header, 'str')
    except XlError as error:
        return error.code

