@publish(data.INPUT5_PUBLIC_GFNS_3_DEBT_SERVICES_FROM_NEW_DEBT_OW_IMF.schema, cells=data.INPUT5_PUBLIC_GFNS_3_DEBT_SERVICES_FROM_NEW_DEBT_OW_IMF.cells)
def input5_public_gfns_3_debt_services_from_new_debt_ow_imf(*, input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None], ext_debt_new_interest_external: data.Series[float | str | None], ext_debt_new_amortization_external: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute Input 5 public GFN debt service from new debt, of which IMF.

    Derives the projection-year series of debt service owed to the IMF on new external debt by converting IMF interest plus amortization from USD into local currency at the average nominal exchange rate.

    Args:
        input5_macro_nominal_exchange_rate_average_lcu_usd: Average nominal exchange rate in local currency per USD, a data.Series[float | str | None] over projection-year coordinates used to convert the IMF debt-service amounts into local currency.
        ext_debt_new_interest_external: Interest on new external debt owed to the IMF, a data.Series[float | str | None] over projection years whose IMF slice is summed with amortization before conversion.
        ext_debt_new_amortization_external: Amortization of new external debt owed to the IMF, a data.Series[float | str | None] over projection years whose IMF slice is summed with interest before conversion.
        input3_old_debt_service: Existing debt service on old debt, a data.Input3OldDebtService whose TIME_PERIOD axis supplies the projection-year grid on which the output series is evaluated.

    Returns:
        A data.Series[float | str | None] keyed by projection years giving debt service from new debt owed to the IMF in local currency, aligned to the old-debt-service time axis.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
