@publish(data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_ST_DISBURSEMENTS_RESIDENCY_BASED.schema, cells=data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_ST_DISBURSEMENTS_RESIDENCY_BASED.cells)
def input5_disbursements_public_domestic_st_disbursements_residency_based(*, input5_maturity_central_bank: int | str, input5_new_issuance: data.Series[float | str | None], input5_new_issuance_short_term_debt: data.Series[float | str | None], input5_new_issuance_domestic_residual_financing_to_close_gap: data.Series[float | str | None], input5_definition_of_external_domestic_debt: str | int | float | bool, lookup_afg: str | int | float | bool, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute public domestic short-term disbursements on the residency basis for Input 5.

    Combine selected new-issuance components and residual financing into the public domestic short-term disbursement path under the chosen debt-definition branch.

    Args:
        input5_maturity_central_bank: Scalar central-bank maturity switch; central-bank financing is included when it equals 1.
        input5_new_issuance: Typed new-issuance series over instrument, residency, and projection years, supplying central-bank financing and local-currency T-bill entries.
        input5_new_issuance_short_term_debt: Typed short-term-debt new-issuance series over residency and projection years, used for the residents aggregate in the alternate branch.
        input5_new_issuance_domestic_residual_financing_to_close_gap: Typed domestic residual-financing series over projection years, added to close the financing gap.
        input5_definition_of_external_domestic_debt: Scalar definition selector for external versus domestic debt, compared with the lookup code to choose the issuance branch.
        lookup_afg: Scalar lookup code compared with the debt-definition selector to determine the applicable branch.
        input3_old_debt_service: Typed Input 3 old debt service object whose TIME_PERIOD axis defines the projection-year grid.

    Returns:
        Typed series of public domestic short-term disbursements by residency, keyed by projection years, with numeric, text, or missing values.
    """
