@publish(key=('INSTRUMENT',), domain=None, cells=data.INPUT5_RESIDUAL_TERMS_AVERAGE_MATURITY_OF_NEW_DEBT_ROUNDED_AVERAGE_CELLS)
def input5_residual_terms_average_maturity_of_new_debt_rounded_average(*, input5_residual_terms_average_grace_period_on_new_debt_rounded_average: int | str, input5_residual_terms_average_maturity_of_new_debt_average: float | str) -> int | str:
    """Compute the rounded average maturity of new debt for Input 5 residual terms.

    Derives the domestic MLT new-debt maturity used by the LIC-DSF template by applying the grace-period floor to the rounded maturity average.

    Args:
        input5_residual_terms_average_grace_period_on_new_debt_rounded_average: Rounded average grace period on new debt, as an integer scalar or an error-code string.
        input5_residual_terms_average_maturity_of_new_debt_average: Average maturity of new debt, as a floating-point scalar or an error-code string.

    Returns:
        Rounded-down maximum of the average maturity and one plus the rounded grace period, as an integer scalar or a workbook error-code string.
    """
    try:
        return as_measure(xl_max(xl_rounddown(input5_residual_terms_average_maturity_of_new_debt_average, 0), xl_add(input5_residual_terms_average_grace_period_on_new_debt_rounded_average, 1)), 'int')
    except XlError as error:
        return error.code

@publish(data.INPUT5_OLD_DEBT_DEBT_SERVICE_FROM_OLD_DEBT_RESIDENCY_BASED.schema, cells=data.INPUT5_OLD_DEBT_DEBT_SERVICE_FROM_OLD_DEBT_RESIDENCY_BASED.cells)
def input5_old_debt_debt_service_from_old_debt_residency_based(*, input5_old_debt_interest_payment_on_old_debt_residency_based: data.Series[float | str | None], input5_old_debt_principal_payment_on_old_debt_residency_based: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute Input 5 residency-based debt service on old debt as the year-by-year sum of old-debt interest and principal payments.

    Derives the residency-based old-debt service series on the Input 5 time grid so it can feed downstream debt-service and DSA calculations.

    Args:
        input5_old_debt_interest_payment_on_old_debt_residency_based: Residency-based interest payments on old debt, as a named-axis series over catalog coordinates that carries float values, text markers, or blanks per projection year.
        input5_old_debt_principal_payment_on_old_debt_residency_based: Residency-based principal payments on old debt, as a named-axis series over catalog coordinates that carries float values, text markers, or blanks per projection year.
        input3_old_debt_service: Old-debt service series from Input 3 whose TIME_PERIOD axis defines the projection-year coordinates the result is evaluated and collected over.

    Returns:
        A float-or-str-or-None series of residency-based debt service on old debt, indexed by the projection years taken from the Input 3 old-debt service coordinates, with per-year interest plus principal and blanks or text propagated unchanged.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(input5_old_debt_interest_payment_on_old_debt_residency_based[time_period], input5_old_debt_principal_payment_on_old_debt_residency_based[time_period]))

    return data.INPUT5_OLD_DEBT_DEBT_SERVICE_FROM_OLD_DEBT_RESIDENCY_BASED.collect(evaluate(formula, data.INPUT5_OLD_DEBT_DEBT_SERVICE_FROM_OLD_DEBT_RESIDENCY_BASED.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.INPUT5_OLD_DEBT_DEBT_SERVICE_FROM_OLD_DEBT_RESIDENCY_BASED.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.schema, cells=data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.cells)
def input5_old_debt_interest_payment_on_old_debt_residency_based(*, input5_definition_of_external_domestic_debt: str | int | float | bool, input5_old_debt_interest_payment_on_old_debt_denominated_in_local_currency: data.Series[float | str | None], input5_old_debt_interest_payment_on_old_debt_denominated_in_foreign_currency: data.Series[float | str | None], lookup_afg: str | int | float | bool, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute residency-based interest payments on OLD debt from local- and foreign-currency Input 5 series.

    Derive the Input 5 old-debt interest series used downstream in old-debt service and DSA projections, adding foreign-currency residents interest only when the debt definition matches the lookup code.

    Args:
        input5_definition_of_external_domestic_debt: Scalar flag or code giving the external versus domestic debt definition for the projection, compared against the lookup value to decide whether foreign-currency interest is included.
        input5_old_debt_interest_payment_on_old_debt_denominated_in_local_currency: Typed series of interest payments on OLD debt denominated in local currency, indexed by projection year and catalog coordinates; its residents slice is consumed here.
        input5_old_debt_interest_payment_on_old_debt_denominated_in_foreign_currency: Typed series of interest payments on OLD debt denominated in foreign currency, indexed by projection year; its residents slice is added when the debt definition matches the lookup.
        lookup_afg: Scalar lookup code compared with the debt-definition flag; equality triggers summing the local- and foreign-currency residents interest payments.
        input3_old_debt_service: Typed dataclass of Input 3 old-debt service series whose TIME_PERIOD axis supplies the projection-year grid and coordinates used to evaluate and align the result.

    Returns:
        Typed series of interest payments on OLD debt on a residency basis, keyed by projection years over the Input 3 old-debt service time axis.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_add(input5_old_debt_interest_payment_on_old_debt_denominated_in_local_currency['residents', time_period], input5_old_debt_interest_payment_on_old_debt_denominated_in_foreign_currency['residents', time_period]) if xl_bool(xl_eq(input5_definition_of_external_domestic_debt, lookup_afg)) else input5_old_debt_interest_payment_on_old_debt_denominated_in_local_currency['residents', time_period]))

    return data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.collect(evaluate(formula, data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_LOCAL_CURRENCY.schema, cells=data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_LOCAL_CURRENCY.cells)
def input5_old_debt_interest_payment_on_old_debt_denominated_in_local_currency(*, input3_domestic_interest_payment_from_existing_debt: data.Input3DomesticInterestPaymentFromExistingDebt, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Interest payment on old debt denominated in local currency, split by holder.

    Derives the local-currency interest payment on old debt for residents and non-residents from domestic interest payments on existing debt, zeroing non-numeric cells.

    Args:
        input3_domestic_interest_payment_from_existing_debt: Domestic interest payment from existing debt series over local-currency holder and time coordinates; supplies the per-holder local-currency interest amounts, with non-numeric entries treated as zero.
        input3_input_3_macro_current_account: Macro current account series whose time coordinate binds the domestic interest payment series schema, aligning the domestic interest payment data to the applicable TIME_PERIOD axis.
        input3_old_debt_service: Old debt service series whose TIME_PERIOD axis defines the output domain over which the per-holder formula is evaluated.

    Returns:
        data.Series[float | str | None] keyed by holder (residents, non-residents) and time period, holding the local-currency interest payment on old debt or 0 where the source value is non-numeric.
    """
    data.INPUT3_DOMESTIC_INTEREST_PAYMENT_FROM_EXISTING_DEBT.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_domestic_interest_payment_from_existing_debt)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(holder: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if holder == 'residents':
            return as_measure((input3_domestic_interest_payment_from_existing_debt['local', 'residents', time_period] if xl_bool(xl_isnumber(lambda: input3_domestic_interest_payment_from_existing_debt['local', 'residents', time_period])) else 0))
        return as_measure((input3_domestic_interest_payment_from_existing_debt['local', 'non-residents', time_period] if xl_bool(xl_isnumber(lambda: input3_domestic_interest_payment_from_existing_debt['local', 'non-residents', time_period])) else 0))

    return data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_LOCAL_CURRENCY.collect(evaluate(formula, data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_LOCAL_CURRENCY.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_LOCAL_CURRENCY.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_FOREIGN_CURRENCY.schema, cells=data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_FOREIGN_CURRENCY.cells)
def input5_old_debt_interest_payment_on_old_debt_denominated_in_foreign_currency(*, input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None], input3_domestic_interest_payment_from_existing_debt: data.Input3DomesticInterestPaymentFromExistingDebt, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute interest payments on old foreign-currency debt in local currency units, split by holder.

    Convert foreign-currency interest payments on existing old debt into LCU using the average nominal exchange rate, preserving the residents versus non-residents breakdown.

    Args:
        input5_macro_nominal_exchange_rate_average_lcu_usd: Typed time-series of the average nominal exchange rate in LCU per USD, used to convert foreign-currency interest amounts into local currency units.
        input3_domestic_interest_payment_from_existing_debt: Typed series of domestic interest payments on existing debt, indexed by holder and time period, supplying the foreign-currency interest amounts that are converted and returned as zero when non-numeric.
        input3_input_3_macro_current_account: Typed macro current-account series whose time coordinate is bound onto the domestic interest-payment schema to align the input series before evaluation.
        input3_old_debt_service: Typed old-debt-service series whose time-period domain defines the evaluation grid and coordinate positions for the computed output.

    Returns:
        A typed series of LCU interest payments on old foreign-currency debt, indexed by holder and time period, with non-numeric source amounts yielding zero.
    """
    data.INPUT3_DOMESTIC_INTEREST_PAYMENT_FROM_EXISTING_DEBT.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_domestic_interest_payment_from_existing_debt)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(holder: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if holder == 'residents':
            return as_measure((xl_mul(input3_domestic_interest_payment_from_existing_debt['foreign', 'residents', time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]) if xl_bool(xl_isnumber(lambda: input3_domestic_interest_payment_from_existing_debt['foreign', 'residents', time_period])) else 0))
        return as_measure((xl_mul(input3_domestic_interest_payment_from_existing_debt['foreign', 'non-residents', time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]) if xl_bool(xl_isnumber(lambda: input3_domestic_interest_payment_from_existing_debt['foreign', 'non-residents', time_period])) else 0))

    return data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_FOREIGN_CURRENCY.collect(evaluate(formula, data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_FOREIGN_CURRENCY.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_FOREIGN_CURRENCY.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.INPUT5_OLD_DEBT_PRINCIPAL_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.schema, cells=data.INPUT5_OLD_DEBT_PRINCIPAL_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.cells)
def input5_old_debt_principal_payment_on_old_debt_residency_based(*, input5_definition_of_external_domestic_debt: str | int | float | bool, input5_old_debt_principal_payments_on_old_debt_denominated_in_local_currency: data.Series[float | str | None], input5_old_debt_principal_payments_on_old_debt_denominated_in_foreign_currency: data.Series[float | str | None], lookup_afg: str | int | float | bool, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute residency-based old-debt principal payments on Input 5.

    Derives the residency-based principal-payment series by summing resident local- and foreign-currency payments when the debt-definition selector matches the lookup value, otherwise retaining local-currency payments only.

    Args:
        input5_definition_of_external_domestic_debt: Scalar selector for the external/domestic debt definition used in the comparison.
        input5_old_debt_principal_payments_on_old_debt_denominated_in_local_currency: Typed data.Series[float | str | None] of old-debt principal payments denominated in local currency, indexed by projection years and residency.
        input5_old_debt_principal_payments_on_old_debt_denominated_in_foreign_currency: Typed data.Series[float | str | None] of old-debt principal payments denominated in foreign currency, indexed by projection years and residency.
        lookup_afg: Scalar lookup value compared with the debt-definition selector to determine whether resident foreign-currency payments are included.
        input3_old_debt_service: Typed data.Input3OldDebtService container whose TIME_PERIOD domain supplies the projection-year grid for evaluation.

    Returns:
        A typed data.Series[float | str | None] of residency-based old-debt principal payments keyed by projection years.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_add(input5_old_debt_principal_payments_on_old_debt_denominated_in_local_currency['residents', time_period], input5_old_debt_principal_payments_on_old_debt_denominated_in_foreign_currency['residents', time_period]) if xl_bool(xl_eq(input5_definition_of_external_domestic_debt, lookup_afg)) else input5_old_debt_principal_payments_on_old_debt_denominated_in_local_currency['residents', time_period]))

    return data.INPUT5_OLD_DEBT_PRINCIPAL_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.collect(evaluate(formula, data.INPUT5_OLD_DEBT_PRINCIPAL_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.INPUT5_OLD_DEBT_PRINCIPAL_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.required.bind(TIME_PERIOD=input3_old_debt_service))

