@publish(data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY.schema, cells=data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY.cells)
def input5_old_debt_outstanding_from_old_debt_in_foreign_currency(*, input5_macro_nominal_exchange_rate_end_of_period_lcu_usd: data.Series[float | str | None], input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Convert old external debt outstanding in foreign currency from USD to local currency.

    Multiply each holder's USD-denominated old foreign-currency debt by the end-of-period LCU/USD exchange rate over the TIME_PERIOD grid supplied by the current-account input.

    Args:
        input5_macro_nominal_exchange_rate_end_of_period_lcu_usd: End-of-period nominal exchange rate in LCU per USD, as a scalar-valued data.Series over TIME_PERIOD.
        input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd: Old debt outstanding in foreign currency denominated in USD, as a scalar-valued data.Series indexed by holder (residents, non-residents) and TIME_PERIOD.
        input3_input_3_macro_current_account: Macro current-account input dataclass whose TIME_PERIOD axis defines the evaluation grid for the conversion.

    Returns:
        data.Series[float | str | None] of old foreign-currency debt outstanding expressed in LCU, indexed by holder and TIME_PERIOD, preserving source blanks and text values.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(holder: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if holder == 'residents':
            return as_measure(xl_mul(input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd['residents', time_period], input5_macro_nominal_exchange_rate_end_of_period_lcu_usd[time_period]))
        return as_measure(xl_mul(input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd['non-residents', time_period], input5_macro_nominal_exchange_rate_end_of_period_lcu_usd[time_period]))

    return data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY.collect(evaluate(formula, data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY_USD.schema, cells=data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY_USD.cells)
def input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd(*, input5_old_debt_principal_payments_on_old_debt_denominated_in_foreign_currency_usd: data.Series[float | str | None], input3_domestic_outstanding_of_existing_debt: data.Input3DomesticOutstandingOfExistingDebt, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derive outstanding old debt in foreign currency (USD) by holder and period by rolling prior balances forward and subtracting principal payments.

    Compute the input5 old-debt outstanding series from domestic outstanding, the macro current-account time grid, and old-debt service inputs.

    Args:
        input5_old_debt_principal_payments_on_old_debt_denominated_in_foreign_currency_usd: Foreign-currency (USD) principal payments on old debt, as a series of floats or missing values indexed by holder and time period.
        input3_domestic_outstanding_of_existing_debt: Domestic outstanding of existing debt by holder, currency, and period; supplies the foreign-holder opening balance at the base period.
        input3_input_3_macro_current_account: Macro current-account series whose TIME_PERIOD axis defines the projection grid used to bind and validate all inputs.
        input3_old_debt_service: Old-debt service series validated against the input schema; provides consistency checks for the debt-service coordinate family.

    Returns:
        Series of outstanding old debt in foreign currency (USD) for residents and non-residents over the projection periods, with prior-period balances reduced by principal payments.
    """
    data.INPUT3_DOMESTIC_OUTSTANDING_OF_EXISTING_DEBT.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_domestic_outstanding_of_existing_debt)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(holder: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 12:
            return as_measure((input3_domestic_outstanding_of_existing_debt['foreign', holder, time_period] if xl_bool(xl_isnumber(lambda: input3_domestic_outstanding_of_existing_debt['foreign', holder, time_period])) else 0))
        elif _p_time_period == 13:
            return as_measure(xl_sub(input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd[holder, axis_step(_ax_time_period, time_period, -1)], input5_old_debt_principal_payments_on_old_debt_denominated_in_foreign_currency_usd[holder, time_period]))
        elif holder == 'residents' and _p_time_period >= 14:
            return as_measure(xl_sub(input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd['residents', axis_step(_ax_time_period, time_period, -1)], input5_old_debt_principal_payments_on_old_debt_denominated_in_foreign_currency_usd['residents', time_period]))
        return as_measure(xl_sub(input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd['non-residents', axis_step(_ax_time_period, time_period, -1)], input5_old_debt_principal_payments_on_old_debt_denominated_in_foreign_currency_usd['non-residents', time_period]))

    input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd = CoordinateReader('input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd', data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY_USD.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY_USD.collect(((coord, input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd[coord]) for coord in data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY_USD.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.INPUT5_OLD_DEBT_OUTSTANDING_FROM_OLD_DEBT_IN_FOREIGN_CURRENCY_USD.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

