def input5_new_debt_outstanding_of_new_debt_residency_based(*, input5_new_debt_debt_stock_on_new_debt_denominated_in_foreign_currency: data.Series[float | str | None], input5_definition_of_external_domestic_debt: str | int | float | bool, input5_new_debt_debt_stock_on_new_debt_denominated_in_local_currency: data.Series[float | str | None], lookup_afg: str | int | float | bool, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the residency-based outstanding stock of new debt by projection year.

    Combines residents' local- and foreign-currency new debt when the external/domestic debt definition matches the lookup flag, otherwise returns local-currency debt only.

    Args:
        input5_new_debt_debt_stock_on_new_debt_denominated_in_foreign_currency: New debt stock denominated in foreign currency for residents, as a typed data.Series over catalog coordinates with float, str, or None cells.
        input5_definition_of_external_domestic_debt: Scalar definition flag for external versus domestic debt, compared against the lookup value to decide whether foreign-currency debt is included.
        input5_new_debt_debt_stock_on_new_debt_denominated_in_local_currency: New debt stock denominated in local currency for residents, as a typed data.Series over catalog coordinates with float, str, or None cells.
        lookup_afg: Scalar lookup value used in the equality test against the external/domestic debt definition.
        input3_old_debt_service: Old debt service input bundle whose TIME_PERIOD axis supplies the projection-year domain used to evaluate and collect the result.

    Returns:
        A typed data.Series of float, str, or None giving the residency-based outstanding stock of new debt keyed by projection years.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_add(input5_new_debt_debt_stock_on_new_debt_denominated_in_local_currency['residents', time_period], input5_new_debt_debt_stock_on_new_debt_denominated_in_foreign_currency['residents', time_period]) if xl_bool(xl_eq(input5_definition_of_external_domestic_debt, lookup_afg)) else input5_new_debt_debt_stock_on_new_debt_denominated_in_local_currency['residents', time_period]))

    return data.INPUT5_NEW_DEBT_OUTSTANDING_OF_NEW_DEBT_RESIDENCY_BASED.collect(evaluate(formula, data.INPUT5_NEW_DEBT_OUTSTANDING_OF_NEW_DEBT_RESIDENCY_BASED.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.INPUT5_NEW_DEBT_OUTSTANDING_OF_NEW_DEBT_RESIDENCY_BASED.required.bind(TIME_PERIOD=input3_old_debt_service))

