@publish(data.INPUT5_SUMMARY_OUTSTANDING_STOCK.schema, cells=data.INPUT5_SUMMARY_OUTSTANDING_STOCK.cells)
def input5_summary_outstanding_stock(*, input5_old_debt_outstanding_of_old_debt_residency_based: data.Series[float | str | None], input5_new_debt_outstanding_of_new_debt_residency_based: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Sum old and new residency-based debt outstanding into the Input 5 summary stock series.

    Combines the old- and new-debt outstanding balances by projection year to produce the total outstanding stock reported on Input 5.

    Args:
        input5_old_debt_outstanding_of_old_debt_residency_based: Residency-based outstanding stock of old debt on Input 5, as a data.Series of floats (or str/None blanks) keyed by projection years.
        input5_new_debt_outstanding_of_new_debt_residency_based: Residency-based outstanding stock of new debt on Input 5, as a data.Series of floats (or str/None blanks) keyed by projection years.
        input3_old_debt_service: Old debt service Input 3 record whose TIME_PERIOD axis supplies the projection-year grid the summary series is evaluated over.

    Returns:
        data.Series[float | str | None] of total outstanding stock on Input 5, keyed by the projection years taken from the old debt service series.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(input5_new_debt_outstanding_of_new_debt_residency_based[time_period], input5_old_debt_outstanding_of_old_debt_residency_based[time_period]))

    return data.INPUT5_SUMMARY_OUTSTANDING_STOCK.collect(evaluate(formula, data.INPUT5_SUMMARY_OUTSTANDING_STOCK.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.INPUT5_SUMMARY_OUTSTANDING_STOCK.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.INPUT5_SUMMARY_MLT.schema, cells=data.INPUT5_SUMMARY_MLT.cells)
def input5_summary_mlt(*, input5_summary_outstanding_stock: data.Series[float | str | None], input5_summary_short_term: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derives the Input 5 medium-and-long-term (MLT) debt series by subtracting short-term debt from outstanding stock along the projection-year axis.

    Produces the MLT summary line reported on the Input 5 sheet, aligned to the debt-service projection calendar.

    Args:
        input5_summary_outstanding_stock: Outstanding-stock series from the Input 5 summary grid, indexed by projection years, with numeric, text, or blank entries as authored in the workbook.
        input5_summary_short_term: Short-term debt series on the same Input 5 summary grid and year coordinates, subtracted element-wise from the outstanding stock.
        input3_old_debt_service: Old debt-service input group whose TIME_PERIOD axis supplies the projection-year coordinate grid on which the result is evaluated and collected.

    Returns:
        A `data.Series[float | str | None]` of medium-and-long-term debt keyed by projection years, holding the outstanding-stock minus short-term difference per year, or a blank/text pass-through where an operand is non-numeric or missing.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_sub(input5_summary_outstanding_stock[time_period], input5_summary_short_term[time_period]))

    return data.INPUT5_SUMMARY_MLT.collect(evaluate(formula, data.INPUT5_SUMMARY_MLT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.INPUT5_SUMMARY_MLT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.INPUT5_SUMMARY_SHORT_TERM.schema, cells=data.INPUT5_SUMMARY_SHORT_TERM.cells)
def input5_summary_short_term(*, input5_maturity_central_bank: int | str, input5_new_issuance: data.Series[float | str | None], input5_new_issuance_short_term_debt: data.Series[float | str | None], input5_new_issuance_domestic_residual_financing_to_close_gap: data.Series[float | str | None], input5_definition_of_external_domestic_debt: str | int | float | bool, lookup_afg: str | int | float | bool, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Aggregate short-term new issuance on Input 5 into the summary short-term series.

    Combines central bank financing, short-term debt issuance, and domestic residual financing into a single projection-year series, switching the debt component on the external/domestic debt definition flag.

    Args:
        input5_maturity_central_bank: Scalar flag or label controlling whether central bank financing is included in the short-term total.
        input5_new_issuance: Typed data series of new issuance by creditor and residency coordinate, from which the central bank financing (and, in the domestic branch, local-currency T-bill) cells are drawn.
        input5_new_issuance_short_term_debt: Typed data series of short-term debt new issuance by residency coordinate, used for residents in the external-definition branch.
        input5_new_issuance_domestic_residual_financing_to_close_gap: Typed data series of domestic residual financing needed to close the gap, added to the total in both branches.
        input5_definition_of_external_domestic_debt: Scalar defining the external/domestic debt definition; when it equals the lookup value, the external branch is taken.
        lookup_afg: Scalar lookup value compared against the debt definition to select the external versus domestic aggregation branch.
        input3_old_debt_service: Typed old-debt-service dataclass whose TIME_PERIOD axis supplies the projection-year domain for evaluation and collection.

    Returns:
        Typed data series of short-term summary values over the projection-year TIME_PERIOD axis, aligned to the old-debt-service domain.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
