@publish(data.INPUT5_VINTAGE_INSTRUMENT_LABEL.schema, cells=data.INPUT5_VINTAGE_INSTRUMENT_LABEL.cells)
def input5_vintage_instrument_label(*, input5_instrument_titles: data.Series[str | int | float | bool | None]) -> data.Series[str | int | float | bool | None]:
    """Compute Input 5 vintage instrument labels.

    Propagate each bond instrument's title across resident holders and issuance years using the authored coordinate identities.

    Args:
        input5_instrument_titles: Keyword-only data.Series[str | int | float | bool | None] of instrument titles for the six input5.vintage_terms bond instruments (Bonds 1-3 years FX/LC, Bonds 4-7 years FX/LC, Bonds beyond 7 years FX/LC); values seed the 2024 vintage label.

    Returns:
        data.Series[str | int | float | bool | None] of vintage instrument labels over the required instrument, resident holder, and issuance-year coordinates; the 2024 issuance year uses the corresponding instrument title, while other years inherit the prior issuance year's label.
    """
    def formula(instrument: str, holder: str, issuance_year: int) -> str | int | float | bool | None:
        if issuance_year == 2024:
            return as_measure(input5_instrument_titles[instrument], 'str')
        return as_measure(input5_vintage_instrument_label[instrument, holder, issuance_year - 1], 'str')

    input5_vintage_instrument_label = CoordinateReader('input5_vintage_instrument_label', data.INPUT5_VINTAGE_INSTRUMENT_LABEL.required, formula)
    return data.INPUT5_VINTAGE_INSTRUMENT_LABEL.collect((coord, input5_vintage_instrument_label[coord]) for coord in data.INPUT5_VINTAGE_INSTRUMENT_LABEL.required)

@publish(data.A1_HIST_PUB_HISTORICAL_STATISTICS.schema, cells=data.A1_HIST_PUB_HISTORICAL_STATISTICS.cells)
def a1_hist_pub_historical_statistics(*, baseline_pub_inflation_rate_gdp_deflator_pct_al: float | str, baseline_pub_primary_deficit_by_indicator: data.Series[float | str | None], baseline_pub_real_gdp_growth_by_indicator: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute A1 historical public statistics from baseline inflation, primary deficit, and real GDP growth.

    Provide historical average and standard deviation inputs for the public debt A1 scenario.

    Args:
        baseline_pub_inflation_rate_gdp_deflator_pct_al: Scalar baseline public inflation rate (GDP deflator, percent) used when no indicator-specific historical value applies.
        baseline_pub_primary_deficit_by_indicator: Named-axis series of baseline public primary deficit by indicator; the Historical coordinate supplies the historical value.
        baseline_pub_real_gdp_growth_by_indicator: Named-axis series of baseline public real GDP growth by indicator; the Historical coordinate supplies the historical value.

    Returns:
        Named-axis series of historical average and standard deviation statistics for the A1 public indicators, with values as float, str, or None.
    """
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'Primary deficit':
            return as_measure(baseline_pub_primary_deficit_by_indicator['Historical'])
        elif indicator == 'Real GDP growth (in percent)':
            return as_measure(baseline_pub_real_gdp_growth_by_indicator['Historical'])
        return as_measure(baseline_pub_inflation_rate_gdp_deflator_pct_al)

    return data.A1_HIST_PUB_HISTORICAL_STATISTICS.collect(evaluate(formula, data.A1_HIST_PUB_HISTORICAL_STATISTICS.required))

@publish(key=(), domain=None, cells=data.BLEND_CALCULATED_BLEND_RATE_CELLS)
def blend_calculated_blend_rate(*, blend_ibrd_group_a_pricing: float | str, blend_sofr_selected_by_maturity: float | str) -> float | str:
    """Compute the uncapped blend floating rate.

    Calculate the blend rate by adding the selected SOFR swap and IBRD Group A pricing and subtracting 2.5%.

    Args:
        blend_ibrd_group_a_pricing: IBRD Group A pricing rate as a scalar float or an error string.
        blend_sofr_selected_by_maturity: Selected SOFR swap rate by maturity as a scalar float or an error string.

    Returns:
        The uncapped blend floating rate as a float, or an error string if the calculation fails.
    """
    try:
        return as_measure(xl_sub(xl_add(blend_sofr_selected_by_maturity, blend_ibrd_group_a_pricing), xl_div(2.5, 100)))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.BLEND_SOFR_SELECTED_BY_MATURITY_CELLS)
def blend_sofr_selected_by_maturity(*, blend_ida_new_floating_maturity: int | str, blend_interpolation_index: data.Series[int | str | None], blend_sofr_interpolated_rate: data.Series[float | str | None]) -> float | str:
    """Select the interpolated SOFR rate matching a floating-loan maturity.

    Look up the interpolated SOFR rate for the specified floating-loan maturity and return it or the lookup error code.

    Args:
        blend_ida_new_floating_maturity: Scalar floating-loan maturity, as an integer or string, used as the XLOOKUP key for selecting the interpolated SOFR rate.
        blend_interpolation_index: Named-axis data series of interpolation indices (integer, string, or missing) over time-period catalog coordinates, used as the lookup array for the maturity match.
        blend_sofr_interpolated_rate: Named-axis data series of interpolated SOFR rates (float, string, or missing) over tenor-axis catalog coordinates, used as the return array for the maturity lookup.

    Returns:
        Selected interpolated SOFR rate as a scalar float, or an Excel error code string if the lookup raises an error.
    """
    data.BLEND_INTERPOLATION_INDEX.schema.validate(blend_interpolation_index)
    _blend_sofr_selected_by_maturity_table_0 = view(blend_interpolation_index, rows=span(data.TIME_PERIOD_AXIS, 1, 30))
    _blend_sofr_selected_by_maturity_table_1 = view(blend_sofr_interpolated_rate, rows=data.TENOR_AXIS_2.keys)
    try:
        return as_measure(xl_xlookup(blend_ida_new_floating_maturity, _blend_sofr_selected_by_maturity_table_0, _blend_sofr_selected_by_maturity_table_1))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.BLEND_IDA_NEW_FLOATING_INTEREST_RATE_CELLS)
def blend_ida_new_floating_interest_rate(*, blend_calculated_blend_rate: float | str) -> float | str:
    """Returns the IDA new floating interest rate after applying the 0.75% floor and 5% ceiling.

    Clamp the calculated blend rate to the IDA new floating-rate corridor.

    Args:
        blend_calculated_blend_rate: Calculated blend rate as a scalar float or string; values below 0.75% use the floor, values above 5% use the ceiling, and values inside the corridor pass through.

    Returns:
        Clamped blend rate as a scalar float, or an error code string when evaluation fails.
    """
    try:
        return as_measure((xl_div(0.75, 100) if xl_bool(xl_le(blend_calculated_blend_rate, xl_div(0.75, 100))) else (xl_div(5, 100) if xl_bool(xl_ge(blend_calculated_blend_rate, xl_div(5, 100))) else blend_calculated_blend_rate)))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.BLEND_SELECTED_BASE_RATE_CELLS)
def blend_selected_base_rate(*, blend_ida_new_floating_currency: str, blend_reference_rate_currency: data.Series[str | None], blend_reference_rate_name: data.Series[str | None]) -> str | int | float | bool:
    """Resolve the blended IDA new floating base rate for a given currency.

    Look up the reference rate name associated with a blended IDA new floating currency from coordinate-indexed currency and rate-name series.

    Args:
        blend_ida_new_floating_currency: Scalar currency code for the blended IDA new floating currency whose base rate is being selected.
        blend_reference_rate_currency: Named-axis series of reference-rate currencies over catalog coordinates, used as the lookup table's currency column, including the USD to GBP row span.
        blend_reference_rate_name: Named-axis series of reference-rate names aligned to the currency series, supplying the base-rate name such as SOFR, EURIBOR, TONA, or SONIA returned by the lookup.

    Returns:
        Scalar result: normally the resolved base-rate name as a string, or an Excel error code when the lookup fails.
    """
    data.BLEND_REFERENCE_RATE_CURRENCY.schema.validate(blend_reference_rate_currency)
    data.BLEND_REFERENCE_RATE_NAME.schema.validate(blend_reference_rate_name)
    _blend_selected_base_rate_table_0 = view(blend_reference_rate_currency, rows=span(data.VARIANT_AXIS, 'USD', 'GBP'))
    _blend_selected_base_rate_table_1 = view(blend_reference_rate_name, rows=span(data.VARIANT_AXIS, 'USD', 'GBP'))
    try:
        return as_measure(xl_xlookup(blend_ida_new_floating_currency, _blend_selected_base_rate_table_0, _blend_selected_base_rate_table_1), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.BLEND_QUOTED_RATE_COLUMN_HEADER_CELLS)
def blend_quoted_rate_column_header(*, blend_selected_base_rate: str | int | float | bool) -> str | int | float | bool:
    """Build a quoted-rate column header from the selected base-rate name.

    Forms the rate-column header by concatenating the selected base-rate value with the literal " Swap rate".

    Args:
        blend_selected_base_rate: Selected base-rate identifier or scalar value used as the header prefix and concatenated with " Swap rate" to produce the column label.

    Returns:
        The resulting column header as a string, or the workbook error code as a scalar string/number when concatenation raises XlError.
    """
    try:
        return as_measure(xl_concat(blend_selected_base_rate, ' Swap rate'), 'str')
    except XlError as error:
        return error.code

@publish(data.BLEND_PUBLISHED_TENOR_YEARS.schema, cells=data.BLEND_PUBLISHED_TENOR_YEARS.cells)
def blend_published_tenor_years(*, blend_sofr_tenor_labels: data.Series[str | None]) -> data.Series[int | str | None]:
    """Derive integer tenor years from published SOFR tenor labels by parsing the leading one or two characters of each label.

    Convert authored blend SOFR tenor labels into the numeric tenor-year series used by swap-curve blend calculations.

    Args:
        blend_sofr_tenor_labels: A data.Series of published SOFR tenor labels (text or null) indexed over catalog coordinates.

    Returns:
        A data.Series containing parsed tenor years as integers where the label starts with 1–5 Year, otherwise the leading two-character parse result, or null when no numeric tenor is available.
    """
