@publish(data.BLEND_SOFR_QUOTED_RATE.schema, cells=data.BLEND_SOFR_QUOTED_RATE.cells)
def blend_sofr_quoted_rate(*, blend_interpolation_index: data.Series[int | str | None], blend_sofr_swap_curve: data.Series[float | str | None], blend_published_tenor_years: data.Series[int | str | None]) -> data.Series[float | str | None]:
    """Interpolate published swap rates onto the SOFR blend grid at each tenor.

    Blends the quoted SOFR swap curve into per-tenor quoted rates used by the SOFR blending calculation.

    Args:
        blend_interpolation_index: data.Series[int | str | None] of lookup indices identifying the interpolation position within the published curve for each tenor.
        blend_sofr_swap_curve: data.Series[float | str | None] of quoted SOFR swap rates indexed by the published swap curve tenor axis; blanks stay blank.
        blend_published_tenor_years: data.Series[int | str | None] of published tenor labels (1-30 years) defining the rows of the interpolation lookup; blank years are omitted.

    Returns:
        data.Series[float | str | None] of interpolated quoted SOFR rates aligned to the 1-30 year grid, with the 25-year point taking the looked-up value nudged by 1e-10 and unavailable lookups returned blank.
    """
    data.BLEND_INTERPOLATION_INDEX.schema.validate(blend_interpolation_index)
    data.BLEND_SOFR_SWAP_CURVE.schema.validate(blend_sofr_swap_curve)
    _blend_sofr_quoted_rate_table_0 = lazy_table(((view(blend_published_tenor_years, rows=data.TENOR_AXIS.keys),), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,)))
    _blend_sofr_quoted_rate_table_1 = lazy_table(((view(blend_sofr_swap_curve, rows=data.TENOR_AXIS.keys),), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,), (lambda: None,)))
    def formula(tenor: int) -> float | str | None:
        if tenor == 25:
            return as_measure(xl_add(xl_ifna(lambda: xl_xlookup(blend_interpolation_index[tenor], _blend_sofr_quoted_rate_table_0, _blend_sofr_quoted_rate_table_1), lambda: ''), 1e-10))
        return as_measure(xl_ifna(lambda: xl_xlookup(blend_interpolation_index[tenor], _blend_sofr_quoted_rate_table_0, _blend_sofr_quoted_rate_table_1), lambda: ''))

    return data.BLEND_SOFR_QUOTED_RATE.collect(evaluate(formula, data.BLEND_SOFR_QUOTED_RATE.required))

