@publish(data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_STRESS_PATH.schema, cells=data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_STRESS_PATH.cells)
def chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path(*, dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Map PV of public debt-to-revenue-and-grants ratios onto the PV-of-debt-to-revenue stress-path chart series.

    Selects the market and non-market B2/B6 scenario values from the source ratio series so the chart's stress-path rows are populated on the projection year grid.

    Args:
        dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio: Typed data series of PV of public debt-to-revenue-and-grants ratios keyed by scenario (including the B2 and B6 market/non-market variants) and time period; supplies the source measures copied into the chart series.
        input3_old_debt_service: Typed Input 3 old-debt-service series whose TIME_PERIOD domain defines the projection year grid over which the stress-path values are collected.

    Returns:
        Typed data series of PV of debt-to-revenue ratios keyed by scenario and stress_path, aligned to the projection year grid derived from the old-debt-service input.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B2.1 Primary balance Market':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B2_mkt', time_period])
        elif scenario == 'B2.2 Primary balance Non-Market':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B2_nonmkt', time_period])
        elif scenario == 'B6.1 Combination of B1-B5 Market':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B6_mkt', time_period])
        return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B6_nonmkt', time_period])

    return data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_STRESS_PATH.collect(evaluate(formula, data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_STRESS_PATH.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE_STRESS_PATH.required.bind(TIME_PERIOD=input3_old_debt_service))

