@publish(data.CHART_INTERNAL_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE_STRESS_PATH.schema, cells=data.CHART_INTERNAL_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE_STRESS_PATH.cells)
def chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_stress_path(*, dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Route each debt service-to-revenue stress path to its corresponding row of the public debt service-to-revenue-and-grants ratio series.

    Builds the Debt Service-to-Revenue Ratio stress-path chart series by relabeling four scenario rows (B2 market/non-market, B6 market/non-market) of the source ratio onto the stress scenario ladder.

    Args:
        dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent: A named-axis series over scenario and time period holding the public debt service-to-revenue-and-grants ratio in percent; the rows keyed `B2_mkt`, `B2_nonmkt`, `B6_mkt`, and `B6_nonmkt` supply the measure copied into each stress path, and any `str` or `None` values propagate unchanged.
        input3_old_debt_service: The Input 3 old debt service series, used only for its `TIME_PERIOD` axis so the bound output series is evaluated over the same projection years as the rest of the chart data.

    Returns:
        A named-axis series over scenario and time period of the Debt Service-to-Revenue Ratio on Chart Data stress path, one row per stress scenario (`B2.1`, `B2.2`, `B6.1`, and the remaining `B6.2` fallback), carrying `float` percentages or `str`/`None` placeholders propagated from the source ratio.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B2.1 Primary balance Market':
            return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent['B2_mkt', time_period])
        elif scenario == 'B2.2 Primary balance Non-Market':
            return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent['B2_nonmkt', time_period])
        elif scenario == 'B6.1 Combination of B1-B5 Market':
            return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent['B6_mkt', time_period])
        return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent['B6_nonmkt', time_period])

    return data.CHART_INTERNAL_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE_STRESS_PATH.collect(evaluate(formula, data.CHART_INTERNAL_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE_STRESS_PATH.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CHART_INTERNAL_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE_STRESS_PATH.required.bind(TIME_PERIOD=input3_old_debt_service))

