@publish(data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_GDP_MODERATE_SPACE.schema, cells=data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_GDP_MODERATE_SPACE.cells)
def chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space(*, fiscal_space_moderate_assessment_flag: int | str, fiscal_space_stock_band: data.FiscalSpaceStockBand, chart_internal_chart_data_pv_debt_to_gdp_pv_debt_gdp_ratio_stress_path: data.Series[float | str | None], chart_output_pv_debt_gdp_ratio: data.ChartOutputPvDebtGdpRatio, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the moderate-risk fiscal-space PV debt-to-GDP chart series from threshold bands and the baseline stress path.

    Derives threshold-adjusted and baseline PV debt-to-GDP paths used to classify moderate fiscal-space positions for the public-debt stress chart.

    Args:
        fiscal_space_moderate_assessment_flag: Scalar integer or string flag; when equal to 1, enables the threshold rows, otherwise threshold outputs remain blank.
        fiscal_space_stock_band: Fiscal-space stock-band series providing the x and y percentage bands used to scale the PV debt-to-GDP threshold.
        chart_internal_chart_data_pv_debt_to_gdp_pv_debt_gdp_ratio_stress_path: Series of PV debt-to-GDP stress-path values keyed by scenario and time period, supplying the baseline path for the baseline row.
        chart_output_pv_debt_gdp_ratio: Chart-output PV debt-to-GDP ratio series keyed by scenario and time period, providing the threshold value used in threshold recipes.
        input3_old_debt_service: Input series of old debt service over catalog coordinates, whose time-period axis defines the output grid.

    Returns:
        A data.Series of float, str, or None values for PV of debt to GDP on Chart Data, keyed by scenario and moderate_space.
    """
    data.FISCAL_SPACE_STOCK_BAND.schema.validate(fiscal_space_stock_band)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == '(1-x)*Threshold':
            return as_measure((xl_mul(xl_sub(1, xl_div(fiscal_space_stock_band['x'], 100)), chart_output_pv_debt_gdp_ratio['Threshold', time_period]) if xl_bool(xl_eq(fiscal_space_moderate_assessment_flag, 1)) else ''))
        elif scenario == '(1-y)*Threshold':
            return as_measure((xl_mul(xl_sub(1, xl_div(fiscal_space_stock_band['y'], 100)), chart_output_pv_debt_gdp_ratio['Threshold', time_period]) if xl_bool(xl_eq(fiscal_space_moderate_assessment_flag, 1)) else ''))
        elif scenario == 'Baseline':
            return as_measure(('' if xl_bool(xl_eq(chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['(1-x)*Threshold', time_period], '')) else chart_internal_chart_data_pv_debt_to_gdp_pv_debt_gdp_ratio_stress_path[scenario, time_period]))
        return as_measure(('' if xl_bool(xl_eq(chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['(1-y)*Threshold', time_period], '')) else (0 if xl_bool(xl_le(chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['Baseline', time_period], chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['(1-y)*Threshold', time_period])) else (2 if xl_bool(xl_gt(chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['Baseline', time_period], chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space['(1-x)*Threshold', time_period])) else 1))))

    chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space = CoordinateReader('chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space', data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_GDP_MODERATE_SPACE.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_GDP_MODERATE_SPACE.collect(((coord, chart_internal_chart_data_fiscal_space_pv_debt_gdp_moderate_space[coord]) for coord in data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_GDP_MODERATE_SPACE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_GDP_MODERATE_SPACE.required.bind(TIME_PERIOD=input3_old_debt_service))

