            return as_measure(('' if xl_bool(xl_eq(chart_internal_chart_data_fiscal_space_pv_debt_exports_moderate_space['(1-x)*Threshold', time_period], '')) else chart_internal_chart_data_pv_debt_to_exports_pv_debt_to_exports_stress_path[scenario, time_period]))
