    chart_internal_chart_data_fiscal_space_pv_debt_exports_moderate_space = CoordinateReader('chart_internal_chart_data_fiscal_space_pv_debt_exports_moderate_space', data.CHART_INTERNAL_CHART_DATA_FISCAL_SPACE_PV_DEBT_EXPORTS_MODERATE_SPACE.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
