@publish(data.EXT_DEBT_RESIDUAL_MATURITY.schema, cells=data.EXT_DEBT_RESIDUAL_MATURITY.cells)
def ext_debt_residual_maturity(*, input4_loan_maturity: data.Input4LoanMaturity, input4_terms_ida_regular: data.Series[float | str | None], input4_terms_ida_and_lc: data.Series[float | str | None], input4_terms_bonds_fx_non_residents: data.Series[float | str | None], input4_terms_bonds_fx_residents: data.Series[float | str | None], ext_debt_new_disbursements_external: data.Series[float | str | None], ext_debt_new_disbursements_non_residents: data.Series[float | str | None], ext_debt_new_disbursements_residents: data.Series[float | str | None], ext_debt_new_disbursements_external_total: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the external-debt residual maturity as the disbursement-weighted average maturity of new external debt for each projection year.

    Derives the yearly residual-financing term used in the LIC-DSF external debt module by weighting instrument loan maturities with new disbursements.

    Args:
        input4_loan_maturity: Input4 loan-maturity table over the instrument axis, supplying per-instrument maturity terms for IMF, multi-creditor, export-credit, NPC, Eurobond, and commercial instruments.
        input4_terms_ida_regular: Input4 terms series over catalog coordinates for IDA regular financing, supplying the IDA-regular loan-maturity term.
        input4_terms_ida_and_lc: Input4 terms series over catalog coordinates for IDA and local-currency financing, supplying loan-maturity terms for IDA 50Y, SML, new 40-year, new regular, blend, and new 60-year credits plus local-currency bonds.
        input4_terms_bonds_fx_non_residents: Input4 terms series over catalog coordinates for FX bonds held by non-residents, restricted to loan-maturity indicators for one-to-three-year and beyond-seven-year FX bonds.
        input4_terms_bonds_fx_residents: Input4 terms series over catalog coordinates for FX bonds held by residents, restricted to loan-maturity indicators for one-to-three-year and beyond-seven-year FX bonds.
        ext_debt_new_disbursements_external: External new-disbursement series over catalog coordinates by instrument, providing the weights for IMF through multi-creditor and other instruments.
        ext_debt_new_disbursements_non_residents: External new-disbursement series over catalog coordinates for non-resident holders, providing weights for local-currency and FX bond instruments.
        ext_debt_new_disbursements_residents: External new-disbursement series over catalog coordinates for resident holders, providing weights for FX bond instruments.
        ext_debt_new_disbursements_external_total: Total external new-disbursement series over catalog coordinates, serving as the denominator and the zero-check that blanks the result.
        input3_old_debt_service: Input3 old-debt-service table over catalog coordinates, whose TIME_PERIOD axis defines the evaluation domain and output year index.

    Returns:
        data.Series[float | str | None] keyed by TIME_PERIOD from the old-debt-service domain; each value is the disbursement-weighted average maturity of new external debt for that year, or a blank string when total new disbursements are zero.
    """
    data.INPUT4_LOAN_MATURITY.schema.validate(input4_loan_maturity)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    _ext_debt_residual_maturity_table_0 = view(input4_loan_maturity, rows=span(data.INSTRUMENT_AXIS, 'OTH_MULTI1', 'OTH_MULTI3'))
    _ext_debt_residual_maturity_table_1 = view(input4_loan_maturity, rows=span(data.INSTRUMENT_AXIS, 'Export Credit Agencies', 'PC5'))
    _ext_debt_residual_maturity_table_2 = view(input4_loan_maturity, rows=span(data.INSTRUMENT_AXIS, 'Export Import Bank of NPC', 'NPC5'))
    _ext_debt_residual_maturity_table_3 = view(input4_loan_maturity, rows=span(data.INSTRUMENT_AXIS, 'Eurobond', 'COM5'))
    _ext_debt_residual_maturity_table_4 = view(input4_terms_ida_and_lc, rows=span(data.INSTRUMENT_AXIS, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=('Loan Maturity',))
    _ext_debt_residual_maturity_table_5 = view(input4_terms_bonds_fx_non_residents, rows={'INSTRUMENT': span(data.INSTRUMENT_AXIS, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX')}, cols={'HOLDER': ('non-residents',), 'INDICATOR': ('Loan Maturity',)})
    _ext_debt_residual_maturity_table_6 = view(input4_terms_bonds_fx_residents, rows={'INSTRUMENT': span(data.INSTRUMENT_AXIS, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX')}, cols={'HOLDER': ('residents',), 'INDICATOR': ('Loan Maturity',)})
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(('' if xl_bool(xl_eq(ext_debt_new_disbursements_external_total[time_period], 0)) else xl_div(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_sumproduct((input4_loan_maturity['IMF'], input4_terms_ida_regular['IDA - regular', 'Loan Maturity'], input4_terms_ida_and_lc['IDA - 50Y loans', 'Loan Maturity'], input4_terms_ida_and_lc['IDA - SML', 'Loan Maturity'], input4_terms_ida_and_lc['IDA NEW 40-year credits', 'Loan Maturity'], input4_terms_ida_and_lc['IDA NEW Regular', 'Loan Maturity'], input4_terms_ida_and_lc['IDA NEW Blend (also enter) -->', 'Loan Maturity'], input4_terms_ida_and_lc['IDA NEW 60-year credits', 'Loan Maturity'], input4_loan_maturity['MULTI1'], input4_loan_maturity['MULTI2']), view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS, 'IMF', 'MULTI2'), cols=(time_period,))), xl_sumproduct(_ext_debt_residual_maturity_table_0, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS, 'OTH_MULTI1', 'OTH_MULTI3'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_1, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS, 'Export Credit Agencies', 'PC5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_2, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS, 'Export Import Bank of NPC', 'NPC5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_3, view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS, 'Eurobond', 'COM5'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_4, view(ext_debt_new_disbursements_non_residents, rows=span(data.INSTRUMENT_AXIS_15, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_5, view(ext_debt_new_disbursements_non_residents, rows=span(data.INSTRUMENT_AXIS_15, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,)))), xl_sumproduct(_ext_debt_residual_maturity_table_6, view(ext_debt_new_disbursements_residents, rows=span(data.INSTRUMENT_AXIS_16, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,)))), ext_debt_new_disbursements_external_total[time_period])))

    return data.EXT_DEBT_RESIDUAL_MATURITY.collect(evaluate(formula, data.EXT_DEBT_RESIDUAL_MATURITY.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.EXT_DEBT_RESIDUAL_MATURITY.required.bind(TIME_PERIOD=input3_old_debt_service))

