@publish(data.IMPORTED_CLASSIFICATION_YEARS.schema, cells=data.IMPORTED_CLASSIFICATION_YEARS.cells)
def imported_classification_years(*, classification_cpia_reported_years: data.Series[int | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[int | str | None]:
    """Derive the imported classification-year series across the projection time axis.

    Fill each TIME_PERIOD with the reported CPIA classification year, offsetting from the anchor year on row 37.

    Args:
        classification_cpia_reported_years: Classification-window years aligned to the projection vintage, supplied as a typed data.Series over TIME_PERIOD that provides the anchor value.
        input3_input_3_macro_current_account: Macro current-account projection series whose TIME_PERIOD coordinate axis defines the year grid and anchor position for the derived classification years.

    Returns:
        A typed data.Series of classification years over TIME_PERIOD, anchored to the reported CPIA year and incremented or decremented by one per year offset.
    """
    data.CLASSIFICATION_CPIA_REPORTED_YEARS.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(classification_cpia_reported_years)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 13:
            return as_measure(classification_cpia_reported_years[_ax_time_period.keys[13]], 'int')
        elif _p_time_period >= 14:
            return as_measure(xl_add(imported_classification_years[axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        return as_measure(xl_sub(imported_classification_years[axis_step(_ax_time_period, time_period, 1)], 1), 'int')

    imported_classification_years = CoordinateReader('imported_classification_years', data.IMPORTED_CLASSIFICATION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.IMPORTED_CLASSIFICATION_YEARS.collect(((coord, imported_classification_years[coord]) for coord in data.IMPORTED_CLASSIFICATION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.IMPORTED_CLASSIFICATION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

