@publish(data.IMPORTED_CLASSIFICATION_IDS.schema, cells=data.IMPORTED_CLASSIFICATION_IDS.cells)
def imported_classification_ids(*, imported_series_stub_cpia: str, imported_series_stub_gr_a: str, imported_series_stub_res_a: str, imported_series_stub_wgr: str, imported_components: data.Series[int | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[str | int | float | bool | None]:
    """Builds the imported classification lookup-key series by concatenating each indicator's stub prefix with its imported component value per time period.

    Produces the text keys that INDEX/MATCH lookups use to resolve imported indicator classifications across the projection year grid.

    Args:
        imported_series_stub_cpia: Scalar string prefix prepended to the imported component when forming the CPIA classification key.
        imported_series_stub_gr_a: Scalar string prefix prepended to the imported component when forming the real growth rate classification key.
        imported_series_stub_res_a: Scalar string prefix prepended to the imported component when forming the import coverage of reserves classification key.
        imported_series_stub_wgr: Scalar string prefix prepended to the imported component when forming the fallback classification key used for any remaining indicator.
        imported_components: Typed series of imported component values over catalog coordinates, indexed per time period and concatenated onto the matching stub prefix to complete each key.
        input3_input_3_macro_current_account: Typed Input 3 macro current account series supplying the TIME_PERIOD axis that defines the output grid and drives per-period evaluation.

    Returns:
        A typed series of the concatenated classification keys over the TIME_PERIOD axis, holding string values or blank-like scalars where the source component is empty.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(indicator: str, time_period: int) -> str | int | float | bool | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if indicator == 'CPIA':
            return as_measure(xl_concat(imported_series_stub_cpia, imported_components[time_period]), 'str')
        elif indicator == 'Real growth rate \n(in percent)':
            return as_measure(xl_concat(imported_series_stub_gr_a, imported_components[time_period]), 'str')
        elif indicator == 'Import coverage of reserves\n(in percent)':
            return as_measure(xl_concat(imported_series_stub_res_a, imported_components[time_period]), 'str')
        return as_measure(xl_concat(imported_series_stub_wgr, imported_components[time_period]), 'str')

    return data.IMPORTED_CLASSIFICATION_IDS.collect(evaluate(formula, data.IMPORTED_CLASSIFICATION_IDS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.IMPORTED_CLASSIFICATION_IDS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

