@publish(data.IMPORTED_CPIA_YEAR_HEADERS.schema, cells=data.IMPORTED_CPIA_YEAR_HEADERS.cells)
def imported_cpia_year_headers(*, probability_scenario_years: data.Series[int | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Builds the CPIA row's year-header series used by the probability approach.

    Anchors the CPIA probability year headers at the base period and propagates them across the macro current-account time grid.

    Args:
        probability_scenario_years: Year-label series supplying the anchor value at the base period of the CPIA header row.
        input3_input_3_macro_current_account: Macro current-account series whose TIME_PERIOD axis defines the output coordinate grid and anchor position.
        input3_old_debt_service: Old debt service series validated alongside the macro current-account series to confirm coordinate compatibility.

    Returns:
        Series of CPIA year headers indexed by TIME_PERIOD, anchored at the base period and stepped outward by one year in each direction.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 13:
            return as_measure(probability_scenario_years[time_period], 'int')
        elif _p_time_period >= 14:
            return as_measure(xl_add(imported_cpia_year_headers[axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        return as_measure(xl_sub(imported_cpia_year_headers[axis_step(_ax_time_period, time_period, 1)], 1), 'int')

    imported_cpia_year_headers = CoordinateReader('imported_cpia_year_headers', data.IMPORTED_CPIA_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.IMPORTED_CPIA_YEAR_HEADERS.collect(((coord, imported_cpia_year_headers[coord]) for coord in data.IMPORTED_CPIA_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.IMPORTED_CPIA_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

