@publish(data.REALISM1_EXTERNAL_CURRENT_VINTAGE_PROJECTION.schema, cells=data.REALISM1_EXTERNAL_CURRENT_VINTAGE_PROJECTION.cells)
def realism1_external_current_vintage_projection(*, display_scale: str, dsa_ext_external_debt_nominal_1: data.Series[float | str | None], dsa_ext_change_in_external_debt: data.Series[float | str | None], dsa_ext_net_fdi_negative_inflow: data.Series[float | str | None], dsa_ext_contribution_from_nominal_interest_rate: data.Series[float | str | None], dsa_ext_contribution_from_real_gdp_growth: data.Series[float | str | None], dsa_ext_contribution_from_price_and_exchange_rate_changes: data.Series[float | str | None], dsa_ext_residual_3: data.Series[float | str | None], dsa_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], dsa_ext_deficit_in_balance_of_goods_and_services: data.Series[float | str | None], dsa_ext_net_current_transfers_negative_inflow: data.Series[float | str | None], dsa_ext_other_current_account_flows_negative_net_inflow: data.Series[float | str | None], dsa_ext_of_which_public_and_publicly_guaranteed_ppg: data.Series[float | str | None], baseline_ext_historical_indicators: data.Series[float | str | None], baseline_ext_year_before_projection: data.Series[float | str | None], lookup_country_scale_phrase: data.Series[str | int | float | bool | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Assemble the Realism 1 external current-vintage debt projection by indicator and year.

    Rebuilds the Realism 1 vintage table that splices historical indicators, the year before projection, and baseline projections into WEO-style external debt rows.

    Args:
        display_scale: Display-scale phrase used to decide whether nominal GDP is rescaled to billions of US dollars.
        dsa_ext_external_debt_nominal_1: Nominal external debt (in percent of GDP) baseline series over catalog coordinates.
        dsa_ext_change_in_external_debt: Change in external debt (in percent of GDP) baseline series over catalog coordinates.
        dsa_ext_net_fdi_negative_inflow: Net FDI (negative = inflow) (in percent of GDP) baseline series over catalog coordinates.
        dsa_ext_contribution_from_nominal_interest_rate: Contribution from nominal interest rate (in percent of GDP) baseline series over catalog coordinates.
        dsa_ext_contribution_from_real_gdp_growth: Contribution from real GDP growth (in percent of GDP) baseline series over catalog coordinates.
        dsa_ext_contribution_from_price_and_exchange_rate_changes: Contribution from price and exchange rate changes (in percent of GDP) baseline series over catalog coordinates.
        dsa_ext_residual_3: Residual term (in percent of GDP) baseline series over catalog coordinates.
        dsa_ext_nominal_gdp_million_of_us_dollars: Nominal GDP in millions of US dollars baseline series over catalog coordinates.
        dsa_ext_deficit_in_balance_of_goods_and_services: Deficit in balance of goods and services (in percent of GDP) baseline series over catalog coordinates.
        dsa_ext_net_current_transfers_negative_inflow: Net current transfers (negative = inflow) (in percent of GDP) baseline series over catalog coordinates.
        dsa_ext_other_current_account_flows_negative_net_inflow: Other noninterest current account flows (negative = net inflow) baseline series over catalog coordinates.
        dsa_ext_of_which_public_and_publicly_guaranteed_ppg: Of which public and publicly guaranteed external debt (in percent of GDP) baseline series over catalog coordinates.
        baseline_ext_historical_indicators: Baseline historical external indicators series keyed by indicator label and year.
        baseline_ext_year_before_projection: Year-before-projection baseline external indicators series supplying the vintage anchor column.
        lookup_country_scale_phrase: Country scale phrase series used to match the display scale when converting nominal GDP units.
        input3_input_3_macro_current_account: Macro current account input dataclass supplying the time-period axis and projection domain.
        input3_old_debt_service: Old debt service input dataclass validated alongside the macro current account input.

    Returns:
        Typed external current-vintage projection series indexed by indicator row label and year, with numeric values or passthrough strings/None.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(indicator: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if indicator == 'Deficit in balance of goods and services (in percent of GDP)' and _p_time_period == 13:
            return as_measure(baseline_ext_year_before_projection['Deficit in balance of goods and services', time_period])
        elif indicator == 'Other noninterest current account flows (negative = net inflow)' and _p_time_period == 13:
            return as_measure(baseline_ext_year_before_projection['Other current account flows (negative = net inflow)', time_period])
        elif indicator == 'Contribution from nominal interest rate (in percent of GDP)' and _p_time_period == 13:
            return as_measure(baseline_ext_year_before_projection['Contribution from nominal interest rate', time_period])
        elif indicator == 'of which: contribution from real GDP growth (in percent of GDP)' and _p_time_period == 13:
            return as_measure(baseline_ext_year_before_projection['Contribution from real GDP growth', time_period])
        elif indicator == 'Contribution from price and exchange rate changes (in percent of GDP)' and _p_time_period == 13:
            return as_measure(baseline_ext_year_before_projection['Contribution from price and exchange rate changes', time_period])
        elif indicator == 'Change in external debt (in percent of GDP)' and _p_time_period == 13:
            return as_measure(baseline_ext_year_before_projection['Change in external debt', time_period])
        elif indicator == 'Residual' and _p_time_period == 13:
            return as_measure(baseline_ext_year_before_projection[f'{indicator} 3/', time_period])
        elif indicator == 'Deficit in balance of goods and services (in percent of GDP)' and 14 <= _p_time_period <= 17:
            return as_measure(dsa_ext_deficit_in_balance_of_goods_and_services['Baseline', time_period])
        elif indicator == 'Other noninterest current account flows (negative = net inflow)' and 14 <= _p_time_period <= 17:
            return as_measure(dsa_ext_other_current_account_flows_negative_net_inflow['Baseline', time_period])
        elif indicator == 'Contribution from nominal interest rate (in percent of GDP)' and 14 <= _p_time_period <= 17:
            return as_measure(dsa_ext_contribution_from_nominal_interest_rate['Baseline', time_period])
        elif indicator == 'of which: contribution from real GDP growth (in percent of GDP)' and 14 <= _p_time_period <= 17:
            return as_measure(dsa_ext_contribution_from_real_gdp_growth['Baseline', time_period])
        elif indicator == 'Contribution from price and exchange rate changes (in percent of GDP)' and 14 <= _p_time_period <= 17:
            return as_measure(dsa_ext_contribution_from_price_and_exchange_rate_changes['Baseline', time_period])
        elif indicator == 'Change in external debt (in percent of GDP)' and 14 <= _p_time_period <= 17:
            return as_measure(dsa_ext_change_in_external_debt['Baseline', time_period])
        elif indicator == 'Residual' and 14 <= _p_time_period <= 17:
            return as_measure(dsa_ext_residual_3['Baseline', time_period])
        elif indicator == 'External debt (nominal; in percent of GDP)' and 7 <= _p_time_period <= 11:
            return as_measure(baseline_ext_historical_indicators['External debt (nominal) 1/', time_period])
        elif indicator == 'Deficit in balance of goods and services (in percent of GDP)' and 8 <= _p_time_period <= 12:
            return as_measure(baseline_ext_historical_indicators['Deficit in balance of goods and services', time_period])
        elif indicator == 'Other noninterest current account flows (negative = net inflow)' and 8 <= _p_time_period <= 12:
            return as_measure(baseline_ext_historical_indicators['Other current account flows (negative = net inflow)', time_period])
        elif indicator == 'Contribution from nominal interest rate (in percent of GDP)' and 8 <= _p_time_period <= 12:
            return as_measure(baseline_ext_historical_indicators['Contribution from nominal interest rate', time_period])
        elif indicator == 'of which: contribution from real GDP growth (in percent of GDP)' and 8 <= _p_time_period <= 12:
            return as_measure(baseline_ext_historical_indicators['Contribution from real GDP growth', time_period])
        elif indicator == 'Contribution from price and exchange rate changes (in percent of GDP)' and 8 <= _p_time_period <= 12:
            return as_measure(baseline_ext_historical_indicators['Contribution from price and exchange rate changes', time_period])
        elif indicator == 'Change in external debt (in percent of GDP)' and 8 <= _p_time_period <= 12:
            return as_measure(baseline_ext_historical_indicators['Change in external debt', time_period])
        elif indicator == 'Residual' and 8 <= _p_time_period <= 12:
            return as_measure(baseline_ext_historical_indicators[f'{indicator} 3/', time_period])
        elif indicator == 'Nominal GDP (in billions of US dollars)' and _p_time_period <= 11:
            return as_measure((xl_div(dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period], 1000) if xl_bool(xl_eq(display_scale, lookup_country_scale_phrase['CPV'])) else dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]))
        elif indicator == 'External debt (nominal; in percent of GDP)' and 12 <= _p_time_period <= 17:
            return as_measure(dsa_ext_external_debt_nominal_1['Baseline', time_period])
        elif indicator == 'External debt o/w public and publicly guaranteed (in percent of GDP)' and _p_time_period <= 11:
            return as_measure(baseline_ext_historical_indicators['of which: public and publicly guaranteed (PPG)', time_period])
        elif indicator == 'Net current transfers (negative = inflow) (in percent of GDP)' and 8 <= _p_time_period <= 17:
            return as_measure(dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period])
        elif indicator == 'Net FDI (in percent of GDP)' and 8 <= _p_time_period <= 17:
            return as_measure(dsa_ext_net_fdi_negative_inflow['Baseline', time_period])
        elif indicator == 'Current account + FDI' and 8 <= _p_time_period <= 17:
            return as_measure(xl_add(xl_add(xl_add(realism1_external_current_vintage_projection['Deficit in balance of goods and services (in percent of GDP)', time_period], realism1_external_current_vintage_projection['Net current transfers (negative = inflow) (in percent of GDP)', time_period]), realism1_external_current_vintage_projection['Other noninterest current account flows (negative = net inflow)', time_period]), realism1_external_current_vintage_projection['Net FDI (in percent of GDP)', time_period]))
        elif indicator == 'change in private sector debt (ppt change)' and 8 <= _p_time_period <= 17:
            return as_measure(xl_sub(realism1_external_current_vintage_projection['External debt o/w private debt (in percent of GDP)', time_period], realism1_external_current_vintage_projection['External debt o/w private debt (in percent of GDP)', axis_step(_ax_time_period, time_period, -1)]))
        elif indicator == 'External debt o/w private debt (in percent of GDP)' and 7 <= _p_time_period <= 17:
            return as_measure(xl_sub(realism1_external_current_vintage_projection['External debt (nominal; in percent of GDP)', time_period], realism1_external_current_vintage_projection['External debt o/w public and publicly guaranteed (in percent of GDP)', time_period]))
        return as_measure(dsa_ext_of_which_public_and_publicly_guaranteed_ppg['Baseline', time_period])

    realism1_external_current_vintage_projection = CoordinateReader('realism1_external_current_vintage_projection', data.REALISM1_EXTERNAL_CURRENT_VINTAGE_PROJECTION.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
