@publish(data.REALISM1_PUBLIC_CURRENT_VINTAGE_PROJECTION.schema, cells=data.REALISM1_PUBLIC_CURRENT_VINTAGE_PROJECTION.cells)
def realism1_public_current_vintage_projection(*, display_scale: str, baseline_pub_historical_indicators: data.Series[float | str | None], baseline_pub_year_before_projection: data.Series[float | str | None], baseline_pub_public_sector_debt: data.Series[float | str | None], baseline_pub_change_in_public_sector_debt: data.Series[float | str | None], baseline_pub_primary_deficit: data.Series[float | str | None], baseline_pub_of_which_contribution_from_average_real: data.Series[float | str | None], baseline_pub_of_which_contribution_from_real_gdp_growth: data.Series[float | str | None], baseline_pub_contribution_from_real_exchange_rate: data.Series[float | str | None], baseline_pub_other_identified_debt_creating_flows: data.Series[float | str | None], baseline_pub_residual: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], lookup_country_scale_phrase: data.Series[str | int | float | bool | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Assemble the current-vintage public-sector debt projection used by the Realism 1 forecast-error view.

    Select indicator- and year-specific baseline, historical, and projection values into one named-axis series aligned to the macro current-account time grid.

    Args:
        display_scale: Scalar display-scale identifier compared against the country scale phrase to decide whether nominal GDP is divided by 1000.
        baseline_pub_historical_indicators: Historical public-debt indicator series over catalog coordinates, supplying pre-projection values such as public sector debt and contributions.
        baseline_pub_year_before_projection: Year-before-projection series providing prior-year indicator values for the first projection step.
        baseline_pub_public_sector_debt: Baseline public sector debt series used as the default value when no indicator-specific branch applies.
        baseline_pub_change_in_public_sector_debt: Projection series for the change in public sector debt as a percent of GDP.
        baseline_pub_primary_deficit: Primary deficit series as a percent of GDP over projection years.
        baseline_pub_of_which_contribution_from_average_real: Projection series for the contribution from the average real interest rate.
        baseline_pub_of_which_contribution_from_real_gdp_growth: Projection series for the contribution from real GDP growth.
        baseline_pub_contribution_from_real_exchange_rate: Projection series for the contribution from real exchange rate depreciation.
        baseline_pub_other_identified_debt_creating_flows: Projection series for other identified debt-creating flows.
        baseline_pub_residual: Projection series for the residual debt-creating balance.
        baseline_pub_nominal_gdp_lc: Nominal GDP series in billions of local currency, conditionally rescaled for display.
        lookup_country_scale_phrase: Lookup series holding the country scale phrase used in the display-scaling comparison.
        input3_input_3_macro_current_account: Validated macro current-account input bundle whose TIME_PERIOD axis defines the projection grid.
        input3_old_debt_service: Validated old debt-service input bundle accepted alongside the macro current-account coordinates.

    Returns:
        Named-axis series of current-vintage public-sector debt projection values by indicator and year, with float, string, or missing entries.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(indicator: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if indicator == 'of which: contribution from average real interest rate (in percent of GDP)' and _p_time_period == 12:
            return as_measure(baseline_pub_year_before_projection['of which: contribution from average real interest rate', time_period])
        elif indicator == 'of which: contribution from real GDP growth (in percent of GDP)' and _p_time_period == 12:
            return as_measure(baseline_pub_year_before_projection['of which: contribution from real GDP growth', time_period])
        elif indicator == 'Contribution from real exchange rate depreciation (in percent of GDP)' and _p_time_period == 12:
            return as_measure(baseline_pub_year_before_projection['Contribution from real exchange rate depreciation', time_period])
        elif indicator == 'Change in public sector debt (in percent of GDP)' and _p_time_period == 12:
            return as_measure(baseline_pub_year_before_projection['Change in public sector debt', time_period])
        elif indicator == 'Other identified debt-creating flows (in percent of GDP)' and _p_time_period == 12:
            return as_measure(baseline_pub_year_before_projection['Other identified debt-creating flows', time_period])
        elif indicator == 'Residual' and _p_time_period == 12:
            return as_measure(baseline_pub_year_before_projection[indicator, time_period])
        elif indicator == 'of which: contribution from average real interest rate (in percent of GDP)' and 8 <= _p_time_period <= 11:
            return as_measure(baseline_pub_historical_indicators['of which: contribution from average real interest rate', time_period])
        elif indicator == 'of which: contribution from real GDP growth (in percent of GDP)' and 8 <= _p_time_period <= 11:
            return as_measure(baseline_pub_historical_indicators['of which: contribution from real GDP growth', time_period])
        elif indicator == 'Contribution from real exchange rate depreciation (in percent of GDP)' and 8 <= _p_time_period <= 11:
            return as_measure(baseline_pub_historical_indicators['Contribution from real exchange rate depreciation', time_period])
        elif indicator == 'Change in public sector debt (in percent of GDP)' and 8 <= _p_time_period <= 11:
            return as_measure(baseline_pub_historical_indicators['Change in public sector debt', time_period])
        elif indicator == 'Other identified debt-creating flows (in percent of GDP)' and 8 <= _p_time_period <= 11:
            return as_measure(baseline_pub_historical_indicators['Other identified debt-creating flows', time_period])
        elif indicator == 'Residual' and 8 <= _p_time_period <= 11:
            return as_measure(baseline_pub_historical_indicators[indicator, time_period])
        elif indicator == 'of which: contribution from average real interest rate (in percent of GDP)' and 13 <= _p_time_period <= 17:
            return as_measure(baseline_pub_of_which_contribution_from_average_real[time_period])
        elif indicator == 'of which: contribution from real GDP growth (in percent of GDP)' and 13 <= _p_time_period <= 17:
            return as_measure(baseline_pub_of_which_contribution_from_real_gdp_growth[time_period])
        elif indicator == 'Contribution from real exchange rate depreciation (in percent of GDP)' and 13 <= _p_time_period <= 17:
            return as_measure(baseline_pub_contribution_from_real_exchange_rate[time_period])
        elif indicator == 'Change in public sector debt (in percent of GDP)' and 13 <= _p_time_period <= 17:
            return as_measure(baseline_pub_change_in_public_sector_debt[time_period])
        elif indicator == 'Other identified debt-creating flows (in percent of GDP)' and 13 <= _p_time_period <= 17:
            return as_measure(baseline_pub_other_identified_debt_creating_flows[time_period])
        elif indicator == 'Residual' and 13 <= _p_time_period <= 17:
            return as_measure(baseline_pub_residual[time_period])
        elif indicator == 'Nominal GDP (in billions of local currency)' and _p_time_period <= 11:
            return as_measure((xl_div(baseline_pub_nominal_gdp_lc[time_period], 1000) if xl_bool(xl_eq(display_scale, lookup_country_scale_phrase['CPV'])) else baseline_pub_nominal_gdp_lc[time_period]))
        elif indicator == 'Public sector debt (in percent of GDP)' and _p_time_period <= 11:
            return as_measure(baseline_pub_historical_indicators['Public sector debt 1/', time_period])
        elif indicator == 'Primary deficit (in percent of GDP)' and 8 <= _p_time_period <= 17:
            return as_measure(baseline_pub_primary_deficit[time_period])
        return as_measure(baseline_pub_public_sector_debt[time_period])

    return data.REALISM1_PUBLIC_CURRENT_VINTAGE_PROJECTION.collect(evaluate(formula, data.REALISM1_PUBLIC_CURRENT_VINTAGE_PROJECTION.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM1_PUBLIC_CURRENT_VINTAGE_PROJECTION.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM1_PUBLIC_FIVE_YEARS_AGO_PROJECTION.schema, cells=data.REALISM1_PUBLIC_FIVE_YEARS_AGO_PROJECTION.cells)
def realism1_public_five_years_ago_projection(*, imported_prev_dsa_public_2019: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Project the public-debt path from the prior DSA vintage onto the current five-years-ago realism grid.

    Reindexes the imported previous-DSA public debt series over the current TIME_PERIOD axis so Realism 1 forecast-error checks compare like-for-like vintages.

    Args:
        imported_prev_dsa_public_2019: Imported public debt series from the DSA vintage five years ago, in local currency, over indicator and time-period coordinates.
        input3_input_3_macro_current_account: Current macro-debt input series supplying the authoritative TIME_PERIOD axis used to align the projection grid; validated against its schema before evaluation.

    Returns:
        Typed float-or-string series of the public debt projection five years ago over the bound TIME_PERIOD coordinate, containing None where the vintage has no value.
    """
