            return as_measure(((realism3_government_capital_actual['Actual Level (3.*4.)', time_period] if xl_bool(xl_lt(realism3_contribution_years[time_period], realism3_latest_vintage_year)) else (xl_add(xl_mul(realism3_government_capital_projected_by_vintage[indicator, axis_step(_ax_time_period, time_period, -1)], xl_sub(1, realism3_depreciation_rate)), xl_mul(xl_mul(xl_div(realism3_public_investment_ratio_by_vintage[indicator, time_period], 100), realism3_baseline_real_gdp_index_by_vintage[indicator, time_period]), realism3_efficiency_public)) if xl_bool(xl_isnumber(lambda: realism3_public_investment_ratio_by_vintage[indicator, time_period])) else '')) if xl_bool(xl_le(realism3_contribution_years[time_period], imported_fad_capital_stock_year)) else (xl_add(xl_mul(realism3_government_capital_projected_by_vintage[indicator, axis_step(_ax_time_period, time_period, -1)], xl_sub(1, realism3_depreciation_rate)), xl_mul(xl_mul(xl_div(realism3_public_investment_ratio_by_vintage[indicator, time_period], 100), realism3_baseline_real_gdp_index_by_vintage[indicator, time_period]), realism3_efficiency_public)) if xl_bool(xl_isnumber(lambda: realism3_public_investment_ratio_by_vintage[indicator, time_period])) else False)))
