@publish(data.BASELINE_EXT_HISTORICAL_INDICATORS.schema, cells=data.BASELINE_EXT_HISTORICAL_INDICATORS.cells)
def baseline_ext_historical_indicators(*, dsa_ext_external_debt_nominal_1: data.Series[float | str | None], dsa_ext_non_interest_current_account_deficit: data.Series[float | str | None], dsa_ext_exports: data.Series[float | str | None], dsa_ext_net_fdi_negative_inflow: data.Series[float | str | None], dsa_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], dsa_ext_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent: data.Series[float | str | None], dsa_ext_net_current_transfers_negative_inflow: data.Series[float | str | None], macro_debt_total_ext_debt_interest_due_include_interest: data.Series[float | str | None], macro_debt_exports_of_goods_services: data.Series[float | str | None], macro_debt_imports_of_goods_services_use_positive_values: data.Series[float | str | None], macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], macro_debt_private_debt_pct_gdp: data.Series[float | str | None], macro_debt_total_public_ext_debt: data.Series[float | str | None], macro_debt_share_of_local_currency_denominated_external: data.Series[float | str | None], macro_debt_depreciation_of_nc_depreciation: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute baseline external historical indicators for the LIC-DSF external table.

    Derive each historical-indicator row (debt stock, flows, contributions, residuals) from the underlying external and macro-debt coordinate series through 2023.

    Args:
        dsa_ext_external_debt_nominal_1: Nominal external debt stock series indexed by TIME_PERIOD, baseline scenario.
        dsa_ext_non_interest_current_account_deficit: Non-interest current account deficit series indexed by TIME_PERIOD, baseline scenario.
        dsa_ext_exports: Exports series indexed by TIME_PERIOD, baseline scenario.
        dsa_ext_net_fdi_negative_inflow: Net FDI series with inflows as negatives, indexed by TIME_PERIOD, baseline scenario.
        dsa_ext_nominal_gdp_million_of_us_dollars: Nominal GDP in millions of U.S. dollars, indexed by TIME_PERIOD, baseline scenario.
        dsa_ext_real_gdp_growth_in_percent: Real GDP growth in percent, indexed by TIME_PERIOD, baseline scenario.
        dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent: GDP deflator change in U.S. dollar terms, in percent, indexed by TIME_PERIOD, baseline scenario.
        dsa_ext_net_current_transfers_negative_inflow: Net current transfers with inflows as negatives, indexed by TIME_PERIOD, baseline scenario.
        macro_debt_total_ext_debt_interest_due_include_interest: Total external debt interest due, including interest, indexed by TIME_PERIOD.
        macro_debt_exports_of_goods_services: Exports of goods and services indexed by TIME_PERIOD.
        macro_debt_imports_of_goods_services_use_positive_values: Imports of goods and services as positive values, indexed by TIME_PERIOD.
        macro_debt_gdp_current_prices_u_s_dollars: GDP at current prices in U.S. dollars, indexed by TIME_PERIOD.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Exchange rate in national currency per U.S. dollar, indexed by TIME_PERIOD.
        macro_debt_private_debt_pct_gdp: Private debt as a percent of GDP, indexed by TIME_PERIOD.
        macro_debt_total_public_ext_debt: Total public external debt stock, indexed by TIME_PERIOD.
        macro_debt_share_of_local_currency_denominated_external: Share of local-currency-denominated external debt in total external debt, indexed by TIME_PERIOD.
        macro_debt_depreciation_of_nc_depreciation: Depreciation of the national currency (positive means depreciation), indexed by TIME_PERIOD.
        input3_input_3_macro_current_account: Input 3 macro current account record supplying the TIME_PERIOD axis used to align every indicator row.

    Returns:
        Typed series of historical indicator values keyed by the indicator row label and TIME_PERIOD, with blanks reported as '…' when an input cannot be evaluated.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(indicator: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if indicator == 'Change in external debt' and _p_time_period == 12:
            return as_measure((xl_sub(dsa_ext_external_debt_nominal_1['Baseline', time_period], baseline_ext_historical_indicators['External debt (nominal) 1/', axis_step(_ax_time_period, time_period, -1)]) if xl_bool(xl_isnumber(lambda: xl_sub(dsa_ext_external_debt_nominal_1['Baseline', time_period], baseline_ext_historical_indicators['External debt (nominal) 1/', axis_step(_ax_time_period, time_period, -1)]))) else '…'))
        elif indicator == 'Deficit in balance of goods and services' and _p_time_period == 12:
            return as_measure((xl_sub(baseline_ext_historical_indicators['Imports', time_period], dsa_ext_exports['Baseline', time_period]) if xl_bool(xl_isnumber(lambda: xl_sub(baseline_ext_historical_indicators['Imports', time_period], dsa_ext_exports['Baseline', time_period]))) else '…'))
        elif indicator == 'Change in external debt' and 8 <= _p_time_period <= 11:
            return as_measure((xl_sub(baseline_ext_historical_indicators['External debt (nominal) 1/', time_period], baseline_ext_historical_indicators['External debt (nominal) 1/', axis_step(_ax_time_period, time_period, -1)]) if xl_bool(xl_isnumber(lambda: xl_sub(baseline_ext_historical_indicators['External debt (nominal) 1/', time_period], baseline_ext_historical_indicators['External debt (nominal) 1/', axis_step(_ax_time_period, time_period, -1)]))) else '…'))
        elif indicator == 'Deficit in balance of goods and services' and 8 <= _p_time_period <= 11:
            return as_measure((xl_sub(baseline_ext_historical_indicators['Imports', time_period], baseline_ext_historical_indicators['Exports', time_period]) if xl_bool(xl_isnumber(lambda: xl_sub(baseline_ext_historical_indicators['Imports', time_period], baseline_ext_historical_indicators['Exports', time_period]))) else '…'))
        elif indicator == 'Exports' and 8 <= _p_time_period <= 11:
            return as_measure((xl_mul(xl_div(macro_debt_exports_of_goods_services[time_period], dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]), 100) if xl_bool(xl_isnumber(lambda: xl_mul(xl_div(macro_debt_exports_of_goods_services[time_period], dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]), 100))) else '…'))
        elif indicator == 'External debt (nominal) 1/' and 7 <= _p_time_period <= 11:
            return as_measure((xl_add(baseline_ext_historical_indicators['of which: public and publicly guaranteed (PPG)', time_period], baseline_ext_historical_indicators['of which: Private', time_period]) if xl_bool(xl_and(xl_isnumber(lambda: baseline_ext_historical_indicators['of which: public and publicly guaranteed (PPG)', time_period]), xl_isnumber(lambda: baseline_ext_historical_indicators['of which: Private', time_period]))) else '…'))
        elif indicator == 'of which: Private' and 7 <= _p_time_period <= 11:
            return as_measure(macro_debt_private_debt_pct_gdp[time_period])
        elif indicator == 'Identified net debt-creating flows' and _p_time_period >= 8:
            return as_measure((xl_add(xl_add(dsa_ext_non_interest_current_account_deficit['Baseline', time_period], dsa_ext_net_fdi_negative_inflow['Baseline', time_period]), baseline_ext_historical_indicators['Endogenous debt dynamics 2/', time_period]) if xl_bool(xl_isnumber(lambda: xl_add(xl_add(dsa_ext_non_interest_current_account_deficit['Baseline', time_period], dsa_ext_net_fdi_negative_inflow['Baseline', time_period]), baseline_ext_historical_indicators['Endogenous debt dynamics 2/', time_period]))) else '…'))
        elif indicator == 'Imports' and _p_time_period >= 8:
            return as_measure((xl_mul(xl_div(macro_debt_imports_of_goods_services_use_positive_values[time_period], dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]), 100) if xl_bool(xl_isnumber(lambda: xl_mul(xl_div(macro_debt_imports_of_goods_services_use_positive_values[time_period], dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]), 100))) else '…'))
        elif indicator == 'Other current account flows (negative = net inflow)' and _p_time_period >= 8:
            return as_measure((xl_sub(xl_sub(dsa_ext_non_interest_current_account_deficit['Baseline', time_period], baseline_ext_historical_indicators['Deficit in balance of goods and services', time_period]), dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period]) if xl_bool(xl_isnumber(lambda: xl_sub(xl_sub(dsa_ext_non_interest_current_account_deficit['Baseline', time_period], baseline_ext_historical_indicators['Deficit in balance of goods and services', time_period]), dsa_ext_net_current_transfers_negative_inflow['Baseline', time_period]))) else '…'))
        elif indicator == 'Endogenous debt dynamics 2/' and _p_time_period >= 8:
            return as_measure((xl_add(xl_add(baseline_ext_historical_indicators['Contribution from nominal interest rate', time_period], baseline_ext_historical_indicators['Contribution from real GDP growth', time_period]), baseline_ext_historical_indicators['Contribution from price and exchange rate changes', time_period]) if xl_bool(xl_isnumber(lambda: xl_add(xl_add(baseline_ext_historical_indicators['Contribution from nominal interest rate', time_period], baseline_ext_historical_indicators['Contribution from real GDP growth', time_period]), baseline_ext_historical_indicators['Contribution from price and exchange rate changes', time_period]))) else '…'))
        elif indicator == 'Denominator: 1+g+ρ+gρ' and _p_time_period >= 8:
            return as_measure((xl_add(xl_add(xl_add(1, xl_div(dsa_ext_real_gdp_growth_in_percent['Baseline', time_period], 100)), xl_div(dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent['Baseline', time_period], 100)), xl_div(xl_mul(xl_div(dsa_ext_real_gdp_growth_in_percent['Baseline', time_period], 100), dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent['Baseline', time_period]), 100)) if xl_bool(xl_isnumber(lambda: xl_add(xl_add(xl_add(1, xl_div(dsa_ext_real_gdp_growth_in_percent['Baseline', time_period], 100)), xl_div(dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent['Baseline', time_period], 100)), xl_div(xl_mul(xl_div(dsa_ext_real_gdp_growth_in_percent['Baseline', time_period], 100), dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent['Baseline', time_period]), 100)))) else '…'))
        elif indicator == 'Contribution from nominal interest rate' and _p_time_period >= 8:
            return as_measure((xl_div(xl_mul(xl_div(baseline_ext_historical_indicators['Effective interest rate (percent) 4/', time_period], 100), baseline_ext_historical_indicators['External debt (nominal) 1/', axis_step(_ax_time_period, time_period, -1)]), baseline_ext_historical_indicators['Denominator: 1+g+ρ+gρ', time_period]) if xl_bool(xl_isnumber(lambda: xl_div(xl_mul(xl_div(baseline_ext_historical_indicators['Effective interest rate (percent) 4/', time_period], 100), baseline_ext_historical_indicators['External debt (nominal) 1/', axis_step(_ax_time_period, time_period, -1)]), baseline_ext_historical_indicators['Denominator: 1+g+ρ+gρ', time_period]))) else '…'))
