    return data.REALISM2_GROWTH_IMPACT_MULTIPLIER_0_6.collect(evaluate(formula, data.REALISM2_GROWTH_IMPACT_MULTIPLIER_0_6.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.REALISM2_GROWTH_IMPACT_MULTIPLIER_0_6.required.bind(TIME_PERIOD=input3_old_debt_service))

