@publish(data.REALISM3_CONTRIBUTION_YEARS.schema, cells=data.REALISM3_CONTRIBUTION_YEARS.cells)
def realism3_contribution_years(*, realism3_first_projection_year: int | str, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[int | str | None]:
    """Build the government-capital contribution year-header series for Realism 3.

    Seeds contribution-year labels from the first projection year and extends them across the macro current-account time axis.

    Args:
        realism3_first_projection_year: First projection year used to seed the contribution-year header sequence on the shared time-period axis.
        input3_input_3_macro_current_account: Macro current-account input series whose TIME_PERIOD axis defines the coordinate positions and domain for the returned year headers.

    Returns:
        A typed year-header series aligned to the input current-account time axis, carrying integer or string year labels from the seeded first projection year and None where unresolved.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 13:
            return as_measure(realism3_first_projection_year, 'int')
        elif _p_time_period >= 14:
            return as_measure(xl_add(realism3_contribution_years[axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        return as_measure(xl_sub(realism3_contribution_years[axis_step(_ax_time_period, time_period, 1)], 1), 'int')

    realism3_contribution_years = CoordinateReader('realism3_contribution_years', data.REALISM3_CONTRIBUTION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.REALISM3_CONTRIBUTION_YEARS.collect(((coord, realism3_contribution_years[coord]) for coord in data.REALISM3_CONTRIBUTION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_CONTRIBUTION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM3_GROWTH_CONTRIBUTIONS.schema, cells=data.REALISM3_GROWTH_CONTRIBUTIONS.cells)
def realism3_growth_contributions(*, realism3_capital_growth_contribution: data.Series[float | str | None], realism3_growth_residual: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute Realism 3 growth-contribution series from government-capital and residual inputs.

    Rebuilds the Realism 3 Invest-Growth contribution measures by scaling stored capital and other-factor contributions to percentage points over the TIME_PERIOD axis.

    Args:
        realism3_capital_growth_contribution: Typed series of government-capital contributions to real GDP growth, indexed by DSA variant (Previous/Current) and time period, expressed in fractional units and multiplied by 100 in the output.
        realism3_growth_residual: Typed series of residual, other-factor contributions to real GDP growth, indexed by DSA variant (Previous/Current) and time period, expressed in fractional units and multiplied by 100 in the output.
        input3_input_3_macro_current_account: Typed macro current-account input series whose TIME_PERIOD axis supplies the projection coordinates and the validation domain for the computed output.

    Returns:
        Typed series of Realism 3 growth contributions in percentage points, aligned to the TIME_PERIOD domain of the supplied macro current-account series, with non-numeric or missing values carried as blanks.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(indicator: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        INDICATOR_TO_REALISM3_CAPITAL_GROWTH_CONTRIBUTION_VARIANT = {'Contribution of government capital (G) - Prev. DSA': 'Previous', 'Contribution of government capital (G) - Curr. DSA': 'Current'}
        INDICATOR_TO_REALISM3_GROWTH_RESIDUAL_VARIANT = {'Contribution of other factors - Prev. DSA': 'Previous', 'Contribution of other factors - Curr. DSA': 'Current'}
        if indicator in ('Contribution of government capital (G) - Prev. DSA', 'Contribution of government capital (G) - Curr. DSA'):
            return as_measure((xl_mul(realism3_capital_growth_contribution[INDICATOR_TO_REALISM3_CAPITAL_GROWTH_CONTRIBUTION_VARIANT[indicator], time_period], 100) if xl_bool(xl_isnumber(lambda: xl_mul(realism3_capital_growth_contribution[INDICATOR_TO_REALISM3_CAPITAL_GROWTH_CONTRIBUTION_VARIANT[indicator], time_period], 100))) else ''))
        return as_measure((xl_mul(realism3_growth_residual[INDICATOR_TO_REALISM3_GROWTH_RESIDUAL_VARIANT[indicator], time_period], 100) if xl_bool(xl_isnumber(lambda: xl_mul(realism3_growth_residual[INDICATOR_TO_REALISM3_GROWTH_RESIDUAL_VARIANT[indicator], time_period], 100))) else ''))

    return data.REALISM3_GROWTH_CONTRIBUTIONS.collect(evaluate(formula, data.REALISM3_GROWTH_CONTRIBUTIONS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_GROWTH_CONTRIBUTIONS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(key=(), domain=None, cells=data.REALISM3_GOVERNMENT_CAPITAL_ACTUAL_LABEL_CELLS)
def realism3_government_capital_actual_label(*, imported_fad_capital_stock_year: int | str) -> str | int | float | bool:
    """Build the historical government-capital actual-share label.

    Formats the Realism 3 label for the historical government-capital share using the imported FAD capital stock year.

    Args:
        imported_fad_capital_stock_year: The scalar year of the imported FAD capital stock data, as an int or str, interpolated into the label.

    Returns:
        The historical government-capital share label as a str, or the error code scalar when evaluation fails.
    """
    try:
        return as_measure(xl_concat(xl_concat('Actual Share of GDP (FAD Database, actual through ', imported_fad_capital_stock_year), ')'), 'str')
    except XlError as error:
        return error.code

@publish(data.REALISM3_GOVERNMENT_CAPITAL_GROWTH.schema, cells=data.REALISM3_GOVERNMENT_CAPITAL_GROWTH.cells)
def realism3_government_capital_growth(*, realism3_government_capital_projected_by_vintage: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute year-over-year growth of the projected government capital stock for each vintage path.

    Derives the Realism 3 investment/growth chart series comparing government capital growth under the previous and current projection vintages.

    Args:
        realism3_government_capital_projected_by_vintage: Named-axis series of projected government capital stock levels indexed by vintage variant and TIME_PERIOD, supplying the current and prior-period values used for the growth ratio.
        input3_input_3_macro_current_account: Macro current-account series whose TIME_PERIOD domain defines the projection grid and period ordering over which growth is evaluated.

    Returns:
        A series over TIME_PERIOD giving the ratio of each period's government capital stock to the prior period's minus one, or '..' where a prior-period comparison is unavailable.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(variant: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if variant == 'Current' and _p_time_period <= 12:
            return as_measure((xl_sub(xl_div(realism3_government_capital_projected_by_vintage['Current', time_period], realism3_government_capital_projected_by_vintage['Current', axis_step(_ax_time_period, time_period, -1)]), 1) if xl_bool(xl_eq(xl_count(view(realism3_government_capital_projected_by_vintage, rows=('Current',), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, -1), time_period))), 2)) else '..'))
        return as_measure((xl_sub(xl_div(realism3_government_capital_projected_by_vintage[variant, time_period], realism3_government_capital_projected_by_vintage[variant, axis_step(_ax_time_period, time_period, -1)]), 1) if xl_bool(xl_eq(xl_count(view(realism3_government_capital_projected_by_vintage, rows=(variant,), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, -1), time_period))), 2)) else '..'))

    return data.REALISM3_GOVERNMENT_CAPITAL_GROWTH.collect(evaluate(formula, data.REALISM3_GOVERNMENT_CAPITAL_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_GOVERNMENT_CAPITAL_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM3_CAPITAL_GROWTH_CONTRIBUTION.schema, cells=data.REALISM3_CAPITAL_GROWTH_CONTRIBUTION.cells)
def realism3_capital_growth_contribution(*, realism3_output_elasticity: float | str, realism3_government_capital_growth: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute the government-capital growth contribution to Realism 3 investment-growth analysis.

    Scale government-capital growth by the output elasticity over the TIME_PERIOD axis, returning '..' where growth is not numeric.

    Args:
        realism3_output_elasticity: Output elasticity applied to government-capital growth, supplied as a scalar float or a string placeholder.
        realism3_government_capital_growth: Government-capital growth series over TIME_PERIOD indexed by variant, whose numeric values are multiplied by the elasticity.
        input3_input_3_macro_current_account: Macro current-account input series whose TIME_PERIOD domain defines the evaluated coordinate grid.

    Returns:
        A data series of the capital-growth contribution values (float, str, or None) over the TIME_PERIOD coordinates.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(variant: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if variant == 'Current' and _p_time_period <= 12:
            return as_measure((xl_mul(realism3_government_capital_growth['Current', time_period], realism3_output_elasticity) if xl_bool(xl_eq(xl_isnumber(lambda: realism3_government_capital_growth['Current', time_period]), True)) else '..'))
        return as_measure((xl_mul(realism3_government_capital_growth[variant, time_period], realism3_output_elasticity) if xl_bool(xl_eq(xl_isnumber(lambda: realism3_government_capital_growth[variant, time_period]), True)) else '..'))

    return data.REALISM3_CAPITAL_GROWTH_CONTRIBUTION.collect(evaluate(formula, data.REALISM3_CAPITAL_GROWTH_CONTRIBUTION.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_CAPITAL_GROWTH_CONTRIBUTION.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM3_GROWTH_RESIDUAL.schema, cells=data.REALISM3_GROWTH_RESIDUAL.cells)
def realism3_growth_residual(*, realism3_real_growth_by_vintage: data.Series[float | str | None], realism3_capital_growth_contribution: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Residual between observed real growth and the government-capital growth contribution, expressed as a growth-rate decimal.

    Supports the Realism 3 invest-growth diagnostic by isolating the growth not explained by public capital accumulation, per variant and projection year.

    Args:
        realism3_real_growth_by_vintage: Real GDP growth by vintage, as a named-axis tensor over variant and TIME_PERIOD coordinates in percentage points; divided by 100 before use.
        realism3_capital_growth_contribution: Government-capital contribution to growth as a named-axis tensor over variant and TIME_PERIOD coordinates in the same growth units.
        input3_input_3_macro_current_account: Macro current-account input series whose TIME_PERIOD axis supplies the projection grid the residual is evaluated over and validated against.

    Returns:
        A named-axis float series over variant and TIME_PERIOD coordinates holding the residual growth rate, or a text marker where either input is non-numeric or missing.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(variant: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if variant == 'Current' and _p_time_period <= 12:
            return as_measure((xl_sub(xl_div(realism3_real_growth_by_vintage['Current', time_period], 100), realism3_capital_growth_contribution['Current', time_period]) if xl_bool(xl_eq(xl_count(realism3_capital_growth_contribution['Current', time_period], realism3_real_growth_by_vintage['Current', time_period]), 2)) else '..'))
        return as_measure((xl_sub(xl_div(realism3_real_growth_by_vintage[variant, time_period], 100), realism3_capital_growth_contribution[variant, time_period]) if xl_bool(xl_eq(xl_count(realism3_capital_growth_contribution[variant, time_period], realism3_real_growth_by_vintage[variant, time_period]), 2)) else '..'))

    return data.REALISM3_GROWTH_RESIDUAL.collect(evaluate(formula, data.REALISM3_GROWTH_RESIDUAL.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_GROWTH_RESIDUAL.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM4_PRIMARY_DEFICIT.schema, cells=data.REALISM4_PRIMARY_DEFICIT.cells)
def realism4_primary_deficit(*, baseline_pub_primary_deficit: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Return the Realism 4 primary-deficit series aligned to macro current-account TIME_PERIOD coordinates.

    Rebuilds the Realism 4 fiscal-adjustment primary deficit from the baseline public primary deficit for downstream fiscal-adjustment charts.

    Args:
        baseline_pub_primary_deficit: Primary deficit in percent of GDP, provided as a named-axis series over catalog coordinates.
        input3_input_3_macro_current_account: Macro current-account input series over catalog coordinates supplying the TIME_PERIOD axis used to evaluate the baseline deficit.

    Returns:
        A data.Series[float | str | None] of the Realism 4 primary-deficit path aligned to the input TIME_PERIOD axis.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(baseline_pub_primary_deficit[time_period])

    return data.REALISM4_PRIMARY_DEFICIT.collect(evaluate(formula, data.REALISM4_PRIMARY_DEFICIT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM4_PRIMARY_DEFICIT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM4_THREE_YEAR_ADJUSTMENT.schema, cells=data.REALISM4_THREE_YEAR_ADJUSTMENT.cells)
def realism4_three_year_adjustment(*, realism4_primary_deficit: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the Realism 4 three-year fiscal adjustment series over the debt-service time grid.

    Derive the change in the primary deficit relative to its value three years earlier, expressed in percentage points of GDP.

    Args:
        realism4_primary_deficit: Primary deficit as a time-indexed data series of floats, text sentinels, or blanks over the catalog time-period coordinate.
        input3_input_3_macro_current_account: Macro current-account data series whose TIME_PERIOD axis is used to align the three-year lagged comparison point.
        input3_old_debt_service: Old debt-service data series whose TIME_PERIOD domain defines the output periods and their coordinate positions.

    Returns:
        A data series of the three-year fiscal adjustment in percentage points of GDP, indexed to the old debt-service time periods, with float, str, or None values.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_neg(xl_sub(realism4_primary_deficit[time_period], realism4_primary_deficit[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -3)])))

    return data.REALISM4_THREE_YEAR_ADJUSTMENT.collect(evaluate(formula, data.REALISM4_THREE_YEAR_ADJUSTMENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.REALISM4_THREE_YEAR_ADJUSTMENT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.IN8_SDR_SDR_INTEREST.schema, cells=data.IN8_SDR_SDR_INTEREST.cells)
def in8_sdr_sdr_interest(*, in8_sdr_sdr_allocation_holdings_in_million_of_usd: data.Series[int | str | None], discount_rate: float | str, input8_sdr_interest_historical: data.Input8SdrInterestHistorical, input8_sdr_interest: data.Input8SdrInterest, input8_sdr_interest_rate: float | str, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute SDR interest on Input 8 by issuance year and projection year.

    Derives the SDR interest schedule from allocation holdings, historical and projected SDR rates, and discount-rate capitalization rules.

    Args:
        in8_sdr_sdr_allocation_holdings_in_million_of_usd: Named-axis series of SDR allocation holdings in millions of USD, indexed by issuance and projection year and allowing numeric, text, or missing sentinel values.
        discount_rate: Scalar discount rate used to capitalize accrued SDR interest in the relevant projection-year cases.
        input8_sdr_interest_historical: Typed historical SDR interest-rate series aligned to the projection TIME_PERIOD axis and used for historical issuance-year calculations.
        input8_sdr_interest: Typed projected SDR interest-rate series aligned to the projection TIME_PERIOD axis and used for the default forward-looking calculation.
        input8_sdr_interest_rate: Scalar SDR interest rate applied in the terminal issuance-year case.
        input3_old_debt_service: Typed old-debt-service series whose TIME_PERIOD axis defines the projection grid and lag positions used to locate prior allocation holdings.

    Returns:
        Named-axis series of SDR interest amounts keyed by issuance year and projection year, with entries matching the data.Series[int | str | None] annotation and allowing numeric measures or missing/text sentinel values.
    """
    data.INPUT8_SDR_INTEREST_HISTORICAL.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(input8_sdr_interest_historical)
    data.INPUT8_SDR_INTEREST.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(input8_sdr_interest)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(issuance_year: int, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if issuance_year == 2024 and _p_time_period == 1:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[issuance_year], input8_sdr_interest_historical[time_period]) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], 0)) else 0), 'int')
        elif issuance_year == 2024 and _p_time_period == 4:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -4)], input8_sdr_interest_historical[time_period]) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], 0)) else 0), 'int')
        elif issuance_year == 2024 and _p_time_period == 5:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -5)], input8_sdr_interest_historical[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -5)], input8_sdr_interest_historical[time_period]), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -5)], 0)) else 0), 'int')
        elif issuance_year == 2025 and _p_time_period == 5:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -4)], input8_sdr_interest_historical[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -4)], input8_sdr_interest_historical[time_period]), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -4)], 0)) else 0), 'int')
        elif issuance_year == 2026 and _p_time_period == 5:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -3)], input8_sdr_interest_historical[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -3)], input8_sdr_interest_historical[time_period]), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -3)], 0)) else 0), 'int')
        elif issuance_year == 2027 and _p_time_period == 5:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -2)], input8_sdr_interest_historical[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -2)], input8_sdr_interest_historical[time_period]), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -2)], 0)) else 0), 'int')
        elif issuance_year == 2028 and _p_time_period == 5:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_interest_historical[_ax_time_period.keys[5]]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_interest_historical[_ax_time_period.keys[5]]), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], 0)) else 0), 'int')
        elif issuance_year == 2043 and _p_time_period == 20:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_interest_rate), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_interest_rate), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], 0)) else 0), 'int')
        elif issuance_year <= 2025 and 3 <= _p_time_period <= 4 and _ax_time_period.keys[_p_time_period] - issuance_year == 3:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -3)], input8_sdr_interest_historical[time_period]) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], 0)) else 0), 'int')
        elif issuance_year <= 2026 and 2 <= _p_time_period <= 4 and _ax_time_period.keys[_p_time_period] - issuance_year == 2:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -2)], input8_sdr_interest_historical[time_period]) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], 0)) else 0), 'int')
        elif 2025 <= issuance_year <= 2027 and 2 <= _p_time_period <= 4 and _ax_time_period.keys[_p_time_period] - issuance_year == 1:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_interest_historical[time_period]) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], 0)) else 0), 'int')
        return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_interest[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_interest[time_period]), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], 0)) else 0), 'int')

    return data.IN8_SDR_SDR_INTEREST.collect(evaluate(formula, data.IN8_SDR_SDR_INTEREST.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.IN8_SDR_SDR_INTEREST.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(key=(), domain=None, cells=data.IN8_SDR_OF_END_2044_CELLS)
def in8_sdr_of_end_2044(*, discount_rate: float | str, input8_sdr_interest_rate: float | str, in8_sdr_sdr_allocation_holdings_in_million_of_usd: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> int | str:
    """Compute the end-2044 SDR value from the SDR allocation holdings, SDR interest rate, and discount rate.

    Evaluate the single-cell end-2044 SDR expression, returning an integer measure or a workbook error code.

    Args:
        discount_rate: Discount rate scalar as a float or workbook expression string, used in the SDR discount term.
        input8_sdr_interest_rate: SDR interest rate scalar as a float or workbook expression string, applied to the end-2044 allocation holdings.
        in8_sdr_sdr_allocation_holdings_in_million_of_usd: SDR allocation holdings in millions of USD as a single-cell `data.Series` anchored at end-2044 and indexed by the debt-service time axis; cells may be blank.
        input3_old_debt_service: Old debt service input bundle whose `TIME_PERIOD` axis keys identify the end-2044 allocation cell to read.

    Returns:
        End-2044 SDR value as an integer, or the workbook error code string if evaluation raises an `XlError`.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    try:
        return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[input3_old_debt_service.domain.axis('TIME_PERIOD').keys[20]], input8_sdr_interest_rate), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[input3_old_debt_service.domain.axis('TIME_PERIOD').keys[20]], input8_sdr_interest_rate), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[input3_old_debt_service.domain.axis('TIME_PERIOD').keys[20]], 0)) else 0), 'int')
    except XlError as error:
        return error.code

@publish(data.C4_MKT_FIN_NOMINAL_GDP.schema, cells=data.C4_MKT_FIN_NOMINAL_GDP.cells)
def c4_mkt_fin_nominal_gdp(*, c4_market_path_nominal_gdp: float | str, c4_mkt_fin_gdp_deflator: data.Series[float | str | None], c4_market_path_real_gdp_growth: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute nominal GDP on the C4 market-financing stress path.

    Projects nominal GDP from a base market-path value by compounding real GDP growth and the GDP deflator across TIME_PERIOD.

    Args:
        c4_market_path_nominal_gdp: Base nominal GDP value for the first TIME_PERIOD, as a scalar number or string expression.
        c4_mkt_fin_gdp_deflator: GDP deflator series indexed by TIME_PERIOD, supplied as a data.Series of numeric, string, or null values.
        c4_market_path_real_gdp_growth: Real GDP growth rate series for the C4_Market scenario over TIME_PERIOD, supplied as a data.Series of numeric, string, or null values.
        input3_old_debt_service: Old debt service input bundle whose TIME_PERIOD domain defines the output coordinate grid and period alignment.

    Returns:
        data.Series[float | str | None] of nominal GDP values over TIME_PERIOD, aligned to the input bundle's domain; string and null expressions propagate through the underlying spreadsheet arithmetic.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 1:
            return as_measure(xl_mul(xl_mul(c4_market_path_nominal_gdp, xl_add(1, xl_div(c4_market_path_real_gdp_growth['C4_Market', time_period], 100))), xl_add(1, xl_div(c4_mkt_fin_gdp_deflator[time_period], 100))))
        return as_measure(xl_mul(xl_mul(c4_mkt_fin_nominal_gdp[axis_step(_ax_time_period, time_period, -1)], xl_add(1, xl_div(c4_market_path_real_gdp_growth['C4_Market', time_period], 100))), xl_add(1, xl_div(c4_mkt_fin_gdp_deflator[time_period], 100))))

    c4_mkt_fin_nominal_gdp = CoordinateReader('c4_mkt_fin_nominal_gdp', data.C4_MKT_FIN_NOMINAL_GDP.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.C4_MKT_FIN_NOMINAL_GDP.collect(((coord, c4_mkt_fin_nominal_gdp[coord]) for coord in data.C4_MKT_FIN_NOMINAL_GDP.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_NOMINAL_GDP.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_GDP_DEFLATOR.schema, cells=data.C4_MKT_FIN_GDP_DEFLATOR.cells)
def c4_mkt_fin_gdp_deflator(*, dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent: data.Series[float | str | None], c4_mkt_fin_nc_depreciation: float | str, c4_mkt_fin_historical_flag: float | str, c4_market_path_non_interest_ca_pct_gdp: float | str, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derive the C4 market-financing GDP deflator series, overlaying a tailored FX-shock adjustment in the first projection year when the historical-flag switch is enabled.

    Produce the deflator path on the market-financing scenario used downstream by the C4 calculations, with a conditional year-one shock overlay.

    Args:
        dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent: Baseline-scenario series of the external GDP deflator change in US dollar terms, expressed in percent over the time grid.
        c4_mkt_fin_nc_depreciation: Scalar nominal depreciation factor applied to the non-interest current account gap when the year-one shock overlay is active.
        c4_mkt_fin_historical_flag: Scalar switch (1 enables) controlling whether the tailored year-one FX-shock adjustment is applied to the deflator.
        c4_market_path_non_interest_ca_pct_gdp: Scalar market-path non-interest current account balance as a percent of GDP, used as the multiplicative gap driver in the shock overlay.
        input3_input_3_macro_current_account: Typed macro current-account series from Input 3 providing scenario- and time-indexed current account values validated against its schema.
        input3_old_debt_service: Typed old-debt-service series from Input 3 whose time axis defines the evaluation grid and output domain for the deflator path.

    Returns:
        Typed series of the GDP deflator (percent change) on the C4 market-financing path over the time axis, carrying floats, strings, or nulls where the source cells are blank or textual.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 1:
            return as_measure((xl_add(dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent['Baseline', time_period], xl_mul(xl_sub(c4_market_path_non_interest_ca_pct_gdp, 1), c4_mkt_fin_nc_depreciation)) if xl_bool(xl_eq(c4_mkt_fin_historical_flag, 1)) else dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent['Baseline', time_period]))
        return as_measure(dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent['Baseline', time_period])

    return data.C4_MKT_FIN_GDP_DEFLATOR.collect(evaluate(formula, data.C4_MKT_FIN_GDP_DEFLATOR.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_GDP_DEFLATOR.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(key=(), domain=None, cells=data.C4_MKT_FIN_NC_DEPRECIATION_CELLS)
def c4_mkt_fin_nc_depreciation(*, c4_mkt_fin_i_macro_indicators: int | str, dsa_ext_depreciation_of_nc_depreciation: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> float | str:
    """Computes the C4 market-financing non-concessional first-year nominal depreciation overlay.

    Evaluates the baseline depreciation series at the old debt-service time key and combines it with the macro-indicator scalar for the C4 shock.

    Args:
        c4_mkt_fin_i_macro_indicators: Scalar macro-indicator value or label used as the additive term in the C4 market-financing non-concessional depreciation calculation.
        dsa_ext_depreciation_of_nc_depreciation: Named-axis series of baseline nominal depreciation values for non-concessional debt; the entry at the second TIME_PERIOD key is selected.
        input3_old_debt_service: Old debt-service input bundle whose TIME_PERIOD axis supplies the projection key used to index the depreciation series.

    Returns:
        Computed overlay as a float, or the XlError code string if evaluation raises an Excel error.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    try:
        return as_measure(xl_add(xl_mul(dsa_ext_depreciation_of_nc_depreciation['Baseline', input3_old_debt_service.domain.axis('TIME_PERIOD').keys[1]], 0), c4_mkt_fin_i_macro_indicators))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.C4_MKT_FIN_HISTORICAL_FLAG_CELLS)
def c4_mkt_fin_historical_flag(*, ext_debt_new_disbursements_external: data.Series[float | str | None]) -> float | str:
    """Derive the historical market-financing flag from external new disbursements.

    Select the historical versus standard shock parameterization by checking whether Commercial external new disbursements are positive over 2024–2044.

    Args:
        ext_debt_new_disbursements_external: Typed catalog tensor of external new disbursements with possible float, string, or blank entries; its Commercial row is summed across 2024–2044 to evaluate the flag.

    Returns:
        Scalar flag: 1 if the summed Commercial external new disbursements over 2024–2044 are positive, 0 otherwise; an XlError code string is returned if evaluation fails.
    """
    _c4_mkt_fin_historical_flag_table_0 = view(ext_debt_new_disbursements_external, rows=('Commercial',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2044))
    try:
        return as_measure((1 if xl_bool(xl_gt(xl_sum(_c4_mkt_fin_historical_flag_table_0), 0)) else 0))
    except XlError as error:
        return error.code

@publish(data.C4_MKT_FIN_STRESSED_LENDING_TERMS.schema, cells=data.C4_MKT_FIN_STRESSED_LENDING_TERMS.cells)
def c4_mkt_fin_stressed_lending_terms(*, c4_market_instruments: data.Series[int | str | None], c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute stressed market-financing lending terms by commercial instrument and term variant.

    Derive stressed bullet/amortization flags, maturity, grace, and rounded terms from baseline instrument maturities and financing parameters.

    Args:
        c4_market_instruments: Named-axis series of market-instrument values over commercial instruments and TIME_PERIOD, used to read original maturities and test bullet/amortization status.
        c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row: Named-axis series of financing-parameter rows supplying the new-maturity threshold, maturity-shortening factor, and grace-period shortening factor used by the stressed-term formulas.
        input3_input_3_macro_current_account: Typed Input 3 macro current-account series whose TIME_PERIOD axis provides the projection-year coordinates used to align instrument maturity lookups.

    Returns:
        A data.Series[float | str | None] of stressed lending terms indexed by commercial instrument and term variant, covering bullet/amortization flag, maturity, grace, and rounded maturity/grace values.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(instrument: str, variant: str) -> float | str | None:
        if variant == 'Bullet (1) or Amort. (>1)':
            return as_measure((1 if xl_bool(xl_le(xl_sub(c4_market_instruments[instrument, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13]], c4_market_instruments[instrument, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]]), 1)) else 0))
        elif variant == 'Maturity':
            return as_measure((c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row['If original maturity is greater than 5 years, new maturity is'] if xl_bool(xl_gt(c4_market_instruments[instrument, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13]], 5)) else xl_mul(c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row['If original maturity is less than 5 years, new maturity is shortened by'], c4_market_instruments[instrument, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13]])))
        elif variant == 'Grace':
            return as_measure((xl_sub(c4_mkt_fin_stressed_lending_terms[instrument, 'Maturity'], 1) if xl_bool(xl_eq(c4_mkt_fin_stressed_lending_terms[instrument, 'Bullet (1) or Amort. (>1)'], 1)) else xl_min(xl_mul(c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row['Shortening of grace period, for 3 years: shortened by'], c4_mkt_fin_stressed_lending_terms[instrument, 'Maturity']), c4_market_instruments[instrument, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]])))
        elif variant == 'Maturity\n(rounded)':
            return as_measure(xl_rounddown(c4_mkt_fin_stressed_lending_terms[instrument, 'Maturity'], 0))
        return as_measure(xl_rounddown(c4_mkt_fin_stressed_lending_terms[instrument, 'Grace'], 0))

    c4_mkt_fin_stressed_lending_terms = CoordinateReader('c4_mkt_fin_stressed_lending_terms', data.C4_MKT_FIN_STRESSED_LENDING_TERMS.required, formula)
    return data.C4_MKT_FIN_STRESSED_LENDING_TERMS.collect((coord, c4_mkt_fin_stressed_lending_terms[coord]) for coord in data.C4_MKT_FIN_STRESSED_LENDING_TERMS.required)

@publish(data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS.schema, cells=data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS.cells)
def c4_mkt_fin_average_residual_terms(*, c4_mkt_fin_stressed_lending_terms: data.Series[float | str | None], c4_mkt_fin_total_commercial_borrowing_total: float | str, c4_mkt_fin_new_borrowing_total: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute disbursement-weighted average residual maturity and grace terms for commercial financing.

    Aggregates stressed lending terms across commercial borrowing categories to derive the residual financing average terms used in the LIC-DSF market-financing calculations.

    Args:
        c4_mkt_fin_stressed_lending_terms: Typed data series of stressed lending terms by commercial borrowing category, carrying the maturity and grace variants.
        c4_mkt_fin_total_commercial_borrowing_total: Scalar total commercial borrowing amount used as the denominator and zero-borrowing guard.
        c4_mkt_fin_new_borrowing_total: Typed data series of new borrowing totals per commercial borrowing category, used as the disbursement weights.

    Returns:
        Typed data series of disbursement-weighted average maturity and grace terms for residual financing, rounded down per term variant, or zero when total commercial borrowing is zero.
    """
    def formula(variant: str) -> float | str | None:
        VARIANT_TO_C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS = {'Maturity\n(rounded)': 'Maturity', 'Grace\n(rounded)': 'Grace'}
        if variant in ('Maturity', 'Grace'):
            return as_measure((0 if xl_bool(xl_eq(c4_mkt_fin_total_commercial_borrowing_total, 0)) else xl_div(xl_add(xl_add(xl_add(xl_add(xl_mul(c4_mkt_fin_stressed_lending_terms['Eurobond', variant], c4_mkt_fin_new_borrowing_total['Eurobond']), xl_mul(c4_mkt_fin_stressed_lending_terms['Commecial Bank', variant], c4_mkt_fin_new_borrowing_total['Commecial Bank'])), xl_mul(c4_mkt_fin_stressed_lending_terms['COM3', variant], c4_mkt_fin_new_borrowing_total['COM3'])), xl_mul(c4_mkt_fin_stressed_lending_terms['COM4', variant], c4_mkt_fin_new_borrowing_total['COM4'])), xl_mul(c4_mkt_fin_stressed_lending_terms['COM5', variant], c4_mkt_fin_new_borrowing_total['COM5'])), c4_mkt_fin_total_commercial_borrowing_total)))
        return as_measure(xl_rounddown(c4_mkt_fin_average_residual_terms[VARIANT_TO_C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS[variant]], 0))

    c4_mkt_fin_average_residual_terms = CoordinateReader('c4_mkt_fin_average_residual_terms', data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS.required, formula)
    return data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS.collect((coord, c4_mkt_fin_average_residual_terms[coord]) for coord in data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS.required)

@publish(key=(), domain=None, cells=data.C4_MKT_FIN_AVERAGE_RESIDUAL_INTEREST_CELLS)
def c4_mkt_fin_average_residual_interest(*, c4_mkt_fin_total_commercial_borrowing_total: float | str, c4_mkt_fin_new_borrowing_total: data.Series[float | str | None], c4_market_instruments_k: data.Series[float | str | None]) -> float | str:
    """Compute the disbursement-weighted average interest rate for residual financing.

    Supports the LIC-DSF residual financing calculation by weighting instrument-specific new borrowing against total commercial borrowing.

    Args:
        c4_mkt_fin_total_commercial_borrowing_total: Total commercial borrowing amount as a scalar float or string value; used as the denominator and zero-guard for the weighted average.
        c4_mkt_fin_new_borrowing_total: Named-axis series of new borrowing amounts over market instrument coordinates, with float, string, or missing entries per instrument.
        c4_market_instruments_k: Named-axis series over the same market instrument coordinates containing instrument-level interest rates or coefficients, with float, string, or missing entries.

    Returns:
        Disbursement-weighted average residual financing interest rate as a float, or an error code string if the calculation encounters an Excel error.
    """
    try:
        return as_measure((0 if xl_bool(xl_eq(c4_mkt_fin_total_commercial_borrowing_total, 0)) else xl_div(xl_add(xl_add(xl_add(xl_add(xl_mul(c4_market_instruments_k['Eurobond'], c4_mkt_fin_new_borrowing_total['Eurobond']), xl_mul(c4_market_instruments_k['Commecial Bank'], c4_mkt_fin_new_borrowing_total['Commecial Bank'])), xl_mul(c4_market_instruments_k['COM3'], c4_mkt_fin_new_borrowing_total['COM3'])), xl_mul(c4_market_instruments_k['COM4'], c4_mkt_fin_new_borrowing_total['COM4'])), xl_mul(c4_market_instruments_k['COM5'], c4_mkt_fin_new_borrowing_total['COM5'])), c4_mkt_fin_total_commercial_borrowing_total)))
    except XlError as error:
        return error.code

@publish(data.C4_MKT_FIN_TOTAL_COMMERCIAL_BORROWING.schema, cells=data.C4_MKT_FIN_TOTAL_COMMERCIAL_BORROWING.cells)
def c4_mkt_fin_total_commercial_borrowing(*, c4_mkt_fin_new_borrowing: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes total commercial borrowing by summing new commercial disbursements over the shock years.

    Aggregates commercial new-borrowing series across the shock-year time axis to produce the total commercial borrowing path.

    Args:
        c4_mkt_fin_new_borrowing: A named-axis tensor of per-instrument, per-year commercial new borrowing amounts (float or passthrough text/None markers) over catalog coordinates, sliced and summed across the commercial instrument span for each shock year.
        input3_old_debt_service: A typed data series of old debt service over catalog coordinates whose TIME_PERIOD axis defines the shock-year grid on which the commercial sums are evaluated and collected.

    Returns:
        A named-axis series (float or passthrough text/None) of total commercial borrowing per shock year, aligned to the TIME_PERIOD domain inherited from the old debt service input.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_sum(view(c4_mkt_fin_new_borrowing, rows=span(data.INSTRUMENT_AXIS, 'Eurobond', 'COM5'), cols=(time_period,))))

    return data.C4_MKT_FIN_TOTAL_COMMERCIAL_BORROWING.collect(evaluate(formula, data.C4_MKT_FIN_TOTAL_COMMERCIAL_BORROWING.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_TOTAL_COMMERCIAL_BORROWING.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(key=(), domain=None, cells=data.C4_MKT_FIN_TOTAL_COMMERCIAL_BORROWING_TOTAL_CELLS)
def c4_mkt_fin_total_commercial_borrowing_total(*, c4_mkt_fin_total_commercial_borrowing: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> float | str:
    """Sum commercial borrowing disbursements across the three-year shock window.

    Computes the C4 market-financing total by summing the first three projection years of the commercial borrowing series, using Input 3 debt-service time coordinates to locate the window.

    Args:
        c4_mkt_fin_total_commercial_borrowing: Named-axis data.Series of commercial borrowing disbursements whose TIME_PERIOD coordinate is restricted to the three-year shock window before summation.
        input3_old_debt_service: data.Input3OldDebtService series supplying the TIME_PERIOD axis whose projection-year keys define the shock window used to slice the borrowing series.

    Returns:
        Scalar float equal to the summed commercial borrowing over the shock window, or a string containing the Excel error code if the summation raises an XlError.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    _c4_mkt_fin_total_commercial_borrowing_total_table_0 = view(c4_mkt_fin_total_commercial_borrowing, cols=span(input3_old_debt_service.domain.axis('TIME_PERIOD'), input3_old_debt_service.domain.axis('TIME_PERIOD').keys[1], input3_old_debt_service.domain.axis('TIME_PERIOD').keys[3]))
    try:
        return as_measure(xl_sum(_c4_mkt_fin_total_commercial_borrowing_total_table_0))
    except XlError as error:
        return error.code

@publish(data.C4_MKT_FIN_NEW_BORROWING.schema, cells=data.C4_MKT_FIN_NEW_BORROWING.cells)
def c4_mkt_fin_new_borrowing(*, ext_debt_new_disbursements_external: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derives the commercial market-financing new-borrowing series from external commercial new disbursements.

    Projects external commercial disbursement amounts onto the market-financing new-borrowing catalog series over the time grid implied by the old debt service data.

    Args:
        ext_debt_new_disbursements_external: Named-axis series of commercial new disbursements by instrument and time period; values may be numeric, textual, or blank.
        input3_old_debt_service: Collection of old debt service series whose schema is validated and whose TIME_PERIOD axis supplies the projection grid for the result.

    Returns:
        Named-axis series of commercial market-financing new borrowing by instrument and time period, with numeric, textual, or blank values.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(ext_debt_new_disbursements_external[instrument, time_period])

    return data.C4_MKT_FIN_NEW_BORROWING.collect(evaluate(formula, data.C4_MKT_FIN_NEW_BORROWING.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_NEW_BORROWING.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_NEW_BORROWING_TOTAL.schema, cells=data.C4_MKT_FIN_NEW_BORROWING_TOTAL.cells)
def c4_mkt_fin_new_borrowing_total(*, c4_mkt_fin_new_borrowing: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes three-year total commercial new borrowing by instrument.

    Aggregates instrument-level commercial disbursements over the Input 3 time span for the LIC-DSF financing block.

    Args:
        c4_mkt_fin_new_borrowing: Typed series of commercial new borrowing amounts or placeholders over catalog coordinates, indexed by instrument and time.
        input3_old_debt_service: Typed Input 3 old-debt-service series whose TIME_PERIOD axis supplies the three-year span used for the total.

    Returns:
        Typed series of three-year total commercial disbursements by instrument, preserving float, string, or null values over catalog coordinates.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str) -> float | str | None:
        return as_measure(xl_sum(view(c4_mkt_fin_new_borrowing, rows=(instrument,), cols=span(input3_old_debt_service.domain.axis('TIME_PERIOD'), input3_old_debt_service.domain.axis('TIME_PERIOD').keys[1], input3_old_debt_service.domain.axis('TIME_PERIOD').keys[3]))))

    return data.C4_MKT_FIN_NEW_BORROWING_TOTAL.collect(evaluate(formula, data.C4_MKT_FIN_NEW_BORROWING_TOTAL.required))

@publish(data.C4_MKT_FIN_GFN_INCREASE.schema, cells=data.C4_MKT_FIN_GFN_INCREASE.cells)
def c4_mkt_fin_gfn_increase(*, c4_market_path_total_debt_service: data.Series[float | str | None], c4_market_path_total_debt_service_alt: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the increase in external gross financing needs on the C4 market-financing stress sheet.

    Subtracts the C4 market-path total debt service from its alternative path, cell by cell over the projection time axis, to yield the financing-need increase series.

    Args:
        c4_market_path_total_debt_service: Total debt service along the C4 market financing path, a named-axis series over the C4_Market scenario and TIME_PERIOD coordinates.
        c4_market_path_total_debt_service_alt: Alternative total debt service along the C4 market financing path, a named-axis series over the same C4_Market and TIME_PERIOD coordinates; its values are the minuend.
        input3_old_debt_service: Input 3 historical debt service series whose TIME_PERIOD axis defines the projection grid over which the difference is evaluated, with its own axis retained as a domain reference.

    Returns:
        A data.Series[float | str | None] holding the per-period increase in gross financing needs over the time axis derived from the Input 3 debt service series, carrying the C4_MKT_FIN_GFN_INCREASE coordinate identity.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_sub(c4_market_path_total_debt_service_alt['C4_Market', time_period], c4_market_path_total_debt_service['C4_Market', time_period]))

    return data.C4_MKT_FIN_GFN_INCREASE.collect(evaluate(formula, data.C4_MKT_FIN_GFN_INCREASE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_GFN_INCREASE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_PV_RESIDUAL_FINANCING.schema, cells=data.C4_MKT_FIN_PV_RESIDUAL_FINANCING.cells)
def c4_mkt_fin_pv_residual_financing(*, pv_stress_pv_of_new_forex_debt: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the PV of residual financing under the market-financing stress scenario.

    Sums the primary and secondary market-financing stress components of PV of new foreign-currency debt into the C4 residual-financing series.

    Args:
        pv_stress_pv_of_new_forex_debt: Named-axis series of PV of new foreign-currency debt under the market-financing stress test, indexed by scenario component and time period; values are floats, strings, or None as carried by catalog coordinates.
        input3_old_debt_service: Input 3 old-debt-service series supplying the TIME_PERIOD coordinate domain used to align and evaluate the residual-financing calculation.

    Returns:
        Named-axis series of PV of residual financing, indexed by the TIME_PERIOD domain of the old-debt-service input; values are floats, strings, or None as carried by catalog coordinates.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(pv_stress_pv_of_new_forex_debt['Market financing stress test / primary', time_period], pv_stress_pv_of_new_forex_debt['Market financing stress test / secondary', time_period]))

    return data.C4_MKT_FIN_PV_RESIDUAL_FINANCING.collect(evaluate(formula, data.C4_MKT_FIN_PV_RESIDUAL_FINANCING.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_PV_RESIDUAL_FINANCING.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_PV_DEBT_ADJUSTMENTS.schema, cells=data.C4_MKT_FIN_PV_DEBT_ADJUSTMENTS.cells)
def c4_mkt_fin_pv_debt_adjustments(*, c4_mkt_fin_pv_residual_financing: data.Series[float | str | None], c4_market_path_pv_of_debt: data.Series[float | str | None], c4_market_path_pv_of_debt_alt: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute C4 market-financing PV-of-debt adjustments from alternate and baseline PV paths plus residual financing.

    Derive the stress-sheet PV-of-debt adjustment series over the Input 3 debt-service time axis.

    Args:
        c4_mkt_fin_pv_residual_financing: Residual financing series over catalog coordinates, aligned to the projection time grid.
        c4_market_path_pv_of_debt: Baseline C4 market-path PV-of-debt series over catalog coordinates.
        c4_market_path_pv_of_debt_alt: Alternate C4 market-path PV-of-debt series over catalog coordinates.
        input3_old_debt_service: Input 3 old-debt-service group used to bind and validate the TIME_PERIOD axis.

    Returns:
        A catalog-coordinate series of adjusted PV-of-debt values, allowing numeric, text, or missing entries.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(xl_sub(c4_market_path_pv_of_debt_alt['C4_Market', time_period], c4_market_path_pv_of_debt['C4_Market', time_period]), c4_mkt_fin_pv_residual_financing[time_period]))

    return data.C4_MKT_FIN_PV_DEBT_ADJUSTMENTS.collect(evaluate(formula, data.C4_MKT_FIN_PV_DEBT_ADJUSTMENTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_PV_DEBT_ADJUSTMENTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_REVISED_PV_DEBT.schema, cells=data.C4_MKT_FIN_REVISED_PV_DEBT.cells)
def c4_mkt_fin_revised_pv_debt(*, c4_market_path_baseline_pv_of_debt: data.Series[float | str | None], c4_mkt_fin_pv_debt_adjustments: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the revised present value of debt on the C4 market-financing stress path.

    Combines the baseline C4 market-path PV of debt with market-financing PV debt adjustments to produce the revised PV series, returning the baseline unchanged in the first time period.

    Args:
        c4_market_path_baseline_pv_of_debt: Baseline PV of debt along the C4 market path, as a named-axis series over catalog coordinates.
        c4_mkt_fin_pv_debt_adjustments: PV of debt adjustments applied on the C4 market-financing stress sheet, aligned to the same time-period coordinate as the baseline series.
        input3_old_debt_service: Old debt service input series that supplies the TIME_PERIOD axis used to evaluate and bind the revised PV of debt output.

    Returns:
        A data.Series[float | str | None] of revised PV of debt on the C4 market-financing stress sheet, indexed by time period.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_add(c4_market_path_baseline_pv_of_debt['C4_Market', time_period], None))
        return as_measure(xl_add(c4_market_path_baseline_pv_of_debt['C4_Market', time_period], c4_mkt_fin_pv_debt_adjustments[time_period]))

    return data.C4_MKT_FIN_REVISED_PV_DEBT.collect(evaluate(formula, data.C4_MKT_FIN_REVISED_PV_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_REVISED_PV_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_REVISED_PV_DEBT_PCT_GDP.schema, cells=data.C4_MKT_FIN_REVISED_PV_DEBT_PCT_GDP.cells)
def c4_mkt_fin_revised_pv_debt_pct_gdp(*, c4_market_path_nominal_gdp_stress: data.Series[float | str | None], c4_mkt_fin_revised_pv_debt: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the C4 market-financing stress revised PV of debt as a percent of GDP.

    Derive the debt-to-GDP ratio under the C4 market-financing stress scenario for the LIC-DSF public-debt stress ladder.

    Args:
        c4_market_path_nominal_gdp_stress: Named-axis series of nominal GDP along the C4 market-financing stress path, used as the denominator for the ratio.
        c4_mkt_fin_revised_pv_debt: Named-axis series of revised present value of debt under C4 market-financing stress, used as the numerator.
        input3_old_debt_service: Typed Input 3 old-debt-service dataclass of series that supplies the TIME_PERIOD axis and coordinate binding for evaluation.

    Returns:
        Named-axis series of the revised present value of debt as a percent of GDP under C4 market-financing stress, with blanks or non-numeric values propagated as strings or None.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(c4_mkt_fin_revised_pv_debt[time_period], c4_market_path_nominal_gdp_stress['C4_Market', time_period]), 100))

    return data.C4_MKT_FIN_REVISED_PV_DEBT_PCT_GDP.collect(evaluate(formula, data.C4_MKT_FIN_REVISED_PV_DEBT_PCT_GDP.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_REVISED_PV_DEBT_PCT_GDP.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_BASELINE_DEBT_SERVICE.schema, cells=data.C4_MKT_FIN_BASELINE_DEBT_SERVICE.cells)
def c4_mkt_fin_baseline_debt_service(*, macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes baseline debt service for the C4 market-financing stress sheet.

    Adds PPG interest due to the year-6 main-assumption dollar component over the prior debt-service time grid.

    Args:
        macro_debt_ppg_interest_due: Per-year series of public-and-publicly-guaranteed interest due used as the interest component of baseline debt service.
        macro_debt_main_assumptions_us_dollars_by_year_6: Per-year series of main-assumption dollar amounts for year 6 used as the component added to interest due.
        input3_input_3_macro_current_account: Validated dataclass of Input 3 macro current-account assumptions supplying workbook macro context for the calculation.
        input3_old_debt_service: Validated dataclass of prior debt-service inputs whose TIME_PERIOD axis defines the output coordinate grid.

    Returns:
        A data.Series of float, str, or None values containing baseline debt service under the C4 market-financing stress, indexed by TIME_PERIOD inherited from prior debt service.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]))

    return data.C4_MKT_FIN_BASELINE_DEBT_SERVICE.collect(evaluate(formula, data.C4_MKT_FIN_BASELINE_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_BASELINE_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_DEBT_SERVICE_ADJUSTMENT.schema, cells=data.C4_MKT_FIN_DEBT_SERVICE_ADJUSTMENT.cells)
def c4_mkt_fin_debt_service_adjustment(*, c4_market_path_total_debt_service: data.Series[float | str | None], c4_market_path_total_debt_service_alt: data.Series[float | str | None], pv_stress_total_debt_service: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Adjustment to debt service on the C4 market-financing stress sheet.

    Computes the time-series adjustment that reconciles C4 market-path debt service with PV-stress debt-service terms.

    Args:
        c4_market_path_total_debt_service: Typed data.Series[float | str | None] of total debt service along the C4 market path, used as the primary leg of the adjustment.
        c4_market_path_total_debt_service_alt: Typed data.Series[float | str | None] of total debt service along an alternative C4 market path, used as the comparison leg in the adjustment formula.
        pv_stress_total_debt_service: Typed data.Series[float | str | None] of PV-stress total debt service, indexed by the Market financing stress test primary and secondary coordinates.
        input3_old_debt_service: data.Input3OldDebtService dataclass supplying the TIME_PERIOD axis and old debt-service values used to bind and validate the output domain.

    Returns:
        A data.Series[float | str | None] of debt-service adjustments over TIME_PERIOD; the first period uses only the PV-stress primary and secondary terms, while later periods add the alternate-minus-primary C4 market-path difference.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_add(xl_add(xl_sub(None, None), pv_stress_total_debt_service['Market financing stress test / primary', time_period]), pv_stress_total_debt_service['Market financing stress test / secondary', time_period]))
        return as_measure(xl_add(xl_add(xl_sub(c4_market_path_total_debt_service_alt['C4_Market', time_period], c4_market_path_total_debt_service['C4_Market', time_period]), pv_stress_total_debt_service['Market financing stress test / primary', time_period]), pv_stress_total_debt_service['Market financing stress test / secondary', time_period]))

    return data.C4_MKT_FIN_DEBT_SERVICE_ADJUSTMENT.collect(evaluate(formula, data.C4_MKT_FIN_DEBT_SERVICE_ADJUSTMENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_DEBT_SERVICE_ADJUSTMENT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_ADJUSTED_DEBT_SERVICE.schema, cells=data.C4_MKT_FIN_ADJUSTED_DEBT_SERVICE.cells)
def c4_mkt_fin_adjusted_debt_service(*, c4_mkt_fin_baseline_debt_service: data.Series[float | str | None], c4_mkt_fin_debt_service_adjustment: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute adjusted C4 market-financing debt service by adding the baseline and adjustment series over each catalog time period.

    Produce the C4 market-financing stress-sheet adjusted debt service series aligned to the input debt-service time axis.

    Args:
        c4_mkt_fin_baseline_debt_service: Baseline debt service as a named-axis data series over catalog coordinates, with scalar values or missing markers per period.
        c4_mkt_fin_debt_service_adjustment: Debt service adjustment as a named-axis data series over catalog coordinates, added period by period to the baseline series.
        input3_old_debt_service: Input 3 old debt service typed series providing the authoritative TIME_PERIOD coordinate axis used to align and evaluate the adjusted debt-service output.

    Returns:
        Adjusted debt service as a named-axis data series over catalog coordinates, containing scalar values or missing markers for each TIME_PERIOD.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(c4_mkt_fin_baseline_debt_service[time_period], c4_mkt_fin_debt_service_adjustment[time_period]))

    return data.C4_MKT_FIN_ADJUSTED_DEBT_SERVICE.collect(evaluate(formula, data.C4_MKT_FIN_ADJUSTED_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_ADJUSTED_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_REVENUE_EX_GRANTS.schema, cells=data.C4_MKT_FIN_REVENUE_EX_GRANTS.cells)
def c4_mkt_fin_revenue_ex_grants(*, dsa_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute revenue excluding grants in nominal USD millions on the C4 market-financing stress sheet.

    Convert the baseline government revenue ratio (excluding grants) into a nominal USD amount by applying it to baseline nominal GDP along the debt-service time axis.

    Args:
        dsa_ext_nominal_gdp_million_of_us_dollars: Baseline nominal GDP series, in millions of US dollars, indexed over catalog time coordinates.
        dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp: Baseline government revenues excluding grants series, expressed in percent of GDP, indexed over catalog time coordinates.
        input3_input_3_macro_current_account: Input 3 macro current account series providing the validated macro projection context used by the sheet.
        input3_old_debt_service: Input 3 old debt service series whose time axis supplies the evaluation and domain grid for the output.

    Returns:
        A data series of floats (or blank string/None placeholders) giving revenue excluding grants in millions of US dollars over the bound time axis.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], 100), dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]))

    return data.C4_MKT_FIN_REVENUE_EX_GRANTS.collect(evaluate(formula, data.C4_MKT_FIN_REVENUE_EX_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_REVENUE_EX_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_REVISED_PV_DEBT_TO_EXPORTS.schema, cells=data.C4_MKT_FIN_REVISED_PV_DEBT_TO_EXPORTS.cells)
def c4_mkt_fin_revised_pv_debt_to_exports(*, c4_mkt_fin_pv_debt_adjustments: data.Series[float | str | None], c4_market_path_baseline_pv_of_debt: data.Series[float | str | None], c4_market_path_exports: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes revised PV of debt-to-exports ratios for the C4 market-financing stress path.

    Supports the C4 market-financing stress sheet by combining baseline PV of debt with PV debt adjustments, scaling by exports, and expressing the result as a percentage.

    Args:
        c4_mkt_fin_pv_debt_adjustments: A data.Series[float | str | None] of per-period PV-of-debt adjustments added to the C4 baseline PV of debt.
        c4_market_path_baseline_pv_of_debt: A data.Series[float | str | None] of baseline PV-of-debt values for the C4 market path.
        c4_market_path_exports: A data.Series[float | str | None] of exports for the C4 market path, used as the denominator.
        input3_old_debt_service: A data.Input3OldDebtService whose TIME_PERIOD axis supplies the projection coordinates and whose schema is validated before evaluation.

    Returns:
        A data.Series[float | str | None] of revised PV of debt-to-exports ratios, expressed as percentages, aligned to the TIME_PERIOD coordinates from the old-debt-service input.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(xl_add(c4_market_path_baseline_pv_of_debt['C4_Market', time_period], c4_mkt_fin_pv_debt_adjustments[time_period]), c4_market_path_exports['C4_Market', time_period]), 100))

    return data.C4_MKT_FIN_REVISED_PV_DEBT_TO_EXPORTS.collect(evaluate(formula, data.C4_MKT_FIN_REVISED_PV_DEBT_TO_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_REVISED_PV_DEBT_TO_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_DSR_EXPORTS_STRESS.schema, cells=data.C4_MKT_FIN_DSR_EXPORTS_STRESS.cells)
def c4_mkt_fin_dsr_exports_stress(*, c4_market_path_exports: data.Series[float | str | None], c4_mkt_fin_adjusted_debt_service: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the C4 market-financing stress ratio of adjusted debt service to exports.

    Derive the stress-test debt service-to-exports percentage by dividing adjusted debt service by C4 market-path exports and scaling by 100 on the market-financing stress sheet.

    Args:
        c4_market_path_exports: Market-path exports series over catalog coordinates, with the C4_Market path selected at each TIME_PERIOD.
        c4_mkt_fin_adjusted_debt_service: Adjusted debt service series over catalog coordinates, aligned to the same TIME_PERIOD axis.
        input3_old_debt_service: Input 3 old debt service series whose TIME_PERIOD domain anchors evaluation and collection of the result.

    Returns:
        A data.Series[float | str | None] containing the computed debt service-to-exports stress ratio, indexed over the TIME_PERIOD coordinates supplied by the Input 3 old debt service series.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(c4_mkt_fin_adjusted_debt_service[time_period], c4_market_path_exports['C4_Market', time_period]), 100))

    return data.C4_MKT_FIN_DSR_EXPORTS_STRESS.collect(evaluate(formula, data.C4_MKT_FIN_DSR_EXPORTS_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_DSR_EXPORTS_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.C4_MKT_FIN_DSR_REVENUE_STRESS.schema, cells=data.C4_MKT_FIN_DSR_REVENUE_STRESS.cells)
def c4_mkt_fin_dsr_revenue_stress(*, c4_mkt_fin_adjusted_debt_service: data.Series[float | str | None], c4_mkt_fin_revenue_ex_grants: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the C4 market-financing stress-test debt-service-to-revenue ratio.

    Derive the stress-test ratio by dividing adjusted debt service by revenue excluding grants and scaling by 100 over catalog time coordinates.

    Args:
        c4_mkt_fin_adjusted_debt_service: Adjusted debt service as a named-axis data series over catalog coordinates, containing per-period numeric, string, or null entries.
        c4_mkt_fin_revenue_ex_grants: Revenue excluding grants as a named-axis data series over catalog coordinates, aligned to the same time periods.
        input3_old_debt_service: Input 3 old debt service structure supplying the TIME_PERIOD axis and coordinate domain used to evaluate the ratio.

    Returns:
        A named-axis data series of per-period debt-service-to-revenue stress ratios as float, string, or null values over the TIME_PERIOD coordinates from the Input 3 old debt service domain.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(c4_mkt_fin_adjusted_debt_service[time_period], c4_mkt_fin_revenue_ex_grants[time_period]), 100))

    return data.C4_MKT_FIN_DSR_REVENUE_STRESS.collect(evaluate(formula, data.C4_MKT_FIN_DSR_REVENUE_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.C4_MKT_FIN_DSR_REVENUE_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(key=(), domain=None, cells=data.CI_SUMMARY_DEBT_CARRYING_CAPACITY_CELLS)
def ci_summary_debt_carrying_capacity(*, lookup_ida_terms_new: str, input6_standard_size_threshold_mode: Literal["New", "Old"], ci_summary_performance_policy: str | int | float | bool, ci_summary_debt_carrying_capacity_vintage_reconciled: str | int | float | bool) -> str | int | float | bool:
    """Return the effective debt-carrying-capacity classification for the IDA terms threshold mode.

    Selects between the vintage-reconciled capacity and performance-policy value according to whether the standard-size threshold mode matches the new IDA terms label.

    Args:
        lookup_ida_terms_new: Scalar IDA terms identifier used as the comparison value for the active standard-size threshold mode.
        input6_standard_size_threshold_mode: Scalar threshold-mode literal, either 'New' or 'Old', that determines which capacity source is selected.
        ci_summary_performance_policy: Scalar performance-policy value, typically the weak/medium/strong classification used for applicable thresholds, returned when the threshold mode does not match the IDA terms label.
        ci_summary_debt_carrying_capacity_vintage_reconciled: Scalar vintage-reconciled debt-carrying-capacity value, typically the weak/medium/strong classification used for applicable thresholds, returned when the threshold mode matches the IDA terms label.

    Returns:
        Scalar value selected from the vintage-reconciled capacity or performance policy, returned as a string measure when conversion succeeds, or the workbook error code string when an XlError occurs.
    """
    try:
        return as_measure((ci_summary_debt_carrying_capacity_vintage_reconciled if xl_bool(xl_eq(input6_standard_size_threshold_mode, lookup_ida_terms_new)) else ci_summary_performance_policy), 'str')
    except XlError as error:
        return error.code

