@publish(data.BASELINE_PUB_RESIDUAL.schema, cells=data.BASELINE_PUB_RESIDUAL.cells)
def baseline_pub_residual(*, baseline_pub_change_in_public_sector_debt: data.Series[float | str | None], baseline_pub_identified_debt_creating_flows: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes the baseline public-sector residual as the difference between the change in public-sector debt and identified debt-creating flows.

    Provides the residual series used in the baseline public-debt projection, aligned to the projection-year grid from the old-debt-service input.

    Args:
        baseline_pub_change_in_public_sector_debt: A data.Series[float | str | None] over TIME_PERIOD containing the baseline change in public-sector debt.
        baseline_pub_identified_debt_creating_flows: A data.Series[float | str | None] over TIME_PERIOD containing baseline identified debt-creating flows.
        input3_old_debt_service: A data.Input3OldDebtService typed input dataclass whose TIME_PERIOD axis defines the projection-year grid and whose schema is validated before evaluation.

    Returns:
        A data.Series[float | str | None] of residuals (baseline public-sector debt change minus identified debt-creating flows), keyed by projection years from row 7.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_sub(baseline_pub_change_in_public_sector_debt[time_period], baseline_pub_identified_debt_creating_flows[time_period]))

    return data.BASELINE_PUB_RESIDUAL.collect(evaluate(formula, data.BASELINE_PUB_RESIDUAL.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.BASELINE_PUB_RESIDUAL.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_GDP_RATIO.schema, cells=data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_GDP_RATIO.cells)
def baseline_pub_pv_of_public_debt_gdp_ratio(*, baseline_pub_nominal_gdp_lc: data.Series[float | str | None], macro_debt_total_public_domestic_debt: data.Series[float | str | None], macro_debt_pv_of_public_sector_ext_debt_end_of_period: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the baseline public PV of public debt-to-GDP ratio path.

    Derive the public-debt present-value ratio used in LIC-DSF baseline and stress-chart outputs.

    Args:
        baseline_pub_nominal_gdp_lc: Nominal GDP in local currency for the baseline scenario, as a named-axis series over projection years; used as the ratio denominator.
        macro_debt_total_public_domestic_debt: Total public domestic debt stock, as a named-axis series over catalog coordinates, added to external PV debt in the numerator.
        macro_debt_pv_of_public_sector_ext_debt_end_of_period: End-of-period present value of public-sector external debt, as a named-axis series over catalog coordinates, added to domestic debt in the numerator.
        input3_input_3_macro_current_account: Input 3 macro current-account block, a typed data input structure validated against its schema and used to align projection coordinates.
        input3_old_debt_service: Input 3 old debt-service block, a typed data input structure whose TIME_PERIOD domain supplies the output projection-year grid.

    Returns:
        A data.Series[float | str | None] of PV of public debt-to-GDP ratios, expressed in percent and keyed by projection years from row 7; entries may be error strings or blanks where required numeric inputs are unavailable.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 20:
            return as_measure((xl_mul(xl_div(xl_add(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], macro_debt_total_public_domestic_debt[time_period]), baseline_pub_nominal_gdp_lc[time_period]), 100) if xl_bool(xl_isnumber(lambda: macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period])) else '...'))
        return as_measure((0 if xl_bool(xl_lt((xl_mul(xl_div(xl_add(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], macro_debt_total_public_domestic_debt[time_period]), baseline_pub_nominal_gdp_lc[time_period]), 100) if xl_bool(xl_isnumber(lambda: macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period])) else '...'), 0)) else (xl_mul(xl_div(xl_add(macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period], macro_debt_total_public_domestic_debt[time_period]), baseline_pub_nominal_gdp_lc[time_period]), 100) if xl_bool(xl_isnumber(lambda: macro_debt_pv_of_public_sector_ext_debt_end_of_period[time_period])) else '...')))

    return data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_GDP_RATIO.collect(evaluate(formula, data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_GDP_RATIO.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_GDP_RATIO.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_REVENUE_GRANTS_RATIO.schema, cells=data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_REVENUE_GRANTS_RATIO.cells)
def baseline_pub_pv_of_public_debt_revenue_grants_ratio(*, baseline_pub_revenue_grants: data.Series[float | str | None], baseline_pub_pv_of_public_debt_gdp_ratio: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the baseline public PV of public debt-to-revenue and grants ratio series.

    Derive the baseline public ratio by dividing the PV of public debt-to-GDP ratio by public revenue and grants and scaling to a percentage, preserving non-numeric entries as placeholder text.

    Args:
        baseline_pub_revenue_grants: Typed data series of baseline public revenue and grants over catalog coordinates, providing the denominator values for each projection year.
        baseline_pub_pv_of_public_debt_gdp_ratio: Typed data series of the baseline public PV of public debt-to-GDP ratio, providing the numerator values used in the ratio calculation.
        input3_input_3_macro_current_account: Typed Input 3 macro current-account series carrying catalog-coordinate structure used to validate and align the computation.
        input3_old_debt_service: Typed Input 3 old-debt-service series whose TIME_PERIOD axis defines the projection-year domain over which the ratio is evaluated.

    Returns:
        A typed data series of float, string, or None keyed by projection years from row 7, holding the baseline public PV of public debt-to-revenue and grants ratio or an ellipsis placeholder where the numerator is non-numeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_div(baseline_pub_pv_of_public_debt_gdp_ratio[time_period], baseline_pub_revenue_grants[time_period]), 100) if xl_bool(xl_isnumber(lambda: baseline_pub_pv_of_public_debt_gdp_ratio[time_period])) else '…'))

    return data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_REVENUE_GRANTS_RATIO.collect(evaluate(formula, data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_REVENUE_GRANTS_RATIO.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_REVENUE_GRANTS_RATIO.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.BASELINE_PUB_DEBT_SERVICE_REVENUE_GRANTS_RATIO.schema, cells=data.BASELINE_PUB_DEBT_SERVICE_REVENUE_GRANTS_RATIO.cells)
def baseline_pub_debt_service_revenue_grants_ratio(*, macro_debt_public_domestic_st: data.Series[float | str | None], macro_debt_total_mlt_public_domestic_debt_amortization_debt: data.Series[float | str | None], macro_debt_public_sector_revenues_including_grants: data.Series[float | str | None], macro_debt_public_sector_interest_expenditure: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the baseline public debt service-to-revenue-and-grants ratio series.

    Evaluate the public-sector debt service burden relative to revenues including grants across projection years using authored coordinate identities.

    Args:
        macro_debt_public_domestic_st: Typed data series of public domestic short-term debt over catalog coordinates, with numeric cells or string/blank placeholders.
        macro_debt_total_mlt_public_domestic_debt_amortization_debt: Typed data series of total medium-and-long-term public domestic debt amortization over catalog coordinates, with numeric cells or string/blank placeholders.
        macro_debt_public_sector_revenues_including_grants: Typed data series of public-sector revenues including grants over catalog coordinates, used as the ratio denominator.
        macro_debt_public_sector_interest_expenditure: Typed data series of public-sector interest expenditure over catalog coordinates, contributing to the debt service numerator.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Typed data series of the national-currency-per-U.S.-dollar exchange rate over catalog coordinates, used to convert foreign-currency items.
        macro_debt_main_assumptions_us_dollars_by_year_6: Typed data series of main assumptions in U.S. dollars by year (series 6) over catalog coordinates, contributing to the debt service numerator.
        input3_input_3_macro_current_account: Input 3 macro current-account dataclass whose TIME_PERIOD axis supplies the prior-period coordinate for lagged domestic short-term debt lookups.
        input3_old_debt_service: Input 3 old debt service dataclass whose TIME_PERIOD axis defines the evaluation domain and year coordinates for the returned series.

    Returns:
        Typed data series of floats or string/blank placeholders containing the baseline public debt service-to-revenue-and-grants ratio, keyed by projection years from row 7.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((0 if xl_bool(xl_lt(xl_mul(xl_div(xl_add(xl_add(macro_debt_public_sector_interest_expenditure[time_period], macro_debt_public_domestic_st[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), xl_mul(xl_add(macro_debt_total_mlt_public_domestic_debt_amortization_debt[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])), macro_debt_public_sector_revenues_including_grants[time_period]), 100), 0)) else xl_mul(xl_div(xl_add(xl_add(macro_debt_public_sector_interest_expenditure[time_period], macro_debt_public_domestic_st[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), xl_mul(xl_add(macro_debt_total_mlt_public_domestic_debt_amortization_debt[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])), macro_debt_public_sector_revenues_including_grants[time_period]), 100)))

    return data.BASELINE_PUB_DEBT_SERVICE_REVENUE_GRANTS_RATIO.collect(evaluate(formula, data.BASELINE_PUB_DEBT_SERVICE_REVENUE_GRANTS_RATIO.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.BASELINE_PUB_DEBT_SERVICE_REVENUE_GRANTS_RATIO.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.BASELINE_PUB_GROSS_FINANCING_NEED.schema, cells=data.BASELINE_PUB_GROSS_FINANCING_NEED.cells)
def baseline_pub_gross_financing_need(*, baseline_pub_nominal_gdp_lc: data.Series[float | str | None], macro_debt_gross_financing_need: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes baseline public gross financing need as a percentage of nominal GDP across projection periods.

    Derives the baseline public gross financing need series for use in debt-sustainability calculations.

    Args:
        baseline_pub_nominal_gdp_lc: Named-axis series of baseline public nominal GDP in local currency, aligned over catalog coordinates and used as the denominator in the financing-need ratio.
        macro_debt_gross_financing_need: Named-axis series of macro-debt gross financing need amounts, aligned over catalog coordinates and divided by nominal GDP to form the percentage ratio.
        input3_input_3_macro_current_account: Validated macro current-account input bundle supplying catalog-domain metadata required by the calculation context.
        input3_old_debt_service: Validated old-debt-service input bundle whose TIME_PERIOD axis defines the projection-year domain on which the result is collected.

    Returns:
        Named-axis series of baseline public gross financing need as a percentage of nominal GDP, keyed by projection TIME_PERIOD; nonnumeric or undefined calculations yield string placeholder values.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
