@publish(data.BASELINE_PUB_GROSS_FINANCING_NEED_BY_YEAR.schema, cells=data.BASELINE_PUB_GROSS_FINANCING_NEED_BY_YEAR.cells)
def baseline_pub_gross_financing_need_by_year(*, baseline_pub_gross_financing_need: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Rescales the baseline public gross financing need from percent of GDP into local-currency amounts for each projection year.

    Express the percent-of-GDP gross financing need in currency units by multiplying it by nominal GDP in local currency, keeping the aligned projection-year axis.

    Args:
        baseline_pub_gross_financing_need: Named-axis series of baseline public gross financing need expressed as a percent of GDP for each projection year.
        baseline_pub_nominal_gdp_lc: Named-axis series of baseline nominal GDP in local currency providing the per-year scale factor.
        input3_input_3_macro_current_account: Macro current-account input group supplying the catalog coordinates that anchor the projection grid.
        input3_old_debt_service: Old debt service input group whose TIME_PERIOD axis defines the projection years the formula is evaluated over.

    Returns:
        Named-axis series of baseline public gross financing need in local currency, keyed by projection TIME_PERIOD.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(baseline_pub_gross_financing_need[time_period], 100), baseline_pub_nominal_gdp_lc[time_period]))

    return data.BASELINE_PUB_GROSS_FINANCING_NEED_BY_YEAR.collect(evaluate(formula, data.BASELINE_PUB_GROSS_FINANCING_NEED_BY_YEAR.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.BASELINE_PUB_GROSS_FINANCING_NEED_BY_YEAR.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_BASELINE.schema, cells=data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_BASELINE.cells)
def baseline_pub_debt_service_in_lcu_baseline(*, macro_debt_public_domestic_st: data.Series[float | str | None], macro_debt_total_mlt_public_domestic_debt_amortization_debt: data.Series[float | str | None], macro_debt_public_sector_interest_expenditure: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], macro_debt_main_assumptions_us_dollars_by_year_6: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes baseline public debt service in local currency units for each projection year.

    Combines interest expense, lagged short-term domestic debt, amortization, and exchange-rate-adjusted USD debt-service components into a baseline public debt-service series.

    Args:
        macro_debt_public_domestic_st: Named-axis series of public domestic short-term debt by projection year, used at a one-period lag in the debt-service formula.
        macro_debt_total_mlt_public_domestic_debt_amortization_debt: Named-axis series of total medium- and long-term public domestic debt amortization by projection year.
        macro_debt_public_sector_interest_expenditure: Named-axis series of public sector interest expenditure by projection year.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Named-axis series of the national-currency-per-U.S.-dollar exchange rate by projection year.
        macro_debt_main_assumptions_us_dollars_by_year_6: Named-axis series of the year-6 U.S.-dollar main-assumptions debt-service component.
        input3_input_3_macro_current_account: Typed input dataclass supplying the macro current-account TIME_PERIOD axis used for prior-period alignment.
        input3_old_debt_service: Typed input dataclass supplying the old-debt-service TIME_PERIOD domain and required coordinate binding for the output series.

    Returns:
        A named-axis data.Series[float | str | None] of baseline public debt service in LCU, keyed by projection years starting from row 7.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(xl_add(macro_debt_public_sector_interest_expenditure[time_period], macro_debt_public_domestic_st[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), xl_mul(xl_add(macro_debt_total_mlt_public_domestic_debt_amortization_debt[time_period], macro_debt_main_assumptions_us_dollars_by_year_6[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])))

    return data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_BASELINE.collect(evaluate(formula, data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_LEVEL_IN_LCU_BASELINE.schema, cells=data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_LEVEL_IN_LCU_BASELINE.cells)
def baseline_pub_pv_of_public_debt_level_in_lcu_baseline(*, baseline_pub_pv_of_public_debt_gdp_ratio: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Convert the baseline public PV-of-debt-to-GDP ratio into a public debt level in local currency.

    Scale the baseline PV of public debt ratio by baseline nominal GDP in LCU and divide by 100 to obtain the corresponding PV debt level series used in the public DSA baseline.

    Args:
        baseline_pub_pv_of_public_debt_gdp_ratio: Baseline PV of public debt as a percent-of-GDP ratio, a named-axis series over catalog coordinates whose values may be numeric, text, or missing.
        baseline_pub_nominal_gdp_lc: Baseline nominal GDP in local currency, a named-axis series over catalog coordinates whose values may be numeric, text, or missing.
        input3_input_3_macro_current_account: Input 3 macro current account assumptions, a typed Input3Input3MacroCurrentAccount dataclass of series supplying the macro projection context.
        input3_old_debt_service: Input 3 old debt service, an Input3OldDebtService series whose TIME_PERIOD axis defines the projection-year grid the result is evaluated over.

    Returns:
        A named-axis data.Series[float | str | None] of the PV of public debt level in LCU baseline, keyed by projection years from row 7.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_div(xl_mul(baseline_pub_pv_of_public_debt_gdp_ratio[time_period], baseline_pub_nominal_gdp_lc[time_period]), 100))

    return data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_LEVEL_IN_LCU_BASELINE.collect(evaluate(formula, data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_LEVEL_IN_LCU_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_LEVEL_IN_LCU_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_GDP_RATIO_B3_EXPORTS.schema, cells=data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_GDP_RATIO_B3_EXPORTS.cells)
def baseline_pub_pv_of_public_debt_gdp_ratio_b3_exports(*, dsa_ext_pv_of_additional_borrowing: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], baseline_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], baseline_pub_pv_of_public_debt_level_in_lcu_baseline: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the baseline public PV of public debt-to-GDP ratio for the B3-minus-exports series.

    Derive the projection-year public debt ratio by combining baseline PV debt, B3 additional borrowing converted to local currency, and baseline nominal GDP.

    Args:
        dsa_ext_pv_of_additional_borrowing: Typed data series of external PV of additional borrowing values, including the B3 scenario used in the numerator adjustment.
        baseline_pub_nominal_gdp_lc: Typed data series of baseline public nominal GDP in local currency over the projection horizon.
        baseline_pub_exchange_rate_lc_per_us_dollar: Typed data series of the baseline public exchange rate expressed as local currency per US dollar.
        baseline_pub_pv_of_public_debt_level_in_lcu_baseline: Typed data series of the baseline public PV of public debt level in local currency units.
        input3_input_3_macro_current_account: Input 3 macro current-account dataclass containing the typed series used for schema validation and coordinate alignment.
        input3_old_debt_service: Input 3 old debt-service dataclass containing the TIME_PERIOD axis that defines the output projection domain.

    Returns:
        A data.Series[float | str | None] keyed by projection years from row 7, containing the baseline-public PV of public debt-to-GDP ratio for the B3-minus-exports series.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(xl_add(baseline_pub_pv_of_public_debt_level_in_lcu_baseline[time_period], xl_mul(dsa_ext_pv_of_additional_borrowing['B3', time_period], baseline_pub_exchange_rate_lc_per_us_dollar[time_period])), baseline_pub_nominal_gdp_lc[time_period]), 100))

    return data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_GDP_RATIO_B3_EXPORTS.collect(evaluate(formula, data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_GDP_RATIO_B3_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.BASELINE_PUB_PV_OF_PUBLIC_DEBT_GDP_RATIO_B3_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service))

