@publish(data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_B3_EXPORT_STRESS_TEST.schema, cells=data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_B3_EXPORT_STRESS_TEST.cells)
def baseline_pub_debt_service_in_lcu_b3_export_stress_test(*, dsa_ext_additional_debt_service_stress: data.Series[float | str | None], baseline_pub_debt_service_in_lcu_baseline: data.Series[float | str | None], leftover_exchange_rate_pa: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute public debt service in LCU under the B3 export stress test.

    Derive the stressed baseline public debt service path by adding B3 stress debt service converted at the baseline exchange rate to the baseline series.

    Args:
        dsa_ext_additional_debt_service_stress: Typed data series of additional debt service under the B3 export stress scenario, indexed consistently with the projection-year coordinate.
        baseline_pub_debt_service_in_lcu_baseline: Typed data series of baseline public debt service in local currency units, indexed by projection year.
        leftover_exchange_rate_pa: Typed data series of exchange-rate values for the baseline scenario, used to convert stress debt service into local currency units.
        input3_old_debt_service: Typed Input 3 old-debt-service structure that supplies schema validation and the projection-year time axis used for binding.

    Returns:
        Typed data series of baseline public debt service in LCU under the B3 export stress test, keyed by projection years from row 7.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(baseline_pub_debt_service_in_lcu_baseline[time_period], xl_mul(dsa_ext_additional_debt_service_stress['B3', time_period], leftover_exchange_rate_pa['Baseline', time_period])))

    return data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_B3_EXPORT_STRESS_TEST.collect(evaluate(formula, data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_B3_EXPORT_STRESS_TEST.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_B3_EXPORT_STRESS_TEST.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_B4_OTHER_FLOWS_STRESS_TEST.schema, cells=data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_B4_OTHER_FLOWS_STRESS_TEST.cells)
def baseline_pub_debt_service_in_lcu_b4_other_flows_stress_test(*, leftover_exchange_rate_pa: data.Series[float | str | None], dsa_ext_additional_debt_service_stress: data.Series[float | str | None], baseline_pub_debt_service_in_lcu_baseline: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute baseline public debt service in LCU under the B4 other-flows stress test.

    Add B4 other-flow debt service, converted at the baseline exchange rate, to the baseline local-currency debt service path.

    Args:
        leftover_exchange_rate_pa: Baseline exchange-rate series used to convert additional debt service into local currency, indexed by projection year.
        dsa_ext_additional_debt_service_stress: Additional external debt service under the B4 other-flows stress scenario, in foreign currency, indexed by projection year.
        baseline_pub_debt_service_in_lcu_baseline: Baseline public debt service path already expressed in local currency, indexed by projection year.
        input3_old_debt_service: Input 3 old-debt-service series supplying the projection-year domain used to align the calculation.

    Returns:
        A data.Series[float | str | None] of stressed public debt service in local currency, keyed by projection years.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_add(baseline_pub_debt_service_in_lcu_baseline[time_period], xl_mul(None, leftover_exchange_rate_pa['Baseline', time_period])))
        return as_measure(xl_add(baseline_pub_debt_service_in_lcu_baseline[time_period], xl_mul(dsa_ext_additional_debt_service_stress['B4', time_period], leftover_exchange_rate_pa['Baseline', time_period])))

    return data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_B4_OTHER_FLOWS_STRESS_TEST.collect(evaluate(formula, data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_B4_OTHER_FLOWS_STRESS_TEST.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_B4_OTHER_FLOWS_STRESS_TEST.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_C4_MARKET_STRESS_TEST.schema, cells=data.BASELINE_PUB_DEBT_SERVICE_IN_LCU_C4_MARKET_STRESS_TEST.cells)
def baseline_pub_debt_service_in_lcu_c4_market_stress_test(*, leftover_exchange_rate_pa: data.Series[float | str | None], c4_mkt_fin_debt_service_adjustment: data.Series[float | str | None], baseline_pub_debt_service_in_lcu_baseline: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute market-stress baseline public debt service in local currency.

    Combines baseline public debt service with the C4 market-financing adjustment scaled by the leftover exchange rate to produce the market-stress debt-service path.

    Args:
        leftover_exchange_rate_pa: Typed data series of leftover exchange-rate values over catalog coordinates, including the 'Baseline' scenario label and projection-year TIME_PERIOD keys.
        c4_mkt_fin_debt_service_adjustment: Typed data series of C4 market-financing debt-service adjustments aligned to projection-year TIME_PERIOD coordinates.
        baseline_pub_debt_service_in_lcu_baseline: Typed data series of baseline public debt service in local currency, keyed by projection-year TIME_PERIOD coordinates.
        input3_old_debt_service: Typed Input3OldDebtService dataclass of series whose TIME_PERIOD axis defines the projection-year domain for evaluation and output collection.

    Returns:
        Typed data series of float, string, or None values giving debt service in LCU under the C4 market stress test (baseline, public), keyed by projection years from row 7.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
