@publish(data.CUSTOM_PUB_USD_DISCOUNT_RATE_BY_YEAR.schema, cells=data.CUSTOM_PUB_USD_DISCOUNT_RATE_BY_YEAR.cells)
def custom_pub_usd_discount_rate_by_year(*, customized_public_external_mlt_disbursement_profile: float | str, custom_pub_avg_maturity_incl_grace_period_by_year: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the customized public USD discount rate by projection year from the customized public external MLT disbursement profile and average maturity including grace period.

    Derive the customized-scenario public USD discount rate series used by the LIC-DSF public debt projections.

    Args:
        customized_public_external_mlt_disbursement_profile: Customized public external MLT disbursement profile scalar, used as the initial value for the 2024 projection year in the discount-rate recursion.
        custom_pub_avg_maturity_incl_grace_period_by_year: Custom public average maturity including grace period, a typed series over catalog coordinates keyed by projection year; each value is subtracted from the prior-year discount rate, or from the initial profile in 2024, to obtain the current-year rate.

    Returns:
        Typed `data.Series[int | str | None]` containing the USD Discount rate (Customized Scenario - public), keyed by projection years from row 60, with recursive values computed from the prior-year rate or the initial 2024 disbursement-profile scalar minus the matching maturity series value.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(xl_sub(customized_public_external_mlt_disbursement_profile, custom_pub_avg_maturity_incl_grace_period_by_year[time_period]), 'int')
        return as_measure(xl_sub(custom_pub_usd_discount_rate_by_year[time_period - 1], custom_pub_avg_maturity_incl_grace_period_by_year[time_period]), 'int')

    custom_pub_usd_discount_rate_by_year = CoordinateReader('custom_pub_usd_discount_rate_by_year', data.CUSTOM_PUB_USD_DISCOUNT_RATE_BY_YEAR.required, formula)
    return data.CUSTOM_PUB_USD_DISCOUNT_RATE_BY_YEAR.collect((coord, custom_pub_usd_discount_rate_by_year[coord]) for coord in data.CUSTOM_PUB_USD_DISCOUNT_RATE_BY_YEAR.required)

@publish(data.CUSTOM_PUB_AVG_MATURITY_INCL_GRACE_PERIOD_BY_YEAR.schema, cells=data.CUSTOM_PUB_AVG_MATURITY_INCL_GRACE_PERIOD_BY_YEAR.cells)
def custom_pub_avg_maturity_incl_grace_period_by_year(*, customized_public_external_mlt_disbursement_profile: float | str, custom_pub_period: data.Series[int | str | None], custom_pub_avg_grace_period: int | str, custom_pub_avg_maturity_incl_grace_period: int | str) -> data.Series[int | str | None]:
    """Compute the customized-scenario public external average maturity including grace period for each projection year.

    Derive the per-year average-maturity-inclusive-of-grace-period series used by the customized public external debt scenario.

    Args:
        customized_public_external_mlt_disbursement_profile: Scalar medium- and long-term external disbursement profile amount for the customized public scenario.
        custom_pub_period: Named-axis series of projection periods (with optional blanks) that sets the customized public scenario timeline relative to the 2024 base year.
        custom_pub_avg_grace_period: Scalar average grace period, in years, applied before customized public amortization begins.
        custom_pub_avg_maturity_incl_grace_period: Scalar average maturity, in years, including the grace period, for the customized public scenario.

    Returns:
        A data.Series[int | str | None] of average maturity including grace period for the customized public scenario, keyed by projection years from row 60.
    """
    def formula(time_period: int) -> int | str | None:
        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(custom_pub_period[time_period], custom_pub_period[2024]), 1), custom_pub_avg_grace_period)) else (xl_div(customized_public_external_mlt_disbursement_profile, xl_sub(custom_pub_avg_maturity_incl_grace_period, custom_pub_avg_grace_period)) if xl_bool(xl_lt(xl_sub(xl_sub(custom_pub_period[time_period], custom_pub_period[2024]), 1), custom_pub_avg_maturity_incl_grace_period)) else 0)), 'int')

    return data.CUSTOM_PUB_AVG_MATURITY_INCL_GRACE_PERIOD_BY_YEAR.collect(evaluate(formula, data.CUSTOM_PUB_AVG_MATURITY_INCL_GRACE_PERIOD_BY_YEAR.required))

@publish(data.CUSTOM_PUB_AVG_GRACE_PERIOD_BY_YEAR.schema, cells=data.CUSTOM_PUB_AVG_GRACE_PERIOD_BY_YEAR.cells)
def custom_pub_avg_grace_period_by_year(*, custom_pub_avg_nominal_interest_rate_new_borrowing_usd: float | str, custom_pub_usd_discount_rate_by_year: data.Series[int | str | None]) -> data.Series[float | str | None]:
    """Compute customized public average grace period by projection year.

    Derive the customized-scenario public average grace-period series from the nominal interest rate on new borrowing and the per-year USD discount-rate series.

    Args:
        custom_pub_avg_nominal_interest_rate_new_borrowing_usd: Customized-scenario nominal interest rate on new external public borrowing; a scalar float or string placeholder.
        custom_pub_usd_discount_rate_by_year: Customized-scenario USD discount-rate series keyed by projection year; each entry is an integer, string placeholder, or missing value.

    Returns:
        A typed series of customized-scenario public average grace-period values keyed by projection years from row 60, yielding a float, string placeholder, or missing value per year.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(custom_pub_usd_discount_rate_by_year[time_period - 1], custom_pub_avg_nominal_interest_rate_new_borrowing_usd))

    return data.CUSTOM_PUB_AVG_GRACE_PERIOD_BY_YEAR.collect(evaluate(formula, data.CUSTOM_PUB_AVG_GRACE_PERIOD_BY_YEAR.required))

@publish(data.CUSTOM_PUB_TOTAL_DEBT_SERVICE.schema, cells=data.CUSTOM_PUB_TOTAL_DEBT_SERVICE.cells)
def custom_pub_total_debt_service(*, custom_pub_avg_maturity_incl_grace_period_by_year: data.Series[int | str | None], custom_pub_avg_grace_period_by_year: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute customized-scenario public total debt service from per-year maturity and grace-period series.

    Derive the customized public total debt service series used in the public DSA scenario ladder.

    Args:
        custom_pub_avg_maturity_incl_grace_period_by_year: Per-year custom public average maturity including grace period, as a data.Series over projection-year coordinates with integer, string, or None values.
        custom_pub_avg_grace_period_by_year: Per-year custom public average grace period, as a data.Series over projection-year coordinates with float, string, or None values.

    Returns:
        A data.Series[float | str | None] keyed by projection years from row 60, containing customized public total debt service.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(custom_pub_avg_maturity_incl_grace_period_by_year[time_period], custom_pub_avg_grace_period_by_year[time_period]))

    return data.CUSTOM_PUB_TOTAL_DEBT_SERVICE.collect(evaluate(formula, data.CUSTOM_PUB_TOTAL_DEBT_SERVICE.required))

@publish(key=(), domain=None, cells=data.CUSTOM_PUB_PV_DEBT_CELLS)
def custom_pub_pv_debt(*, custom_pub_usd_discount_rate_by_year: data.Series[int | str | None], custom_pub_total_debt_service: data.Series[float | str | None], custom_pub_avg_nominal_interest_rate_new_borrowing_usd: float | str, custom_pub_usd_discount_rate: float | str) -> float | str:
    """Compute the present value of public debt for the customized scenario.

    Return the customized public-debt PV using either the 2024 discount rate or an NPV of projected debt service, depending on whether the new-borrowing interest rate exceeds the discount rate.

    Args:
        custom_pub_usd_discount_rate_by_year: Year-indexed `data.Series[int | str | None]` of USD discount rates; its 2024 element is returned directly when the new-borrowing rate is above the discount rate.
        custom_pub_total_debt_service: `data.Series[float | str | None]` of total debt service over the catalog time axis; values from 2025 through 2073 are discounted in the fallback branch.
        custom_pub_avg_nominal_interest_rate_new_borrowing_usd: Scalar `float | str` average nominal interest rate on new USD borrowing; compared with the discount rate to choose between the direct-rate and NPV calculations.
        custom_pub_usd_discount_rate: Scalar `float | str` USD discount rate; used as the NPV rate when the new-borrowing rate does not exceed it.

    Returns:
        `float | str`: present value of customized public debt as a scalar float, or an Excel error-code string if the underlying computation raises `XlError`.
    """
    _custom_pub_pv_debt_table_0 = view(custom_pub_total_debt_service, cols=span(data.TIME_PERIOD_AXIS, 2025, 2073))
    try:
        return as_measure((custom_pub_usd_discount_rate_by_year[2024] if xl_bool(xl_gt(custom_pub_avg_nominal_interest_rate_new_borrowing_usd, custom_pub_usd_discount_rate)) else xl_npv(custom_pub_usd_discount_rate, _custom_pub_pv_debt_table_0)))
    except XlError as error:
        return error.code

@publish(data.CUSTOM_PUB_DOMESTIC_MLT_DEBT.schema, cells=data.CUSTOM_PUB_DOMESTIC_MLT_DEBT.cells)
def custom_pub_domestic_mlt_debt(*, custom_pub_inflation_gdp_deflator: data.Series[float | str | None], custom_pub_avg_real_interest_rate_new_borrowing_by_year: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute customized-scenario public domestic medium- and long-term debt by projection year.

    Combines per-year inflation/GDP deflator and average real interest rate on new borrowing, aligned to Input 3 old debt service years, to produce the domestic MLT debt series.

    Args:
        custom_pub_inflation_gdp_deflator: Customized-scenario public inflation/GDP deflator series keyed by projection year, with numeric, placeholder-string, or missing values per year.
        custom_pub_avg_real_interest_rate_new_borrowing_by_year: Customized-scenario public average real interest rate on new borrowing by year, as a projection-year series of numeric, string, or missing values.
        input3_old_debt_service: Input 3 old debt service dataclass of series; its TIME_PERIOD axis supplies the projection-year coordinates used to align the calculated debt series.

    Returns:
        Customized-scenario public domestic MLT debt as a data.Series[float | str | None] keyed by projection years from row 7, with numeric, placeholder-string, or missing values per year.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(custom_pub_avg_real_interest_rate_new_borrowing_by_year[time_period], custom_pub_inflation_gdp_deflator[time_period]))

    return data.CUSTOM_PUB_DOMESTIC_MLT_DEBT.collect(evaluate(formula, data.CUSTOM_PUB_DOMESTIC_MLT_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CUSTOM_PUB_DOMESTIC_MLT_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.CUSTOM_PUB_AVG_INTEREST_RATE.schema, cells=data.CUSTOM_PUB_AVG_INTEREST_RATE.cells)
def custom_pub_avg_interest_rate(*, custom_pub_inflation_gdp_deflator: data.Series[float | str | None], custom_pub_avg_real_interest_rate_by_year: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derive the customized-scenario public average interest rate by adding the GDP-deflator inflation series to the average real interest rate series.

    Produces the nominal average interest rate path used by the customized public-debt scenario, aligned to the projection-year grid carried by the Input 3 old debt-service series.

    Args:
        custom_pub_inflation_gdp_deflator: Inflation (GDP deflator) assumptions for the customized public scenario, as a named-axis series over projection-year coordinates; entries propagate through the addition and may be blank or text.
        custom_pub_avg_real_interest_rate_by_year: Average real interest rate by year for the customized public scenario, as a named-axis series over projection-year coordinates, summed elementwise with the deflator series.
        input3_old_debt_service: Input 3 old debt-service data whose validated schema supplies the TIME_PERIOD coordinate grid that determines the output's projection years.

    Returns:
        A data.Series[float | str | None] of customized-scenario public average interest rates keyed by projection years, with blanks and text carried through from the input series.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(custom_pub_avg_real_interest_rate_by_year[time_period], custom_pub_inflation_gdp_deflator[time_period]))

    return data.CUSTOM_PUB_AVG_INTEREST_RATE.collect(evaluate(formula, data.CUSTOM_PUB_AVG_INTEREST_RATE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CUSTOM_PUB_AVG_INTEREST_RATE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.CUSTOM_PUB_INFLATION_GDP_DEFLATOR.schema, cells=data.CUSTOM_PUB_INFLATION_GDP_DEFLATOR.cells)
def custom_pub_inflation_gdp_deflator(*, custom_pub_inflation_rate_gdp_deflator_pct_by_year: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Build the customized-scenario public inflation (GDP deflator) series as decimal rates keyed by projection year.

    Converts the customized public inflation-rate assumptions from percent to decimal (dividing by 100) on the projection-year axis bound from Input 3.

    Args:
        custom_pub_inflation_rate_gdp_deflator_pct_by_year: Customized-scenario public inflation (GDP deflator) rates in percent, a year-keyed data.Series of floats, strings, or blanks; the rate at the preceding time step is divided by 100 for each projection year.
        input3_old_debt_service: Input 3 old debt service data whose TIME_PERIOD domain supplies the projection-year axis (and its ordering) used to align the deflator series and evaluate the prior-period lookup.

    Returns:
        A data.Series[float | str | None] of customized public inflation (GDP deflator) values as decimal rates, indexed by projection years.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_div(custom_pub_inflation_rate_gdp_deflator_pct_by_year[axis_step(_ax_time_period, time_period, -1)], 100))

    return data.CUSTOM_PUB_INFLATION_GDP_DEFLATOR.collect(evaluate(formula, data.CUSTOM_PUB_INFLATION_GDP_DEFLATOR.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CUSTOM_PUB_INFLATION_GDP_DEFLATOR.required.bind(TIME_PERIOD=input3_old_debt_service))

