        if _p_time_period == 0:
            return as_measure(xl_sub(custom_pub_real_gdp_growth[time_period], (customized_scenario_spec['size_of_associated_real_gdp_growth_shock', input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[11]] if xl_bool(xl_eq(customized_public_template_anchor, customized_public_natural_disaster_year)) else 0)))
        return as_measure(xl_sub(custom_pub_real_gdp_growth[time_period], (customized_scenario_spec['size_of_associated_real_gdp_growth_shock', input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[11]] if xl_bool(xl_eq(custom_pub_please_do_not_change_these_numbers[time_period], customized_public_natural_disaster_year)) else 0)))

