@publish(data.CUSTOM_PUB_AVERAGE_NOMINAL_INTEREST_RATE_EXT_DEBT.schema, cells=data.CUSTOM_PUB_AVERAGE_NOMINAL_INTEREST_RATE_EXT_DEBT.cells)
def custom_pub_average_nominal_interest_rate_ext_debt(*, custom_pub_total_public_ext_debt: data.Series[float | str | None], custom_pub_ext_debt: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the customized-scenario public average nominal interest rate on external debt.

    Derive the percent interest rate implied by external debt, lagged total public external debt, and exchange-rate conversion across projection years.

    Args:
        custom_pub_total_public_ext_debt: Total public external debt stock series for the customized public scenario, indexed by TIME_PERIOD and used as the lagged denominator.
        custom_pub_ext_debt: External debt stock series for the customized public scenario, indexed by TIME_PERIOD and used as the numerator.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: National-currency-per-U.S.-dollar exchange-rate series indexed by TIME_PERIOD, applied at the prior period for conversion.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: National-currency-per-U.S.-dollar exchange-rate series indexed by TIME_PERIOD, applied at the current period for conversion.
        input3_input_3_macro_current_account: Typed Input 3 macro current-account dataclass providing the TIME_PERIOD axis used to align and lag projection inputs.
        input3_old_debt_service: Typed Input 3 old-debt-service dataclass whose TIME_PERIOD axis defines the output projection domain.

    Returns:
        data.Series[float | str | None] of average nominal interest rates in percent, keyed by projection years from row 7 and preserving blank or text values.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
