        return as_measure((xl_sub(custom_ext_period[time_period], custom_ext_average_interest_rate_new_debt_by_row['Average maturity of new debt']) if xl_bool(xl_gt(xl_sub(custom_ext_period[time_period], custom_ext_average_interest_rate_new_debt_by_row['Average maturity of new debt']), 0)) else 0), 'int')

