    return data.CUSTOM_EXT_PV_PPG_STRESS.collect(evaluate(formula, data.CUSTOM_EXT_PV_PPG_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CUSTOM_EXT_PV_PPG_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service))

