@publish(data.MACRO_DEBT_EXPORTS_OF_GOODS_SERVICES.schema, cells=data.MACRO_DEBT_EXPORTS_OF_GOODS_SERVICES.cells)
def macro_debt_exports_of_goods_services(*, input3_input_3_macro_exports_of_goods_and_services: data.Input3Input3MacroExportsOfGoodsAndServices, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute the Macro-Debt exports of goods and services series from Input 3 values over projection years.

    Align Input 3 exports of goods and services to the current-account projection-year axis and return the Macro-Debt series, substituting 0 for non-numeric entries.

    Args:
        input3_input_3_macro_exports_of_goods_and_services: A typed Input 3 Macro-Debt_Data series of exports of goods and services in US Dollars, supplying the per-year values used in the calculation.
        input3_input_3_macro_current_account: A typed Input 3 Macro-Debt_Data current-account series whose TIME_PERIOD axis provides the projection years used to bind and validate the exports series.

    Returns:
        A typed data.Series[float | str | None] Macro-Debt_Data series of exports of goods and services in US Dollars, keyed by projection years from row 1, with non-numeric source entries represented as 0.
    """
    data.INPUT3_INPUT_3_MACRO_EXPORTS_OF_GOODS_AND_SERVICES.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_input_3_macro_exports_of_goods_and_services)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((input3_input_3_macro_exports_of_goods_and_services[time_period] if xl_bool(xl_isnumber(lambda: input3_input_3_macro_exports_of_goods_and_services[time_period])) else 0))

    return data.MACRO_DEBT_EXPORTS_OF_GOODS_SERVICES.collect(evaluate(formula, data.MACRO_DEBT_EXPORTS_OF_GOODS_SERVICES.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_EXPORTS_OF_GOODS_SERVICES.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_IMPORTS_OF_GOODS_SERVICES_USE_POSITIVE_VALUES.schema, cells=data.MACRO_DEBT_IMPORTS_OF_GOODS_SERVICES_USE_POSITIVE_VALUES.cells)
def macro_debt_imports_of_goods_services_use_positive_values(*, input3_imports: data.Series[float | str | None], input3_input_3_macro_imports_of_goods_and_services_enter_as_a_positive_number: data.Input3Input3MacroImportsOfGoodsAndServicesEnterAsAPositiveNumber, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Selects the macro imports of goods and services figure for each projection year from the historical series or the projected positive-value series.

    Builds the positive-value imports path used by the LIC-DSF macro-debt block by switching from historical imports to the projected entry once the year index passes the historical horizon, treating non-numeric cells as zero.

    Args:
        input3_imports: Historical-dollar imports of goods and services series keyed by projection year; consulted for the early (historical) positions of the timeline.
        input3_input_3_macro_imports_of_goods_and_services_enter_as_a_positive_number: Projected imports of goods and services entered as a positive number, a data series over projection years supplying values once the timeline moves past the historical horizon.
        input3_input_3_macro_current_account: Current-account macro series whose TIME_PERIOD axis defines the projection-year grid that the output and evaluation are bound to.
        input3_old_debt_service: Old debt service series over the same projection-year grid, used to anchor the input coordinate alignments for the calculation.

    Returns:
        A data series of US-dollar imports of goods and services (positive values) keyed by projection years, with non-numeric entries resolved to zero.
    """
    data.INPUT3_IMPORTS.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_imports)
    data.INPUT3_INPUT_3_MACRO_IMPORTS_OF_GOODS_AND_SERVICES_ENTER_AS_A_POSITIVE_NUMBER.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(input3_input_3_macro_imports_of_goods_and_services_enter_as_a_positive_number)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period <= 13:
            return as_measure((input3_imports['Imports of goods and services (enter as a positive number)', time_period] if xl_bool(xl_isnumber(lambda: input3_imports['Imports of goods and services (enter as a positive number)', time_period])) else 0))
        return as_measure((input3_input_3_macro_imports_of_goods_and_services_enter_as_a_positive_number[time_period] if xl_bool(xl_isnumber(lambda: input3_input_3_macro_imports_of_goods_and_services_enter_as_a_positive_number[time_period])) else 0))

    return data.MACRO_DEBT_IMPORTS_OF_GOODS_SERVICES_USE_POSITIVE_VALUES.collect(evaluate(formula, data.MACRO_DEBT_IMPORTS_OF_GOODS_SERVICES_USE_POSITIVE_VALUES.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_IMPORTS_OF_GOODS_SERVICES_USE_POSITIVE_VALUES.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

