    return data.MACRO_DEBT_US_DOLLARS_BY_YEAR_V.collect(evaluate(formula, data.MACRO_DEBT_US_DOLLARS_BY_YEAR_V.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.MACRO_DEBT_US_DOLLARS_BY_YEAR_V.required.bind(TIME_PERIOD=input3_old_debt_service))

