def macro_debt_share_of_commodity_exports_fuel_of_exports_of_g(*, input3_input_3_macro_exports_of_goods_and_services: data.Input3Input3MacroExportsOfGoodsAndServices, input3_input_3_macro_exports_commodity_fuel: data.Input3Input3MacroExportsCommodityFuel, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute fuel commodity exports as a share of exports of goods and services.

    Derive the Macro-Debt_Data commodity-export share series for LIC-DSF external-sector analysis.

    Args:
        input3_input_3_macro_exports_of_goods_and_services: Time-series of exports of goods and services, used as the denominator for the commodity-fuel export share.
        input3_input_3_macro_exports_commodity_fuel: Time-series of commodity fuel exports, used as the numerator for the commodity-fuel export share.
        input3_input_3_macro_current_account: Macro current-account time series whose period axis supplies the projection-year coordinates for validation and output collection.

    Returns:
        Typed `data.Series[float | str | None]` keyed by projection years from row 1, containing the fuel commodity export share of exports of goods and services, including workbook-derived numeric, string, or blank values.
    """
    data.INPUT3_INPUT_3_MACRO_EXPORTS_OF_GOODS_AND_SERVICES.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_input_3_macro_exports_of_goods_and_services)
    data.INPUT3_INPUT_3_MACRO_EXPORTS_COMMODITY_FUEL.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_input_3_macro_exports_commodity_fuel)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_div(input3_input_3_macro_exports_commodity_fuel[time_period], input3_input_3_macro_exports_of_goods_and_services[time_period]) if xl_bool(xl_isnumber(lambda: xl_div(input3_input_3_macro_exports_commodity_fuel[time_period], input3_input_3_macro_exports_of_goods_and_services[time_period]))) else 0))

    return data.MACRO_DEBT_SHARE_OF_COMMODITY_EXPORTS_FUEL_OF_EXPORTS_OF_G.collect(evaluate(formula, data.MACRO_DEBT_SHARE_OF_COMMODITY_EXPORTS_FUEL_OF_EXPORTS_OF_G.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_SHARE_OF_COMMODITY_EXPORTS_FUEL_OF_EXPORTS_OF_G.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

