    return data.MACRO_DEBT_SHARE_OF_COMMODITY_EXPORTS_NON_FUEL_OF_EXPORTS.collect(evaluate(formula, data.MACRO_DEBT_SHARE_OF_COMMODITY_EXPORTS_NON_FUEL_OF_EXPORTS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_SHARE_OF_COMMODITY_EXPORTS_NON_FUEL_OF_EXPORTS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

