@publish(data.MACRO_DEBT_PUBLIC_SECTOR_GRANTS.schema, cells=data.MACRO_DEBT_PUBLIC_SECTOR_GRANTS.cells)
def macro_debt_public_sector_grants(*, input3_input_3_macro_government_grants: data.Input3Input3MacroGovernmentGrants, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute public-sector grants for macro debt by aligning government grants to the old debt-service year axis.

    Derive the public-sector grants series used in macro-debt calculations on the projection-year grid.

    Args:
        input3_input_3_macro_government_grants: Input 3 government grants as a named-axis macro series over TIME_PERIOD; numeric values are passed through and non-numeric entries are treated as zero.
        input3_old_debt_service: Input 3 old debt service as a named-axis series whose TIME_PERIOD coordinates define the projection-year alignment for the computed grants.

    Returns:
        A data.Series of floats, strings, or None on National Currency Macro-Debt coordinates, keyed by projection years from row 1.
    """
    data.INPUT3_INPUT_3_MACRO_GOVERNMENT_GRANTS.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(input3_input_3_macro_government_grants)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((input3_input_3_macro_government_grants[time_period] if xl_bool(xl_isnumber(lambda: input3_input_3_macro_government_grants[time_period])) else 0))

    return data.MACRO_DEBT_PUBLIC_SECTOR_GRANTS.collect(evaluate(formula, data.MACRO_DEBT_PUBLIC_SECTOR_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.MACRO_DEBT_PUBLIC_SECTOR_GRANTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.MACRO_DEBT_PRIVATIZATION_RECEIPTS.schema, cells=data.MACRO_DEBT_PRIVATIZATION_RECEIPTS.cells)
def macro_debt_privatization_receipts(*, input3_other_debt_flows: data.Series[float | str | None], input3_input_3_macro_privatization_proceeds: data.Input3Input3MacroPrivatizationProceeds, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Build the macro-debt privatization receipts series from historical other debt flows and projected privatization proceeds.

    Selects historical "Privatization Proceeds" amounts for the initial projection periods and projected macro privatization proceeds thereafter, returning a National Currency Macro-Debt_Data series aligned to projection years.

    Args:
        input3_other_debt_flows: Historical other debt flow series containing the "Privatization Proceeds" line, indexed over the projection-year TIME_PERIOD coordinate and used for the early periods.
        input3_input_3_macro_privatization_proceeds: Projected macro privatization proceeds series, indexed by projection year, used after the historical cutoff.
        input3_input_3_macro_current_account: Macro current-account series whose TIME_PERIOD coordinate defines the projection-year axis and domain for evaluation.
        input3_old_debt_service: Old debt service series whose TIME_PERIOD coordinate constrains and validates the projected privatization proceeds series.

    Returns:
        A National Currency Macro-Debt_Data series of privatization receipts, keyed by projection years from row 1, with float values or string/None placeholders.
    """
    data.INPUT3_OTHER_DEBT_FLOWS.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_other_debt_flows)
    data.INPUT3_INPUT_3_MACRO_PRIVATIZATION_PROCEEDS.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(input3_input_3_macro_privatization_proceeds)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period <= 12:
            return as_measure((input3_other_debt_flows['Privatization Proceeds', time_period] if xl_bool(xl_isnumber(lambda: input3_other_debt_flows['Privatization Proceeds', time_period])) else 0))
        return as_measure((input3_input_3_macro_privatization_proceeds[time_period] if xl_bool(xl_isnumber(lambda: input3_input_3_macro_privatization_proceeds[time_period])) else 0))

    return data.MACRO_DEBT_PRIVATIZATION_RECEIPTS.collect(evaluate(formula, data.MACRO_DEBT_PRIVATIZATION_RECEIPTS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_PRIVATIZATION_RECEIPTS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

