@publish(data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.schema, cells=data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.cells)
def macro_debt_public_sector_interest_expenditure(*, macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_total_public_domestic_debt_interest_due: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute public-sector interest expenditure in national currency from PPG and domestic debt interest due converted at the exchange rate.

    Multiplies the combined PPG and domestic public debt interest due by the national-currency-per-USD exchange rate over each projection year.

    Args:
        macro_debt_ppg_interest_due: Named-axis series of public and publicly guaranteed interest due, indexed by projection year.
        macro_debt_total_public_domestic_debt_interest_due: Named-axis series of total public domestic debt interest due, indexed by projection year.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Named-axis series of the exchange rate expressed in national currency per U.S. dollar, indexed by projection year.
        input3_input_3_macro_current_account: Typed Input 3 macro current-account series whose TIME_PERIOD axis defines the projection-year grid over which the expenditure series is evaluated.

    Returns:
        Named-axis series of public-sector interest expenditure in national currency, with float values or string/None placeholders on the TIME_PERIOD projection-year axis.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_total_public_domestic_debt_interest_due[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.collect(evaluate(formula, data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

