@publish(data.MACRO_DEBT_NONE.schema, cells=data.MACRO_DEBT_NONE.cells)
def macro_debt_none(*, input3_us_deflator: data.Series[float | str | None], input3_input_3_macro_u_s_deflator: data.Input3Input3MacroUSDeflator, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Build the Macro-Debt_Data U.S. deflator path from historical and projected deflator series.

    Produces the deflator series consumed by downstream macro-debt calculations over the current-account projection grid.

    Args:
        input3_us_deflator: A named-axis data series of U.S. deflator values (float, text, or blank) keyed by TIME_PERIOD, supplying the `U.S. Deflator` coordinate used for the first twelve periods.
        input3_input_3_macro_u_s_deflator: A typed `Input3Input3MacroUSDeflator` series over TIME_PERIOD providing the projected U.S. deflator values used after the historical window.
        input3_input_3_macro_current_account: A typed `Input3Input3MacroCurrentAccount` series over TIME_PERIOD whose domain supplies the projection-year grid used to bind and validate the inputs and the returned series.

    Returns:
        A `data.Series[float | str | None]` (Macro-Debt_Data) keyed by the same TIME_PERIOD projection years, with non-numeric entries coerced to 0.
    """
    data.INPUT3_US_DEFLATOR.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_us_deflator)
    data.INPUT3_INPUT_3_MACRO_U_S_DEFLATOR.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_input_3_macro_u_s_deflator)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period <= 11:
            return as_measure((input3_us_deflator['U.S. Deflator', time_period] if xl_bool(xl_isnumber(lambda: input3_us_deflator['U.S. Deflator', time_period])) else 0))
        return as_measure((input3_input_3_macro_u_s_deflator[time_period] if xl_bool(xl_isnumber(lambda: input3_input_3_macro_u_s_deflator[time_period])) else 0))

    return data.MACRO_DEBT_NONE.collect(evaluate(formula, data.MACRO_DEBT_NONE.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_NONE.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

