@publish(data.MACRO_DEBT_PRIVATE_DEBT_PCT_GDP.schema, cells=data.MACRO_DEBT_PRIVATE_DEBT_PCT_GDP.cells)
def macro_debt_private_debt_pct_gdp(*, macro_debt_private_sector_ext_debt: data.Series[float | str | None], macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute private debt as a percentage of GDP over projection years.

    Derives the Macro-Debt private-debt-to-GDP series by dividing private sector external debt by current-price GDP and scaling by 100.

    Args:
        macro_debt_private_sector_ext_debt: Private sector external debt series, keyed by projection-year coordinates, used as the ratio numerator.
        macro_debt_gdp_current_prices_u_s_dollars: GDP at current prices in U.S. dollars series, keyed by the same projection-year coordinates, used as the denominator.
        input3_input_3_macro_current_account: Typed Input 3 macro current-account data whose TIME_PERIOD axis supplies the projection-year coordinates for evaluating the ratio.

    Returns:
        A data.Series[float | str | None] of private debt in percent of GDP, keyed by projection years from row 1; nonnumeric or invalid ratio results are returned as an ellipsis string.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_div(macro_debt_private_sector_ext_debt[time_period], macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100) if xl_bool(xl_isnumber(lambda: xl_mul(xl_div(macro_debt_private_sector_ext_debt[time_period], macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100))) else '…'))

    return data.MACRO_DEBT_PRIVATE_DEBT_PCT_GDP.collect(evaluate(formula, data.MACRO_DEBT_PRIVATE_DEBT_PCT_GDP.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_PRIVATE_DEBT_PCT_GDP.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_PRIVATE_DEBT_SERVICE_PCT_EXPORTS.schema, cells=data.MACRO_DEBT_PRIVATE_DEBT_SERVICE_PCT_EXPORTS.cells)
def macro_debt_private_debt_service_pct_exports(*, macro_debt_private_sector_short_term: data.Series[float | str | None], macro_debt_private_external_interest_due: data.Series[float | str | None], macro_debt_mlt_private_ext_debt_amortization: data.Series[float | str | None], macro_debt_exports_of_goods_services: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute private external debt service as a percentage of exports of goods and services.

    Derives the Macro-Debt_Data private debt service ratio by summing amortization, interest due, and lagged short-term private debt, then scaling by exports.

    Args:
        macro_debt_private_sector_short_term: Named-axis data series of short-term private sector debt values over catalog coordinates; read at the prior TIME_PERIOD position.
        macro_debt_private_external_interest_due: Named-axis data series of private external interest due values over catalog coordinates.
        macro_debt_mlt_private_ext_debt_amortization: Named-axis data series of medium- and long-term private external debt amortization values over catalog coordinates.
        macro_debt_exports_of_goods_services: Named-axis data series of exports of goods and services values over catalog coordinates, used as the denominator.
        input3_input_3_macro_current_account: Typed data series over catalog coordinates supplying the current-account input domain whose TIME_PERIOD axis defines the lag for short-term debt.
        input3_old_debt_service: Typed data series over catalog coordinates providing the output TIME_PERIOD domain and validating the projection-year grid.

    Returns:
        A named-axis data series of float, str, or None values keyed by projection years, holding the private debt service percentage of exports or a blank marker where the ratio is not numeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_div(xl_add(xl_add(macro_debt_mlt_private_ext_debt_amortization[time_period], macro_debt_private_external_interest_due[time_period]), macro_debt_private_sector_short_term[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), macro_debt_exports_of_goods_services[time_period]), 100) if xl_bool(xl_isnumber(lambda: xl_mul(xl_div(xl_add(xl_add(macro_debt_mlt_private_ext_debt_amortization[time_period], macro_debt_private_external_interest_due[time_period]), macro_debt_private_sector_short_term[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), macro_debt_exports_of_goods_services[time_period]), 100))) else '…'))

    return data.MACRO_DEBT_PRIVATE_DEBT_SERVICE_PCT_EXPORTS.collect(evaluate(formula, data.MACRO_DEBT_PRIVATE_DEBT_SERVICE_PCT_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.MACRO_DEBT_PRIVATE_DEBT_SERVICE_PCT_EXPORTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.MACRO_DEBT_TOTAL_PUBLIC_DEBT_OUTSTANDING_YEAR_END.schema, cells=data.MACRO_DEBT_TOTAL_PUBLIC_DEBT_OUTSTANDING_YEAR_END.cells)
def macro_debt_total_public_debt_outstanding_year_end(*, macro_debt_total_public_ext_debt: data.Series[float | str | None], macro_debt_total_public_domestic_debt: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute year-end total public debt outstanding from external and domestic public debt series.

    Sum external and domestic public debt by projection year, treating nonnumeric additions as zero.

    Args:
        macro_debt_total_public_ext_debt: A data.Series[float | str | None] of external public debt outstanding in National Currency, keyed by projection years from row 1.
        macro_debt_total_public_domestic_debt: A data.Series[float | str | None] of domestic public debt outstanding in National Currency, keyed by projection years from row 1.
        input3_input_3_macro_current_account: A data.Input3Input3MacroCurrentAccount whose TIME_PERIOD axis provides the projection-year coordinate grid for evaluation.

    Returns:
        A data.Series[float | str | None] of year-end total public debt outstanding in National Currency, keyed by projection years, with nonnumeric additions represented as 0.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_add(macro_debt_total_public_ext_debt[time_period], macro_debt_total_public_domestic_debt[time_period]) if xl_bool(xl_isnumber(lambda: xl_add(macro_debt_total_public_ext_debt[time_period], macro_debt_total_public_domestic_debt[time_period]))) else 0))

    return data.MACRO_DEBT_TOTAL_PUBLIC_DEBT_OUTSTANDING_YEAR_END.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_PUBLIC_DEBT_OUTSTANDING_YEAR_END.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_TOTAL_PUBLIC_DEBT_OUTSTANDING_YEAR_END.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_TOTAL_PUBLIC_EXT_DEBT.schema, cells=data.MACRO_DEBT_TOTAL_PUBLIC_EXT_DEBT.cells)
def macro_debt_total_public_ext_debt(*, macro_debt_us_dollars_by_year: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Convert total public external debt from US dollars to national currency across projection years.

    Produces the Macro-Debt_Data national-currency public external debt series by multiplying dollar-denominated debt by the period exchange rate under Excel-style multiplication semantics.

    Args:
        macro_debt_us_dollars_by_year: Named-axis series of total public external debt in US dollars, indexed by projection year, with blank or text cells allowed.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: Named-axis series of the exchange rate in national currency per US dollar, indexed by projection year, with blank or text cells allowed.
        input3_input_3_macro_current_account: Typed Input 3 macro current-account record whose TIME_PERIOD axis supplies the projection-year grid on which the result is evaluated and validated.

    Returns:
        Named-axis series of total public external debt in national currency, keyed by the same projection years; products follow Excel-style multiplication so blank or non-numeric cells propagate rather than raise.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(macro_debt_us_dollars_by_year[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]))

    return data.MACRO_DEBT_TOTAL_PUBLIC_EXT_DEBT.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_PUBLIC_EXT_DEBT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_TOTAL_PUBLIC_EXT_DEBT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT.schema, cells=data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT.cells)
def macro_debt_total_public_domestic_debt(*, macro_debt_national_currency: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute total public domestic debt from national currency values over the macro current-account projection grid.

    Produce a projection-year series of public domestic debt, using numeric national currency entries and treating non-numeric entries as zero.

    Args:
        macro_debt_national_currency: National Currency (Macro-Debt_Data) data series keyed by projection years, supplying the debt values used in the calculation.
        input3_input_3_macro_current_account: Macro current-account input series whose TIME_PERIOD domain defines the projection years for the resulting series.

    Returns:
        data.Series[float | str | None] of total public domestic debt keyed by the current-account projection years.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((macro_debt_national_currency[time_period] if xl_bool(xl_isnumber(lambda: macro_debt_national_currency[time_period])) else 0))

    return data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_TOTAL_PUBLIC_DOMESTIC_DEBT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_FX_DENOMINATED_PUBLIC_DEBT_END_OF_PERIOD.schema, cells=data.MACRO_DEBT_FX_DENOMINATED_PUBLIC_DEBT_END_OF_PERIOD.cells)
def macro_debt_fx_denominated_public_debt_end_of_period(*, input3_local_currency_external_debt: data.Series[float | str | None], ext_debt_fx_denominated_debt_outstanding: data.Series[float | str | None], in3_macro_fx_denominated_debt_including_locally_issued: float | str, macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute end-of-period FX-denominated public debt in national currency.

    Converts the applicable FX-denominated public debt stock into national currency using the period exchange rate across the projection-year grid.

    Args:
        input3_local_currency_external_debt: Local-currency external debt series keyed by projection year; its foreign-currency-denominated component, including locally issued debt, supplies the debt stock for earlier projection periods.
        ext_debt_fx_denominated_debt_outstanding: FX-denominated external debt outstanding series keyed by projection year, used for periods beyond the authored projection-window anchor.
        in3_macro_fx_denominated_debt_including_locally_issued: Scalar FX-denominated public debt stock including locally issued debt, applied at the terminal projection year.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: National-currency-per-U.S.-dollar exchange rate series by projection year, used to convert each period's FX debt stock into national currency.
        input3_input_3_macro_current_account: Macro current-account data series supplying the TIME_PERIOD axis that defines projection-year positions and selects the applicable formula branch.
        input3_old_debt_service: Old debt service data series validated for schema consistency and aligned to the same projection-year grid.

    Returns:
        A data.Series[float | str | None] of end-of-period FX-denominated public debt in national currency, keyed by projection year, with numeric values or string/blank sentinels where inputs are missing.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 12:
            return as_measure(xl_mul(in3_macro_fx_denominated_debt_including_locally_issued, macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]))
        elif _p_time_period <= 11:
            return as_measure(xl_mul(input3_local_currency_external_debt['Foreign currency-denominated debt (including locally-issued debt)', time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]))
        return as_measure(xl_mul(ext_debt_fx_denominated_debt_outstanding[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]))

    return data.MACRO_DEBT_FX_DENOMINATED_PUBLIC_DEBT_END_OF_PERIOD.collect(evaluate(formula, data.MACRO_DEBT_FX_DENOMINATED_PUBLIC_DEBT_END_OF_PERIOD.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_FX_DENOMINATED_PUBLIC_DEBT_END_OF_PERIOD.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL.schema, cells=data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL.cells)
def macro_debt_share_of_local_currency_denominated_external(*, input3_local_currency_external_debt: data.Series[float | str | None], input5_old_debt_outstanding_from_old_debt_in_local_currency: data.Series[float | str | None], input5_new_debt_debt_stock_on_new_debt_denominated_in_local_currency: data.Series[float | str | None], external_domestic_debt_definition: str, in3_macro_transition_formula_these_outstanding: float | str, macro_debt_us_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], lookup_afg: str | int | float | bool, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes the share of local-currency denominated external public debt in total external debt by projection year.

    Produces the Macro-Debt_Data share series used in LIC-DSF external debt sustainability calculations.

    Args:
        input3_local_currency_external_debt: Local-currency external debt series over catalog coordinates, supplying outstanding values by time period.
        input5_old_debt_outstanding_from_old_debt_in_local_currency: Old debt outstanding in local currency series over catalog coordinates, supplying non-resident amounts by time period.
        input5_new_debt_debt_stock_on_new_debt_denominated_in_local_currency: New debt stock denominated in local currency series over catalog coordinates, supplying non-resident amounts by time period.
        external_domestic_debt_definition: Scalar debt-definition selector tested against the lookup value to determine whether the share is populated.
        in3_macro_transition_formula_these_outstanding: Scalar transition-formula outstanding amount used for the final projection-year branch.
        macro_debt_us_dollars: Total external debt in U.S. dollars series over catalog coordinates, used as the denominator.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: Exchange-rate series in national currency per U.S. dollar over catalog coordinates, used to convert local-currency amounts.
        lookup_afg: Scalar lookup value compared with the debt-definition selector.
        input3_input_3_macro_current_account: Typed macro current-account series container that validates input and supplies the TIME_PERIOD axis and domain.
        input3_old_debt_service: Typed old-debt-service series container validated before computation.

    Returns:
        A data.Series[float | str | None] of local-currency external debt shares in percent, keyed by projection-year TIME_PERIOD coordinates from row 1.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 12:
            return as_measure((xl_mul(xl_div(in3_macro_transition_formula_these_outstanding, macro_debt_us_dollars[time_period]), 100) if xl_bool(xl_eq(external_domestic_debt_definition, lookup_afg)) else 0))
        elif _p_time_period <= 11:
            return as_measure((xl_mul(xl_div(input3_local_currency_external_debt['Outstanding', time_period], macro_debt_us_dollars[time_period]), 100) if xl_bool(xl_eq(external_domestic_debt_definition, lookup_afg)) else 0))
        return as_measure((xl_mul(xl_div(xl_div(xl_add(input5_old_debt_outstanding_from_old_debt_in_local_currency['non-residents', time_period], input5_new_debt_debt_stock_on_new_debt_denominated_in_local_currency['non-residents', time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]), macro_debt_us_dollars[time_period]), 100) if xl_bool(xl_eq(external_domestic_debt_definition, lookup_afg)) else 0))

    return data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL.collect(evaluate(formula, data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_INTEREST_RATE_EXT_DEBT.schema, cells=data.MACRO_DEBT_INTEREST_RATE_EXT_DEBT.cells)
def macro_debt_interest_rate_ext_debt(*, macro_debt_us_dollars_by_year: data.Series[float | str | None], macro_debt_ppg_interest_due: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute the external-debt interest rate from PPG interest due and prior-year U.S.-dollar debt.

    Derives the Macro-Debt_Data external debt interest rate series by dividing interest due by lagged debt stock and scaling by 100.

    Args:
        macro_debt_us_dollars_by_year: Named-axis series of U.S.-dollar debt stock by year; the value one period before each projection year supplies the denominator.
        macro_debt_ppg_interest_due: Named-axis series of PPG interest due by year; values are divided by the lagged debt stock and multiplied by 100.
        input3_input_3_macro_current_account: Input 3 macro current-account typed series whose TIME_PERIOD axis defines the projection-year coordinates used to align and collect the rate series.

    Returns:
        A named-axis series of external-debt interest rates over the projection-year coordinates, with non-numeric division results represented by the workbook's '...' marker.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_div(macro_debt_ppg_interest_due[time_period], macro_debt_us_dollars_by_year[axis_step(_ax_time_period, time_period, -1)]), 100) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_ppg_interest_due[time_period], macro_debt_us_dollars_by_year[axis_step(_ax_time_period, time_period, -1)]))) else '...'))

    return data.MACRO_DEBT_INTEREST_RATE_EXT_DEBT.collect(evaluate(formula, data.MACRO_DEBT_INTEREST_RATE_EXT_DEBT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_INTEREST_RATE_EXT_DEBT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_INTEREST_RATE_DOMESTIC_DEBT.schema, cells=data.MACRO_DEBT_INTEREST_RATE_DOMESTIC_DEBT.cells)
def macro_debt_interest_rate_domestic_debt(*, macro_debt_national_currency: data.Series[float | str | None], macro_debt_total_public_domestic_debt_interest_due: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute the interest rate on domestic debt from interest due, national-currency GDP, and the exchange rate.

    Derives the Macro-Debt domestic-debt interest rate series used in the LIC-DSF public-debt interest-rate paths.

    Args:
        macro_debt_national_currency: Named-axis series of national-currency GDP over projection years; the prior-year value is the lagged denominator.
        macro_debt_total_public_domestic_debt_interest_due: Named-axis series of total public domestic debt interest due, in national currency, over projection years.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Named-axis series of the exchange rate expressed as national currency per U.S. dollar over projection years.
        input3_input_3_macro_current_account: Input 3 macro current-account input record whose TIME_PERIOD axis defines the projection-year domain for evaluation and alignment.

    Returns:
        Named-axis series of the domestic-debt interest rate in percent, keyed by projection-year coordinates and carrying '...' where the ratio is not numeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_mul(xl_div(macro_debt_total_public_domestic_debt_interest_due[time_period], macro_debt_national_currency[axis_step(_ax_time_period, time_period, -1)]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]), 100) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_total_public_domestic_debt_interest_due[time_period], macro_debt_national_currency[axis_step(_ax_time_period, time_period, -1)]))) else '...'))

    return data.MACRO_DEBT_INTEREST_RATE_DOMESTIC_DEBT.collect(evaluate(formula, data.MACRO_DEBT_INTEREST_RATE_DOMESTIC_DEBT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_INTEREST_RATE_DOMESTIC_DEBT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_PV_OF_PUBLIC_SECTOR_EXT_DEBT_END_OF_PERIOD.schema, cells=data.MACRO_DEBT_PV_OF_PUBLIC_SECTOR_EXT_DEBT_END_OF_PERIOD.cells)
def macro_debt_pv_of_public_sector_ext_debt_end_of_period(*, ext_debt_total_pv_of_debt: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Convert total public external debt PV into national-currency terms at end of period.

    Multiplies each projection year's total PV of external debt by the national-currency-per-USD exchange rate to produce the macro-debt PV series over catalog coordinates.

    Args:
        ext_debt_total_pv_of_debt: Named-axis series of total PV of external debt, keyed by projection years.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: Named-axis series of the exchange rate in national currency per U.S. dollar for each projection year.
        input3_input_3_macro_current_account: Macro current-account input series group supplying validated macro context for the projection grid.
        input3_old_debt_service: Old debt service input series group whose TIME_PERIOD axis defines the projection years evaluated.

    Returns:
        Series of PV of public sector external debt (end of period) keyed by projection years.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(ext_debt_total_pv_of_debt[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period]))

    return data.MACRO_DEBT_PV_OF_PUBLIC_SECTOR_EXT_DEBT_END_OF_PERIOD.collect(evaluate(formula, data.MACRO_DEBT_PV_OF_PUBLIC_SECTOR_EXT_DEBT_END_OF_PERIOD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.MACRO_DEBT_PV_OF_PUBLIC_SECTOR_EXT_DEBT_END_OF_PERIOD.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.MACRO_DEBT_NATIONAL_CURRENCY_US_DOLLARS.schema, cells=data.MACRO_DEBT_NATIONAL_CURRENCY_US_DOLLARS.cells)
def macro_debt_national_currency_us_dollars(*, macro_debt_public_sector_revenues_including_grants: data.Series[float | str | None], macro_debt_public_sector_grants: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Converts public-sector revenues net of grants from national currency to US dollars, per projection year.

    Produces the US-dollar macro-debt revenues series by subtracting grants from revenues including grants and dividing by the national-currency-per-US-dollar exchange rate.

    Args:
        macro_debt_public_sector_revenues_including_grants: Named-axis series of public-sector revenues including grants over catalog projection years, with blanks and non-numeric markers preserved as scalars rather than expanded per cell.
        macro_debt_public_sector_grants: Named-axis series of public-sector grants over the same projection years, subtracted from revenues including grants before the currency conversion.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Named-axis series of the exchange rate in national currency per US dollar, supplying the divisor for each projection year's conversion.
        input3_input_3_macro_current_account: Input 3 macro current-account group, a typed data.* dataclass of macro-debt series sharing the projection-year coordinate axis, schema-validated before evaluation.
        input3_old_debt_service: Input 3 old debt-service group whose TIME_PERIOD axis supplies the projection-year domain that the result series is bound to and collected over.

    Returns:
        data.Series[float | str | None] — US Dollars (Macro-Debt_Data) keyed by projection years from row 1, holding revenues net of grants divided by the exchange rate, or '…' where that quotient is not numeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_div(xl_sub(macro_debt_public_sector_revenues_including_grants[time_period], macro_debt_public_sector_grants[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]) if xl_bool(xl_isnumber(lambda: xl_div(xl_sub(macro_debt_public_sector_revenues_including_grants[time_period], macro_debt_public_sector_grants[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))) else '…'))

    return data.MACRO_DEBT_NATIONAL_CURRENCY_US_DOLLARS.collect(evaluate(formula, data.MACRO_DEBT_NATIONAL_CURRENCY_US_DOLLARS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.MACRO_DEBT_NATIONAL_CURRENCY_US_DOLLARS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.MACRO_DEBT_REVENUES_PCT_GDP.schema, cells=data.MACRO_DEBT_REVENUES_PCT_GDP.cells)
def macro_debt_revenues_pct_gdp(*, macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_national_currency_us_dollars: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute revenues in percent of GDP from Macro-Debt data.

    Derives the revenues-to-GDP ratio series used by the LIC-DSF macro-debt framework and downstream fiscal-risk indicators.

    Args:
        macro_debt_gdp_current_prices_u_s_dollars: Named-axis series over catalog coordinates of GDP at current prices in U.S. dollars, providing the denominator for the ratio.
        macro_debt_national_currency_us_dollars: Named-axis series over catalog coordinates of debt in national currency expressed in U.S. dollars (the numerator basis), evaluated per projection year.
        input3_input_3_macro_current_account: Validated Input 3 macro current-account record supplying the scenario context and its named-axis coordinates.
        input3_old_debt_service: Validated Input 3 old debt service record whose TIME_PERIOD axis defines the year grid the result is collected over.

    Returns:
        A `data.Series[float | str | None]` keyed by projection years (from row 1) holding revenues in percent of GDP; non-numeric or undefined computations yield the series' placeholder string rather than a number.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_div(macro_debt_national_currency_us_dollars[time_period], macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100) if xl_bool(xl_isnumber(lambda: xl_mul(xl_div(macro_debt_national_currency_us_dollars[time_period], macro_debt_gdp_current_prices_u_s_dollars[time_period]), 100))) else '…'))

    return data.MACRO_DEBT_REVENUES_PCT_GDP.collect(evaluate(formula, data.MACRO_DEBT_REVENUES_PCT_GDP.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.MACRO_DEBT_REVENUES_PCT_GDP.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.MACRO_DEBT_REAL_GDP_GROWTH.schema, cells=data.MACRO_DEBT_REAL_GDP_GROWTH.cells)
def macro_debt_real_gdp_growth(*, macro_debt_gdp_constant_prices: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Computes real GDP growth from the constant-price GDP series.

    Derives year-over-year real GDP growth as a percentage using each period's constant-price GDP relative to the prior period, keyed by the projection-year TIME_PERIOD axis.

    Args:
        macro_debt_gdp_constant_prices: Named-axis data.Series of constant-price GDP levels over TIME_PERIOD, supplying the current and prior-period values used in the growth ratio.
        input3_input_3_macro_current_account: Validated Input3Input3MacroCurrentAccount series whose TIME_PERIOD axis defines the projection-year grid and coordinate positions for the calculation.

    Returns:
        A data.Series[float | str | None] of real GDP growth (Macro-Debt_Data) keyed by projection years, carrying a non-numeric placeholder where the growth value is not numeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_sub(xl_div(macro_debt_gdp_constant_prices[time_period], macro_debt_gdp_constant_prices[axis_step(_ax_time_period, time_period, -1)]), 1), 100) if xl_bool(xl_isnumber(lambda: xl_mul(xl_sub(xl_div(macro_debt_gdp_constant_prices[time_period], macro_debt_gdp_constant_prices[axis_step(_ax_time_period, time_period, -1)]), 1), 100))) else '…'))

    return data.MACRO_DEBT_REAL_GDP_GROWTH.collect(evaluate(formula, data.MACRO_DEBT_REAL_GDP_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_REAL_GDP_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_GDP_DEFLATOR_INDEX_NATIONAL_CURRENCY.schema, cells=data.MACRO_DEBT_GDP_DEFLATOR_INDEX_NATIONAL_CURRENCY.cells)
def macro_debt_gdp_deflator_index_national_currency(*, macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_gdp_constant_prices: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute the national-currency GDP deflator index from current-price and constant-price GDP and the exchange rate.

    Derive the Macro-Debt_Data GDP deflator index keyed by projection years from row 1.

    Args:
        macro_debt_gdp_current_prices_u_s_dollars: Current-price GDP series in U.S. dollars; multiplied by the exchange rate to express current-price GDP in national currency.
        macro_debt_gdp_constant_prices: Constant-price GDP series serving as the denominator in the deflator ratio.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Exchange rate series in national currency per U.S. dollar; converts current-price U.S. dollar GDP to national currency.
        input3_input_3_macro_current_account: Input 3 macro current-account input bundle whose TIME_PERIOD domain supplies the projection-year coordinates for the calculation.

    Returns:
        GDP deflator index (national currency) as a float series keyed by projection years from row 1, with a string placeholder where the ratio is nonnumeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_div(xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]), macro_debt_gdp_constant_prices[time_period]), 100) if xl_bool(xl_isnumber(lambda: xl_div(xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]), macro_debt_gdp_constant_prices[time_period]))) else '…'))

    return data.MACRO_DEBT_GDP_DEFLATOR_INDEX_NATIONAL_CURRENCY.collect(evaluate(formula, data.MACRO_DEBT_GDP_DEFLATOR_INDEX_NATIONAL_CURRENCY.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_GDP_DEFLATOR_INDEX_NATIONAL_CURRENCY.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR.schema, cells=data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR.cells)
def macro_debt_change_in_gdp_deflator_factor(*, macro_debt_gdp_deflator_index_national_currency: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute the annual percent change in the GDP deflator factor from the national-currency deflator index.

    Derives the Macro-Debt GDP deflator change series used by the LIC-DSF projections.

    Args:
        macro_debt_gdp_deflator_index_national_currency: National-currency GDP deflator index as a data.Series[float | str | None] keyed by projection years, with non-numeric entries allowed.
        input3_input_3_macro_current_account: Macro current-account input as a data.Input3Input3MacroCurrentAccount object whose TIME_PERIOD axis defines the projection-year grid for the calculation.

    Returns:
        data.Series[float | str | None] of percent changes in the GDP deflator factor keyed by projection years from row 1, with '...' where the prior-year index is not numeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_sub(xl_div(macro_debt_gdp_deflator_index_national_currency[time_period], macro_debt_gdp_deflator_index_national_currency[axis_step(_ax_time_period, time_period, -1)]), 1), 100) if xl_bool(xl_isnumber(lambda: macro_debt_gdp_deflator_index_national_currency[axis_step(_ax_time_period, time_period, -1)])) else '...'))

    return data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR.collect(evaluate(formula, data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_GDP_DEFLATOR_INDEX_DOLLARS.schema, cells=data.MACRO_DEBT_GDP_DEFLATOR_INDEX_DOLLARS.cells)
def macro_debt_gdp_deflator_index_dollars(*, macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_gdp_constant_prices: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute the GDP deflator index in dollar terms from current- and constant-price debt series.

    Derives projection-year deflator index values by dividing current-price debt by constant-price debt and scaling by 100 where numeric inputs are available.

    Args:
        macro_debt_gdp_current_prices_u_s_dollars: A named-axis series of current-price macro debt-to-GDP values in U.S. dollars, indexed over catalog coordinates and allowed to contain blanks or text.
        macro_debt_gdp_constant_prices: A named-axis series of constant-price macro debt-to-GDP values, indexed over catalog coordinates and used as the denominator for the deflator calculation.
        input3_input_3_macro_current_account: A typed Input 3 macro current-account series container that supplies the TIME_PERIOD axis and validates the projection-year coordinate space.

    Returns:
        A named-axis series of GDP deflator index values in dollars, keyed by projection years from row 1, preserving blanks or text where the calculation is nonnumeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_div(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_gdp_constant_prices[time_period]), 100) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_gdp_constant_prices[time_period]))) else '…'))

    return data.MACRO_DEBT_GDP_DEFLATOR_INDEX_DOLLARS.collect(evaluate(formula, data.MACRO_DEBT_GDP_DEFLATOR_INDEX_DOLLARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_GDP_DEFLATOR_INDEX_DOLLARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_BY_YEAR.schema, cells=data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_BY_YEAR.cells)
def macro_debt_change_in_gdp_deflator_factor_by_year(*, macro_debt_gdp_deflator_index_dollars: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute the year-over-year percent change in the GDP deflator index across projection years.

    Derives the GDP deflator change factor (percent) used in macro-debt real-value adjustments for each projection year, keyed by TIME_PERIOD.

    Args:
        macro_debt_gdp_deflator_index_dollars: GDP deflator index expressed in dollars, a named-axis data series over catalog coordinates whose prior-year values supply the comparison base.
        input3_input_3_macro_current_account: Macro current account input series whose TIME_PERIOD axis defines the projection-year grid and coordinate positions for the calculation.

    Returns:
        A data series of floats, strings, or None holding the GDP deflator change factor (percent) per projection year, indexed by the TIME_PERIOD axis.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_sub(xl_div(macro_debt_gdp_deflator_index_dollars[time_period], macro_debt_gdp_deflator_index_dollars[axis_step(_ax_time_period, time_period, -1)]), 1), 100) if xl_bool(xl_isnumber(lambda: macro_debt_gdp_deflator_index_dollars[axis_step(_ax_time_period, time_period, -1)])) else '...'))

    return data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_BY_YEAR.collect(evaluate(formula, data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_BY_YEAR.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_CHANGE_IN_GDP_DEFLATOR_FACTOR_BY_YEAR.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_US_GDP_DEFLATOR_PERCENT_CHANGE.schema, cells=data.MACRO_DEBT_US_GDP_DEFLATOR_PERCENT_CHANGE.cells)
def macro_debt_us_gdp_deflator_percent_change(*, macro_debt_none: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Computes the year-over-year percent change of the US GDP deflator.

    Derives the GDP deflator percent-change series over the macro projection-year domain.

    Args:
        macro_debt_none: Typed data series of US GDP deflator values or placeholders indexed by projection year; the prior year's value supplies the percent-change denominator.
        input3_input_3_macro_current_account: Typed Input 3 macro current-account series whose TIME_PERIOD axis validates schema alignment and defines the output projection-year coordinate domain.

    Returns:
        A data.Series[float | str | None] of US GDP deflator percent changes over the bound TIME_PERIOD domain, using a placeholder when the prior-year input is not numeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_sub(xl_div(macro_debt_none[time_period], macro_debt_none[axis_step(_ax_time_period, time_period, -1)]), 1), 100) if xl_bool(xl_isnumber(lambda: macro_debt_none[axis_step(_ax_time_period, time_period, -1)])) else '...'))

    return data.MACRO_DEBT_US_GDP_DEFLATOR_PERCENT_CHANGE.collect(evaluate(formula, data.MACRO_DEBT_US_GDP_DEFLATOR_PERCENT_CHANGE.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_US_GDP_DEFLATOR_PERCENT_CHANGE.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC.schema, cells=data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC.cells)
def macro_debt_exchange_rate_dollar_nc(*, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Invert a national-currency-per-U.S.-dollar exchange rate series into U.S. dollars per unit of national currency.

    Derive the dollar-denominated exchange rate used by macro-debt calculations by taking the reciprocal of each projected period's rate over the current-account year axis.

    Args:
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Typed series of exchange rates expressed as national currency per U.S. dollar, keyed by projection years; each entry is a float, text, or blank and is inverted individually.
        input3_input_3_macro_current_account: Typed current-account input series whose domain supplies the validated TIME_PERIOD axis, fixing the projection years over which the reciprocal is evaluated and collected.

    Returns:
        Typed series of exchange rates expressed as U.S. dollars per unit of national currency, keyed by the same projection years, retaining float, text, or blank values from the reciprocal computation.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_div(1, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC.collect(evaluate(formula, data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_EXCHANGE_RATE_DOLLAR_NC.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION.schema, cells=data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION.cells)
def macro_debt_depreciation_of_nc_depreciation(*, macro_debt_exchange_rate_dollar_nc: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute annual depreciation of the national currency from exchange-rate changes.

    Derive the macro-debt depreciation series used in external debt dynamics, with positive values indicating depreciation.

    Args:
        macro_debt_exchange_rate_dollar_nc: Exchange-rate time series in dollars per unit of national currency, keyed by projection years and evaluated against its prior-year value.
        input3_input_3_macro_current_account: Macro current-account input series that supplies the TIME_PERIOD domain and projection-year coordinates used to validate and align the calculation.

    Returns:
        A data.Series[float | str | None] of national-currency depreciation by projection year, positive for depreciation and carrying missing or text placeholders where the calculation is not numeric.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_mul(xl_neg(100), xl_sub(xl_div(macro_debt_exchange_rate_dollar_nc[time_period], macro_debt_exchange_rate_dollar_nc[axis_step(_ax_time_period, time_period, -1)]), 1)) if xl_bool(xl_isnumber(lambda: xl_mul(xl_neg(100), xl_sub(xl_div(macro_debt_exchange_rate_dollar_nc[time_period], macro_debt_exchange_rate_dollar_nc[axis_step(_ax_time_period, time_period, -1)]), 1)))) else '...'))

    return data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION.collect(evaluate(formula, data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_DEPRECIATION_OF_NC_DEPRECIATION.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(key=(), domain=None, cells=data.START_DEBT_SUSTAINABILITY_ANALYSIS_CELLS)
def start_debt_sustainability_analysis(*, start_working_language: Literal["English", "Espa\u00f1ol", "Fran\u00e7ais", "Portugues"], lookup_language_native_name: data.Series[str | None], lookup_language_english_name: data.Series[str | None]) -> str | int | float | bool:
    """Return the English-language name for a selected working language.

    Resolve the single-cell language lookup used by the debt sustainability analysis start anchor.

    Args:
        start_working_language: Selected working language, restricted to English, Español, Français, or Portugues.
        lookup_language_native_name: Named-axis series over catalog language coordinates holding native language names, with nulls allowed.
        lookup_language_english_name: Named-axis series over catalog language coordinates holding English language names, with nulls allowed.

    Returns:
        A scalar string giving the matched English language name, or the spreadsheet error code when the lookup fails; the str | int | float | bool annotation reflects the lookup and error-result surface.
    """
    data.LOOKUP_LANGUAGE_NATIVE_NAME.schema.validate(lookup_language_native_name)
    data.LOOKUP_LANGUAGE_ENGLISH_NAME.schema.validate(lookup_language_english_name)
    _start_debt_sustainability_analysis_table_0 = lazy_table(((view(lookup_language_native_name, rows=data.LANGUAGE_AXIS.keys), view(lookup_language_english_name, rows=data.LANGUAGE_AXIS.keys)),))
    try:
        return as_measure(xl_vlookup(start_working_language, _start_debt_sustainability_analysis_table_0, 2, False), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.START_DEBT_SUSTAINABILITY_ANALYSIS_M_CELLS)
def start_debt_sustainability_analysis_m(*, start_debt_sustainability_analysis: str | int | float | bool) -> int | str:
    """Compute the START debt sustainability analysis language anchor as a numeric code.

    Resolve the single-cell Debt Sustainability Analysis (START) selection to the language index used by the authored workbook identities.

    Args:
        start_debt_sustainability_analysis: Scalar language selector whose English, French, and Portuguese values map to 0, 1, and 2; any other value maps to 3.

    Returns:
        Integer language code (0 for English, 1 for French, 2 for Portuguese, 3 otherwise), or the XlError code string when evaluation fails.
    """
    try:
        return as_measure((0 if xl_bool(xl_eq(start_debt_sustainability_analysis, 'English')) else (1 if xl_bool(xl_eq(start_debt_sustainability_analysis, 'French')) else (2 if xl_bool(xl_eq(start_debt_sustainability_analysis, 'Portuguese')) else 3))), 'int')
    except XlError as error:
        return error.code

