@publish(data.INPUT6_STANDARD_PARAMS_2.schema, cells=data.INPUT6_STANDARD_PARAMS_2.cells)
def input6_standard_params_2(*, in6opt_standard_inflation_elasticity_default: float | str, in6opt_standard_addl_borrowing_cost_default: float | str, in6opt_standard_gdp_exports_elasticity_default: float | str, in6opt_standard_fx_passthrough_default: float | str, in6opt_standard_nx_elasticity_default: float | str, in6opt_standard_us_inflation_default: float | str) -> data.Series[float | str | None]:
    """Build the standardized LIC-DSF stress-test parameter series from Input 6 defaults.

    Map Input 6 standardized-stress default scalars to LIC-DSF parameter fields for internal formula use.

    Args:
        in6opt_standard_inflation_elasticity_default: Default inflation elasticity for the standardized stress-test options, supplied as a scalar or workbook string.
        in6opt_standard_addl_borrowing_cost_default: Default additional borrowing cost for the standardized stress-test options, supplied as a scalar or workbook string.
        in6opt_standard_gdp_exports_elasticity_default: Default GDP-to-exports elasticity for the standardized stress-test options, supplied as a scalar or workbook string.
        in6opt_standard_fx_passthrough_default: Default exchange-rate passthrough coefficient for the standardized stress-test options, supplied as a scalar or workbook string.
        in6opt_standard_nx_elasticity_default: Default net-export elasticity for the standardized stress-test options, supplied as a scalar or workbook string.
        in6opt_standard_us_inflation_default: Default U.S. inflation rate for the standardized stress-test options, supplied as a scalar or workbook string.

    Returns:
        A data.Series[float | str | None] of standardized stress-test parameter values indexed by LIC-DSF parameter field name, preserving the authored coordinate metadata and workbook blank/string sentinels.
    """
    def formula(parameter: str, variant: str) -> float | str | None:
        if parameter == 'b1_real_gdp_growth':
            return as_measure(in6opt_standard_inflation_elasticity_default)
        elif parameter == 'b2_primary_balance':
            return as_measure(in6opt_standard_addl_borrowing_cost_default)
        elif parameter == 'b3_exports':
            return as_measure(in6opt_standard_gdp_exports_elasticity_default)
        elif parameter == 'b5_depreciation_1':
            return as_measure(in6opt_standard_fx_passthrough_default)
        elif parameter == 'b5_depreciation_2':
            return as_measure(in6opt_standard_nx_elasticity_default)
        elif parameter == 'b5_depreciation_3':
            return as_measure(in6opt_standard_us_inflation_default)
        elif parameter == 'b6_combination':
            return as_measure(input6_standard_params_2['b1_real_gdp_growth', variant])
        elif parameter == 'real_overvaluation_eba':
            return as_measure(input6_standard_params_2['b5_depreciation_1', variant])
        return as_measure(input6_standard_params_2['b5_depreciation_2', variant])

    input6_standard_params_2 = CoordinateReader('input6_standard_params_2', data.INPUT6_STANDARD_PARAMS_2.required, formula)
    return data.INPUT6_STANDARD_PARAMS_2.collect((coord, input6_standard_params_2[coord]) for coord in data.INPUT6_STANDARD_PARAMS_2.required)

@publish(data.LEFTOVER_PRIMARY_DEFICIT.schema, cells=data.LEFTOVER_PRIMARY_DEFICIT.cells)
def leftover_primary_deficit(*, a1_hist_pub_historical_statistics: data.Series[float | str | None], baseline_pub_primary_deficit_by_indicator: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Builds the leftover primary-deficit series from historical and baseline primary-deficit inputs.

    Selects the historical-average primary deficit at the configured time position and the baseline standard deficit elsewhere, aligned to the macro current-account time axis.

    Args:
        a1_hist_pub_historical_statistics: Historical public primary-deficit statistics series containing the historical-average values used for the special time-period position.
        baseline_pub_primary_deficit_by_indicator: Baseline primary-deficit-by-indicator series supplying the standard baseline deficit values for other time periods.
        input3_input_3_macro_current_account: Macro current-account input object whose TIME_PERIOD axis is validated and used to align and evaluate the output series.

    Returns:
        A data.Series[float | str | None] of primary-deficit leftover values keyed by scenario and year, with historical-average or baseline-standard values selected according to the time-period position.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 12:
            return as_measure(a1_hist_pub_historical_statistics['Primary deficit', 'Historical average'])
        return as_measure(baseline_pub_primary_deficit_by_indicator['Standard'])

    return data.LEFTOVER_PRIMARY_DEFICIT.collect(evaluate(formula, data.LEFTOVER_PRIMARY_DEFICIT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.LEFTOVER_PRIMARY_DEFICIT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.CUSTOMIZED_SCENARIO_SPEC.schema, cells=data.CUSTOMIZED_SCENARIO_SPEC.cells)
def customized_scenario_spec(*, input6_tailored_params_2: data.Series[float | str | None], input6_tailored_params_3: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute the customized-scenario specification series from tailored shock parameters and macro current-account time coordinates.

    Assemble the customized-scenario spec over the macro current-account TIME_PERIOD axis, substituting tailored Input 6 shock values at the shock year and carrying other entries through coordinate identities.

    Args:
        input6_tailored_params_2: Tailored-parameter series of floats, strings, or None providing the market PPG debt-to-GDP shock used for the customized scenario's size-of-shock entry.
        input6_tailored_params_3: Tailored-parameter series of floats, strings, or None providing disaster-associated real GDP growth and export growth shocks keyed by their tailored-parameter labels.
        input3_input_3_macro_current_account: Macro current-account input series whose TIME_PERIOD axis supplies the coordinate domain and lagged time stepping for binding and collecting the customized-scenario specification.

    Returns:
        A data.Series[float | str | None] containing customized-scenario specification values over the required customized-scenario coordinates bound to the macro current-account TIME_PERIOD domain.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(parameter: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        PARAMETER_TO_INPUT6_TAILORED_PARAMS_3 = {'size_of_associated_real_gdp_growth_shock': 'disaster_shock_pct_gdp', 'size_of_associated_exports_growth_shock': 'disaster_export_growth_shock'}
        if parameter == 'size_of_shock' and _p_time_period == 12:
            return as_measure(input6_tailored_params_2['mkt_ppg_debt_gdp_shock'])
        elif parameter in ('size_of_associated_real_gdp_growth_shock', 'size_of_associated_exports_growth_shock') and _p_time_period == 12:
            return as_measure(input6_tailored_params_3[PARAMETER_TO_INPUT6_TAILORED_PARAMS_3[parameter]])
        return as_measure(customized_scenario_spec[parameter, axis_step(_ax_time_period, time_period, 1)])

    customized_scenario_spec = CoordinateReader('customized_scenario_spec', data.CUSTOMIZED_SCENARIO_SPEC.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    for coordinate in reversed(tuple(data.CUSTOMIZED_SCENARIO_SPEC.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))):
        customized_scenario_spec[coordinate]
    return data.CUSTOMIZED_SCENARIO_SPEC.collect(((coord, customized_scenario_spec[coord]) for coord in data.CUSTOMIZED_SCENARIO_SPEC.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.CUSTOMIZED_SCENARIO_SPEC.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.LEFTOVER_REAL_GDP_GROWTH.schema, cells=data.LEFTOVER_REAL_GDP_GROWTH.cells)
def leftover_real_gdp_growth(*, a1_hist_pub_historical_statistics: data.Series[float | str | None], baseline_pub_real_gdp_growth_by_indicator: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute the leftover real GDP growth series from historical-average and baseline indicator paths.

    Resolve each scenario-year cell to the A1 historical average at the terminal historical year and to the baseline standard path otherwise, producing leftover real GDP growth keyed by scenario and year.

    Args:
        a1_hist_pub_historical_statistics: Historical-statistics series of real GDP growth values (float, text, or blank) over catalog coordinates, including the 'Real GDP growth (in percent)', 'Historical average' label used for the terminal historical year.
        baseline_pub_real_gdp_growth_by_indicator: Baseline real GDP growth series by indicator (float, text, or blank) over catalog coordinates, whose 'Standard' label supplies projection-year values.
        input3_input_3_macro_current_account: Validated macro current-account input dataclass whose TIME_PERIOD axis provides the year grid and horizon position used to switch between historical-average and baseline sources.

    Returns:
        A data.Series[float | str | None] of leftover real GDP growth values keyed by scenario and year, aligned to the current-account TIME_PERIOD axis.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 12:
            return as_measure(a1_hist_pub_historical_statistics['Real GDP growth (in percent)', 'Historical average'])
        return as_measure(baseline_pub_real_gdp_growth_by_indicator['Standard'])

    return data.LEFTOVER_REAL_GDP_GROWTH.collect(evaluate(formula, data.LEFTOVER_REAL_GDP_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.LEFTOVER_REAL_GDP_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

