@publish(data.CI_SUMMARY_MEDIUM.schema, cells=data.CI_SUMMARY_MEDIUM.cells)
def ci_summary_medium(*, imported_composite_indicator: data.Series[str | int | float | bool | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[str | int | float | bool | None]:
    """Selects the prior- or current-vintage imported composite indicator value for CI Summary medium outputs.

    Provides the internal lookup that populates CI Summary medium cells from the appropriate vintage based on the old-debt-service time axis.

    Args:
        imported_composite_indicator: A typed data series over catalog coordinates holding imported composite indicator text or scalar values.
        input3_old_debt_service: Typed input data for old debt service whose TIME_PERIOD axis supplies the previous and current vintage keys.

    Returns:
        A data.Series[str | int | float | bool | None] containing the selected imported composite-indicator value keyed by the CI Summary medium coordinates.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(indicator: str) -> str | int | float | bool | None:
        if indicator == 'Classification based on the previous vintage':
            return as_measure(imported_composite_indicator[input3_old_debt_service.domain.axis('TIME_PERIOD').keys[0]], 'str')
        return as_measure(imported_composite_indicator[input3_old_debt_service.domain.axis('TIME_PERIOD').keys[1]], 'str')

    return data.CI_SUMMARY_MEDIUM.collect(evaluate(formula, data.CI_SUMMARY_MEDIUM.required))

