@publish(data.REALISM1_PUBLIC_VINTAGE_DEBT_PATHS.schema, cells=data.REALISM1_PUBLIC_VINTAGE_DEBT_PATHS.cells)
def realism1_public_vintage_debt_paths(*, realism1_public_current_vintage_projection: data.Series[float | str | None], realism1_public_five_years_ago_rebased_projection: data.Series[float | str | None], realism1_public_last_vintage_stock_copies: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Realism1PublicVintageDebtPaths:
    """Assemble the Realism 1 vintage public-debt paths across current, previous, and five-years-ago rebased DSA projections.

    Selects the public-sector-debt-to-GDP measure from each vintage projection for every time period and collects the results into the Realism 1 public vintage debt path series.

    Args:
        realism1_public_current_vintage_projection: Named-axis series of the current-vintage public debt projection, varying over the TIME_PERIOD coordinate and holding the public-sector-debt-to-GDP measure per period (numeric values, text labels, or blanks).
        realism1_public_five_years_ago_rebased_projection: Named-axis series of the five-years-ago rebased public debt projection over the same TIME_PERIOD coordinate and public-sector-debt-to-GDP measure, supplying the rebased vintage path.
        realism1_public_last_vintage_stock_copies: Named-axis series of the last-vintage stock copies over the same TIME_PERIOD coordinate and public-sector-debt-to-GDP measure, supplying the previous DSA path.
        input3_input_3_macro_current_account: Macro current-account input dataclass whose domain supplies the TIME_PERIOD axis and schema used to validate and position periods for the vintage path lookup.

    Returns:
        A Realism1PublicVintageDebtPaths dataclass of series holding the current, previous, and five-years-ago rebased public debt paths over the TIME_PERIOD axis.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Current DSA':
            return as_measure(realism1_public_current_vintage_projection['Public sector debt (in percent of GDP)', time_period])
        elif scenario == 'Previous DSA':
            return as_measure(realism1_public_last_vintage_stock_copies['Public sector debt (in percent of GDP)', time_period])
        return as_measure(realism1_public_five_years_ago_rebased_projection['Public sector debt (in percent of GDP)', time_period])

    return data.REALISM1_PUBLIC_VINTAGE_DEBT_PATHS.collect(evaluate(formula, data.REALISM1_PUBLIC_VINTAGE_DEBT_PATHS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM1_PUBLIC_VINTAGE_DEBT_PATHS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

