@publish(data.REALISM2_FISCAL_ADJUSTMENT_YEARS.schema, cells=data.REALISM2_FISCAL_ADJUSTMENT_YEARS.cells)
def realism2_fiscal_adjustment_years(*, realism2_history_years: data.Series[int | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Realism2FiscalAdjustmentYears:
    """Compute the Realism 2 fiscal-adjustment year axis from historical anchors over the macro current-account time grid.

    Derive the fiscal-adjustment-on-growth panel's year coordinates by anchoring at the history year and stepping backward and forward across TIME_PERIOD.

    Args:
        realism2_history_years: Historical year series supplying the anchor value used at the designated history coordinate; non-history coordinates are calculated from the adjacent year.
        input3_input_3_macro_current_account: Macro current-account series whose TIME_PERIOD axis defines the coordinate grid and position mapping for the fiscal-adjustment year series.

    Returns:
        A data.Realism2FiscalAdjustmentYears series containing the fiscal-adjustment year coordinate values indexed over the supplied TIME_PERIOD domain.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 13:
            return as_measure(realism2_history_years[time_period], 'int')
        elif _p_time_period == 14:
            return as_measure(xl_add(realism2_fiscal_adjustment_years[axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        return as_measure(xl_sub(realism2_fiscal_adjustment_years[axis_step(_ax_time_period, time_period, 1)], 1), 'int')

    realism2_fiscal_adjustment_years = CoordinateReader('realism2_fiscal_adjustment_years', data.REALISM2_FISCAL_ADJUSTMENT_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.REALISM2_FISCAL_ADJUSTMENT_YEARS.collect(((coord, realism2_fiscal_adjustment_years[coord]) for coord in data.REALISM2_FISCAL_ADJUSTMENT_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM2_FISCAL_ADJUSTMENT_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

