@publish(data.REALISM2_GROWTH_T_MINUS_1.schema, cells=data.REALISM2_GROWTH_T_MINUS_1.cells)
def realism2_growth_t_minus_1(*, realism2_baseline_growth: data.Realism2BaselineGrowth, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Realism2GrowthTMinus1:
    """Build the lagged Realism 2 growth series carried into the underlying-growth panel.

    Shifts baseline growth across the projection grid so prior-period growth values are available for the Realism 2 underlying-growth panel.

    Args:
        realism2_baseline_growth: Baseline growth series over catalog coordinates, providing the anchor growth value at the first projection period.
        input3_input_3_macro_current_account: Macro current-account input series whose TIME_PERIOD axis supplies the output domain and validates coordinate alignment.

    Returns:
        A data.Realism2GrowthTMinus1 series aligned to the current-account TIME_PERIOD axis, containing pre-projection growth carried into the underlying-growth panel.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 12:
            return as_measure(realism2_baseline_growth[_ax_time_period.keys[12]])
        return as_measure(realism2_growth_t_minus_1[axis_step(_ax_time_period, time_period, -1)])

    realism2_growth_t_minus_1 = CoordinateReader('realism2_growth_t_minus_1', data.REALISM2_GROWTH_T_MINUS_1.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.REALISM2_GROWTH_T_MINUS_1.collect(((coord, realism2_growth_t_minus_1[coord]) for coord in data.REALISM2_GROWTH_T_MINUS_1.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM2_GROWTH_T_MINUS_1.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM2_FISCAL_ADJUSTMENT_GROWTH_IMPACT.schema, cells=data.REALISM2_FISCAL_ADJUSTMENT_GROWTH_IMPACT.cells)
def realism2_fiscal_adjustment_growth_impact(*, realism2_growth_impact_multiplier_0_2_cumulative: data.Series[float | str | None], realism2_growth_impact_multiplier_0_4_cumulative: data.Series[float | str | None], realism2_growth_impact_multiplier_0_6_cumulative: data.Series[float | str | None], realism2_growth_impact_multiplier_0_8_cumulative: data.Series[float | str | None], realism2_growth_impact_multiplier_1_0_cumulative: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Realism2FiscalAdjustmentGrowthImpact:
    """Build the Realism 2 growth-impact table for the planned fiscal adjustment across the five cumulative multiplier variants.

    Selects, per projection year, the cumulative growth impact belonging to each fiscal-multiplier variant so the Realism 2 fiscal-adjustment chart can be assembled on the shared catalog year axis.

    Args:
        realism2_growth_impact_multiplier_0_2_cumulative: Cumulative growth impact series for the 0.2 fiscal multiplier, a named-axis tensor over catalog coordinates whose cells hold floats, text, or blanks.
        realism2_growth_impact_multiplier_0_4_cumulative: Cumulative growth impact series for the 0.4 fiscal multiplier, a named-axis tensor over catalog coordinates whose cells hold floats, text, or blanks.
        realism2_growth_impact_multiplier_0_6_cumulative: Cumulative growth impact series for the 0.6 fiscal multiplier, a named-axis tensor over catalog coordinates whose cells hold floats, text, or blanks.
        realism2_growth_impact_multiplier_0_8_cumulative: Cumulative growth impact series for the 0.8 fiscal multiplier, a named-axis tensor over catalog coordinates whose cells hold floats, text, or blanks.
        realism2_growth_impact_multiplier_1_0_cumulative: Cumulative growth impact series for the 1.0 fiscal multiplier, a named-axis tensor over catalog coordinates whose cells hold floats, text, or blanks; it also supplies the fallback value for any variant outside the four lower multipliers.
        input3_old_debt_service: Old debt service record whose TIME_PERIOD axis fixes the projection-year grid that every multiplier series is reindexed onto before evaluation.

    Returns:
        A Realism2FiscalAdjustmentGrowthImpact dataclass of series: one growth-impact path per multiplier variant label, laid out over the TIME_PERIOD coordinate inherited from the old debt service input, carrying floats, text, or blanks.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int, variant: str) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if variant == 'Multiplier = 0.2':
            return as_measure(realism2_growth_impact_multiplier_0_2_cumulative[time_period])
        elif variant == 'Multiplier = 0.4':
            return as_measure(realism2_growth_impact_multiplier_0_4_cumulative[time_period])
        elif variant == 'Multiplier = 0.6':
            return as_measure(realism2_growth_impact_multiplier_0_6_cumulative[time_period])
        elif variant == 'Multiplier = 0.8':
            return as_measure(realism2_growth_impact_multiplier_0_8_cumulative[time_period])
        return as_measure(realism2_growth_impact_multiplier_1_0_cumulative[time_period])

    return data.REALISM2_FISCAL_ADJUSTMENT_GROWTH_IMPACT.collect(evaluate(formula, data.REALISM2_FISCAL_ADJUSTMENT_GROWTH_IMPACT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.REALISM2_FISCAL_ADJUSTMENT_GROWTH_IMPACT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.REALISM2_UNDERLYING_GROWTH.schema, cells=data.REALISM2_UNDERLYING_GROWTH.cells)
def realism2_underlying_growth(*, realism2_growth_t_minus_1: data.Realism2GrowthTMinus1, realism2_fiscal_adjustment_growth_impact: data.Realism2FiscalAdjustmentGrowthImpact, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Realism2UnderlyingGrowth:
    """Derive underlying growth paths under alternative fiscal-multiplier assumptions for the Realism 2 fiscal-multiplier tool.

    Seed the first projection year from prior-period growth and accumulate the fiscal-adjustment growth impact across multiplier variants to produce the full underlying-growth path.

    Args:
        realism2_growth_t_minus_1: Named-axis series of prior-period growth rates over the projection-year grid, supplying the starting value for the first projected year and the baseline for subsequent accumulation.
        realism2_fiscal_adjustment_growth_impact: Named-axis series of fiscal-adjustment growth impacts indexed by projection year and multiplier variant, added to prior-period growth in every projected year after the first.
        input3_input_3_macro_current_account: Named-axis macro current-account series whose TIME_PERIOD axis defines the projection-year domain and variant coordinates the output is bound to.
        input3_old_debt_service: Named-axis historical debt service series on the same projection grid; validated for schema and coordinate consistency with the rest of the calculation.

    Returns:
        A typed data.Realism2UnderlyingGrowth series giving underlying growth for each projection year and multiplier variant, with the first projected year taken from prior-period growth and later years equal to prior-period growth plus the variant's fiscal-adjustment impact.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int, variant: str) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        VARIANT_TO_REALISM2_UNDERLYING_GROWTH = {'Multiplier = 0.4': 'Multiplier = 0.2', 'Multiplier = 0.6': 'Multiplier = 0.4', 'Multiplier = 0.8': 'Multiplier = 0.6', 'Multiplier = 1': 'Multiplier = 0.8'}
        if _p_time_period == 12 and variant == 'Multiplier = 0.2':
            return as_measure(realism2_growth_t_minus_1[time_period])
        elif _p_time_period == 12 and variant in ('Multiplier = 0.4', 'Multiplier = 0.6', 'Multiplier = 0.8', 'Multiplier = 1'):
            return as_measure(realism2_underlying_growth[time_period, VARIANT_TO_REALISM2_UNDERLYING_GROWTH[variant]])
        return as_measure(xl_add(realism2_growth_t_minus_1[time_period], realism2_fiscal_adjustment_growth_impact[time_period, variant]))

    realism2_underlying_growth = CoordinateReader('realism2_underlying_growth', data.REALISM2_UNDERLYING_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.REALISM2_UNDERLYING_GROWTH.collect(((coord, realism2_underlying_growth[coord]) for coord in data.REALISM2_UNDERLYING_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM2_UNDERLYING_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM3_INVESTMENT_YEARS.schema, cells=data.REALISM3_INVESTMENT_YEARS.cells)
def realism3_investment_years(*, realism3_first_projection_year: int | str, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Realism3InvestmentYears:
    """Build the Realism 3 investment-year series.

    Generate the year axis used by the public/private investment vintage-comparison chart.

    Args:
        realism3_first_projection_year: Anchor year, as an integer or string, assigned at the first projection period and used to seed the surrounding year sequence.
        input3_input_3_macro_current_account: Macro current-account series whose TIME_PERIOD coordinate axis defines the year grid over which investment years are constructed.

    Returns:
        A Realism3InvestmentYears series indexed by TIME_PERIOD, seeded from the anchor year and extended by one year per period.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 13:
            return as_measure(realism3_first_projection_year, 'int')
        elif _p_time_period >= 14:
            return as_measure(xl_add(realism3_investment_years[axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        return as_measure(xl_sub(realism3_investment_years[axis_step(_ax_time_period, time_period, 1)], 1), 'int')

    realism3_investment_years = CoordinateReader('realism3_investment_years', data.REALISM3_INVESTMENT_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.REALISM3_INVESTMENT_YEARS.collect(((coord, realism3_investment_years[coord]) for coord in data.REALISM3_INVESTMENT_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_INVESTMENT_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM3_INVESTMENT_PATH_LABELS.schema, cells=data.REALISM3_INVESTMENT_PATH_LABELS.cells)
def realism3_investment_path_labels(*, translation_investment_phrases: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> data.Realism3InvestmentPathLabels:
    """Compute the Realism 3 investment-path row legends from translated investment phrases.

    Resolve the previous and current DSA public and private investment path labels used by the Realism 3 Invest-Growth tool.

    Args:
        translation_investment_phrases: Keyword-only data.Series[str | None] of translated investment phrases indexed by indicator and language, whose English entries supply the row legends for previous and current DSA public and private investment paths.
        start_debt_sustainability_analysis_m: Keyword-only scalar (int or str) selecting the start column or year of the debt sustainability analysis on the English language axis used to look up each phrase.

    Returns:
        A data.Realism3InvestmentPathLabels dataclass whose fields are typed data.Series[str | None] giving the previous and current DSA public and private investment path row legends.
    """
    data.TRANSLATION_INVESTMENT_PHRASES.schema.validate(translation_investment_phrases)
    def formula(indicator: str) -> str | int | float | bool | None:
        return as_measure(translation_investment_phrases[indicator, axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')

    return data.REALISM3_INVESTMENT_PATH_LABELS.collect(evaluate(formula, data.REALISM3_INVESTMENT_PATH_LABELS.required))

@publish(data.REALISM3_PUBLIC_PRIVATE_INVESTMENT_PATHS.schema, cells=data.REALISM3_PUBLIC_PRIVATE_INVESTMENT_PATHS.cells)
def realism3_public_private_investment_paths(*, realism3_public_investment_ratio_by_vintage: data.Series[float | str | None], realism3_private_investment_ratio_by_vintage: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Realism3PublicPrivateInvestmentPaths:
    """Build public and private investment-to-GDP paths by DSA vintage from Realism 3 ratios on the macro current-account year grid.

    Map current and previous DSA vintage public and private investment ratios to the indicator rows used by the Realism 3 investment-growth chart.

    Args:
        realism3_public_investment_ratio_by_vintage: Public investment ratio (% of GDP) as a data series indexed by DSA vintage and time period, carrying previous and current vintage values; non-numeric entries are emitted as blanks.
        realism3_private_investment_ratio_by_vintage: Private investment ratio (% of GDP) as a data series indexed by DSA vintage and time period, carrying previous and current vintage values; non-numeric entries are emitted as blanks.
        input3_input_3_macro_current_account: Macro current-account input series whose TIME_PERIOD axis supplies the projection-year domain and indicator alignment for the collected investment paths.

    Returns:
        A data.Realism3PublicPrivateInvestmentPaths binding of collected public and private investment ratio paths over the TIME_PERIOD domain derived from the current-account input.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(indicator: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        INDICATOR_TO_REALISM3_PUBLIC_INVESTMENT_RATIO_BY_VINTAGE = {'Gov. Invest. - Prev. DSA': 'Previous', 'Gov. Invest. - Curr. DSA': 'Current'}
        INDICATOR_TO_REALISM3_PRIVATE_INVESTMENT_RATIO_BY_VINTAGE = {'Priv. Invest. - Prev. DSA': 'Previous', 'Priv. Invest. - Curr. DSA': 'Current'}
        if indicator in ('Gov. Invest. - Prev. DSA', 'Gov. Invest. - Curr. DSA'):
            return as_measure((realism3_public_investment_ratio_by_vintage[INDICATOR_TO_REALISM3_PUBLIC_INVESTMENT_RATIO_BY_VINTAGE[indicator], time_period] if xl_bool(xl_isnumber(lambda: xl_mul(realism3_public_investment_ratio_by_vintage[INDICATOR_TO_REALISM3_PUBLIC_INVESTMENT_RATIO_BY_VINTAGE[indicator], time_period], 100))) else ''))
        return as_measure((realism3_private_investment_ratio_by_vintage[INDICATOR_TO_REALISM3_PRIVATE_INVESTMENT_RATIO_BY_VINTAGE[indicator], time_period] if xl_bool(xl_isnumber(lambda: xl_mul(realism3_private_investment_ratio_by_vintage[INDICATOR_TO_REALISM3_PRIVATE_INVESTMENT_RATIO_BY_VINTAGE[indicator], time_period], 100))) else ''))

    return data.REALISM3_PUBLIC_PRIVATE_INVESTMENT_PATHS.collect(evaluate(formula, data.REALISM3_PUBLIC_PRIVATE_INVESTMENT_PATHS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_PUBLIC_PRIVATE_INVESTMENT_PATHS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM3_GROWTH_ACCOUNTING_VINTAGES.schema, cells=data.REALISM3_GROWTH_ACCOUNTING_VINTAGES.cells)
def realism3_growth_accounting_vintages(*, translation_projection_phrases: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> data.Realism3GrowthAccountingVintages:
    """Assemble the vintage headers for the Realism 3 investment-growth accounting summary.

    Resolves each required vintage variant's translated projection phrase for the given DSA start year and collects the results into the Realism 3 growth-accounting vintage structure.

    Args:
        translation_projection_phrases: Named-axis series of the language-specific projection phrases used as vintage headers, with None for variants that have no phrase on the selected language axis.
        start_debt_sustainability_analysis_m: Scalar start year of the debt sustainability analysis, used as the step offset along the language axis when selecting which vintage phrase applies.

    Returns:
        data.Realism3GrowthAccountingVintages dataclass of named-axis series, one entry per required vintage variant, holding the resolved growth-accounting vintage headers.
    """
    data.TRANSLATION_PROJECTION_PHRASES.schema.validate(translation_projection_phrases)
    def formula(variant: str) -> str | int | float | bool | None:
        return as_measure(translation_projection_phrases[variant, axis_step(span(data.LANGUAGE_AXIS, 'English', 'French'), 'English', start_debt_sustainability_analysis_m)], 'str')

    return data.REALISM3_GROWTH_ACCOUNTING_VINTAGES.collect(evaluate(formula, data.REALISM3_GROWTH_ACCOUNTING_VINTAGES.required))

@publish(data.REALISM3_GROWTH_ACCOUNTING_CONTRIBUTIONS.schema, cells=data.REALISM3_GROWTH_ACCOUNTING_CONTRIBUTIONS.cells)
def realism3_growth_accounting_contributions(*, realism3_growth_contributions: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Realism3GrowthAccountingContributions:
    """Compute five-year-average growth-accounting contributions from authored coordinate identities.

    Averages government-capital and other factor contributions over historical and projected five-year windows to populate the Realism 3 invest-growth summary.

    Args:
        realism3_growth_contributions: Named-axis series of growth-contribution values (numeric measures, labels, or blanks) indexed by contribution indicator and DSA vintage variant, supplying the per-period contributions to average.
        input3_input_3_macro_current_account: Macro current-account input series whose TIME_PERIOD axis determines the historical and projected five-year windows used for each average.

    Returns:
        A data.Realism3GrowthAccountingContributions series holding the five-year-average contribution of government capital and other factors to growth.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(indicator: str, variant: str) -> float | str | None:
        if variant == 'Historical':
            return as_measure(xl_average(view(realism3_growth_contributions, rows=(f'{indicator} - Curr. DSA',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))))
        elif variant == 'Projected (Prev. DSA)':
            return as_measure(xl_average(view(realism3_growth_contributions, rows=(f'{indicator} - Prev. DSA',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))))
        return as_measure(xl_average(view(realism3_growth_contributions, rows=(f'{indicator} - Curr. DSA',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))))

    return data.REALISM3_GROWTH_ACCOUNTING_CONTRIBUTIONS.collect(evaluate(formula, data.REALISM3_GROWTH_ACCOUNTING_CONTRIBUTIONS.required))

@publish(key=(), domain=None, cells=data.REALISM4_PROJECTED_3YR_ADJUSTMENT_LABEL_CELLS)
def realism4_projected_3yr_adjustment_label(*, translation_adjustment_phrase: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> str | int | float | bool:
    """Return the projected 3-year fiscal-adjustment label used by the Realism 4 chart.

    Selects the English translation of the Realism 4 projected adjustment phrase for the DSA horizon.

    Args:
        translation_adjustment_phrase: Translated adjustment-label phrases as a data.Series[str | None] over the catalog language axis, allowing null entries.
        start_debt_sustainability_analysis_m: Scalar DSA-start coordinate, integer or text, used to pick the English-language phrase step.

    Returns:
        A scalar result typed str | int | float | bool; in practice the selected English projected 3-year adjustment label or an Excel error code string when the lookup fails.
    """
    data.TRANSLATION_ADJUSTMENT_PHRASE.schema.validate(translation_adjustment_phrase)
    try:
        return as_measure(translation_adjustment_phrase[axis_step(span(data.LANGUAGE_AXIS, 'English', 'French'), 'English', start_debt_sustainability_analysis_m)], 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.REALISM4_PROJECTED_3YR_ADJUSTMENT_CELLS)
def realism4_projected_3yr_adjustment(*, realism4_three_year_adjustment: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> float | str:
    """Return the Realism 4 projected three-year fiscal adjustment for the third time period.

    Selects the third TIME_PERIOD value from the Realism 4 fiscal-adjustment series so downstream Realism 4 outputs can report the projected three-year adjustment.

    Args:
        realism4_three_year_adjustment: Series of the projected three-year fiscal adjustment (ppt of GDP) indexed over catalog coordinates, including the TIME_PERIOD axis used for the lookup.
        input3_old_debt_service: Validated old-debt-service series whose TIME_PERIOD axis supplies the coordinate keys that select the adjustment value.

    Returns:
        The selected projected three-year fiscal adjustment as a float, or the Excel error-code string when the lookup raises an XlError.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    try:
        return as_measure(realism4_three_year_adjustment[input3_old_debt_service.domain.axis('TIME_PERIOD').keys[2]])
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.REALISM4_PROJECTED_3YR_ADJUSTMENT_BIN_CELLS)
def realism4_projected_3yr_adjustment_bin(*, realism4_projected_3yr_adjustment: float | str) -> float | str:
    """Round the projected three-year fiscal adjustment to the nearest histogram bin edge.

    Supports Realism 4 fiscal-adjustment placement by snapping the projected adjustment to a half-unit histogram bin.

    Args:
        realism4_projected_3yr_adjustment: Projected three-year adjustment as a scalar float, or a string error code when the upstream calculation is unavailable.

    Returns:
        The binned projected three-year adjustment as a scalar float, or the propagated string error code if the calculation raises an XlError.
    """
    try:
        return as_measure(xl_div(xl_round(xl_mul(2, realism4_projected_3yr_adjustment), 0), 2))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.REALISM4_PROJECTED_3YR_ADJUSTMENT_CATEGORY_CELLS)
def realism4_projected_3yr_adjustment_category(*, realism4_projected_3yr_adjustment_bin: float | str, realism4_fiscal_adjustment_bin_edges: data.Series[float | str | None], realism4_fiscal_adjustment_bin_frequencies: data.Series[float | str | None], realism4_fiscal_adjustment_bin_categories: data.Series[int | str | None]) -> float | str:
    """Return the Realism 4 fiscal-adjustment histogram category index assigned to a projected 3-year adjustment.

    Classify the projected 3-year fiscal adjustment into the authored Realism 4 fiscal-adjustment bin distribution, clamping values outside the bin range to the first or last category.

    Args:
        realism4_projected_3yr_adjustment_bin: Scalar projected 3-year fiscal adjustment value (numeric or string bin label) to be located within the fiscal-adjustment bin table.
        realism4_fiscal_adjustment_bin_edges: Named-axis series of fiscal-adjustment bin edge values over the Realism 4 variant axis, used to bracket the projected adjustment value against the first and last edges.
        realism4_fiscal_adjustment_bin_frequencies: Named-axis series of bin frequencies aligned with the bin edges, supplying the distribution table consulted by the lookup.
        realism4_fiscal_adjustment_bin_categories: Named-axis series of integer or string histogram category indices aligned with the bin edges, providing the category returned for the bin that matches the projected adjustment.

    Returns:
        Scalar histogram category index (integer-valued float or string label) for the projected 3-year adjustment; values below the first edge or above the last edge map to the first or last category respectively, and a spreadsheet lookup error yields its error-code string.
    """
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_EDGES.schema.validate(realism4_fiscal_adjustment_bin_edges)
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_FREQUENCIES.schema.validate(realism4_fiscal_adjustment_bin_frequencies)
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_CATEGORIES.schema.validate(realism4_fiscal_adjustment_bin_categories)
    _realism4_projected_3yr_adjustment_category_table_0 = lazy_table(((view(realism4_fiscal_adjustment_bin_edges, rows=span(data.VARIANT_AXIS_5, 2, 27)), view(realism4_fiscal_adjustment_bin_frequencies, rows=span(data.VARIANT_AXIS_5, 2, 27)), view(realism4_fiscal_adjustment_bin_categories, rows=span(data.VARIANT_AXIS_5, 2, 27))),))
    try:
        return as_measure((realism4_fiscal_adjustment_bin_categories[1] if xl_bool(xl_lt(realism4_projected_3yr_adjustment_bin, realism4_fiscal_adjustment_bin_edges[2])) else (realism4_fiscal_adjustment_bin_categories[28] if xl_bool(xl_gt(realism4_projected_3yr_adjustment_bin, realism4_fiscal_adjustment_bin_edges[27])) else xl_vlookup(realism4_projected_3yr_adjustment_bin, _realism4_projected_3yr_adjustment_category_table_0, 3, False))))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.REALISM4_PROJECTED_3YR_ADJUSTMENT_SAMPLE_SHARE_CELLS)
def realism4_projected_3yr_adjustment_sample_share(*, realism4_projected_3yr_adjustment_category: float | str, realism4_fiscal_adjustment_bin_categories: data.Series[int | str | None], realism4_fiscal_adjustment_sample_share: data.Realism4FiscalAdjustmentSampleShare) -> float | str:
    """Return the Realism 4 percent-of-sample share for a projected 3-year fiscal-adjustment category.

    Look up the fiscal-adjustment sample share at the country's projected-adjustment bin.

    Args:
        realism4_projected_3yr_adjustment_category: Projected 3-year fiscal-adjustment category label or numeric bin key to match; scalar.
        realism4_fiscal_adjustment_bin_categories: Named-axis series of fiscal-adjustment bin categories (integer, string, or None) aligned to catalog coordinates; supplies the lookup keys.
        realism4_fiscal_adjustment_sample_share: Named-axis Realism4FiscalAdjustmentSampleShare series of percent-of-sample (Y) values aligned to the bin categories and catalog coordinates; supplies the matched share values.

    Returns:
        Scalar percent-of-sample (Y) share at the projected-adjustment bin, or an Excel error-code string if the lookup fails.
    """
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_CATEGORIES.schema.validate(realism4_fiscal_adjustment_bin_categories)
    _realism4_projected_3yr_adjustment_sample_share_table_0 = lazy_table(((view(realism4_fiscal_adjustment_bin_categories, rows=data.VARIANT_AXIS_5.keys), view(realism4_fiscal_adjustment_sample_share, rows=data.VARIANT_AXIS_5.keys)),))
    try:
        return as_measure(xl_vlookup(realism4_projected_3yr_adjustment_category, _realism4_projected_3yr_adjustment_sample_share_table_0, 2, False))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.REALISM4_FISCAL_ADJUSTMENT_TOP_BIN_LABEL_CELLS)
def realism4_fiscal_adjustment_top_bin_label(*, translation_more_phrase: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> str | int | float | bool:
    """Return the open-ended top-bin label for the Realism 4 fiscal-adjustment histogram.

    Resolve the top fiscal-adjustment bin label from a translation-phrase series at a debt-sustainability-analysis start coordinate.

    Args:
        translation_more_phrase: A named-axis data.Series of optional strings holding the translated 'More' phrase over the catalog's language coordinates.
        start_debt_sustainability_analysis_m: Scalar start-debt-sustainability-analysis marker, either an integer or string, used to select the coordinate step on the language axis.

    Returns:
        The selected top-bin label as a string, or the workbook XL error code when the coordinate lookup fails.
    """
    data.TRANSLATION_MORE_PHRASE.schema.validate(translation_more_phrase)
    try:
        return as_measure(translation_more_phrase[axis_step(span(data.LANGUAGE_AXIS, 'English', 'French'), 'English', start_debt_sustainability_analysis_m)], 'str')
    except XlError as error:
        return error.code

@publish(data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.schema, cells=data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.cells)
def realism4_fiscal_adjustment_sample_share(*, realism4_fiscal_adjustment_bin_frequencies: data.Series[float | str | None]) -> data.Realism4FiscalAdjustmentSampleShare:
    """Compute LIC-DSF Realism 4 fiscal-adjustment sample shares.

    Normalize 3-year fiscal-adjustment bin frequencies into percentage shares of the total LIC sample.

    Args:
        realism4_fiscal_adjustment_bin_frequencies: Keyword-only data.Series[float | str | None] giving the LIC sample percentage in each 3-year fiscal-adjustment bin; each entry is divided by the series total and scaled to 100.

    Returns:
        A data.Realism4FiscalAdjustmentSampleShare typed result mapping each fiscal-adjustment bin to its percentage share of the LIC sample.
    """
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_FREQUENCIES.schema.validate(realism4_fiscal_adjustment_bin_frequencies)
    _realism4_fiscal_adjustment_sample_share_table_0 = view(realism4_fiscal_adjustment_bin_frequencies, rows=data.VARIANT_AXIS_5.keys)
    def formula(variant: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(realism4_fiscal_adjustment_bin_frequencies[variant], xl_sum(_realism4_fiscal_adjustment_sample_share_table_0)), 100))

    return data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.collect(evaluate(formula, data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.required))

@publish(data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.schema, cells=data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.cells)
def realism4_fiscal_adjustment_cumulative_share(*, realism4_fiscal_adjustment_sample_share: data.Realism4FiscalAdjustmentSampleShare) -> data.Realism4FiscalAdjustmentCumulativeShare:
    """Compute the cumulative share of the LIC sample across fiscal-adjustment bins.

    Derive the cumulative fiscal-adjustment distribution by accumulating the sample-share series over the authored bin coordinates.

    Args:
        realism4_fiscal_adjustment_sample_share: Sample-share series over catalog fiscal-adjustment bins, providing the per-bin percent of the LIC sample to accumulate.

    Returns:
        A data.Realism4FiscalAdjustmentCumulativeShare series giving the cumulative percent of the LIC sample up to each fiscal-adjustment bin.
    """
    def formula(variant: int) -> float | str | None:
        if variant == 2:
            return as_measure(xl_add(realism4_fiscal_adjustment_sample_share[variant - 1], realism4_fiscal_adjustment_sample_share[variant]))
        return as_measure(xl_add(realism4_fiscal_adjustment_cumulative_share[variant - 1], realism4_fiscal_adjustment_sample_share[variant]))

    realism4_fiscal_adjustment_cumulative_share = CoordinateReader('realism4_fiscal_adjustment_cumulative_share', data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.required, formula)
    return data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.collect((coord, realism4_fiscal_adjustment_cumulative_share[coord]) for coord in data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.required)

@publish(data.PROBABILITY_PV_DEBT_TO_GDP.schema, cells=data.PROBABILITY_PV_DEBT_TO_GDP.cells)
def probability_pv_debt_to_gdp(*, probability_borderline_bandwidth: float | str, chart_output_pv_debt_gdp_ratio: data.ChartOutputPvDebtGdpRatio, input3_old_debt_service: data.Input3OldDebtService) -> data.ProbabilityPvDebtToGdp:
    """Build the probability-approach series for the PV of PPG external debt to GDP, applying borderline bandwidth around the threshold.

    Derive baseline, historical, shock, threshold, and banded probability paths aligned to the input debt-service time grid.

    Args:
        probability_borderline_bandwidth: Scalar borderline bandwidth applied symmetrically to the threshold to form the lower and upper probability bands.
        chart_output_pv_debt_gdp_ratio: Typed data series of PV of PPG external debt to GDP covering baseline, historical, MX shock, threshold, and band scenarios.
        input3_old_debt_service: Typed data series of old debt service whose TIME_PERIOD axis supplies the coordinate grid for the output.

    Returns:
        Typed data.ProbabilityPvDebtToGdp series of PV of PPG external debt to GDP probability paths over TIME_PERIOD.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Lower Band':
            return as_measure(xl_mul(probability_pv_debt_to_gdp['Threshold', time_period], xl_sub(1, xl_div(probability_borderline_bandwidth, 2))))
        elif scenario == 'Upper Band':
            return as_measure(xl_mul(probability_pv_debt_to_gdp['Threshold', time_period], xl_add(1, xl_div(probability_borderline_bandwidth, 2))))
        return as_measure(chart_output_pv_debt_gdp_ratio[scenario, time_period])

    probability_pv_debt_to_gdp = CoordinateReader('probability_pv_debt_to_gdp', data.PROBABILITY_PV_DEBT_TO_GDP.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.PROBABILITY_PV_DEBT_TO_GDP.collect(((coord, probability_pv_debt_to_gdp[coord]) for coord in data.PROBABILITY_PV_DEBT_TO_GDP.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PROBABILITY_PV_DEBT_TO_GDP.required.bind(TIME_PERIOD=input3_old_debt_service))

