@publish(data.PROBABILITY_PV_DEBT_TO_GDP_DISTRESS.schema, cells=data.PROBABILITY_PV_DEBT_TO_GDP_DISTRESS.cells)
def probability_pv_debt_to_gdp_distress(*, probability_debt_carrying_capacity_paths: data.Series[float | str | None], probability_regression_diagonal: data.Series[float | str | None], probability_distress_thresholds: data.Series[float | str | None], probability_regression_coefficients: data.Series[float | str | None], probability_pv_debt_to_gdp: data.ProbabilityPvDebtToGdp, input3_old_debt_service: data.Input3OldDebtService) -> data.ProbabilityPvDebtToGdpDistress:
    """Compute the probability of external-debt distress from PV debt-to-GDP under baseline, historical, MX, and threshold scenarios.

    Evaluate the probit regression that maps PV debt-to-GDP and debt-carrying-capacity drivers to distress probabilities across scenario paths.

    Args:
        probability_debt_carrying_capacity_paths: Named-axis series of debt-carrying-capacity indicators such as CPIA, real GDP growth, reserves, remittances, and world growth over time periods and scenario paths.
        probability_regression_diagonal: Series of probit regression slope coefficients for PV debt-to-GDP, keyed by catalog coordinates.
        probability_distress_thresholds: Series of distress-threshold values for PV debt-to-GDP, keyed by catalog coordinates.
        probability_regression_coefficients: Series of probit regression coefficients for capacity drivers and the constant term, keyed by indicator and metric coordinates.
        probability_pv_debt_to_gdp: Typed series of PV debt-to-GDP paths by scenario and time period.
        input3_old_debt_service: Typed series of historical debt-service inputs providing the time-period axis used for evaluation.

    Returns:
        A data.ProbabilityPvDebtToGdpDistress series of distress probabilities by scenario and time period, with threshold values expressed as percentages.
    """
    data.PROBABILITY_REGRESSION_DIAGONAL.schema.validate(probability_regression_diagonal)
    data.PROBABILITY_DISTRESS_THRESHOLDS.schema.validate(probability_distress_thresholds)
    data.PROBABILITY_REGRESSION_COEFFICIENTS.schema.validate(probability_regression_coefficients)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Threshold':
            return as_measure(xl_mul(probability_distress_thresholds['npvgdp'], 100))
        return as_measure(xl_mul(xl_normdist(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_div(xl_mul(probability_regression_diagonal['npvgdp'], probability_pv_debt_to_gdp[scenario, time_period]), 100), xl_mul(probability_regression_coefficients['CPIA', 'npvgdp'], probability_debt_carrying_capacity_paths['CPIA', time_period])), xl_div(xl_mul(probability_regression_coefficients['Growth', 'npvgdp'], probability_debt_carrying_capacity_paths['Real GDP Growth', time_period]), 100)), xl_div(xl_mul(probability_regression_coefficients['Reserves', 'npvgdp'], probability_debt_carrying_capacity_paths['Reserves', time_period]), 100)), xl_mul(probability_regression_coefficients['Reserves^2', 'npvgdp'], xl_pow(xl_div(probability_debt_carrying_capacity_paths['Reserves', time_period], 100), 2))), xl_div(xl_mul(probability_regression_coefficients['Remittances', 'npvgdp'], probability_debt_carrying_capacity_paths['Remittances', time_period]), 100)), xl_div(xl_mul(probability_regression_coefficients['World Growth', 'npvgdp'], probability_debt_carrying_capacity_paths['World Growth', time_period]), 100)), probability_regression_coefficients['Constant', 'npvgdp']), 0, 1, 1), 100))

    return data.PROBABILITY_PV_DEBT_TO_GDP_DISTRESS.collect(evaluate(formula, data.PROBABILITY_PV_DEBT_TO_GDP_DISTRESS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PROBABILITY_PV_DEBT_TO_GDP_DISTRESS.required.bind(TIME_PERIOD=input3_old_debt_service))

