@publish(key=(), domain=None, cells=data.EXTERNAL_DSA_RISK_RATING_NUMERIC_CELLS)
def external_dsa_risk_rating_numeric(*, external_baseline_breach: float | str, external_shock_breach: float | str) -> float | str:
    """Return the numeric external DSA risk rating from baseline and shock breach flags.

    Maps external DSA breach indicators to the Chart Data numeric external risk-rating signal.

    Args:
        external_baseline_breach: External DSA baseline breach flag as a scalar float or string; evaluated as a workbook boolean where 1 indicates a breach.
        external_shock_breach: External DSA shock breach flag as a scalar float or string; used when the baseline is not breached, with 1 indicating a shock breach.

    Returns:
        External DSA risk-rating numeric code as a scalar float (3 for baseline breach, 2 for shock-only breach, 1 for no breach), or the error code string if evaluation raises XlError.
    """
    try:
        return as_measure((3 if xl_bool(xl_eq(external_baseline_breach, 1)) else (2 if xl_bool(xl_and(xl_eq(external_baseline_breach, 0), xl_eq(external_shock_breach, 1))) else 1)))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.EXTERNAL_BASELINE_BREACH_CELLS)
def external_baseline_breach(*, chart_years_of_breaches_to_exclude: int | str, chart_chart_data_pv_debt_to_gdp_baseline_breach_count: int | str, chart_chart_data_pv_debt_to_exports_baseline_breach_count: int | str, chart_chart_data_debt_service_to_exports_baseline_breach_count: int | str, chart_chart_data_debt_service_to_revenue_baseline_breach_count: int | str) -> float | str:
    """Compute the external baseline breach flag from four external debt indicator breach counts.

    Determines whether any external baseline indicator exceeds the excluded-years threshold, treating one-year breaches as non-breaches.

    Args:
        chart_years_of_breaches_to_exclude: Scalar threshold (integer or string-form numeric) giving the number of breach years to exclude when deciding whether a baseline breach qualifies.
        chart_chart_data_pv_debt_to_gdp_baseline_breach_count: Scalar count (integer or string-form numeric) of baseline breach years for the PV of debt-to-GDP ratio.
        chart_chart_data_pv_debt_to_exports_baseline_breach_count: Scalar count (integer or string-form numeric) of baseline breach years for the PV of debt-to-exports ratio.
        chart_chart_data_debt_service_to_exports_baseline_breach_count: Scalar count (integer or string-form numeric) of baseline breach years for the debt service-to-exports ratio.
        chart_chart_data_debt_service_to_revenue_baseline_breach_count: Scalar count (integer or string-form numeric) of baseline breach years for the debt service-to-revenue ratio.

    Returns:
        Float or string: 1.0 when at least one indicator's baseline breach count exceeds the excluded-years threshold, 0.0 when none do, or an Excel error code string when evaluation fails.
    """
    try:
        return as_measure((1 if xl_bool(xl_or(xl_gt(chart_chart_data_pv_debt_to_gdp_baseline_breach_count, chart_years_of_breaches_to_exclude), xl_gt(chart_chart_data_pv_debt_to_exports_baseline_breach_count, chart_years_of_breaches_to_exclude), xl_gt(chart_chart_data_debt_service_to_exports_baseline_breach_count, chart_years_of_breaches_to_exclude), xl_gt(chart_chart_data_debt_service_to_revenue_baseline_breach_count, chart_years_of_breaches_to_exclude))) else 0))
    except XlError as error:
        return error.code

