@publish(key=(), domain=None, cells=data.FISCAL_SPACE_MODERATE_RISK_SIGNAL_CELLS)
def fiscal_space_moderate_risk_signal(*, fiscal_space_some_threshold: float | str, fiscal_space_substantial_threshold: float | str, chart_fiscal_space_pv_of_debt_to_gdp_max_baseline_breach: int | str, chart_fiscal_space_pv_of_debt_to_exports_max_baseline_breach: int | str, chart_fiscal_space_debt_service_to_exports_max_baseline_breach: int | str, chart_fiscal_space_debt_service_to_revenue_max_baseline_breach: int | str) -> str | int | float | bool:
    """Return the moderate-risk fiscal-space classification from the maximum baseline breach and threshold comparisons.

    Computes the Chart Data moderate-risk fiscal-space text signal (D23) using the largest baseline breach across four debt indicators against some/substantial thresholds.

    Args:
        fiscal_space_some_threshold: fiscal_space_some_threshold: Scalar threshold used to classify some fiscal space when the maximum baseline breach equals this value.
        fiscal_space_substantial_threshold: fiscal_space_substantial_threshold: Scalar threshold used to classify substantial fiscal space when the maximum baseline breach is below this value.
        chart_fiscal_space_pv_of_debt_to_gdp_max_baseline_breach: chart_fiscal_space_pv_of_debt_to_gdp_max_baseline_breach: Scalar breach indicator (or error string) for the PV of debt-to-GDP baseline; one of the four inputs to the maximum breach comparison.
        chart_fiscal_space_pv_of_debt_to_exports_max_baseline_breach: chart_fiscal_space_pv_of_debt_to_exports_max_baseline_breach: Scalar breach indicator (or error string) for the PV of debt-to-exports baseline; one of the four inputs to the maximum breach comparison.
        chart_fiscal_space_debt_service_to_exports_max_baseline_breach: chart_fiscal_space_debt_service_to_exports_max_baseline_breach: Scalar breach indicator (or error string) for the debt-service-to-exports baseline; one of the four inputs to the maximum breach comparison.
        chart_fiscal_space_debt_service_to_revenue_max_baseline_breach: chart_fiscal_space_debt_service_to_revenue_max_baseline_breach: Scalar breach indicator (or error string) for the debt-service-to-revenue baseline; one of the four inputs to the maximum breach comparison.

    Returns:
        str | int | float | bool: The fiscal-space classification string ('Substantial space', 'Some space', or 'Limited space'), or the workbook error code when an XlError is raised.
    """
    try:
        return as_measure(('Substantial space' if xl_bool(xl_lt(xl_max((chart_fiscal_space_pv_of_debt_to_gdp_max_baseline_breach, chart_fiscal_space_pv_of_debt_to_exports_max_baseline_breach, chart_fiscal_space_debt_service_to_exports_max_baseline_breach, chart_fiscal_space_debt_service_to_revenue_max_baseline_breach)), fiscal_space_substantial_threshold)) else ('Some space' if xl_bool(xl_eq(xl_max((chart_fiscal_space_pv_of_debt_to_gdp_max_baseline_breach, chart_fiscal_space_pv_of_debt_to_exports_max_baseline_breach, chart_fiscal_space_debt_service_to_exports_max_baseline_breach, chart_fiscal_space_debt_service_to_revenue_max_baseline_breach)), fiscal_space_some_threshold)) else 'Limited space')), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.OVERALL_RISK_RATING_SIGNAL_CELLS)
def overall_risk_rating_signal(*, overall_risk_rating_numeric: float | str, chart_numeric_risk_rating: data.Series[int | str | None], chart_risk_labels: data.Series[str | None]) -> str | int | float | bool:
    """Compute the overall combined risk-rating signal.

    Looks up the supplied overall risk-rating value in the authored Chart Data combined rating table to produce the external risk-rating text signal.

    Args:
        overall_risk_rating_numeric: The overall risk rating as a numeric or text value used as the lookup key.
        chart_numeric_risk_rating: A named-axis data.Series of numeric risk-rating values over catalog coordinates, validated against the CHART_NUMERIC_RISK_RATING schema and used for the Low-to-Moderate and High rating rows.
        chart_risk_labels: A named-axis data.Series of risk-label strings over catalog coordinates, validated against the CHART_RISK_LABELS schema and aligned with the numeric rating rows.

    Returns:
        A scalar combined overall risk-rating signal from the lookup as a str, int, float, or bool, or an Excel error code when the lookup fails.
    """
    data.CHART_NUMERIC_RISK_RATING.schema.validate(chart_numeric_risk_rating)
    data.CHART_RISK_LABELS.schema.validate(chart_risk_labels)
    _overall_risk_rating_signal_table_0 = lazy_table(((view(chart_numeric_risk_rating, rows=span(data.VARIANT_AXIS, 'Low', 'Moderate')), view(chart_risk_labels, rows=span(data.VARIANT_AXIS, 'Low', 'Moderate'))), (lambda: None, lambda: None), (lambda: None, lambda: None), (lambda: chart_numeric_risk_rating['High'], lambda: chart_risk_labels['High'])))
    try:
        return as_measure(xl_vlookup(overall_risk_rating_numeric, _overall_risk_rating_signal_table_0, 2, False), 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.OVERALL_RISK_RATING_NUMERIC_CELLS)
def overall_risk_rating_numeric(*, external_dsa_risk_rating_numeric: float | str, fiscal_risk_rating_numeric: float | str) -> float | str:
    """Compute the overall combined risk-rating numeric code.

    Combine the external DSA and fiscal risk-rating signals into the workbook's overall rating used on Chart Data.

    Args:
        external_dsa_risk_rating_numeric: Numeric code or string signal for the external DSA risk rating.
        fiscal_risk_rating_numeric: Numeric code or string signal for the fiscal (total public debt) risk rating.

    Returns:
        Overall combined risk-rating numeric code (Chart Data!L11) as 1, 2, or 3; or an XlError code string when evaluation fails.
    """
    try:
        return as_measure((1 if xl_bool(xl_and(xl_eq(external_dsa_risk_rating_numeric, 1), xl_eq(fiscal_risk_rating_numeric, 1))) else (3 if xl_bool(xl_or(xl_eq(external_dsa_risk_rating_numeric, 3), xl_eq(fiscal_risk_rating_numeric, 3))) else 2)))
    except XlError as error:
        return error.code

@publish(data.CHART_OUTPUT_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.schema, cells=data.CHART_OUTPUT_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.cells)
def chart_output_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue(*, chart_tailored_test_marker: int | str, dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio: data.Series[float | str | None], customized_public_include_scenario: str, chart_chart_data_pv_of_debt_to_revenue_ratio_c2_natural_disaster_stres: int | str, chart_chart_data_pv_of_debt_to_revenue_ratio_c3_commodity_price_stress: int | str, chart_chart_data_pv_of_debt_to_revenue_ratio_c4_market_financing_stres: int | str, chart_pv_of_debt_to_revenue_ratio_applicable_flag_b2_1_primary_balance_market: int | str, chart_pv_of_debt_to_revenue_ratio_applicable_flag_combined_market_financing_stress: int | str, chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path: data.Series[float | str | None], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_figure: data.Series[float | str | None], baseline_pub_pv_of_public_debt_revenue_grants_ratio: data.Series[float | str | None], baseline_pub_pv_of_public_debt_revenue_grants_ratio_exports_shock: data.Series[float | str | None], baseline_pub_pv_of_public_debt_revenue_grants_ratio_b4_other: data.Series[float | str | None], custom_pub_pv_of_public_debt_revenue_grants_ratio: data.Series[float | str | None], in6opt_standard_scenario: int | str, input3_old_debt_service: data.Input3OldDebtService) -> data.ChartOutputChartDataPvOfDebtToRevenueRatioPvDebtToRevenue:
    """Assemble the PV of Debt-to-Revenue ratio chart series across the baseline, standardized, tailored, and customized scenarios.

    Builds the Chart Data PV of Debt-to-Revenue figure ladder for the public-debt stress block by dispatching each scenario row to its source series and gating market-financing and tailored-stress variants on the applicable flags.

    Args:
        chart_tailored_test_marker: Scalar tailored-test marker compared against the per-test applicability flags to decide whether each tailored stress row is shown or blanked.
        dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio: Typed data series of PV of public debt-to-revenue-and-grants ratio keyed by scenario, supplying the A1, B1, B5, and C1 ladder rows.
        customized_public_include_scenario: Scalar customized-scenario inclusion text; when 'No', the customized row resolves to #N/A instead of the custom series.
        chart_chart_data_pv_of_debt_to_revenue_ratio_c2_natural_disaster_stres: Scalar natural-disaster tailored-stress applicability flag gating the C2 scenario row.
        chart_chart_data_pv_of_debt_to_revenue_ratio_c3_commodity_price_stress: Scalar commodity-price tailored-stress applicability flag gating the C3 scenario row.
        chart_chart_data_pv_of_debt_to_revenue_ratio_c4_market_financing_stres: Scalar market-financing tailored-stress applicability flag gating the C4 scenario row.
        chart_pv_of_debt_to_revenue_ratio_applicable_flag_b2_1_primary_balance_market: Scalar applicability flag selecting the B2 market-financing primary-balance stress path over the non-market variant.
        chart_pv_of_debt_to_revenue_ratio_applicable_flag_combined_market_financing_stress: Scalar applicability flag selecting the B6 combined market-financing stress path over the non-market variant.
        chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path: Typed data series of PV of debt-to-revenue stress paths keyed by scenario, providing the B2 and B6 market and non-market rows.
        chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_figure: Typed data series of PV of debt-to-revenue figure values keyed by scenario, providing the C2, C3, and C4 tailored-stress rows.
        baseline_pub_pv_of_public_debt_revenue_grants_ratio: Typed data series of baseline PV of public debt revenue-grants ratio over the projection horizon, used for the Baseline row.
        baseline_pub_pv_of_public_debt_revenue_grants_ratio_exports_shock: Typed data series of baseline PV of public debt revenue-grants ratio under the exports shock, used for the B3 row.
        baseline_pub_pv_of_public_debt_revenue_grants_ratio_b4_other: Typed data series of baseline PV of public debt revenue-grants ratio for B4 other flows, used for the B4 row.
        custom_pub_pv_of_public_debt_revenue_grants_ratio: Typed data series of customized PV of public debt revenue-grants ratio over the projection horizon, used for the customized row.
        in6opt_standard_scenario: Scalar standard-scenario option; when zero, the B3 and B4 shock rows resolve to zero rather than their series values.
        input3_old_debt_service: Typed data input bundle providing the old debt service domain whose TIME_PERIOD axis defines the projection grid for the collected series.

    Returns:
        Typed Chart Data series of PV of Debt-to-Revenue ratio values keyed by scenario over the projection time grid.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Baseline':
            return as_measure(baseline_pub_pv_of_public_debt_revenue_grants_ratio[time_period])
        elif scenario == 'A1. Key variables at their historical averages in 2024-2034 2/':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['A1', time_period])
        elif scenario == 'B1. Real GDP growth':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B1', time_period])
        elif scenario == 'B2. Primary balance':
            return as_measure((chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path['B2.1 Primary balance Market', time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_pv_of_debt_to_revenue_ratio_applicable_flag_b2_1_primary_balance_market)) else chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path['B2.2 Primary balance Non-Market', time_period]))
        elif scenario == 'B3. Exports':
            return as_measure((0 if xl_bool(xl_eq(in6opt_standard_scenario, 0)) else baseline_pub_pv_of_public_debt_revenue_grants_ratio_exports_shock[time_period]))
        elif scenario == 'B4. Other flows 3/':
            return as_measure((0 if xl_bool(xl_eq(in6opt_standard_scenario, 0)) else baseline_pub_pv_of_public_debt_revenue_grants_ratio_b4_other[time_period]))
        elif scenario == 'B5. Depreciation':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['B5', time_period])
        elif scenario == 'B6. Combination of B1-B5':
            return as_measure((chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path['B6.1 Combination of B1-B5 Market', time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_pv_of_debt_to_revenue_ratio_applicable_flag_combined_market_financing_stress)) else chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_stress_path['B6.2 Combination of B1-B5 Non-Market', time_period]))
        elif scenario == 'C1. Combined contingent liabilities':
            return as_measure(dsa_pub_pv_of_public_debt_to_revenue_and_grants_ratio['C1', time_period])
        elif scenario == 'C2. Natural disaster':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_pv_of_debt_to_revenue_ratio_c2_natural_disaster_stres)) else ' '), lambda: ' '))
        elif scenario == 'C3. Commodity price':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_pv_of_debt_to_revenue_ratio_c3_commodity_price_stress)) else ' '), lambda: ' '))
        elif scenario == 'C4. Market Financing':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_pv_of_debt_to_revenue_ratio_c4_market_financing_stres)) else ' '), lambda: ' '))
        return as_measure((xl_raise('#N/A') if xl_bool(xl_eq(customized_public_include_scenario, 'No')) else custom_pub_pv_of_public_debt_revenue_grants_ratio[time_period]))

    return data.CHART_OUTPUT_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.collect(evaluate(formula, data.CHART_OUTPUT_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CHART_OUTPUT_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE.schema, cells=data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE.cells)
def chart_output_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue(*, chart_tailored_test_marker: int | str, dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent: data.Series[float | str | None], customized_public_include_scenario: str, chart_chart_data_debt_service_to_revenue_ratio_c2_natural_disaster_str: int | str, chart_chart_data_debt_service_to_revenue_ratio_c3_commodity_price_stre: int | str, chart_chart_data_debt_service_to_revenue_ratio_c4_market_financing_str: int | str, chart_applicable_flag_b2_1_primary_balance_market: int | str, chart_applicable_flag_combined_market_financing_stress: int | str, chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_stress_path: data.Series[float | str | None], chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_figure: data.Series[float | str | None], baseline_pub_debt_service_revenue_grants_ratio: data.Series[float | str | None], baseline_pub_debt_service_revenue_grants_ratio_b3_exports: data.Series[float | str | None], baseline_pub_debt_service_revenue_grants_ratio_b4_other_flows: data.Series[float | str | None], custom_pub_debt_service_revenue_grants_ratio: data.Series[float | str | None], in6opt_standard_scenario: int | str, input3_old_debt_service: data.Input3OldDebtService) -> data.ChartOutputChartDataDebtServiceToRevenueRatioDebtServiceToRevenue:
    """Assemble the public-debt Debt Service-to-Revenue ratio chart series by resolving each scenario ladder row from its authored source.

    Produce the scenario-keyed Chart Data series used in the public DSA debt service-to-revenue stress chart.

    Args:
        chart_tailored_test_marker: Scalar tailored-test marker compared against the applicable tailored-stress flags to select market or non-market stress paths.
        dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent: Named-axis series of DSA public debt service-to-revenue-and-grants ratio in percent, keyed by scenario and time period for the A1, B1, B5, and C1 ladder rows.
        customized_public_include_scenario: Scalar customized-scenario inclusion switch; when set to 'No' the customized fallback raises rather than reading the custom series.
        chart_chart_data_debt_service_to_revenue_ratio_c2_natural_disaster_str: Scalar applicability marker compared against the natural-disaster tailored-test flag to decide whether the C2 figure path is shown.
        chart_chart_data_debt_service_to_revenue_ratio_c3_commodity_price_stre: Scalar applicability marker compared against the commodity-price tailored-test flag to decide whether the C3 figure path is shown.
        chart_chart_data_debt_service_to_revenue_ratio_c4_market_financing_str: Scalar applicability marker compared against the market-financing tailored-test flag to decide whether the C4 figure path is shown.
        chart_applicable_flag_b2_1_primary_balance_market: Scalar applicable flag for the B2.1 primary balance market stress path, compared against the tailored-test marker.
        chart_applicable_flag_combined_market_financing_stress: Scalar applicable flag for the combined market-financing stress, compared against the tailored-test marker for the B6 row.
        chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_stress_path: Named-axis series of internal debt service-to-revenue stress paths, keyed by scenario and time period, supplying the B2 and B6 market/non-market rows.
        chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_figure: Named-axis series of internal debt service-to-revenue figure values, keyed by scenario and time period, supplying the C2, C3, and C4 tailored-stress rows.
        baseline_pub_debt_service_revenue_grants_ratio: Named-axis baseline public debt service-to-revenue-and-grants ratio series used for the Baseline scenario row.
        baseline_pub_debt_service_revenue_grants_ratio_b3_exports: Named-axis baseline public debt service-to-revenue-and-grants ratio under the B3 exports shock, zeroed when the standard scenario option is off.
        baseline_pub_debt_service_revenue_grants_ratio_b4_other_flows: Named-axis baseline public debt service-to-revenue-and-grants ratio for other flows, zeroed when the standard scenario option is off.
        custom_pub_debt_service_revenue_grants_ratio: Named-axis customized public debt service-to-revenue-and-grants ratio series used for any scenario outside the standard ladder.
        in6opt_standard_scenario: Scalar standard-scenario option switch; when zero the B3 and B4 shock rows are forced to zero.
        input3_old_debt_service: Typed input record carrying the historical debt service data whose TIME_PERIOD axis defines the output coordinate domain.

    Returns:
        Typed ChartOutputChartDataDebtServiceToRevenueRatioDebtServiceToRevenue series of debt service-to-revenue ratio values keyed by scenario and time period.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Baseline':
            return as_measure(baseline_pub_debt_service_revenue_grants_ratio[time_period])
        elif scenario == 'A1. Key variables at their historical averages in 2024-2034 2/':
            return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent['A1', time_period])
        elif scenario == 'B1. Real GDP growth':
            return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent['B1', time_period])
        elif scenario == 'B2. Primary balance':
            return as_measure((chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_stress_path['B2.1 Primary balance Market', time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_applicable_flag_b2_1_primary_balance_market)) else chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_stress_path['B2.2 Primary balance Non-Market', time_period]))
        elif scenario == 'B3. Exports':
            return as_measure((0 if xl_bool(xl_eq(in6opt_standard_scenario, 0)) else baseline_pub_debt_service_revenue_grants_ratio_b3_exports[time_period]))
        elif scenario == 'B4. Other flows 3/':
            return as_measure((0 if xl_bool(xl_eq(in6opt_standard_scenario, 0)) else baseline_pub_debt_service_revenue_grants_ratio_b4_other_flows[time_period]))
        elif scenario == 'B5. Depreciation':
            return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent['B5', time_period])
        elif scenario == 'B6. Combination of B1-B5':
            return as_measure((chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_stress_path['B6.1 Combination of B1-B5 Market', time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_applicable_flag_combined_market_financing_stress)) else chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_stress_path['B6.2 Combination of B1-B5 Non-Market', time_period]))
        elif scenario == 'C1. Combined contingent liabilities':
            return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent['C1', time_period])
        elif scenario == 'C2. Natural disaster':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_debt_service_to_revenue_ratio_c2_natural_disaster_str)) else ' '), lambda: ' '))
        elif scenario == 'C3. Commodity price':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_debt_service_to_revenue_ratio_c3_commodity_price_stre)) else ' '), lambda: ' '))
        elif scenario == 'C4. Market Financing':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_debt_service_to_revenue_ratio_debt_service_to_revenue_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_debt_service_to_revenue_ratio_c4_market_financing_str)) else ' '), lambda: ' '))
        return as_measure((xl_raise('#N/A') if xl_bool(xl_eq(customized_public_include_scenario, 'No')) else custom_pub_debt_service_revenue_grants_ratio[time_period]))

    return data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE.collect(evaluate(formula, data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_REVENUE_RATIO_DEBT_SERVICE_TO_REVENUE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_GDP_RATIO_DEBT_SERVICE_GDP_RATIO.schema, cells=data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_GDP_RATIO_DEBT_SERVICE_GDP_RATIO.cells)
def chart_output_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio(*, chart_tailored_test_marker: int | str, dsa_pub_debt_service_to_gdp_ratio_in_percent: data.Series[float | str | None], customized_public_include_scenario: str, chart_chart_data_debt_service_to_gdp_ratio_c2_natural_disaster_stress_: int | str, chart_chart_data_debt_service_to_gdp_ratio_c3_commodity_price_stress_p: int | str, chart_chart_data_debt_service_to_gdp_ratio_c4_market_financing_stress_: int | str, chart_debt_service_to_gdp_ratio_applicable_flag_b2_1_primary_balance_market: int | str, chart_debt_service_to_gdp_ratio_applicable_flag_combined_market_financing_stress: int | str, chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_stress_path: data.Series[float | str | None], chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_figure: data.Series[float | str | None], baseline_pub_debt_service_gdp_ratio_baseline: data.Series[float | str | None], baseline_pub_debt_service_gdp_ratio_b3_exports: data.Series[float | str | None], baseline_pub_debt_service_gdp_ratio_b4_other_flows: data.Series[float | str | None], custom_pub_debt_service_gdp_ratio: data.Series[float | str | None], in6opt_standard_scenario: int | str, input3_old_debt_service: data.Input3OldDebtService) -> data.ChartOutputChartDataDebtServiceToGdpRatioDebtServiceGdpRatio:
    """Builds the Chart Data debt service-to-GDP ratio scenario series from baseline, standardized stress, tailored stress, and customized inputs.

    Selects the appropriate debt service-to-GDP ratio path per scenario for chart output.

    Args:
        chart_tailored_test_marker: Scalar tailored-test marker used to compare against applicability flags when choosing market versus non-market stress paths or tailored stress figures.
        dsa_pub_debt_service_to_gdp_ratio_in_percent: Scenario- and time-keyed series of DSA public debt service-to-GDP ratios in percent for standard scenarios A1, B1, B5, and C1.
        customized_public_include_scenario: Scenario switch string, typically "Yes" or "No", controlling whether the customized public scenario is included and whether the fallback path yields #N/A.
        chart_chart_data_debt_service_to_gdp_ratio_c2_natural_disaster_stress_: Scalar tailored-test marker or applicability value for the C2 natural disaster stress, compared with the tailored-test marker to decide whether to emit the figure or a blank placeholder.
        chart_chart_data_debt_service_to_gdp_ratio_c3_commodity_price_stress_p: Scalar tailored-test marker or applicability value for the C3 commodity price stress, compared with the tailored-test marker to decide whether to emit the figure or a blank placeholder.
        chart_chart_data_debt_service_to_gdp_ratio_c4_market_financing_stress_: Scalar tailored-test marker or applicability value for the C4 market financing stress, compared with the tailored-test marker to decide whether to emit the figure or a blank placeholder.
        chart_debt_service_to_gdp_ratio_applicable_flag_b2_1_primary_balance_market: Scalar applicability flag for the B2.1 primary balance market stress, used to select B2.1 market or B2.2 non-market stress path.
        chart_debt_service_to_gdp_ratio_applicable_flag_combined_market_financing_stress: Scalar applicability flag for the B6 combined market financing stress, used to select B6.1 market or B6.2 non-market stress path.
        chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_stress_path: Scenario- and time-keyed internal stress-path series containing B2.1, B2.2, B6.1, and B6.2 public debt service-to-GDP ratio values.
        chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_figure: Scenario- and time-keyed internal figure series containing tailored C2, C3, and C4 public debt service-to-GDP ratio values.
        baseline_pub_debt_service_gdp_ratio_baseline: Time-keyed series of baseline public debt service-to-GDP ratios.
        baseline_pub_debt_service_gdp_ratio_b3_exports: Time-keyed series of the B3 exports stress path, suppressed to zero when the standard-scenario option is zero.
        baseline_pub_debt_service_gdp_ratio_b4_other_flows: Time-keyed series of the B4 other-flows stress path, suppressed to zero when the standard-scenario option is zero.
        custom_pub_debt_service_gdp_ratio: Time-keyed series of customized public debt service-to-GDP ratios used for the non-standard customized scenario path.
        in6opt_standard_scenario: Scalar standard-scenario option; a value of zero suppresses the B3 exports and B4 other-flows stress values.
        input3_old_debt_service: Input 3 old debt service dataclass providing the TIME_PERIOD axis and bound domain used to evaluate output years.

    Returns:
        A typed Chart Data debt service-to-GDP ratio series keyed by scenario and TIME_PERIOD, containing baseline, standardized stress-ladder, tailored C2/C3/C4, and customized scenario values, with string blanks or #N/A placeholders where the workbook marks a path inapplicable.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Baseline':
            return as_measure(baseline_pub_debt_service_gdp_ratio_baseline[time_period])
        elif scenario == 'A1. Key variables at their historical averages in 2024-2034 2/':
            return as_measure(dsa_pub_debt_service_to_gdp_ratio_in_percent['A1', time_period])
        elif scenario == 'B1. Real GDP growth':
            return as_measure(dsa_pub_debt_service_to_gdp_ratio_in_percent['B1', time_period])
        elif scenario == 'B2. Primary balance':
            return as_measure((chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_stress_path['B2.1 Primary balance Market', time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_debt_service_to_gdp_ratio_applicable_flag_b2_1_primary_balance_market)) else chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_stress_path['B2.2 Primary balance Non-Market', time_period]))
        elif scenario == 'B3. Exports':
            return as_measure((0 if xl_bool(xl_eq(in6opt_standard_scenario, 0)) else baseline_pub_debt_service_gdp_ratio_b3_exports[time_period]))
        elif scenario == 'B4. Other flows 3/':
            return as_measure((0 if xl_bool(xl_eq(in6opt_standard_scenario, 0)) else baseline_pub_debt_service_gdp_ratio_b4_other_flows[time_period]))
        elif scenario == 'B5. Depreciation':
            return as_measure(dsa_pub_debt_service_to_gdp_ratio_in_percent['B5', time_period])
        elif scenario == 'B6. Combination of B1-B5':
            return as_measure((chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_stress_path['B6.1 Combination of B1-B5 Market', time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_debt_service_to_gdp_ratio_applicable_flag_combined_market_financing_stress)) else chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_stress_path['B6.2 Combination of B1-B5 Non-Market', time_period]))
        elif scenario == 'C1. Combined contingent liabilities':
            return as_measure(dsa_pub_debt_service_to_gdp_ratio_in_percent['C1', time_period])
        elif scenario == 'C2. Natural disaster':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_debt_service_to_gdp_ratio_c2_natural_disaster_stress_)) else ' '), lambda: ' '))
        elif scenario == 'C3. Commodity price':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_debt_service_to_gdp_ratio_c3_commodity_price_stress_p)) else ' '), lambda: ' '))
        elif scenario == 'C4. Market Financing':
            return as_measure(xl_iferror(lambda: (chart_internal_chart_data_debt_service_to_gdp_ratio_debt_service_gdp_ratio_figure[scenario, time_period] if xl_bool(xl_eq(chart_tailored_test_marker, chart_chart_data_debt_service_to_gdp_ratio_c4_market_financing_stress_)) else ' '), lambda: ' '))
        return as_measure((xl_raise('#N/A') if xl_bool(xl_eq(customized_public_include_scenario, 'No')) else custom_pub_debt_service_gdp_ratio[time_period]))

    return data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_GDP_RATIO_DEBT_SERVICE_GDP_RATIO.collect(evaluate(formula, data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_GDP_RATIO_DEBT_SERVICE_GDP_RATIO.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CHART_OUTPUT_CHART_DATA_DEBT_SERVICE_TO_GDP_RATIO_DEBT_SERVICE_GDP_RATIO.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.CHART_PV_DEBT_GDP_RATIO_CUSTOM_ALTERNATIVE_SCENARIO.schema, cells=data.CHART_PV_DEBT_GDP_RATIO_CUSTOM_ALTERNATIVE_SCENARIO.cells)
def chart_pv_debt_gdp_ratio_custom_alternative_scenario(*, custom_ext_pv_ppg_ext_debt_gdp_ratio: data.Series[float | str | None], custom_ext_include_external_customized_scenario_in_charts: str | int | float | bool, input3_old_debt_service: data.Input3OldDebtService) -> data.ChartPvDebtGdpRatioCustomAlternativeScenario:
    """Builds the Chart Data row 51 series for the PV of debt-to-GDP ratio under the customized external alternative (A2) scenario.

    Resolve the A2 customized-scenario figure path across projection years, suppressing it with `#N/A` when the customized external scenario is excluded from charts.

    Args:
        custom_ext_pv_ppg_ext_debt_gdp_ratio: Series of customized external PV of PPG debt-to-GDP ratio values (title text, numbers, or blanks) indexed over TIME_PERIOD.
        custom_ext_include_external_customized_scenario_in_charts: Scalar switch whose value `'No'` excludes the external customized scenario from charts, resolving every year to `#N/A`; any other value passes the supplied series through.
        input3_old_debt_service: Typed `data.Input3OldDebtService` bundle whose `TIME_PERIOD` axis defines the projection-year grid the output is aligned to.

    Returns:
        `data.ChartPvDebtGdpRatioCustomAlternativeScenario` series over `TIME_PERIOD` holding the A2 customized-scenario PV of debt-to-GDP path, or `#N/A` per year when the customized external scenario is excluded.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_raise('#N/A') if xl_bool(xl_eq(custom_ext_include_external_customized_scenario_in_charts, 'No')) else custom_ext_pv_ppg_ext_debt_gdp_ratio[time_period]))

    return data.CHART_PV_DEBT_GDP_RATIO_CUSTOM_ALTERNATIVE_SCENARIO.collect(evaluate(formula, data.CHART_PV_DEBT_GDP_RATIO_CUSTOM_ALTERNATIVE_SCENARIO.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CHART_PV_DEBT_GDP_RATIO_CUSTOM_ALTERNATIVE_SCENARIO.required.bind(TIME_PERIOD=input3_old_debt_service))

