@publish(data.PV_BASE_MULTILATERALS.schema, cells=data.PV_BASE_MULTILATERALS.cells)
def pv_base_multilaterals(*, pv_base_constant_discount_schedule_period: int | str, pv_base_discount_schedule_period: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the PV-base multilaterals discount-schedule period series.

    Resolve IDA-regular multilaterals discount-schedule periods across the PV-base projection horizon, using a scalar override for 2024.

    Args:
        pv_base_constant_discount_schedule_period: Scalar discount-schedule period, as an int or str, used as the 2024 multilaterals value.
        pv_base_discount_schedule_period: Named-axis data series of int, str, or None discount-schedule periods keyed by creditor and time period; supplies IDA - regular values for years other than 2024.

    Returns:
        data.Series[int | str | None] aligned to the PV_BASE_MULTILATERALS required coordinates, giving the multilaterals discount-schedule period per time period.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(pv_base_constant_discount_schedule_period, 'int')
        return as_measure(pv_base_discount_schedule_period['IDA - regular', time_period], 'int')

    return data.PV_BASE_MULTILATERALS.collect(evaluate(formula, data.PV_BASE_MULTILATERALS.required))

@dataclass(frozen=True, slots=True)
class ScanPvBaseMultilateralsByYearResult:
    """Complete named results of one recurrence group evaluation."""
    pv_base_multilaterals_by_year: data.Series[int | str | None]
    pv_base_grace_ida_regular_by_year: data.Series[int | str | None]
    pv_base_output_projection_year: data.Series[int | str | None]

def scan_pv_base_multilaterals_by_year(*, macro_debt_data: int | str) -> ScanPvBaseMultilateralsByYearResult:
    """Evaluate the recurrence group `pv_base_multilaterals_by_year`, `pv_base_grace_ida_regular_by_year`, `pv_base_output_projection_year` and publish complete tensors."""
    def pv_base_multilaterals_by_year_formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(macro_debt_data, 'int')
        return as_measure(pv_base_grace_ida_regular_by_year[time_period], 'int')

    pv_base_multilaterals_by_year = CoordinateReader('pv_base_multilaterals_by_year', data.PV_BASE_MULTILATERALS_BY_YEAR.required, pv_base_multilaterals_by_year_formula)
    def pv_base_grace_ida_regular_by_year_formula(time_period: int) -> int | str | None:
        return as_measure(pv_base_output_projection_year['IDA - regular', time_period], 'int')

    pv_base_grace_ida_regular_by_year = CoordinateReader('pv_base_grace_ida_regular_by_year', data.PV_BASE_GRACE_IDA_REGULAR_BY_YEAR.required, pv_base_grace_ida_regular_by_year_formula)
    def pv_base_output_projection_year_formula(instrument: str, time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(pv_base_multilaterals_by_year[2024], 'int')
        elif time_period == 2025:
            return as_measure(xl_add(pv_base_output_projection_year[instrument, time_period - 1], 1), 'int')
        return as_measure(xl_add(pv_base_output_projection_year['IDA - regular', time_period - 1], 1), 'int')

    pv_base_output_projection_year = CoordinateReader('pv_base_output_projection_year', data.PV_BASE_OUTPUT_PROJECTION_YEAR.required, pv_base_output_projection_year_formula)
    return ScanPvBaseMultilateralsByYearResult(
        pv_base_multilaterals_by_year=data.PV_BASE_MULTILATERALS_BY_YEAR.collect((coord, pv_base_multilaterals_by_year[coord]) for coord in data.PV_BASE_MULTILATERALS_BY_YEAR.required),
        pv_base_grace_ida_regular_by_year=data.PV_BASE_GRACE_IDA_REGULAR_BY_YEAR.collect((coord, pv_base_grace_ida_regular_by_year[coord]) for coord in data.PV_BASE_GRACE_IDA_REGULAR_BY_YEAR.required),
        pv_base_output_projection_year=data.PV_BASE_OUTPUT_PROJECTION_YEAR.collect((coord, pv_base_output_projection_year[coord]) for coord in data.PV_BASE_OUTPUT_PROJECTION_YEAR.required),
    )

@publish(data.PV_BASE_BLOCK_GRACE.schema, cells=data.PV_BASE_BLOCK_GRACE.cells)
def pv_base_block_grace(*, input4_grace_period: data.Input4GracePeriod, input4_terms_ida_regular: data.Series[float | str | None], input4_terms_ida_and_lc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Resolve grace periods for PV_Base instrument blocks.

    Compute per-instrument grace periods for the PV_Base block from Input 4 grace-period and IDA terms series.

    Args:
        input4_grace_period: Authoritative Input 4 grace-period series; supplies the fallback grace period for each PV_Base instrument not handled by the IDA-specific terms.
        input4_terms_ida_regular: Input 4 IDA - regular terms series keyed by instrument and term field; provides the 'Grace period' measure for the IDA - regular instrument block.
        input4_terms_ida_and_lc: Input 4 IDA and local-currency terms series keyed by instrument and term field; maps the remaining IDA variants to their catalog labels and reads the 'Grace period' measure.

    Returns:
        A data.Series[float | str | None] of grace periods, with one cell per required PV_Base instrument block.
    """
    data.INPUT4_GRACE_PERIOD.schema.validate(input4_grace_period)
    def formula(instrument: str) -> float | str | None:
        INSTRUMENT_TO_INPUT4_TERMS_IDA_AND_LC = {'IDA - 50Y loans': 'IDA - 50Y loans', 'IDA - SML': 'IDA - SML', 'IDA NEW 40-year credits': 'IDA NEW 40-year credits', 'IDA NEW Regular': 'IDA NEW Regular', 'IDA NEW Blend floating': 'IDA NEW Blend (also enter) -->', 'IDA NEW 60-year credits': 'IDA NEW 60-year credits'}
        if instrument == 'IDA - regular':
            return as_measure(input4_terms_ida_regular[instrument, 'Grace period'])
        elif instrument in ('IDA - 50Y loans', 'IDA - SML', 'IDA NEW 40-year credits', 'IDA NEW Regular', 'IDA NEW Blend floating', 'IDA NEW 60-year credits'):
            return as_measure(input4_terms_ida_and_lc[INSTRUMENT_TO_INPUT4_TERMS_IDA_AND_LC[instrument], 'Grace period'])
        return as_measure(input4_grace_period[instrument])

    return data.PV_BASE_BLOCK_GRACE.collect(evaluate(formula, data.PV_BASE_BLOCK_GRACE.required))

@publish(data.PV_BASE_BLOCK_MATURITY.schema, cells=data.PV_BASE_BLOCK_MATURITY.cells)
def pv_base_block_maturity(*, input4_loan_maturity: data.Input4LoanMaturity, input4_terms_ida_regular: data.Series[float | str | None], input4_terms_ida_and_lc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute PV_Base block maturity.

    Resolve the loan maturity used for each PV_Base instrument block, applying IDA and IDA/LC term overrides where required.

    Args:
        input4_loan_maturity: Loan maturity input keyed by instrument, supplied as a data.Input4LoanMaturity series over catalog coordinates.
        input4_terms_ida_regular: IDA regular loan-maturity term series as data.Series[float | str | None] over catalog coordinates.
        input4_terms_ida_and_lc: IDA and local-currency loan-maturity term series as data.Series[float | str | None] over catalog coordinates.

    Returns:
        data.Series[float | str | None] with one maturity value per PV_Base instrument block.
    """
    data.INPUT4_LOAN_MATURITY.schema.validate(input4_loan_maturity)
    def formula(instrument: str) -> float | str | None:
        INSTRUMENT_TO_INPUT4_TERMS_IDA_AND_LC = {'IDA - 50Y loans': 'IDA - 50Y loans', 'IDA - SML': 'IDA - SML', 'IDA NEW 40-year credits': 'IDA NEW 40-year credits', 'IDA NEW Regular': 'IDA NEW Regular', 'IDA NEW Blend floating': 'IDA NEW Blend (also enter) -->', 'IDA NEW 60-year credits': 'IDA NEW 60-year credits'}
        if instrument == 'IDA - regular':
            return as_measure(input4_terms_ida_regular[instrument, 'Loan Maturity'])
        elif instrument in ('IDA - 50Y loans', 'IDA - SML', 'IDA NEW 40-year credits', 'IDA NEW Regular', 'IDA NEW Blend floating', 'IDA NEW 60-year credits'):
            return as_measure(input4_terms_ida_and_lc[INSTRUMENT_TO_INPUT4_TERMS_IDA_AND_LC[instrument], 'Loan Maturity'])
