@publish(data.PV_BASE_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD_FX.schema, cells=data.PV_BASE_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD_FX.cells)
def pv_base_output_total_debt_service_in_usd_fx(*, pv_base_output_interest_fx: data.Series[float | str | None], pv_base_output_amortization_fx: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Sum FX interest and amortization into total debt service in USD.

    Combines per-instrument interest and amortization series into the total debt service series over the TIME_PERIOD axis.

    Args:
        pv_base_output_interest_fx: Interest payments (in USD, FX instruments) as a data series over instrument, holder, and TIME_PERIOD coordinates.
        pv_base_output_amortization_fx: Amortization payments (in USD, FX instruments) as a data series over instrument, holder, and TIME_PERIOD coordinates; added elementwise to the interest series.
        input3_old_debt_service: Old debt service input series whose TIME_PERIOD axis supplies the output domain for the evaluation.

    Returns:
        data.Series[float | str | None] of total debt service in USD over the TIME_PERIOD axis, indexed by instrument and holder.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Bonds (1 to 3 years)-FX' and holder == 'non-residents':
            return as_measure(xl_add(pv_base_output_interest_fx['Bonds (1 to 3 years)-FX', 'non-residents', time_period], pv_base_output_amortization_fx['Bonds (1 to 3 years)-FX', 'non-residents', time_period]))
        elif instrument == 'Bonds (4 to 7 years)-FX' and holder == 'non-residents':
            return as_measure(xl_add(pv_base_output_interest_fx['Bonds (4 to 7 years)-FX', 'non-residents', time_period], pv_base_output_amortization_fx['Bonds (4 to 7 years)-FX', 'non-residents', time_period]))
        elif instrument == 'Bonds (beyond 7 years)-FX' and holder == 'non-residents':
            return as_measure(xl_add(pv_base_output_interest_fx['Bonds (beyond 7 years)-FX', 'non-residents', time_period], pv_base_output_amortization_fx['Bonds (beyond 7 years)-FX', 'non-residents', time_period]))
        elif instrument == 'Bonds (1 to 3 years)-FX' and holder == 'residents':
            return as_measure(xl_add(pv_base_output_interest_fx['Bonds (1 to 3 years)-FX', 'residents', time_period], pv_base_output_amortization_fx['Bonds (1 to 3 years)-FX', 'residents', time_period]))
        elif instrument == 'Bonds (4 to 7 years)-FX' and holder == 'residents':
            return as_measure(xl_add(pv_base_output_interest_fx['Bonds (4 to 7 years)-FX', 'residents', time_period], pv_base_output_amortization_fx['Bonds (4 to 7 years)-FX', 'residents', time_period]))
        return as_measure(xl_add(pv_base_output_interest_fx['Bonds (beyond 7 years)-FX', 'residents', time_period], pv_base_output_amortization_fx['Bonds (beyond 7 years)-FX', 'residents', time_period]))

    return data.PV_BASE_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD_FX.collect(evaluate(formula, data.PV_BASE_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD_FX.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASE_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD_FX.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASE_ADD_COST_MKT_SHOCK_SCHEDULE_PERIOD.schema, cells=data.PV_BASE_ADD_COST_MKT_SHOCK_SCHEDULE_PERIOD.cells)
def pv_base_add_cost_mkt_shock_schedule_period(*, pv_base_add_cost_mkt_opening_stock_percent_of_face: int | str, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Builds the PV_Base-add market-cost shock schedule period series across projection years.

    Seeds the first projection period from the opening-stock percent of face, then carries each period forward as the prior year's schedule period plus one.

    Args:
        pv_base_add_cost_mkt_opening_stock_percent_of_face: Scalar (integer or string) percent-of-face opening stock that seeds the schedule period for the first projection year.
        input3_old_debt_service: Input 3 old debt service series whose TIME_PERIOD axis supplies the projection-year coordinates over which the schedule period is computed.

    Returns:
        A data.Series[int | str | None] of schedule-period values on PV_Base-add.cost.mkt, keyed by projection years.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 1:
            return as_measure(xl_add(pv_base_add_cost_mkt_opening_stock_percent_of_face, 1), 'int')
        return as_measure(xl_add(pv_base_add_cost_mkt_shock_schedule_period[axis_step(_ax_time_period, time_period, -1)], 1), 'int')

    pv_base_add_cost_mkt_shock_schedule_period = CoordinateReader('pv_base_add_cost_mkt_shock_schedule_period', data.PV_BASE_ADD_COST_MKT_SHOCK_SCHEDULE_PERIOD.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.PV_BASE_ADD_COST_MKT_SHOCK_SCHEDULE_PERIOD.collect(((coord, pv_base_add_cost_mkt_shock_schedule_period[coord]) for coord in data.PV_BASE_ADD_COST_MKT_SHOCK_SCHEDULE_PERIOD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASE_ADD_COST_MKT_SHOCK_SCHEDULE_PERIOD.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(key=(), domain=None, cells=data.PV_BASE_ADD_COST_MKT_WHICHEVER_LOWER_CELLS)
def pv_base_add_cost_mkt_whichever_lower(*, leftover_inflation_gdp_deflator: str | int | float | bool) -> str | int | float | bool:
    """Return whichever is lower between PV base addition and market cost for the GDP deflator.

    Implements the LIC-DSF helper that selects the lower GDP-deflator cost measure for PV base calculations.

    Args:
        leftover_inflation_gdp_deflator: Scalar leftover inflation GDP deflator value used in the lower-of comparison; may be a string, integer, float, or boolean.

    Returns:
        A string measure of the selected lower value, or the XL error code when the measure cannot be evaluated.
    """
    try:
        return as_measure(leftover_inflation_gdp_deflator, 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.PV_BASE_ADD_COST_MKT_OR_CELLS)
def pv_base_add_cost_mkt_or(*, input6_tailored_params_2: data.Series[float | str | None]) -> int | str:
    """Return the market-financing shock switch from a tailored-parameter series.

    Extracts the `mkt_financing_shock_on` coordinate as an integer indicator, falling back to an Excel error code.

    Args:
        input6_tailored_params_2: A keyword-only typed data series of tailored stress parameters indexed by catalog coordinates; its `mkt_financing_shock_on` entry provides the market-financing shock flag as a float, string, or blank.

    Returns:
        The market-financing shock switch as an `int`, or the originating Excel error code as a `str` if extraction fails.
    """
    try:
        return as_measure(input6_tailored_params_2['mkt_financing_shock_on'], 'int')
    except XlError as error:
        return error.code

@publish(data.PV_BASE_ADD_COST_MKT_PB_BASELINE.schema, cells=data.PV_BASE_ADD_COST_MKT_PB_BASELINE.cells)
def pv_base_add_cost_mkt_pb_baseline(*, baseline_pub_primary_deficit: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Return the PB-baseline market-cost add-cost series by shifting the published-baseline primary deficit one period along the macro current-account timeline.

    Line up the baseline public primary deficit with the market-cost PB timeline so the resulting series can be consumed as the PB-baseline add-cost term over the old debt-service year grid.

    Args:
        baseline_pub_primary_deficit: Typed data series of per-year baseline public primary deficit values (floats, text flags, or blanks) indexed over catalog coordinates; the value at each target year is taken from the next period along the macro current-account time axis.
        input3_input_3_macro_current_account: Typed Input 3 macro current-account series whose TIME_PERIOD axis supplies the one-step offset applied when picking each primary-deficit observation.
        input3_old_debt_service: Typed Input 3 old debt-service series; its TIME_PERIOD domain defines the output years the resulting series is bound and collected over.

    Returns:
        A data series of floats, text flags, or blanks over the PB-baseline add-cost coordinates (TIME_PERIOD bound by the old debt-service domain), holding the period-shifted baseline public primary deficit values.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(baseline_pub_primary_deficit[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, 1)])

    return data.PV_BASE_ADD_COST_MKT_PB_BASELINE.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_PB_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASE_ADD_COST_MKT_PB_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASE_ADD_COST_MKT_SHOCK.schema, cells=data.PV_BASE_ADD_COST_MKT_SHOCK.cells)
def pv_base_add_cost_mkt_shock(*, dsa_pub_primary_deficit: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the PV base add-cost series under the B6 market-financing shock.

    Derive the market-shock add-cost path on the PV base by aligning the B6_mkt primary-deficit component to the old debt-service time grid.

    Args:
        dsa_pub_primary_deficit: Primary-deficit series over catalog coordinates; its `B6_mkt` market-shock component is sampled with a one-period time offset.
        input3_old_debt_service: Input 3 old debt-service typed series whose `TIME_PERIOD` axis defines and validates the output time domain.

    Returns:
        A `data.Series[float | str | None]` of PV base add-cost values under the market shock, indexed on the old debt-service `TIME_PERIOD` domain.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(dsa_pub_primary_deficit['B6_mkt', axis_step(_ax_time_period, time_period, 1)])

    return data.PV_BASE_ADD_COST_MKT_SHOCK.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_SHOCK.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASE_ADD_COST_MKT_SHOCK.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASE_ADD_COST_MKT_SHOCK_DEVIATION_FROM_BASELINE.schema, cells=data.PV_BASE_ADD_COST_MKT_SHOCK_DEVIATION_FROM_BASELINE.cells)
def pv_base_add_cost_mkt_shock_deviation_from_baseline(*, pv_base_add_cost_mkt_pb_baseline: data.Series[float | str | None], pv_base_add_cost_mkt_shock: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the market-cost shock deviation from the baseline for PV_Base-add.cost.mkt across projection years.

    Returns the per-year difference between the shocked and baseline market-cost addition series on the old-debt-service time grid.

    Args:
        pv_base_add_cost_mkt_pb_baseline: Baseline market-cost addition series over projection years, with numeric, text, or missing values.
        pv_base_add_cost_mkt_shock: Shock-scenario market-cost addition series over projection years, aligned to the same coordinate grid.
        input3_old_debt_service: Old debt service input series whose TIME_PERIOD coordinate supplies the projection-year axis for evaluation.

    Returns:
        Projection-year series of shock minus baseline deviations, preserving numeric, text, or missing values.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_sub(pv_base_add_cost_mkt_shock[time_period], pv_base_add_cost_mkt_pb_baseline[time_period]))

    return data.PV_BASE_ADD_COST_MKT_SHOCK_DEVIATION_FROM_BASELINE.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_SHOCK_DEVIATION_FROM_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASE_ADD_COST_MKT_SHOCK_DEVIATION_FROM_BASELINE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASE_ADD_COST_MKT_SHOCK_INCREASE_IN_BORROWING_COSTS.schema, cells=data.PV_BASE_ADD_COST_MKT_SHOCK_INCREASE_IN_BORROWING_COSTS.cells)
def pv_base_add_cost_mkt_shock_increase_in_borrowing_costs(*, pv_base_add_cost_mkt_opening_percent_of_face: int | str, pv_base_add_cost_mkt_whichever_lower: str | int | float | bool, pv_base_add_cost_mkt_or: int | str, pv_base_add_cost_mkt_shock_deviation_from_baseline: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the PV_Base-add.cost.mkt shock increase in borrowing costs across projection years.

    Applies the market-cost shock deviation to the opening stock and resolves the applied cap/floor policy, yielding the per-year increase in borrowing costs on the PV_Base-add.cost.mkt line.

    Args:
        pv_base_add_cost_mkt_opening_percent_of_face: Opening stock of market-cost debt expressed as a percentage of face value, supplied as an integer or string scalar.
        pv_base_add_cost_mkt_whichever_lower: Policy selector scalar (string label, integer, float, or bool code) choosing which capping rule governs the computed increase.
        pv_base_add_cost_mkt_or: Cap or fallback scalar (integer or string) providing the alternate ceiling value used when the whichever-lower rule clamps the product of opening stock and shock deviation.
        pv_base_add_cost_mkt_shock_deviation_from_baseline: Typed series of per-year deviations from the baseline market interest rate used to shock the cost of debt, aligned to the projection-year axis and permitting blanks.
        input3_old_debt_service: Typed Input 3 old debt service series by projection year, providing the TIME_PERIOD domain against which the result is aligned and validated.

    Returns:
        A typed data.Series[float | str | None] of the increase in borrowing costs on PV_Base-add.cost.mkt, keyed by projection years and carrying blanks where the opening stock or shock deviation is missing.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_whichever_lower, 0)) else (xl_min(xl_mul(pv_base_add_cost_mkt_opening_percent_of_face, pv_base_add_cost_mkt_shock_deviation_from_baseline[time_period]), pv_base_add_cost_mkt_or) if xl_bool(xl_eq(pv_base_add_cost_mkt_whichever_lower, 'Whichever is lower')) else (pv_base_add_cost_mkt_or if xl_bool(xl_eq(pv_base_add_cost_mkt_whichever_lower, 400)) else xl_mul(pv_base_add_cost_mkt_opening_percent_of_face, pv_base_add_cost_mkt_shock_deviation_from_baseline[time_period])))))
        return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_opening_percent_of_face, 0)) else (xl_min(xl_mul(pv_base_add_cost_mkt_opening_percent_of_face, pv_base_add_cost_mkt_shock_deviation_from_baseline[time_period]), pv_base_add_cost_mkt_or) if xl_bool(xl_eq(pv_base_add_cost_mkt_whichever_lower, 'Whichever is lower')) else (pv_base_add_cost_mkt_or if xl_bool(xl_eq(pv_base_add_cost_mkt_whichever_lower, 400)) else xl_mul(pv_base_add_cost_mkt_opening_percent_of_face, pv_base_add_cost_mkt_shock_deviation_from_baseline[time_period])))))

    return data.PV_BASE_ADD_COST_MKT_SHOCK_INCREASE_IN_BORROWING_COSTS.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_SHOCK_INCREASE_IN_BORROWING_COSTS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASE_ADD_COST_MKT_SHOCK_INCREASE_IN_BORROWING_COSTS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(key=(), domain=None, cells=data.PV_BASE_ADD_COST_MKT_SHOCK_AVERAGE_CELLS)
def pv_base_add_cost_mkt_shock_average(*, pv_base_add_cost_mkt_shock_increase_in_borrowing_costs: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> float | str:
    """Average market-shock increase in borrowing costs on the PV_Base-add cost basis.

    Compute the PV_Base-add.cost.mkt shock average from the authored series over the old-debt-service time coordinates.

    Args:
        pv_base_add_cost_mkt_shock_increase_in_borrowing_costs: A named-axis series of market-shock increases in borrowing costs, with numeric, text, or blank values over catalog coordinates.
        input3_old_debt_service: The Input 3 old-debt-service data series, whose TIME_PERIOD axis defines the slice used for the average.

    Returns:
        The average of the selected borrowing-cost series slice as a float, or an Excel error code string if the average cannot be computed.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    _pv_base_add_cost_mkt_shock_average_table_0 = view(pv_base_add_cost_mkt_shock_increase_in_borrowing_costs, cols=span(input3_old_debt_service.domain.axis('TIME_PERIOD'), input3_old_debt_service.domain.axis('TIME_PERIOD').keys[0], input3_old_debt_service.domain.axis('TIME_PERIOD').keys[1]))
    try:
        return as_measure(xl_average(_pv_base_add_cost_mkt_shock_average_table_0))
    except XlError as error:
        return error.code

@publish(data.PV_BASE_ADD_COST_MKT_SHOCK_ADDITION_NOMINAL_INTEREST_PAYMENTS_ON_EXTERNAL_DEBT.schema, cells=data.PV_BASE_ADD_COST_MKT_SHOCK_ADDITION_NOMINAL_INTEREST_PAYMENTS_ON_EXTERNAL_DEBT.cells)
def pv_base_add_cost_mkt_shock_addition_nominal_interest_payments_on_external_debt(*, pv_base_add_cost_mkt_output_interest: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Sum external-debt nominal interest components into the PV_Base market-cost shock-addition series.

    Aggregates selected external-debt instrument interest entries by projection year onto the PV_Base market-cost shock-addition nominal interest payments coordinate.

    Args:
        pv_base_add_cost_mkt_output_interest: Typed `data.Series[float | str | None]` of PV_Base market-cost output interest over projection years and external-debt instrument coordinates, including Eurobond, Commercial Bank, and COM3–COM5 entries summed by year.
        input3_old_debt_service: Typed `data.Input3OldDebtService` supplying the old debt-service schedule whose `TIME_PERIOD` axis defines the projection years to evaluate.

    Returns:
        Typed `data.Series[float | str | None]` keyed by projection years on `PV_Base-add.cost.mkt` for shock-addition nominal interest payments on external debt.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(xl_add(xl_add(xl_add(pv_base_add_cost_mkt_output_interest['Eurobond', time_period], pv_base_add_cost_mkt_output_interest['Commecial Bank', time_period]), pv_base_add_cost_mkt_output_interest['COM3', time_period]), pv_base_add_cost_mkt_output_interest['COM4', time_period]), pv_base_add_cost_mkt_output_interest['COM5', time_period]))

    return data.PV_BASE_ADD_COST_MKT_SHOCK_ADDITION_NOMINAL_INTEREST_PAYMENTS_ON_EXTERNAL_DEBT.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_SHOCK_ADDITION_NOMINAL_INTEREST_PAYMENTS_ON_EXTERNAL_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASE_ADD_COST_MKT_SHOCK_ADDITION_NOMINAL_INTEREST_PAYMENTS_ON_EXTERNAL_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASE_ADD_COST_MKT_GRACE.schema, cells=data.PV_BASE_ADD_COST_MKT_GRACE.cells)
def pv_base_add_cost_mkt_grace(*, input4_grace_period: data.Input4GracePeriod) -> data.Series[int | str | None]:
    """Compute PV Base add-cost market grace period by instrument.

    Projects Input 4 grace-period values into the PV Base add-cost market grace series used by the external debt PV calculation.

    Args:
        input4_grace_period: Grace-period input series for the five instruments (COM3, COM4, COM5, Commercial Bank, Eurobond).

    Returns:
        Typed series of grace-period measures indexed by the required PV Base add-cost market grace coordinates, yielding int values where available and str or None where the input is blank or non-numeric.
    """
    data.INPUT4_GRACE_PERIOD.schema.validate(input4_grace_period)
    def formula(instrument: str) -> int | str | None:
        return as_measure(input4_grace_period[instrument], 'int')

    return data.PV_BASE_ADD_COST_MKT_GRACE.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_GRACE.required))

@publish(data.PV_BASE_ADD_COST_MKT_MATURITY.schema, cells=data.PV_BASE_ADD_COST_MKT_MATURITY.cells)
def pv_base_add_cost_mkt_maturity(*, input4_loan_maturity: data.Input4LoanMaturity) -> data.Series[int | str | None]:
    """Compute the PV_Base add-cost market-maturity series from the Input 4 loan-maturity inputs.

    Projects per-instrument loan maturities onto the PV_Base add-cost market-maturity coordinates so downstream add-cost calculations can consume them.

    Args:
        input4_loan_maturity: Loan-maturity input series (data.Input4LoanMaturity) over catalog coordinates, giving the per-instrument maturity values that supply the PV_Base add-cost market-maturity series.

    Returns:
        data.Series[int | str | None] holding the PV_Base add-cost market-maturity values, lifted per instrument from the Maturity Eurobond internal series across the COM3, COM4, COM5, Commercial Bank, and Eurobond instruments.
    """
    data.INPUT4_LOAN_MATURITY.schema.validate(input4_loan_maturity)
    def formula(instrument: str) -> int | str | None:
        return as_measure(input4_loan_maturity[instrument], 'int')

    return data.PV_BASE_ADD_COST_MKT_MATURITY.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_MATURITY.required))

@publish(data.PV_BASE_ADD_COST_MKT_DISCOUNT_INTEREST_RATE.schema, cells=data.PV_BASE_ADD_COST_MKT_DISCOUNT_INTEREST_RATE.cells)
def pv_base_add_cost_mkt_discount_interest_rate(*, pv_base_add_cost_mkt_shock_average: float | str) -> data.Series[float | str | None]:
    """Compute the PV base additional-cost market discount interest-rate series.

    Derive per-instrument discount interest rates from the average market shock using the authored coordinate scaling.

    Args:
        pv_base_add_cost_mkt_shock_average: Scalar average market discount-rate shock as a float or string, used as the dividend in the authored discount-rate formula.

    Returns:
        A data.Series[float | str | None] over the PV_BASE_ADD_COST_MKT_DISCOUNT_INTEREST_RATE instrument coordinate, containing the computed interest rate for COM3, COM4, COM5, Commecial Bank, and Eurobond.
    """
    def formula(instrument: str) -> float | str | None:
        return as_measure(xl_div(pv_base_add_cost_mkt_shock_average, 10000))

    return data.PV_BASE_ADD_COST_MKT_DISCOUNT_INTEREST_RATE.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_DISCOUNT_INTEREST_RATE.required))

@publish(data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0.schema, cells=data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0.cells)
def pv_base_add_cost_mkt_discount_t_g_0(*, pv_base_add_cost_mkt_opening_stock_percent_of_face: int | str, pv_base_add_cost_mkt_shock_schedule_period: data.Series[int | str | None], pv_base_add_cost_mkt_grace: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Computes the per-instrument, per-period market-discount add-on cost on the PV base, subtracting grace and flooring the result at zero.

    Produces the discount add-on cost series used when building the market-cost component of the PV baseline for commercial instruments.

    Args:
        pv_base_add_cost_mkt_opening_stock_percent_of_face: Scalar opening-stock percent of face value applied to every instrument at the first time period.
        pv_base_add_cost_mkt_shock_schedule_period: Per-period schedule series supplying the reference amount used for time periods after the first.
        pv_base_add_cost_mkt_grace: Per-instrument grace series subtracted from the opening stock or schedule value before the zero floor is applied.
        input3_old_debt_service: Input 3 old-debt-service series whose TIME_PERIOD axis defines the output period grid and is schema-validated before computation.

    Returns:
        A data.Series[int | str | None] over the instrument and TIME_PERIOD coordinates holding the floored add-on discount cost for each instrument and period.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0 = {'COM4': 'Eurobond', 'COM5': 'Commecial Bank'}
        if instrument == 'Eurobond' and _p_time_period == 0:
            return as_measure((xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_grace['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_grace['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank' and _p_time_period == 0:
            return as_measure((xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_grace['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_grace['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3' and _p_time_period == 0:
            return as_measure((xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_grace['COM3']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_grace['COM3']), 0)) else 0), 'int')
        elif instrument == 'Eurobond' and _p_time_period >= 1:
            return as_measure((xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_grace['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_grace['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank' and _p_time_period >= 1:
            return as_measure((xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_grace['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_grace['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3' and _p_time_period >= 1:
            return as_measure((xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_grace['COM3']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_grace['COM3']), 0)) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_grace['COM4']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_grace['COM4']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_grace['COM5']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_grace['COM5']), 0)) else 0), 'int')

    pv_base_add_cost_mkt_discount_t_g_0 = CoordinateReader('pv_base_add_cost_mkt_discount_t_g_0', data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0.collect(((coord, pv_base_add_cost_mkt_discount_t_g_0[coord]) for coord in data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_GRACE_CUMULATIVE.schema, cells=data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_GRACE_CUMULATIVE.cells)
def pv_base_add_cost_mkt_discount_post_grace_cumulative(*, pv_base_add_cost_mkt_discount_t_g_0: data.Series[int | str | None], pv_base_add_cost_mkt_output_cumulative: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes post-grace cumulative market-discount values for instruments on the PV base add-cost schedule.

    Selects cumulative output by grace-period timing and returns the per-instrument, per-time-period post-grace series.

    Args:
        pv_base_add_cost_mkt_discount_t_g_0: Per-instrument, per-time-period series of integer or string grace-period selectors, with nulls where the selector is unavailable.
        pv_base_add_cost_mkt_output_cumulative: Per-instrument cumulative output series of floats or strings used as lookup values when the grace-period selector indexes into the time axis.
        input3_old_debt_service: Typed old-debt-service input series whose schema and TIME_PERIOD axis define the coordinate alignment for the computation.

    Returns:
        A data series of float or string values, indexed by instrument and time period, containing the post-grace cumulative market-discount results.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
