@publish(data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_M_CONDITION.schema, cells=data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_M_CONDITION.cells)
def pv_base_add_cost_mkt_discount_t_m_condition(*, pv_base_add_cost_mkt_opening_stock_percent_of_face: int | str, pv_base_add_cost_mkt_shock_schedule_period: data.Series[int | str | None], pv_base_add_cost_mkt_maturity: data.Series[int | str | None], pv_base_add_cost_mkt_discount_t_g_0: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Computes the t–m discount condition for market-based add-on cost across five instruments, floored at zero.

    Derive each instrument's period-wise excess of the amortized stock (or scheduled shock profile) over maturity, yielding non-negative t–m condition measures on the projection grid.

    Args:
        pv_base_add_cost_mkt_opening_stock_percent_of_face: Scalar opening stock expressed as a percent of face value, used as the starting amortized balance in the initial period.
        pv_base_add_cost_mkt_shock_schedule_period: Integer-or-text series giving the shock-schedule period balance applied beyond the first projection period for each instrument.
        pv_base_add_cost_mkt_maturity: Integer-or-text series holding the instrument maturity values referenced when comparing against the opening stock and schedule balances.
        pv_base_add_cost_mkt_discount_t_g_0: Integer-or-text series of the prior-period discount balances, keyed by mapped instrument name and time period before differencing against maturity.
        input3_old_debt_service: Typed old-debt-service input whose TIME_PERIOD axis supplies the coordinate domain and period positions for evaluation.

    Returns:
        Integer-or-text series of t–m condition values per instrument and time period, zero where the difference is non-positive.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0 = {'COM4': 'Eurobond', 'COM5': 'Commecial Bank'}
        if instrument == 'Eurobond' and _p_time_period == 0:
            return as_measure((xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank' and _p_time_period == 0:
            return as_measure((xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3' and _p_time_period == 0:
            return as_measure((xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['COM3']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['COM3']), 0)) else 0), 'int')
        elif instrument == 'Eurobond' and _p_time_period >= 1:
            return as_measure((xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank' and _p_time_period >= 1:
            return as_measure((xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3' and _p_time_period >= 1:
            return as_measure((xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['COM3']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['COM3']), 0)) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_maturity['COM4']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_maturity['COM4']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_maturity['COM5']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_maturity['COM5']), 0)) else 0), 'int')

    return data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_M_CONDITION.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_M_CONDITION.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_M_CONDITION.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_MATURITY_CUMULATIVE.schema, cells=data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_MATURITY_CUMULATIVE.cells)
def pv_base_add_cost_mkt_discount_post_maturity_cumulative(*, pv_base_add_cost_mkt_discount_t_m_condition: data.Series[int | str | None], pv_base_add_cost_mkt_output_cumulative: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Builds the post-maturity cumulative market-discount series per instrument from the cumulative discount table.

    Selects, per instrument and period, either zero or the cumulative post-maturity value according to the time/market condition selector.

    Args:
        pv_base_add_cost_mkt_discount_t_m_condition: Per-instrument, per-period selector series over the five tracked instruments; a zero entry forces a zero result, while any other value is used to choose from the corresponding cumulative row.
        pv_base_add_cost_mkt_output_cumulative: Cumulative market-discount output series indexed by instrument rows (Eurobond, Commecial Bank, COM3, COM4, COM5) and TIME_PERIOD columns, sliced to the first 28 periods as the lookup table.
        input3_old_debt_service: Input 3 old debt service data whose TIME_PERIOD axis defines the domain and binding used to evaluate and collect the result.

    Returns:
        Series of post-maturity cumulative market-discount values over instrument and TIME_PERIOD coordinates, yielding zero where the selector is zero.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_0 = view(pv_base_add_cost_mkt_output_cumulative, rows=('Eurobond',), cols=span(_ax_time_period, _ax_time_period.keys[0], _ax_time_period.keys[27]))
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_1 = view(pv_base_add_cost_mkt_output_cumulative, rows=('Commecial Bank',), cols=span(_ax_time_period, _ax_time_period.keys[0], _ax_time_period.keys[27]))
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_2 = view(pv_base_add_cost_mkt_output_cumulative, rows=('COM3',), cols=span(_ax_time_period, _ax_time_period.keys[0], _ax_time_period.keys[27]))
