@publish(data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.schema, cells=data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.cells)
def pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd(*, ext_debt_new_disbursements_external: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Builds the gross new forex borrowing (USD) output series by lifting each instrument's new external disbursement onto the projection time grid.

    Produces the market-financing cost add-on output for new forex borrowing, gross, in USD across the five financing instruments.

    Args:
        ext_debt_new_disbursements_external: Typed data series of new external debt disbursements per instrument and time period, providing the gross borrowing amounts for Eurobond, Commercial Bank, COM3, COM4, and COM5; per-cell values may be numeric, text, or blank.
        input3_old_debt_service: Typed input3 old debt service series whose TIME_PERIOD axis supplies the projection coordinate grid the output is aligned to.

    Returns:
        A typed data series of gross new forex borrowing in USD per instrument and time period, with values that may be numeric, text, or blank.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure(ext_debt_new_disbursements_external['Eurobond', time_period])
        elif instrument == 'Commecial Bank':
            return as_measure(ext_debt_new_disbursements_external['Commecial Bank', time_period])
        elif instrument == 'COM3':
            return as_measure(ext_debt_new_disbursements_external['COM3', time_period])
        elif instrument == 'COM4':
            return as_measure(ext_debt_new_disbursements_external['COM4', time_period])
        return as_measure(ext_debt_new_disbursements_external['COM5', time_period])

    return data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.required.bind(TIME_PERIOD=input3_old_debt_service))

