@publish(data.PV_LC_TERMS_GRACE.schema, cells=data.PV_LC_TERMS_GRACE.cells)
def pv_lc_terms_grace(*, input5_grace_period: data.Input5GracePeriod) -> data.Series[float | str | None]:
    """Extract PV_LC grace terms from the Input 5 grace-period series.

    Builds the grace-period term series used by PV_LC calculations from validated Input 5 grace-period data.

    Args:
        input5_grace_period: Keyword-only data.Input5GracePeriod named-axis series over catalog coordinates; each resident-held instrument entry supplies the raw grace-period value, and the series is schema-validated before extraction.

    Returns:
        A data.Series[float | str | None] keyed by INSTRUMENT across PV_LC_NR1, PV_LC_NR2, and PV_LC_NR3, containing per-instrument grace-period values (numeric, text, or None).
    """
    data.INPUT5_GRACE_PERIOD.schema.validate(input5_grace_period)
    def formula(instrument: str, holder: str) -> float | str | None:
        return as_measure(input5_grace_period[instrument, 'residents'])

    return data.PV_LC_TERMS_GRACE.collect(evaluate(formula, data.PV_LC_TERMS_GRACE.required))

