@publish(data.PV_LC_OUTPUT_ISSUANCE_YEAR.schema, cells=data.PV_LC_OUTPUT_ISSUANCE_YEAR.cells)
def pv_lc_output_issuance_year(*, pv_lc_nr1_terms_projection_year: data.Series[int | str | None], pv_lc_terms_projection_year: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Resolve PV_LC output issuance years per instrument from LC terms projections or prior-year roll-forward.

    Supplies the instrument-keyed issuance-year series that downstream PV_LC aggregation and chart outputs consume.

    Args:
        pv_lc_nr1_terms_projection_year: Named-axis tensor over instrument, holder, and issuance year holding the NR1 terms projection year, consulted for 'Bonds (1 to 3 years)-LC' at issuance year 2024.
        pv_lc_terms_projection_year: Named-axis tensor over instrument, holder, and issuance year holding the LC terms projection year for the 4–7 year and beyond-7-year bond instruments at issuance year 2024.

    Returns:
        Named-axis data.Series of issuance years on PV_LC, keyed by INSTRUMENT across the required output coordinates and typed int, str, or None.
    """
    def formula(instrument: str, holder: str, issuance_year: int) -> int | str | None:
        if instrument == 'Bonds (1 to 3 years)-LC' and issuance_year == 2024:
            return as_measure(pv_lc_nr1_terms_projection_year[instrument, holder, issuance_year], 'int')
        elif instrument in ('Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC') and issuance_year == 2024:
            return as_measure(pv_lc_terms_projection_year[instrument, holder, issuance_year], 'int')
        return as_measure(xl_add(pv_lc_output_issuance_year[instrument, holder, issuance_year - 1], 1), 'int')

    pv_lc_output_issuance_year = CoordinateReader('pv_lc_output_issuance_year', data.PV_LC_OUTPUT_ISSUANCE_YEAR.required, formula)
    return data.PV_LC_OUTPUT_ISSUANCE_YEAR.collect((coord, pv_lc_output_issuance_year[coord]) for coord in data.PV_LC_OUTPUT_ISSUANCE_YEAR.required)

