def pv_lc_output_total_debt_service_in_usd(*, pv_lc_output_interest_in_usd: data.Series[float | str | None], pv_lc_output_amortization_in_usd: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Sums PV_LC interest and amortization into total debt service in USD.

    Computes the PV_LC total debt service series by adding each instrument's interest and amortization per projection year, using the time grid supplied by the old-debt-service input.

    Args:
        pv_lc_output_interest_in_usd: Interest payments in USD on PV_LC, a named-axis series over instrument, holder, issuance year, and time period.
        pv_lc_output_amortization_in_usd: Amortization payments in USD on PV_LC, a named-axis series over instrument, holder, issuance year, and time period.
        input3_old_debt_service: Old debt service input whose TIME_PERIOD axis defines the year grid used to evaluate the per-year interest-plus-amortization sum.

    Returns:
        A data.Series[float | str | None] of total debt service in USD on PV_LC, keyed by instrument across the PV_LC_NR1, PV_LC_NR2, and PV_LC_NR3 coordinates.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, holder: str, issuance_year: int, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if issuance_year == 2024:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2024, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2024, time_period]))
        elif issuance_year == 2025:
            return as_measure(xl_add(pv_lc_output_interest_in_usd[instrument, holder, 2025, time_period], pv_lc_output_amortization_in_usd[instrument, holder, 2025, time_period]))
