@publish(data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.schema, cells=data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.cells)
def pv_stress_bounds_total_debt_service_in_usd(*, pv_stress_opening_stock_percent_of_face: int | str, pv_stress_bounds_interest: data.Series[float | str | None], pv_stress_bounds_amortization: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the PV-stress bounding-rectangle total debt service series in USD.

    Combines interest and amortization coordinates per bound scenario, seeding the exports-shock first year with the opening-stock percent of face.

    Args:
        pv_stress_opening_stock_percent_of_face: Opening-stock scalar expressed as a percent of face, folded into amortization for the exports shock in the first projection year; accepts an int or spreadsheet-style string.
        pv_stress_bounds_interest: Interest series on the pv_stress.bounds scenario axis over TIME_PERIOD, read per bound scenario for the debt-service sum.
        pv_stress_bounds_amortization: Amortization series aligned with the interest coordinate over the same scenario and TIME_PERIOD axes.
        input3_old_debt_service: Old debt service input series supplying the TIME_PERIOD axis and domain against which the resulting bound layer is evaluated and aligned.

    Returns:
        A data.Series[float | str | None] on pv_stress.bounds holding total debt service in USD for the six bound scenarios, including the five member-row cells contributed by the bounding rectangle.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Bound Test 2: Exports Shock' and _p_time_period == 0:
            return as_measure(xl_add(pv_stress_opening_stock_percent_of_face, pv_stress_bounds_amortization['Bound Test 2: Exports Shock', time_period]))
        elif scenario == 'Bounds Test 1: Real GDP Growth Shock' and _p_time_period >= 1:
            return as_measure(xl_add(pv_stress_bounds_interest['Bounds Test 1: Real GDP Growth Shock', time_period], pv_stress_bounds_amortization['Bounds Test 1: Real GDP Growth Shock', time_period]))
        elif scenario == 'Bound Test 2: Exports Shock' and _p_time_period >= 1:
            return as_measure(xl_add(pv_stress_bounds_interest['Bound Test 2: Exports Shock', time_period], pv_stress_bounds_amortization['Bound Test 2: Exports Shock', time_period]))
        elif scenario == 'Bound Test 4: Other Flows Shock' and _p_time_period >= 1:
            return as_measure(xl_add(pv_stress_bounds_interest['Bound Test 4: Other Flows Shock', time_period], pv_stress_bounds_amortization['Bound Test 4: Other Flows Shock', time_period]))
        elif scenario == 'Bounds Test 6: Combined Shock for Market Access Countries' and _p_time_period >= 1:
            return as_measure(xl_add(pv_stress_bounds_interest['Bounds Test 6: Combined Shock for Market Access Countries', time_period], pv_stress_bounds_amortization['Bounds Test 6: Combined Shock for Market Access Countries', time_period]))
        elif scenario == 'Bounds Test 6: Combined Shock for Non-Market Access Countries' and _p_time_period >= 1:
            return as_measure(xl_add(pv_stress_bounds_interest['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period], pv_stress_bounds_amortization['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]))
        return as_measure(xl_add(pv_stress_bounds_interest['Bounds Test 5: Exchange Rate Shock', time_period], pv_stress_bounds_amortization['Bounds Test 5: Exchange Rate Shock', time_period]))

    return data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.collect(evaluate(formula, data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_BOUNDS_T_G_0.schema, cells=data.PV_STRESS_BOUNDS_T_G_0.cells)
def pv_stress_bounds_t_g_0(*, pv_stress_calendar_period: data.Series[int | str | None], pv_stress_average_grace_period_new_debt: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Computes the PV stress bounds series for the t−g>0 condition across the six stress scenarios.

    Derives each scenario’s positive calendar-period minus historical-average grace-period margin, defaulting to zero when non-positive.

    Args:
        pv_stress_calendar_period: Calendar-period series over catalog coordinates, used as the starting period for the bounds calculation.
        pv_stress_average_grace_period_new_debt: Average grace-period series for new debt at the historical-average scenario, subtracted from the calendar period.
        input3_old_debt_service: Typed old-debt-service input series over catalog coordinates, supplying the TIME_PERIOD axis used to align the output.

    Returns:
        A data.Series[int | str | None] aligned to the old-debt-service TIME_PERIOD axis, containing the positive margin or zero for each stress scenario.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_grace_period_new_debt['Key variables at historical average']) if xl_bool(xl_gt(xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_grace_period_new_debt['Key variables at historical average']), 0)) else 0), 'int')

    return data.PV_STRESS_BOUNDS_T_G_0.collect(evaluate(formula, data.PV_STRESS_BOUNDS_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_BOUNDS_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_BOUNDS_T_M_CONDITION.schema, cells=data.PV_STRESS_BOUNDS_T_M_CONDITION.cells)
def pv_stress_bounds_t_m_condition(*, pv_stress_calendar_period: data.Series[int | str | None], pv_stress_average_maturity_of_new_debt: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute the t-minus-maturity stress-bounds condition over scenario and time-period coordinates.

    Return a per-scenario time series that is the positive difference between calendar period and average maturity of new debt, or zero when that difference is not positive.

    Args:
        pv_stress_calendar_period: Calendar-period series over the TIME_PERIOD coordinate, supplying the time-period value used in the condition and difference calculation.
        pv_stress_average_maturity_of_new_debt: Average-maturity-of-new-debt series, sampled at the historical-average key variable, providing the maturity term subtracted from the calendar period.
        input3_old_debt_service: Validated input-3 old-debt-service bundle whose TIME_PERIOD axis supplies the target evaluation domain and time-period positions.

    Returns:
        A data.Series[int | str | None] collected over the scenario and TIME_PERIOD domain, containing the nonnegative t-minus-maturity condition value for each scenario and time period.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_maturity_of_new_debt['Key variables at historical average']) if xl_bool(xl_gt(xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_maturity_of_new_debt['Key variables at historical average']), 0)) else 0), 'int')

    return data.PV_STRESS_BOUNDS_T_M_CONDITION.collect(evaluate(formula, data.PV_STRESS_BOUNDS_T_M_CONDITION.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_BOUNDS_T_M_CONDITION.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_SHARE_OF_MARGINAL_DEBT.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_SHARE_OF_MARGINAL_DEBT.cells)
def pv_resfin_pub_assumptions_share_of_marginal_debt(*, in7_resfin_domestic_st: data.Series[float | str | None], in7_resfin_shares_effective: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Return the public residual-financing assumptions series for the share of marginal debt by instrument.

    Combines domestic short-term residual financing with effective instrument shares to populate the public assumptions share-of-marginal-debt series.

    Args:
        in7_resfin_domestic_st: Input series providing the domestic short-term residual-financing value selected for calculation.
        in7_resfin_shares_effective: Input series of effective residual-financing shares keyed by instrument, supplying the remaining share-of-marginal-debt assumptions.

    Returns:
        A data.Series[float | str | None] over the instrument coordinate containing the share-of-marginal-debt assumption for domestic medium- and long-term, domestic short-term, and external PPG medium- and long-term instruments.
    """
    def formula(instrument: str) -> float | str | None:
        if instrument == 'Domestic short-term':
            return as_measure(in7_resfin_domestic_st['Value used for calculation'])
        return as_measure(in7_resfin_shares_effective[instrument])

    return data.PV_RESFIN_PUB_ASSUMPTIONS_SHARE_OF_MARGINAL_DEBT.collect(evaluate(formula, data.PV_RESFIN_PUB_ASSUMPTIONS_SHARE_OF_MARGINAL_DEBT.required))

@publish(data.PV_RESFIN_PUB_DISCOUNT_PERIOD.schema, cells=data.PV_RESFIN_PUB_DISCOUNT_PERIOD.cells)
def pv_resfin_pub_discount_period(*, pv_resfin_pub_opening_stock_period: int | str) -> data.Series[int | str | None]:
    """Compute the public residual-financing discount period series for the External MLT debt instrument.

    Derive each projection period's public discount period from the 2025 opening-stock period and prior-period values.

    Args:
        pv_resfin_pub_opening_stock_period: Opening-stock period scalar (year or label) used as the 2025 seed when deriving the External MLT debt discount period.

    Returns:
        A data.Series over the pv_resfin_pub.discount_schedule Period coordinate for External MLT debt, yielding the computed discount period as an int, str, or None.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if time_period == 2025:
            return as_measure(xl_add(pv_resfin_pub_opening_stock_period, 1), 'int')
        return as_measure(xl_add(pv_resfin_pub_discount_period['External MLT debt', time_period - 1], 1), 'int')

    pv_resfin_pub_discount_period = CoordinateReader('pv_resfin_pub_discount_period', data.PV_RESFIN_PUB_DISCOUNT_PERIOD.required, formula)
    return data.PV_RESFIN_PUB_DISCOUNT_PERIOD.collect((coord, pv_resfin_pub_discount_period[coord]) for coord in data.PV_RESFIN_PUB_DISCOUNT_PERIOD.required)

@publish(key=('INSTRUMENT',), domain=None, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_NOMINAL_INTEREST_RATE_ON_NEW_BORROWING_IN_USD_CELLS)
def pv_resfin_pub_assumptions_avg_nominal_interest_rate_on_new_borrowing_in_usd(*, in7_resfin_ext_mlt_effective: data.Series[float | str | None]) -> float | str:
    """Return the average nominal interest rate on new external MLT borrowing in USD.

    Extract the published residual-financing interest-rate assumption from the external MLT debt series.

    Args:
        in7_resfin_ext_mlt_effective: External MLT debt series containing the average nominal interest rate on new borrowing in USD, keyed by catalog coordinates.

    Returns:
        The average nominal interest rate on new borrowing in USD as a float, or an XL error code string if the referenced series value cannot be evaluated.
    """
    try:
        return as_measure(in7_resfin_ext_mlt_effective['Avg. nominal interest rate on new borrowing in USD'])
    except XlError as error:
        return error.code

@publish(key=('INSTRUMENT',), domain=None, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_USD_DISCOUNT_RATE_CELLS)
def pv_resfin_pub_assumptions_usd_discount_rate(*, in7_resfin_ext_mlt_effective: data.Series[float | str | None]) -> float | str:
    """Return the USD discount rate for external MLT debt from public assumptions.

    Extract and measure the `USD Discount rate` coordinate from the external MLT effective-assumption series.

    Args:
        in7_resfin_ext_mlt_effective: Catalog-coordinate series of external MLT effective assumptions containing the `USD Discount rate` coordinate, with float, string, or null values.

    Returns:
        Float USD discount rate when available, or the string Excel error code if measurement raises an `XlError`.
    """
    try:
        return as_measure(in7_resfin_ext_mlt_effective['USD Discount rate'])
    except XlError as error:
        return error.code

@publish(data.PV_RESFIN_PUB_DISCOUNT_DEBT_STOCK.schema, cells=data.PV_RESFIN_PUB_DISCOUNT_DEBT_STOCK.cells)
def pv_resfin_pub_discount_debt_stock(*, pv_resfin_pub_opening_stock_disbursement: int | str, pv_resfin_pub_discount_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public discount-window debt stock for external MLT debt.

    Projects outstanding public debt by applying discount amortization to the prior stock, seeded by opening stock disbursement in 2024.

    Args:
        pv_resfin_pub_opening_stock_disbursement: Opening public stock disbursement for the initial projection year, provided as an integer or string scalar.
        pv_resfin_pub_discount_amortization: Discount amortization series over catalog coordinates, indexed by instrument and time period; currently carries the External MLT debt instrument.

    Returns:
        A typed data.Series of float, str, or None values containing the projected public discount-window debt stock for each required catalog coordinate.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_sub(pv_resfin_pub_opening_stock_disbursement, pv_resfin_pub_discount_amortization['External MLT debt', time_period]))
        elif time_period == 2025:
            return as_measure(xl_sub(pv_resfin_pub_discount_debt_stock[instrument, time_period - 1], pv_resfin_pub_discount_amortization['External MLT debt', time_period]))
        return as_measure(xl_sub(pv_resfin_pub_discount_debt_stock['External MLT debt', time_period - 1], pv_resfin_pub_discount_amortization['External MLT debt', time_period]))

    pv_resfin_pub_discount_debt_stock = CoordinateReader('pv_resfin_pub_discount_debt_stock', data.PV_RESFIN_PUB_DISCOUNT_DEBT_STOCK.required, formula)
    return data.PV_RESFIN_PUB_DISCOUNT_DEBT_STOCK.collect((coord, pv_resfin_pub_discount_debt_stock[coord]) for coord in data.PV_RESFIN_PUB_DISCOUNT_DEBT_STOCK.required)

@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD.cells)
def pv_resfin_pub_assumptions_avg_maturity_incl_grace_period(*, in7_resfin_dom_mlt_effective: data.Series[float | str | None], in7_resfin_ext_mlt_effective: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public rescheduling/financing average maturity (including grace period) assumption per MLT debt instrument.

    Derive the published per-instrument average-maturity assumption series consumed by the public ResFin assumptions block.

    Args:
        in7_resfin_dom_mlt_effective: data.Series[float | str | None] over the MLT-debt instrument axis (Domestic MLT debt), carrying the Input 7 average maturity (incl. grace period) values to be rounded down to whole years.
        in7_resfin_ext_mlt_effective: data.Series[float | str | None] over the MLT-debt instrument axis (External MLT debt), carrying the Input 7 average maturity (incl. grace period) values used as-is.

    Returns:
        data.Series[float | str | None] over the MLT-debt instrument axis holding the average maturity (incl. grace period) per instrument, with the domestic value rounded down to whole years.
    """
    def formula(instrument: str) -> float | str | None:
        if instrument == 'External MLT debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. maturity (incl. grace period)'])
        return as_measure(xl_rounddown(in7_resfin_dom_mlt_effective['Avg. maturity (incl. grace period)'], 0))

    return data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD.collect(evaluate(formula, data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD.required))

@publish(data.PV_RESFIN_PUB_DISCOUNT_AMORTIZATION.schema, cells=data.PV_RESFIN_PUB_DISCOUNT_AMORTIZATION.cells)
def pv_resfin_pub_discount_amortization(*, pv_resfin_pub_discount_period: data.Series[int | str | None], pv_resfin_pub_opening_stock_period: int | str, pv_resfin_pub_opening_stock_disbursement: int | str, pv_resfin_pub_assumptions_avg_maturity_incl_grace_period: data.Series[float | str | None], pv_resfin_pub_assumptions_avg_grace_period: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute amortization for the public discount schedule.

    Computes amortization amounts for External MLT debt based on discount periods, opening stock data, and maturity/grace assumptions.

    Args:
        pv_resfin_pub_discount_period: A data.Series of discount schedule periods (int, str, or None) aligned with catalog coordinates.
        pv_resfin_pub_opening_stock_period: The opening stock period (int or str) as a scalar.
        pv_resfin_pub_opening_stock_disbursement: The opening stock disbursement amount (int or str) as a scalar.
        pv_resfin_pub_assumptions_avg_maturity_incl_grace_period: A data.Series of average maturity including grace period (float, str, or None) per instrument.
        pv_resfin_pub_assumptions_avg_grace_period: A data.Series of average grace period (float, str, or None) per instrument.

    Returns:
        A data.Series of amortization values (float, str, or None) for the discount schedule.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_resfin_pub_opening_stock_period, pv_resfin_pub_opening_stock_period), 1), pv_resfin_pub_assumptions_avg_grace_period['External MLT debt'])) else (xl_div(pv_resfin_pub_opening_stock_disbursement, xl_sub(pv_resfin_pub_assumptions_avg_maturity_incl_grace_period['External MLT debt'], pv_resfin_pub_assumptions_avg_grace_period['External MLT debt'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_resfin_pub_opening_stock_period, pv_resfin_pub_opening_stock_period), 1), pv_resfin_pub_assumptions_avg_maturity_incl_grace_period['External MLT debt'])) else 0)))
        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_resfin_pub_discount_period['External MLT debt', time_period], pv_resfin_pub_opening_stock_period), 1), pv_resfin_pub_assumptions_avg_grace_period['External MLT debt'])) else (xl_div(pv_resfin_pub_opening_stock_disbursement, xl_sub(pv_resfin_pub_assumptions_avg_maturity_incl_grace_period['External MLT debt'], pv_resfin_pub_assumptions_avg_grace_period['External MLT debt'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_resfin_pub_discount_period['External MLT debt', time_period], pv_resfin_pub_opening_stock_period), 1), pv_resfin_pub_assumptions_avg_maturity_incl_grace_period['External MLT debt'])) else 0)))

    return data.PV_RESFIN_PUB_DISCOUNT_AMORTIZATION.collect(evaluate(formula, data.PV_RESFIN_PUB_DISCOUNT_AMORTIZATION.required))

@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_GRACE_PERIOD.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_GRACE_PERIOD.cells)
def pv_resfin_pub_assumptions_avg_grace_period(*, in7_resfin_dom_mlt_effective: data.Series[float | str | None], in7_resfin_ext_mlt_effective: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public residual-financing average grace period assumptions by MLT debt instrument.

    Derive the published `Avg. grace period` series on `pv_resfin_pub.assumptions` from the domestic and external MLT effective-assumption inputs.

    Args:
        in7_resfin_dom_mlt_effective: Series of effective assumption values for domestic MLT debt; its `Avg. grace period` coordinate is rounded down to a whole number for the domestic instrument.
        in7_resfin_ext_mlt_effective: Series of effective assumption values for external MLT debt; its `Avg. grace period` coordinate is used without rounding for the external instrument.

    Returns:
        Series of average grace period values keyed by public residual-financing MLT debt instrument (Domestic MLT debt and External MLT debt), using the rounded-down domestic value and the unrounded external value.
    """
    def formula(instrument: str) -> float | str | None:
        if instrument == 'External MLT debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. grace period'])
        return as_measure(xl_rounddown(in7_resfin_dom_mlt_effective['Avg. grace period'], 0))

    return data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_GRACE_PERIOD.collect(evaluate(formula, data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_GRACE_PERIOD.required))

@publish(data.PV_RESFIN_PUB_DISCOUNT_INTEREST.schema, cells=data.PV_RESFIN_PUB_DISCOUNT_INTEREST.cells)
def pv_resfin_pub_discount_interest(*, pv_resfin_pub_assumptions_avg_nominal_interest_rate_on_new_borrowing_in_usd: float | str, pv_resfin_pub_discount_debt_stock: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute interest on public discount debt stock.

    Derive public discount interest for external MLT debt using prior-period debt stock and the new-borrowing interest rate.

    Args:
        pv_resfin_pub_assumptions_avg_nominal_interest_rate_on_new_borrowing_in_usd: Average nominal interest rate on new borrowing in USD, provided as a scalar float or str.
        pv_resfin_pub_discount_debt_stock: Public discount debt stock series over instrument and time, whose prior-period External MLT debt value feeds the interest calculation.

    Returns:
        data.Series[float | str | None] of computed interest amounts aligned to the public discount schedule coordinates.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(pv_resfin_pub_discount_debt_stock['External MLT debt', time_period - 1], pv_resfin_pub_assumptions_avg_nominal_interest_rate_on_new_borrowing_in_usd))

    return data.PV_RESFIN_PUB_DISCOUNT_INTEREST.collect(evaluate(formula, data.PV_RESFIN_PUB_DISCOUNT_INTEREST.required))

@publish(data.PV_RESFIN_PUB_DISCOUNT_TOTAL_DEBT_SERVICE.schema, cells=data.PV_RESFIN_PUB_DISCOUNT_TOTAL_DEBT_SERVICE.cells)
def pv_resfin_pub_discount_total_debt_service(*, pv_resfin_pub_discount_amortization: data.Series[float | str | None], pv_resfin_pub_discount_interest: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Total debt service for external MLT debt.

    Adds discount-schedule amortization and interest to produce the total debt service series.

    Args:
        pv_resfin_pub_discount_amortization: Named-axis tensor over catalog coordinates containing amortization amounts for external MLT debt, with float or string/None values for blanks.
        pv_resfin_pub_discount_interest: Named-axis tensor over catalog coordinates containing interest amounts for external MLT debt, with float or string/None values for blanks.

    Returns:
        A data.Series[float | str | None] over the corresponding instrument and time-period coordinates containing total debt service, preserving float, string, or None values.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(pv_resfin_pub_discount_amortization['External MLT debt', time_period], pv_resfin_pub_discount_interest['External MLT debt', time_period]))

    return data.PV_RESFIN_PUB_DISCOUNT_TOTAL_DEBT_SERVICE.collect(evaluate(formula, data.PV_RESFIN_PUB_DISCOUNT_TOTAL_DEBT_SERVICE.required))

@publish(data.PV_RESFIN_PUB_DISCOUNT_PV_OF_DEBT.schema, cells=data.PV_RESFIN_PUB_DISCOUNT_PV_OF_DEBT.cells)
def pv_resfin_pub_discount_pv_of_debt(*, pv_resfin_pub_assumptions_avg_nominal_interest_rate_on_new_borrowing_in_usd: float | str, pv_resfin_pub_assumptions_usd_discount_rate: float | str, pv_resfin_pub_discount_debt_stock: data.Series[float | str | None], pv_resfin_pub_discount_total_debt_service: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes the present value of public external debt for the discount schedule.

    Resolves each instrument and time-period PV by either passing through the debt stock or discounting future total debt service, depending on the interest-rate comparison.

    Args:
        pv_resfin_pub_assumptions_avg_nominal_interest_rate_on_new_borrowing_in_usd: Scalar or string average nominal interest rate on new external borrowing in USD, used to select debt-stock pass-through versus discounting.
        pv_resfin_pub_assumptions_usd_discount_rate: Scalar or string USD discount rate applied to the NPV of future total debt service.
        pv_resfin_pub_discount_debt_stock: Named-axis series of public debt stock over instrument and time-period coordinates, returned as-is when the rate comparison holds.
        pv_resfin_pub_discount_total_debt_service: Named-axis series of total public debt service over instrument and time-period coordinates, discounted from the following period through 2074.
        input3_old_debt_service: Typed input-3 dataclass of old debt service whose TIME_PERIOD axis aligns and constrains the output domain.

    Returns:
        data.Series[float | str | None] of PV of debt per instrument and time period on the pv_resfin_pub.discount_schedule coordinate space.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((pv_resfin_pub_discount_debt_stock[instrument, time_period] if xl_bool(xl_ge(pv_resfin_pub_assumptions_avg_nominal_interest_rate_on_new_borrowing_in_usd, pv_resfin_pub_assumptions_usd_discount_rate)) else xl_npv(pv_resfin_pub_assumptions_usd_discount_rate, view(pv_resfin_pub_discount_total_debt_service, rows=(instrument,), cols=span(data.TIME_PERIOD_AXIS, time_period + 1, 2074)))))

    return data.PV_RESFIN_PUB_DISCOUNT_PV_OF_DEBT.collect(evaluate(formula, data.PV_RESFIN_PUB_DISCOUNT_PV_OF_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_PUB_DISCOUNT_PV_OF_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_DOMESTIC_MLT_DEBT.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_DOMESTIC_MLT_DEBT.cells)
def pv_resfin_pub_assumptions_domestic_mlt_debt(*, pv_resfin_pub_assumptions_inflation_gdp_deflator: data.Series[float | str | None], pv_resfin_pub_avg_real_interest_rate_new_borrowing: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes the domestic medium- and long-term debt assumptions series by adding the GDP-deflator inflation to the average real interest rate on new borrowing.

    Produces the nominal interest-rate assumption path for domestic medium- and long-term debt, indexed over the projection years of the old-debt-service input.

    Args:
        pv_resfin_pub_assumptions_inflation_gdp_deflator: Named-axis series of GDP-deflator inflation values, keyed by time period, used as the inflation component of the nominal rate.
        pv_resfin_pub_avg_real_interest_rate_new_borrowing: Named-axis series of average real interest rates on new borrowing for the Domestic medium and long-term instrument, keyed by time period, supplying the real-rate component.
        input3_old_debt_service: Surrounding old-debt-service input record whose TIME_PERIOD axis fixes the projection grid the output series is evaluated over.

    Returns:
        Series of nominal interest-rate assumptions for domestic medium- and long-term debt, over catalog time-period coordinates, with float values or string/None placeholders where inputs are blank.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(pv_resfin_pub_avg_real_interest_rate_new_borrowing['Domestic medium and long-term', time_period], pv_resfin_pub_assumptions_inflation_gdp_deflator[time_period]))

    return data.PV_RESFIN_PUB_ASSUMPTIONS_DOMESTIC_MLT_DEBT.collect(evaluate(formula, data.PV_RESFIN_PUB_ASSUMPTIONS_DOMESTIC_MLT_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_PUB_ASSUMPTIONS_DOMESTIC_MLT_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(key=('INSTRUMENT',), domain=None, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_REAL_INTEREST_RATE_ON_NEW_BORROWING_CELLS)
def pv_resfin_pub_assumptions_avg_real_interest_rate_on_new_borrowing(*, in7_resfin_dom_mlt_effective: data.Series[float | str | None]) -> float | str:
    """Extract the average real interest rate on new domestic MLT borrowing from the public assumptions series.

    Provide the scalar financing-cost assumption for domestic MLT debt used in public DSA calculations.

    Args:
        in7_resfin_dom_mlt_effective: A typed data series over catalog coordinates containing the `Avg. real interest rate on new borrowing` assumption for the Domestic MLT debt instrument, with values that may be floats, strings, or None.

    Returns:
        The average real interest rate as a float, or an XlError code string if the assumption value cannot be evaluated.
    """
    try:
        return as_measure(in7_resfin_dom_mlt_effective['Avg. real interest rate on new borrowing'])
    except XlError as error:
        return error.code

@publish(data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE_NEW_BORROWING.schema, cells=data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE_NEW_BORROWING.cells)
def pv_resfin_pub_avg_real_interest_rate_new_borrowing(*, pv_resfin_pub_assumptions_avg_real_interest_rate_on_new_borrowing: float | str, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Lift the assumed average real interest rate on new public borrowing into a typed series over the time grid supplied by Input 3 old debt service.

    Exposes the single assumption scalar as a broadcast series so downstream public-debt residency-financing formulas can consume it alongside Input 3 old debt service on matching TIME_PERIOD coordinates.

    Args:
        pv_resfin_pub_assumptions_avg_real_interest_rate_on_new_borrowing: Assumed average real interest rate on new borrowing for domestic medium- and long-term instruments, given as a scalar float or a string literal and broadcast unchanged across every time period.
        input3_old_debt_service: Input 3 old debt service data series whose validated TIME_PERIOD axis defines the output domain and supplies the per-period coordinate positions used when collecting the result.

    Returns:
        A data.Series over TIME_PERIOD holding the assumed average real interest rate on new borrowing, with the same repeated value in each period; cells may be float, str, or None.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(pv_resfin_pub_assumptions_avg_real_interest_rate_on_new_borrowing)

    return data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE_NEW_BORROWING.collect(evaluate(formula, data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE_NEW_BORROWING.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE_NEW_BORROWING.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_INTEREST_RATE.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_INTEREST_RATE.cells)
def pv_resfin_pub_assumptions_avg_interest_rate(*, pv_resfin_pub_assumptions_inflation_gdp_deflator: data.Series[float | str | None], pv_resfin_pub_avg_real_interest_rate: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the public assumptions average interest rate for domestic short-term debt by adding GDP-deflator inflation to the average real interest rate.

    Produces the nominal average interest rate series used in public debt realism and financing assumptions, aligned to the old debt service time horizon.

    Args:
        pv_resfin_pub_assumptions_inflation_gdp_deflator: Inflation (GDP deflator) series over catalog coordinates, providing the nominal addend for each time period; entries may be float, str, or None.
        pv_resfin_pub_avg_real_interest_rate: Average real interest rate series over catalog coordinates, indexed by instrument and time period, with the domestic short-term instrument used in the calculation; entries may be float, str, or None.
        input3_old_debt_service: Old debt service input dataclass whose TIME_PERIOD axis defines the output horizon and time alignment for the calculation.

    Returns:
        A data.Series[float | str | None] of average nominal interest rates over the TIME_PERIOD coordinates derived from the old debt service input.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(pv_resfin_pub_avg_real_interest_rate['Domestic short-term', time_period], pv_resfin_pub_assumptions_inflation_gdp_deflator[time_period]))

    return data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_INTEREST_RATE.collect(evaluate(formula, data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_INTEREST_RATE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_INTEREST_RATE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(key=('INSTRUMENT',), domain=None, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_AVG_REAL_INTEREST_RATE_CELLS)
def pv_resfin_pub_assumptions_avg_real_interest_rate(*, in7_resfin_dom_st_interest_effective: float | str) -> float | str:
    """Compute the public residual-financing average real interest rate assumption for domestic short-term debt.

    Map the domestic short-term effective interest rate into the published average real interest rate used in public debt projections.

    Args:
        in7_resfin_dom_st_interest_effective: Domestic short-term debt effective interest rate input, supplied as a scalar float or an Excel error string.

    Returns:
        Published average real interest rate for domestic short-term public debt, returned as a scalar float or an Excel error string.
    """
    try:
        return as_measure(in7_resfin_dom_st_interest_effective)
    except XlError as error:
        return error.code

@publish(data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.schema, cells=data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.cells)
def pv_resfin_pub_avg_real_interest_rate(*, pv_resfin_pub_assumptions_avg_real_interest_rate: float | str, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the public residual-financing average real interest rate series.

    Seeds the Domestic short-term path from the assumptions scalar in the first period and carries the prior-period value forward thereafter.

    Args:
        pv_resfin_pub_assumptions_avg_real_interest_rate: Assumption scalar for the average real interest rate, supplied as a float or string and used for the initial time period.
        input3_old_debt_service: Typed old debt service input series whose TIME_PERIOD axis defines the target coordinate domain and alignment for the computed path.

    Returns:
        A data.Series[float | str | None] over the old debt service TIME_PERIOD domain containing the Domestic short-term average real interest rate path.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 1:
            return as_measure(pv_resfin_pub_assumptions_avg_real_interest_rate)
        return as_measure(pv_resfin_pub_avg_real_interest_rate['Domestic short-term', axis_step(_ax_time_period, time_period, -1)])

    pv_resfin_pub_avg_real_interest_rate = CoordinateReader('pv_resfin_pub_avg_real_interest_rate', data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.collect(((coord, pv_resfin_pub_avg_real_interest_rate[coord]) for coord in data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_PUB_AVG_REAL_INTEREST_RATE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_INFLATION_GDP_DEFLATOR.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_INFLATION_GDP_DEFLATOR.cells)
def pv_resfin_pub_assumptions_inflation_gdp_deflator(*, macro_debt_change_in_gdp_deflator_factor: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Convert the macro-debt GDP deflator inflation factor into a fractional inflation rate for public rescheduling assumptions.

    Scale the percentage GDP-deflator inflation factor down by 100 so the public PV rescheduling assumptions carry it as a decimal rate over the projection years.

    Args:
        macro_debt_change_in_gdp_deflator_factor: Named-axis tensor of GDP-deflator inflation factors expressed in percent, indexed by projection year; each value is divided by 100 to yield a decimal inflation rate, preserving strings and blanks as authored.
        input3_input_3_macro_current_account: Typed record of Input 3 macro current-account assumptions, validated against its schema; it supplies the coordinate framework and macro context but is not read term-by-term in the calculation.
        input3_old_debt_service: Typed record of Input 3 old debt service whose TIME_PERIOD axis defines the projection-year domain over which the converted inflation series is evaluated and collected.

    Returns:
        Named-axis tensor of the decimal GDP-deflator inflation rate, keyed by the projection years taken from the old debt service time axis, retaining float, string, or blank entries as authored.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_div(macro_debt_change_in_gdp_deflator_factor[time_period], 100))

    return data.PV_RESFIN_PUB_ASSUMPTIONS_INFLATION_GDP_DEFLATOR.collect(evaluate(formula, data.PV_RESFIN_PUB_ASSUMPTIONS_INFLATION_GDP_DEFLATOR.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_PUB_ASSUMPTIONS_INFLATION_GDP_DEFLATOR.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_AVERAGE_INTEREST_RATE_ON_DOMESTIC_DEBT.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_AVERAGE_INTEREST_RATE_ON_DOMESTIC_DEBT.cells)
def pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt(*, pv_resfin_pub_assumptions_share_of_marginal_debt: data.Series[float | str | None], pv_resfin_pub_assumptions_domestic_mlt_debt: data.Series[float | str | None], pv_resfin_pub_assumptions_avg_interest_rate: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the average interest rate on domestic debt from marginal debt shares, domestic medium- and long-term debt, and short-term interest rates.

    Derive the projection-year domestic-debt average interest rate used in public-debt residual financing assumptions.

    Args:
        pv_resfin_pub_assumptions_share_of_marginal_debt: Data series of domestic marginal debt shares by maturity bucket over projection years, used as weighting terms and checked for an all-zero share sum.
        pv_resfin_pub_assumptions_domestic_mlt_debt: Data series of domestic medium- and long-term debt by projection year, used in the weighted average and as the fallback value when marginal shares sum to zero.
        pv_resfin_pub_assumptions_avg_interest_rate: Data series of average interest rates on domestic short-term debt by projection year, contributing the short-term component of the weighted average.
        input3_old_debt_service: Typed old debt service input whose TIME_PERIOD axis defines the projection-year grid, validates the schema, and binds evaluation coordinates.

    Returns:
        Data series of average interest rates on domestic debt keyed by projection years from the old debt service time axis, preserving float, string, or blank cells.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((pv_resfin_pub_assumptions_domestic_mlt_debt['Domestic medium and long-term', time_period] if xl_bool(xl_eq(xl_add(pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic medium and long-term'], pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic short-term']), 0)) else xl_add(xl_div(xl_mul(pv_resfin_pub_assumptions_domestic_mlt_debt['Domestic medium and long-term', time_period], pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic medium and long-term']), xl_add(pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic medium and long-term'], pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic short-term'])), xl_div(xl_mul(pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic short-term'], pv_resfin_pub_assumptions_avg_interest_rate['Domestic short-term', time_period]), xl_add(pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic medium and long-term'], pv_resfin_pub_assumptions_share_of_marginal_debt['Domestic short-term'])))))

