@publish(data.PV_RESFIN_PUB_ASSUMPTIONS_EXCHANGE_RATE_PA.schema, cells=data.PV_RESFIN_PUB_ASSUMPTIONS_EXCHANGE_RATE_PA.cells)
def pv_resfin_pub_assumptions_exchange_rate_pa(*, input3_input_3_macro_national_currency_per_u_s_dollar_p_a: data.Input3Input3MacroNationalCurrencyPerUSDollarPA, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Project the public real-sector financing exchange-rate assumption as a time-keyed series.

    Produces the PV_ResFin_pub exchange-rate (per annum) series by resampling the macro national-currency-per-US-dollar path onto the projection-year axis used for public debt service.

    Args:
        input3_input_3_macro_national_currency_per_u_s_dollar_p_a: Typed data series of the Input 3 macro national currency per U.S. dollar exchange rate (per annum) over projected years; supplies the measure values and is validated against the current-account time axis.
        input3_input_3_macro_current_account: Typed data series of the Input 3 macro current account over projected years; its time-period domain is used to bind and validate the exchange-rate series' coordinate alignment.
        input3_old_debt_service: Typed data series of Input 3 old debt service; its TIME_PERIOD axis defines the projection-year positions and required domain for the evaluated output series.

    Returns:
        A typed data series of floats, strings, or nulls keyed by projection years from row 2, holding the projected exchange-rate assumption aligned to the old debt service time axis.
    """
    data.INPUT3_INPUT_3_MACRO_NATIONAL_CURRENCY_PER_U_S_DOLLAR_P_A.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_input_3_macro_national_currency_per_u_s_dollar_p_a)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(input3_input_3_macro_national_currency_per_u_s_dollar_p_a[time_period])

    return data.PV_RESFIN_PUB_ASSUMPTIONS_EXCHANGE_RATE_PA.collect(evaluate(formula, data.PV_RESFIN_PUB_ASSUMPTIONS_EXCHANGE_RATE_PA.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_PUB_ASSUMPTIONS_EXCHANGE_RATE_PA.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_RESFIN_PUB_OUTPUT_NEW_BORROWING_UNDER_THE_EXTERNAL_DSA_IN_USD.schema, cells=data.PV_RESFIN_PUB_OUTPUT_NEW_BORROWING_UNDER_THE_EXTERNAL_DSA_IN_USD.cells)
def pv_resfin_pub_output_new_borrowing_under_the_external_dsa_in_usd(*, dsa_ext_residual_gross_borrowing: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Map external DSA residual gross borrowing into published public residual-financing new-borrowing values by scenario and time period.

    Produces the external-DSA new-borrowing output series by relabeling stress-scenario borrowing paths onto the six public output scenarios.

    Args:
        dsa_ext_residual_gross_borrowing: Typed data series of external DSA residual gross borrowing values indexed over catalog coordinates; source scenarios A1, B1, B5, B6_mkt, B6_nonmkt, and C3 supply the output values.
        input3_old_debt_service: Typed Input 3 old-debt-service bundle whose TIME_PERIOD domain defines the output projection grid and validates the time coordinate.

    Returns:
        Typed data series of new borrowing under the external DSA in USD, indexed by instrument, the six public scenarios, and the TIME_PERIOD grid inherited from old debt service.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Key variables at historical average':
            return as_measure(dsa_ext_residual_gross_borrowing['A1', time_period])
        elif scenario == 'Bounds Test 1: Real GDP Growth Shock':
            return as_measure(dsa_ext_residual_gross_borrowing['B1', time_period])
        elif scenario == 'Bounds Test 5: Exchange Rate Shock':
            return as_measure(dsa_ext_residual_gross_borrowing['B5', time_period])
        elif scenario == 'Bounds Test 6: Combined Shock for Market Access Countries':
            return as_measure(dsa_ext_residual_gross_borrowing['B6_mkt', time_period])
        elif scenario == 'Bounds Test 6: Combined Shock for Non-Market Access Countries':
            return as_measure(dsa_ext_residual_gross_borrowing['B6_nonmkt', time_period])
        return as_measure(dsa_ext_residual_gross_borrowing['C3', time_period])

    return data.PV_RESFIN_PUB_OUTPUT_NEW_BORROWING_UNDER_THE_EXTERNAL_DSA_IN_USD.collect(evaluate(formula, data.PV_RESFIN_PUB_OUTPUT_NEW_BORROWING_UNDER_THE_EXTERNAL_DSA_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_PUB_OUTPUT_NEW_BORROWING_UNDER_THE_EXTERNAL_DSA_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service))

