@publish(data.PV_RESFIN_ADD_INT_COST_MKT_INTEREST_BEYOND_PROJECTION_WINDOW.schema, cells=data.PV_RESFIN_ADD_INT_COST_MKT_INTEREST_BEYOND_PROJECTION_WINDOW.cells)
def pv_resfin_add_int_cost_mkt_interest_beyond_projection_window(*, pv_resfin_add_output_stock_of_new_forex_debt_in_usd: data.Series[float | str | None], pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window: data.Series[float | str | None], pv_resfin_add_int_cost_mkt_avg_nominal_interest_rate_new_borrowing_usd_two_year_average: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes interest cost on new market-access foreign-currency debt beyond the projection window.

    Evaluates the Bounds Test 2 market-access scenario interest cost by multiplying the relevant debt stock or new borrowing output by the two-year average nominal interest rate.

    Args:
        pv_resfin_add_output_stock_of_new_forex_debt_in_usd: A typed data.Series[float | str | None] over catalog coordinates giving the output stock of new foreign-currency debt in USD, used for the initial projection-window boundary period.
        pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window: A typed data.Series[float | str | None] over catalog coordinates giving the stock of new foreign-currency debt carried beyond the projection window, used for subsequent periods.
        pv_resfin_add_int_cost_mkt_avg_nominal_interest_rate_new_borrowing_usd_two_year_average: A typed data.Series[float | str | None] over catalog coordinates giving the two-year average nominal interest rate on new USD borrowing for the market-access scenario.
        input3_old_debt_service: A typed data.Input3OldDebtService dataclass providing old debt-service data and the TIME_PERIOD axis used to align projection-period coordinates.

    Returns:
        A data.Series[float | str | None] over instrument, scenario, and time-period coordinates containing the computed interest cost beyond the projection window for external PPG medium- and long-term debt under the specified market-access bounds test.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, scenario: str, time_period: int) -> float | str | None:
        if time_period == 26:
            return as_measure(xl_mul(pv_resfin_add_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', input3_old_debt_service.domain.axis('TIME_PERIOD').keys[data.TIME_PERIOD_AXIS.position(time_period)]], pv_resfin_add_int_cost_mkt_avg_nominal_interest_rate_new_borrowing_usd_two_year_average['Bounds Test 2: Primary Balance Shock for Market Access Countries']))
        return as_measure(xl_mul(pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period - 1], pv_resfin_add_int_cost_mkt_avg_nominal_interest_rate_new_borrowing_usd_two_year_average['Bounds Test 2: Primary Balance Shock for Market Access Countries']))

    return data.PV_RESFIN_ADD_INT_COST_MKT_INTEREST_BEYOND_PROJECTION_WINDOW.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_INTEREST_BEYOND_PROJECTION_WINDOW.required))

@publish(data.PV_RESFIN_ADD_ASSUMPTIONS_DEVIATION_IN_PB_PPT.schema, cells=data.PV_RESFIN_ADD_ASSUMPTIONS_DEVIATION_IN_PB_PPT.cells)
def pv_resfin_add_assumptions_deviation_in_pb_ppt(*, dsa_pub_primary_deficit: data.Series[float | str | None], baseline_pub_primary_deficit: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Derive the scenario-level deviation in primary balance (ppt) for the PV residual-financing assumptions block.

    Subtract the baseline public primary deficit from each Bounds Test 2 and Bounds Test 6 shock deficit and collect the results on the catalog TIME_PERIOD domain.

    Args:
        dsa_pub_primary_deficit: Scenario-level DSA public primary deficit series over catalog coordinates, indexed by scenario bucket (B2/B6 market and non-market) and TIME_PERIOD.
        baseline_pub_primary_deficit: Baseline public primary deficit series over the catalog TIME_PERIOD axis, used as the subtrahend for every scenario.
        input3_input_3_macro_current_account: Input 3 macroeconomic current-account series from the typed catalog collection, schema-validated before evaluation and unused by the formula body.
        input3_old_debt_service: Input 3 old debt service series whose TIME_PERIOD domain axis defines the output time grid.

    Returns:
        A typed data.Series[float | str | None] holding the deviation in primary balance in percentage points for each scenario and TIME_PERIOD, on the TIME_PERIOD domain inherited from the old debt service series.
    """
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Bounds Test 2: Primary Balance Shock for Market Access Countries':
            return as_measure(xl_sub(dsa_pub_primary_deficit['B2_mkt', time_period], baseline_pub_primary_deficit[time_period]))
        elif scenario == 'Bounds Test 2: Primary Balance Shock for non-market access countries':
            return as_measure(xl_sub(dsa_pub_primary_deficit['B2_nonmkt', time_period], baseline_pub_primary_deficit[time_period]))
        elif scenario == 'Bounds Test 6: Combined Shock for Market Access Countries':
            return as_measure(xl_sub(dsa_pub_primary_deficit['B6_mkt', time_period], baseline_pub_primary_deficit[time_period]))
        return as_measure(xl_sub(dsa_pub_primary_deficit['B6_nonmkt', time_period], baseline_pub_primary_deficit[time_period]))

    return data.PV_RESFIN_ADD_ASSUMPTIONS_DEVIATION_IN_PB_PPT.collect(evaluate(formula, data.PV_RESFIN_ADD_ASSUMPTIONS_DEVIATION_IN_PB_PPT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_ADD_ASSUMPTIONS_DEVIATION_IN_PB_PPT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_RESFIN_ADD_INT_COST_MKT_AMORTIZATION_BEYOND_PROJECTION_WINDOW.schema, cells=data.PV_RESFIN_ADD_INT_COST_MKT_AMORTIZATION_BEYOND_PROJECTION_WINDOW.cells)
def pv_resfin_add_int_cost_mkt_amortization_beyond_projection_window(*, pv_resfin_add_assumptions_avg_maturity_incl_grace_period: data.Series[float | str | None], pv_resfin_add_assumptions_avg_grace_period: data.Series[float | str | None], pv_resfin_add_int_cost_mkt_cumulative_selected_t_g_0_beyond_projection_window: data.Series[float | str | None], pv_resfin_add_int_cost_mkt_cumulative_selected_t_m_condition_beyond_projection_window: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Derives market-access amortization falling beyond the projection window from the gap between two cumulative interest-cost selections divided by the net of average maturity over grace period.

    Produces the residual-financing add-on amortization series for external PPG medium- and long-term debt under the Bounds Test 2 primary-balance shock.

    Args:
        pv_resfin_add_assumptions_avg_maturity_incl_grace_period: Assumption series of average maturity including the grace period, in years, for external MLT debt.
        pv_resfin_add_assumptions_avg_grace_period: Assumption series of average grace period, in years, for external MLT debt.
        pv_resfin_add_int_cost_mkt_cumulative_selected_t_g_0_beyond_projection_window: Cumulative market interest-cost selection under the T-G-0 condition carried beyond the projection window for external PPG medium- and long-term debt.
        pv_resfin_add_int_cost_mkt_cumulative_selected_t_m_condition_beyond_projection_window: Cumulative market interest-cost selection under the T-M condition carried beyond the projection window for external PPG medium- and long-term debt.

    Returns:
        A data.Series[float | str | None] indexed over catalog coordinates holding the computed amortization beyond the projection window, with non-numeric results preserved as strings or blanks.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_sub(pv_resfin_add_int_cost_mkt_cumulative_selected_t_g_0_beyond_projection_window['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period], pv_resfin_add_int_cost_mkt_cumulative_selected_t_m_condition_beyond_projection_window['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), xl_sub(pv_resfin_add_assumptions_avg_maturity_incl_grace_period['External MLT debt'], pv_resfin_add_assumptions_avg_grace_period['External MLT debt'])))

    return data.PV_RESFIN_ADD_INT_COST_MKT_AMORTIZATION_BEYOND_PROJECTION_WINDOW.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_AMORTIZATION_BEYOND_PROJECTION_WINDOW.required))

@publish(data.PV_RESFIN_ADD_INT_COST_MKT_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_SHOCK_YEARS.schema, cells=data.PV_RESFIN_ADD_INT_COST_MKT_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_SHOCK_YEARS.cells)
def pv_resfin_add_int_cost_mkt_avg_nominal_interest_rate_new_borrowing_usd_shock_years(*, pv_resfin_add_assumptions_deviation_in_pb_ppt: data.Series[float | str | None], pv_resfin_add_assumptions_additional_borrowing_costs_external: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute shock-year average nominal USD interest rates on new external borrowing.

    Derive scenario-specific new-borrowing interest rates by applying primary-balance shock deviations to external borrowing-cost assumptions and capping them against the alternative-cost rate.

    Args:
        pv_resfin_add_assumptions_deviation_in_pb_ppt: Primary-balance assumption deviation series in percentage points, indexed by scenario and time period.
        pv_resfin_add_assumptions_additional_borrowing_costs_external: External additional borrowing-cost assumptions series containing standard and alternative cost components used to scale shock-year rates.
        input3_old_debt_service: Old debt service input series whose TIME_PERIOD coordinate axis defines the projection-year domain for the result.

    Returns:
        A data series of average nominal interest rates on new external borrowing in USD for shock years over instrument, scenario, and time period coordinates, with values that may be floats, strings, or nulls as propagated from the source calculations.
    """
    data.PV_RESFIN_ADD_ASSUMPTIONS_ADDITIONAL_BORROWING_COSTS_EXTERNAL.schema.validate(pv_resfin_add_assumptions_additional_borrowing_costs_external)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Bounds Test 2: Primary Balance Shock for Market Access Countries':
            return as_measure(xl_min(xl_div(pv_resfin_add_assumptions_additional_borrowing_costs_external['alternative'], 10000), xl_div(xl_mul(pv_resfin_add_assumptions_additional_borrowing_costs_external['standard'], pv_resfin_add_assumptions_deviation_in_pb_ppt['Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]), 100)))
        return as_measure(xl_min(xl_div(pv_resfin_add_assumptions_additional_borrowing_costs_external['alternative'], 10000), xl_div(xl_mul(pv_resfin_add_assumptions_additional_borrowing_costs_external['standard'], pv_resfin_add_assumptions_deviation_in_pb_ppt['Bounds Test 6: Combined Shock for Market Access Countries', time_period]), 100)))

    return data.PV_RESFIN_ADD_INT_COST_MKT_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_SHOCK_YEARS.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_SHOCK_YEARS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_ADD_INT_COST_MKT_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_SHOCK_YEARS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_RESFIN_ADD_OUTPUT_T_G_0.schema, cells=data.PV_RESFIN_ADD_OUTPUT_T_G_0.cells)
def pv_resfin_add_output_t_g_0(*, pv_resfin_add_assumptions_avg_grace_period: data.Series[float | str | None], pv_resfin_add_opening_stock_period_seed: int | str, pv_resfin_add_projection_years_period_index: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute the `t-g>0` grace-period countdown series on `pv_resfin_add.residual_output`.

    Derive, for each instrument/scenario/year cell, how many years have elapsed beyond the assumed average grace period, flooring at zero while the grace window is still open.

    Args:
        pv_resfin_add_assumptions_avg_grace_period: Named-axis series of average grace-period assumptions over instrument labels (`External MLT debt`, `Domestic MLT debt`), consumed through the instrument remapping map and compared against the seed or period index; ragged year widths are expected.
        pv_resfin_add_opening_stock_period_seed: Scalar opening-stock period seed used for the first `TIME_PERIOD` position, subtracted from the matching average grace period to produce the initial countdown value.
        pv_resfin_add_projection_years_period_index: Named-axis series of projection-year period indices, read at offset `time_period - 2024` for non-initial years and then reduced by the instrument's average grace period.
        input3_old_debt_service: Input 3 old-debt-service block supplying the `TIME_PERIOD` axis, instrument and scenario coordinates, and the domain the formula is evaluated over.

    Returns:
        A `data.Series[int | str | None]` on the `PV_RESFIN_ADD_OUTPUT_T_G_0` domain (instrument × scenario × `TIME_PERIOD`) holding integer years-past-grace counts, or 0 where the grace period has not yet been exhausted.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, scenario: str, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        INSTRUMENT_TO_PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD = {'External PPG medium and long-term': 'External MLT debt', 'Domestic medium and long-term': 'Domestic MLT debt'}
        if _p_time_period == 0:
            return as_measure((xl_sub(pv_resfin_add_opening_stock_period_seed, pv_resfin_add_assumptions_avg_grace_period[INSTRUMENT_TO_PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD[instrument]]) if xl_bool(xl_gt(xl_sub(pv_resfin_add_opening_stock_period_seed, pv_resfin_add_assumptions_avg_grace_period[INSTRUMENT_TO_PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD[instrument]]), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_resfin_add_projection_years_period_index[time_period - 2024], pv_resfin_add_assumptions_avg_grace_period[INSTRUMENT_TO_PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD[instrument]]) if xl_bool(xl_gt(xl_sub(pv_resfin_add_projection_years_period_index[time_period - 2024], pv_resfin_add_assumptions_avg_grace_period[INSTRUMENT_TO_PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD[instrument]]), 0)) else 0), 'int')

    return data.PV_RESFIN_ADD_OUTPUT_T_G_0.collect(evaluate(formula, data.PV_RESFIN_ADD_OUTPUT_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_RESFIN_ADD_OUTPUT_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_RESFIN_ADD_INT_COST_MKT_T_G_0_BEYOND_PROJECTION_WINDOW.schema, cells=data.PV_RESFIN_ADD_INT_COST_MKT_T_G_0_BEYOND_PROJECTION_WINDOW.cells)
def pv_resfin_add_int_cost_mkt_t_g_0_beyond_projection_window(*, pv_resfin_add_assumptions_avg_grace_period: data.Series[float | str | None], pv_resfin_add_projection_years_period_index: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute integer years beyond the projection window for external MLT market-access residual financing add-on cost.

    Supports LIC-DSF residual financing add-on calculations by measuring how far projection-year indices exceed assumed average grace periods for external PPG medium- and long-term debt under the Bounds Test 2 primary-balance-shock scenario.

    Args:
        pv_resfin_add_assumptions_avg_grace_period: data.Series over catalog coordinates holding average grace period assumptions for external medium- and long-term debt, with float, string, or None entries.
        pv_resfin_add_projection_years_period_index: data.Series over catalog coordinates holding projection-year period indices, with integer, string, or None entries.

    Returns:
        data.Series over catalog coordinates of integer, string, or None values giving the positive difference between each projection-year period index and the external MLT average grace period, or zero when that difference is not positive.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> int | str | None:
        return as_measure((xl_sub(pv_resfin_add_projection_years_period_index[time_period], pv_resfin_add_assumptions_avg_grace_period['External MLT debt']) if xl_bool(xl_gt(xl_sub(pv_resfin_add_projection_years_period_index[time_period], pv_resfin_add_assumptions_avg_grace_period['External MLT debt']), 0)) else 0), 'int')

    return data.PV_RESFIN_ADD_INT_COST_MKT_T_G_0_BEYOND_PROJECTION_WINDOW.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_T_G_0_BEYOND_PROJECTION_WINDOW.required))

@publish(data.PV_RESFIN_ADD_INT_COST_MKT_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_TWO_YEAR_AVERAGE.schema, cells=data.PV_RESFIN_ADD_INT_COST_MKT_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_TWO_YEAR_AVERAGE.cells)
def pv_resfin_add_int_cost_mkt_avg_nominal_interest_rate_new_borrowing_usd_two_year_average(*, pv_resfin_add_int_cost_mkt_avg_nominal_interest_rate_new_borrowing_usd_shock_years: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the two-year average nominal interest rate on new USD borrowing for each market-access scenario.

    Collapses the shock-year interest-rate series to a per-scenario two-year mean over the TIME_PERIOD window anchored on the old debt service domain, feeding the residual-financing interest-cost block.

    Args:
        pv_resfin_add_int_cost_mkt_avg_nominal_interest_rate_new_borrowing_usd_shock_years: Typed `data.Series[float | str | None]` over catalog coordinates holding the shock-year average nominal interest rate on new borrowing in USD, restricted here to the External PPG medium and long-term instrument across the market-access scenarios.
        input3_old_debt_service: `data.Input3OldDebtService` dataclass of series supplying the authoritative TIME_PERIOD axis whose second and third keys define the two-year span averaged per scenario.

    Returns:
        A `data.Series[float | str | None]` of the two-year average nominal interest rate on new USD borrowing, indexed by scenario along the required coordinates, with `None` where the underlying shock-year values are missing or non-numeric.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str) -> float | str | None:
        return as_measure(xl_average(view(pv_resfin_add_int_cost_mkt_avg_nominal_interest_rate_new_borrowing_usd_shock_years, rows={'INSTRUMENT': ('External PPG medium and long-term',), 'SCENARIO': (scenario,)}, cols={'TIME_PERIOD': span(input3_old_debt_service.domain.axis('TIME_PERIOD'), input3_old_debt_service.domain.axis('TIME_PERIOD').keys[1], input3_old_debt_service.domain.axis('TIME_PERIOD').keys[2])})))

    return data.PV_RESFIN_ADD_INT_COST_MKT_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_TWO_YEAR_AVERAGE.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_AVG_NOMINAL_INTEREST_RATE_NEW_BORROWING_USD_TWO_YEAR_AVERAGE.required))

