    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(xl_add(xl_add(xl_add(pv_baseline_com_output_pv_of_debt['Eurobond', time_period], pv_baseline_com_output_pv_of_debt['Commecial Bank', time_period]), pv_baseline_com_output_pv_of_debt['COM3', time_period]), pv_baseline_com_output_pv_of_debt['COM4', time_period]), pv_baseline_com_output_pv_of_debt['COM5', time_period]))

    return data.PV_BASELINE_COM_PV_DEBT.collect(evaluate(formula, data.PV_BASELINE_COM_PV_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASELINE_COM_PV_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

