@publish(data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.schema, cells=data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.cells)
def pv_baseline_com_discount_debt_stock(*, pv_baseline_com_opening_percent_of_face: data.Series[int | str | None], pv_baseline_com_discount_amortization: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the discounted baseline commercial debt stock by instrument and time period.

    Derives each period's debt stock by rolling forward the prior-period stock and subtracting scheduled amortization, using opening percent-of-face for the first period.

    Args:
        pv_baseline_com_opening_percent_of_face: Opening percent-of-face series over instrument coordinates, providing the initial balance used in the first projection period.
        pv_baseline_com_discount_amortization: Discount amortization series over instrument and time-period coordinates, subtracted from the opening balance or prior-period debt stock.
        input3_old_debt_service: Input 3 old debt service object whose TIME_PERIOD axis defines the projection grid and validates the calculation domain.

    Returns:
        A data.Series[float | str | None] of discounted commercial debt stock over instrument and time-period coordinates.
    """
    data.PV_BASELINE_COM_OPENING_PERCENT_OF_FACE.schema.validate(pv_baseline_com_opening_percent_of_face)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond' and _p_time_period == 0:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Eurobond' and _p_time_period == 1:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, axis_step(_ax_time_period, time_period, -1)], pv_baseline_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and _p_time_period == 0:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'Commecial Bank' and _p_time_period == 1:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, axis_step(_ax_time_period, time_period, -1)], pv_baseline_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and _p_time_period == 0:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM3' and _p_time_period == 1:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, axis_step(_ax_time_period, time_period, -1)], pv_baseline_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM4' and _p_time_period == 0:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['COM4', time_period]))
        elif instrument == 'COM4' and _p_time_period == 1:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, axis_step(_ax_time_period, time_period, -1)], pv_baseline_com_discount_amortization['COM4', time_period]))
        elif instrument == 'COM5' and _p_time_period == 0:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['COM5', time_period]))
        elif instrument == 'COM5' and _p_time_period == 1:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, axis_step(_ax_time_period, time_period, -1)], pv_baseline_com_discount_amortization['COM5', time_period]))
        elif instrument == 'Eurobond' and _p_time_period >= 2:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['Eurobond', axis_step(_ax_time_period, time_period, -1)], pv_baseline_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and _p_time_period >= 2:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['Commecial Bank', axis_step(_ax_time_period, time_period, -1)], pv_baseline_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and _p_time_period >= 2:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['COM3', axis_step(_ax_time_period, time_period, -1)], pv_baseline_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM4' and _p_time_period >= 2:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['COM4', axis_step(_ax_time_period, time_period, -1)], pv_baseline_com_discount_amortization['COM4', time_period]))
        return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['COM5', axis_step(_ax_time_period, time_period, -1)], pv_baseline_com_discount_amortization['COM5', time_period]))

    pv_baseline_com_discount_debt_stock = CoordinateReader('pv_baseline_com_discount_debt_stock', data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.collect(((coord, pv_baseline_com_discount_debt_stock[coord]) for coord in data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.required.bind(TIME_PERIOD=input3_old_debt_service))

