@publish(data.PV_BASELINE_COM_DISCOUNT_INTEREST.schema, cells=data.PV_BASELINE_COM_DISCOUNT_INTEREST.cells)
def pv_baseline_com_discount_interest(*, pv_baseline_com_discount_debt_stock: data.Series[float | str | None], pv_baseline_com_discount_interest_rate: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute baseline commercial discount interest by instrument.

    Multiplies each instrument's interest rate by its prior-period debt stock and collects the result over the Input 3 time axis.

    Args:
        pv_baseline_com_discount_debt_stock: Named-axis debt-stock series over instruments and time periods, whose prior-period values provide the interest base for each instrument.
        pv_baseline_com_discount_interest_rate: Named-axis interest-rate series over instruments and time periods, aligned to the same instrument coordinates as the debt-stock series.
        input3_old_debt_service: Validated Input 3 old-debt-service dataclass whose TIME_PERIOD axis supplies the target time grid for the collected interest series.

    Returns:
        A data.Series[float | str | None] of baseline commercial discount interest indexed by instrument and time period, preserving blank or string values through the arithmetic.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['Eurobond'], pv_baseline_com_discount_debt_stock['Eurobond', axis_step(_ax_time_period, time_period, -1)]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['Commecial Bank'], pv_baseline_com_discount_debt_stock['Commecial Bank', axis_step(_ax_time_period, time_period, -1)]))
        elif instrument == 'COM3':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM3'], pv_baseline_com_discount_debt_stock['COM3', axis_step(_ax_time_period, time_period, -1)]))
        elif instrument == 'COM4':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM4'], pv_baseline_com_discount_debt_stock['COM4', axis_step(_ax_time_period, time_period, -1)]))
        return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM5'], pv_baseline_com_discount_debt_stock['COM5', axis_step(_ax_time_period, time_period, -1)]))

    return data.PV_BASELINE_COM_DISCOUNT_INTEREST.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_INTEREST.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASELINE_COM_DISCOUNT_INTEREST.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.schema, cells=data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.cells)
def pv_baseline_com_discount_total_debt_service(*, pv_baseline_com_discount_amortization: data.Series[float | str | None], pv_baseline_com_discount_interest: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute total debt service by adding baseline commercial discount-schedule amortization and interest for each instrument.

    Supports PV baseline discount-schedule construction by deriving instrument-level total debt service over the Input 3 time grid.

    Args:
        pv_baseline_com_discount_amortization: Amortization series over catalog instrument and time coordinates for the baseline commercial discount schedule, with numeric, string, or blank values.
        pv_baseline_com_discount_interest: Interest series over the same instrument and time coordinates, added to amortization to form total debt service.
        input3_old_debt_service: Input 3 old debt service data used to validate and bind the shared TIME_PERIOD coordinate domain for the calculation.

    Returns:
        A typed data.Series[float | str | None] of total debt service over instrument and time coordinates, with numeric measures, strings, or blank values.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['Eurobond', time_period], pv_baseline_com_discount_interest['Eurobond', time_period]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['Commecial Bank', time_period], pv_baseline_com_discount_interest['Commecial Bank', time_period]))
        elif instrument == 'COM3':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['COM3', time_period], pv_baseline_com_discount_interest['COM3', time_period]))
        elif instrument == 'COM4':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['COM4', time_period], pv_baseline_com_discount_interest['COM4', time_period]))
        return as_measure(xl_add(pv_baseline_com_discount_amortization['COM5', time_period], pv_baseline_com_discount_interest['COM5', time_period]))

    return data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.schema, cells=data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.cells)
def pv_baseline_com_discount_pv_of_debt(*, pv_baseline_com_discount_debt_stock: data.Series[float | str | None], pv_baseline_com_discount_interest_rate: data.Series[float | str | None], pv_baseline_com_discount_discount_rate: data.Series[float | str | None], pv_baseline_com_discount_total_debt_service: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the baseline commercial discount present value of debt by instrument and time period.

    Discount baseline commercial total debt service to present value unless the instrument's interest rate meets or exceeds its discount rate, in which case the debt stock is carried through.

    Args:
        pv_baseline_com_discount_debt_stock: Baseline commercial debt stock as a typed data.Series[float | str | None] over catalog instrument coordinates (COM3, COM4, COM5, Commercial Bank, Eurobond) and TIME_PERIOD.
        pv_baseline_com_discount_interest_rate: Baseline commercial interest rate as a typed data.Series[float | str | None] over instrument and TIME_PERIOD coordinates, compared per instrument with the discount rate.
        pv_baseline_com_discount_discount_rate: Baseline commercial discount rate as a typed data.Series[float | str | None] over instrument and TIME_PERIOD coordinates, used to discount debt service for instruments whose interest rate is below it.
        pv_baseline_com_discount_total_debt_service: Baseline commercial total debt service as a typed data.Series[float | str | None] over instrument and TIME_PERIOD coordinates, discounted over the forward horizon by instrument.
        input3_old_debt_service: Input 3 old debt service as a typed data.Input3OldDebtService series, validated against its schema and used for the TIME_PERIOD axis that defines the output domain.

    Returns:
        A typed data.Series[float | str | None] aligned to the Input3OldDebtService TIME_PERIOD domain, containing present value of debt by instrument and time period.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((pv_baseline_com_discount_debt_stock[instrument, time_period] if xl_bool(xl_ge(pv_baseline_com_discount_interest_rate[instrument], pv_baseline_com_discount_discount_rate[instrument])) else xl_npv(pv_baseline_com_discount_discount_rate[instrument], view(pv_baseline_com_discount_total_debt_service, rows=(instrument,), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, 1), _ax_time_period.keys[39])))))

    return data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASELINE_COM_DISCOUNT_T_G_0.schema, cells=data.PV_BASELINE_COM_DISCOUNT_T_G_0.cells)
def pv_baseline_com_discount_t_g_0(*, pv_baseline_com_discount_period: data.Series[int | str | None], pv_baseline_com_grace: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute the positive discount-period spread over grace for each baseline commercial instrument.

    Derive per-instrument `max(discount_period - grace, 0)` values used by the baseline commercial discount schedule, keyed to the Input 3 old-debt-service time grid.

    Args:
        pv_baseline_com_discount_period: Per-instrument, per-period discount periods as a `data.Series[int | str | None]` over catalog coordinates; values are compared with the matching grace-period series.
        pv_baseline_com_grace: Per-instrument grace periods as a `data.Series[int | str | None]`, broadcast across periods and subtracted from the corresponding discount period.
        input3_old_debt_service: Input 3 old debt service series as a `data.Input3OldDebtService`, whose `TIME_PERIOD` axis supplies the output time coordinate and binding domain.

    Returns:
        A `data.Series[int | str | None]` over instrument and time period giving the discount period minus grace when positive and zero otherwise, one value per baseline commercial instrument.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure((xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_grace['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_grace['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank':
            return as_measure((xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_grace['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_grace['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3':
            return as_measure((xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_grace['COM3']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_grace['COM3']), 0)) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_grace['COM4']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_grace['COM4']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_grace['COM5']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_grace['COM5']), 0)) else 0), 'int')

    return data.PV_BASELINE_COM_DISCOUNT_T_G_0.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASELINE_COM_DISCOUNT_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service))

