@publish(data.PV_BASELINE_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.schema, cells=data.PV_BASELINE_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.cells)
def pv_baseline_com_output_total_debt_service_in_usd(*, pv_baseline_com_output_interest: data.Series[float | str | None], pv_baseline_com_output_amortization: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes total debt service in USD for the baseline commercial-loan output.

    Sums interest and amortization per instrument over the catalog time grid, with the output period axis taken from Input 3 old debt service.

    Args:
        pv_baseline_com_output_interest: Typed data series of interest amounts in USD per instrument over catalog time periods, with values as floats, strings, or None.
        pv_baseline_com_output_amortization: Typed data series of amortization amounts in USD per instrument over catalog time periods, with values as floats, strings, or None.
        input3_old_debt_service: Typed Input 3 old debt service series whose TIME_PERIOD axis defines the instrument/time grid over which the result is evaluated.

    Returns:
        Typed data series of total debt service in USD per instrument and time period, with float, string, or None values.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure(xl_add(pv_baseline_com_output_interest['Eurobond', time_period], pv_baseline_com_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_add(pv_baseline_com_output_interest['Commecial Bank', time_period], pv_baseline_com_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3':
            return as_measure(xl_add(pv_baseline_com_output_interest['COM3', time_period], pv_baseline_com_output_amortization['COM3', time_period]))
        elif instrument == 'COM4':
            return as_measure(xl_add(pv_baseline_com_output_interest['COM4', time_period], pv_baseline_com_output_amortization['COM4', time_period]))
        return as_measure(xl_add(pv_baseline_com_output_interest['COM5', time_period], pv_baseline_com_output_amortization['COM5', time_period]))

    return data.PV_BASELINE_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.collect(evaluate(formula, data.PV_BASELINE_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASELINE_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASELINE_COM_OUTPUT_INTEREST.schema, cells=data.PV_BASELINE_COM_OUTPUT_INTEREST.cells)
def pv_baseline_com_output_interest(*, pv_baseline_com_discount_interest_rate: data.Series[float | str | None], pv_baseline_com_output_stock_of_new_forex_debt_in_usd: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute baseline commercial interest output by instrument.

    Multiplies each instrument's discount interest rate by its prior-period stock of new forex debt to produce baseline interest projections.

    Args:
        pv_baseline_com_discount_interest_rate: Named-axis series of discount interest rates over catalog instruments (COM3, COM4, COM5, Commecial Bank, Eurobond), with scalar float, str, or None cells.
        pv_baseline_com_output_stock_of_new_forex_debt_in_usd: Named-axis series of the stock of new forex debt in USD by instrument and TIME_PERIOD; the value from the preceding period is used in each multiplication.
        input3_old_debt_service: Input3 old-debt-service series providing the TIME_PERIOD axis and domain used to align the projection grid.

    Returns:
        A data.Series of float, str, or None holding computed baseline commercial interest by instrument and TIME_PERIOD.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['Eurobond'], pv_baseline_com_output_stock_of_new_forex_debt_in_usd['Eurobond', axis_step(_ax_time_period, time_period, -1)]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['Commecial Bank'], pv_baseline_com_output_stock_of_new_forex_debt_in_usd['Commecial Bank', axis_step(_ax_time_period, time_period, -1)]))
        elif instrument == 'COM3':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM3'], pv_baseline_com_output_stock_of_new_forex_debt_in_usd['COM3', axis_step(_ax_time_period, time_period, -1)]))
        elif instrument == 'COM4':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM4'], pv_baseline_com_output_stock_of_new_forex_debt_in_usd['COM4', axis_step(_ax_time_period, time_period, -1)]))
        return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM5'], pv_baseline_com_output_stock_of_new_forex_debt_in_usd['COM5', axis_step(_ax_time_period, time_period, -1)]))

    return data.PV_BASELINE_COM_OUTPUT_INTEREST.collect(evaluate(formula, data.PV_BASELINE_COM_OUTPUT_INTEREST.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASELINE_COM_OUTPUT_INTEREST.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_BASELINE_COM_OUTPUT_AMORTIZATION.schema, cells=data.PV_BASELINE_COM_OUTPUT_AMORTIZATION.cells)
def pv_baseline_com_output_amortization(*, pv_baseline_com_grace: data.Series[int | str | None], pv_baseline_com_maturity: data.Series[int | str | None], pv_baseline_com_discount_cumulative_selected_by_t_g_0: data.Series[float | str | None], pv_baseline_com_discount_cumulative_selected_by_t_m_condition: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute baseline commercial amortization output per instrument and time period.

    Derive amortization amounts by dividing cumulative discount differentials by each instrument's maturity-less-grace term.

    Args:
        pv_baseline_com_grace: Grace period by instrument, as a named-axis series of integers, strings, or None over catalog coordinates.
        pv_baseline_com_maturity: Maturity by instrument, as a named-axis series of integers, strings, or None over catalog coordinates.
        pv_baseline_com_discount_cumulative_selected_by_t_g_0: Cumulative discount factor selected by the g_0 condition, as a named-axis series of floats, strings, or None indexed by instrument and time period.
        pv_baseline_com_discount_cumulative_selected_by_t_m_condition: Cumulative discount factor selected by the m condition, as a named-axis series of floats, strings, or None indexed by instrument and time period.
        input3_old_debt_service: Old debt service input bundle whose time-period axis defines the evaluation grid and instrument coordinates.

    Returns:
        Named-axis series of amortization values, typed as float, string, or None, over commercial instruments and time periods.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure(xl_div(xl_sub(pv_baseline_com_discount_cumulative_selected_by_t_g_0['Eurobond', time_period], pv_baseline_com_discount_cumulative_selected_by_t_m_condition['Eurobond', time_period]), xl_sub(pv_baseline_com_maturity['Eurobond'], pv_baseline_com_grace['Eurobond'])))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_div(xl_sub(pv_baseline_com_discount_cumulative_selected_by_t_g_0['Commecial Bank', time_period], pv_baseline_com_discount_cumulative_selected_by_t_m_condition['Commecial Bank', time_period]), xl_sub(pv_baseline_com_maturity['Commecial Bank'], pv_baseline_com_grace['Commecial Bank'])))
        elif instrument == 'COM3':
            return as_measure(xl_div(xl_sub(pv_baseline_com_discount_cumulative_selected_by_t_g_0['COM3', time_period], pv_baseline_com_discount_cumulative_selected_by_t_m_condition['COM3', time_period]), xl_sub(pv_baseline_com_maturity['COM3'], pv_baseline_com_grace['COM3'])))
        elif instrument == 'COM4':
            return as_measure(xl_div(xl_sub(pv_baseline_com_discount_cumulative_selected_by_t_g_0['COM4', time_period], pv_baseline_com_discount_cumulative_selected_by_t_m_condition['COM4', time_period]), xl_sub(pv_baseline_com_maturity['COM4'], pv_baseline_com_grace['COM4'])))
        return as_measure(xl_div(xl_sub(pv_baseline_com_discount_cumulative_selected_by_t_g_0['COM5', time_period], pv_baseline_com_discount_cumulative_selected_by_t_m_condition['COM5', time_period]), xl_sub(pv_baseline_com_maturity['COM5'], pv_baseline_com_grace['COM5'])))

    return data.PV_BASELINE_COM_OUTPUT_AMORTIZATION.collect(evaluate(formula, data.PV_BASELINE_COM_OUTPUT_AMORTIZATION.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_BASELINE_COM_OUTPUT_AMORTIZATION.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(key=(), domain=None, cells=data.PV_STRESS_COM_ASSUMPTIONS_INCREASE_IN_EXTERNAL_BORROWING_COSTS_CELLS)
def pv_stress_com_assumptions_increase_in_external_borrowing_costs(*, c4_market_path_us_gdp_deflator: int | str) -> float | str:
    """Compute the PV_stress_com increase in external borrowing costs from the market-path U.S. GDP deflator scalar.

    Resolves the single-cell external borrowing cost stress assumption for PV_stress_com formulas.

    Args:
        c4_market_path_us_gdp_deflator: Scalar int or str giving the market-path U.S. GDP deflator value or coordinate used by the external borrowing cost stress formula.

    Returns:
        The increase in external borrowing costs as a float, or an Excel error code string if the input cannot be measured.
    """
    try:
        return as_measure(c4_market_path_us_gdp_deflator)
    except XlError as error:
        return error.code

@publish(data.PV_STRESS_COM_PV_DEBT.schema, cells=data.PV_STRESS_COM_PV_DEBT.cells)
def pv_stress_com_pv_debt(*, pv_stress_com_output_pv_of_debt: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Sum the PV-of-debt components across commercial instruments to build the PV Stress commercial PV of debt series.

    Aggregates the Eurobond, commercial bank, and COM3–COM5 PV-of-debt entries into a single period-indexed total for the PV Stress commercial calculation.

    Args:
        pv_stress_com_output_pv_of_debt: Named-axis `data.Series` of PV of debt on `pv_stress_com.totals`, indexed by instrument and `TIME_PERIOD`, supplying the commercial instrument components that are summed (Eurobond, commecial bank, and COM3–COM5) as scalar values per coordinate cell.
        input3_old_debt_service: Typed `data.Input3OldDebtService` bundle whose `TIME_PERIOD` axis scopes the output and supplies the bound projection grid used to align the evaluated result.

    Returns:
        `data.Series[float | str | None]` named `PV_STRESS_COM_PV_DEBT` over `TIME_PERIOD`, holding the per-period sum of the commercial PV-of-debt components for the bound years.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(xl_add(xl_add(xl_add(pv_stress_com_output_pv_of_debt['Eurobond', time_period], pv_stress_com_output_pv_of_debt['Commecial Bank', time_period]), pv_stress_com_output_pv_of_debt['COM3', time_period]), pv_stress_com_output_pv_of_debt['COM4', time_period]), pv_stress_com_output_pv_of_debt['COM5', time_period]))

    return data.PV_STRESS_COM_PV_DEBT.collect(evaluate(formula, data.PV_STRESS_COM_PV_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_PV_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_COM_TOTAL_DEBT_SERVICE.schema, cells=data.PV_STRESS_COM_TOTAL_DEBT_SERVICE.cells)
def pv_stress_com_total_debt_service(*, pv_stress_com_output_total_debt_service_in_usd: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Sums the commercial total-debt-service components (Eurobond, Commercial Bank, COM3, COM4, COM5) into the PV stress commercial total debt service series.

    Aggregates the per-instrument total debt service outputs on `pv_stress_com.totals` into a single lifted total commercial series aligned to the Input 3 time grid.

    Args:
        pv_stress_com_output_total_debt_service_in_usd: Per-instrument total debt service series (in USD) over catalog coordinates; the Eurobond, Commercial Bank, COM3, COM4, and COM5 instrument rows are added for each time period.
        input3_old_debt_service: `data.Input3OldDebtService` series whose `TIME_PERIOD` axis domain defines the projection grid the summed total debt service series is evaluated over.

    Returns:
        The `PV_STRESS_COM_TOTAL_DEBT_SERVICE` series of floats (or blank/string passthroughs), indexed by the same time periods as the Input 3 domain.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(xl_add(xl_add(xl_add(pv_stress_com_output_total_debt_service_in_usd['Eurobond', time_period], pv_stress_com_output_total_debt_service_in_usd['Commecial Bank', time_period]), pv_stress_com_output_total_debt_service_in_usd['COM3', time_period]), pv_stress_com_output_total_debt_service_in_usd['COM4', time_period]), pv_stress_com_output_total_debt_service_in_usd['COM5', time_period]))

    return data.PV_STRESS_COM_TOTAL_DEBT_SERVICE.collect(evaluate(formula, data.PV_STRESS_COM_TOTAL_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_TOTAL_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_COM_DISCOUNT_PERIOD.schema, cells=data.PV_STRESS_COM_DISCOUNT_PERIOD.cells)
def pv_stress_com_discount_period(*, pv_stress_com_opening_stock_percent_of_face: int | str, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Build the PV-stress discount period schedule for each COM instrument.

    Seeds the first period from the opening-stock percent of face, then increments it by one for each later period to produce the per-instrument discount-period series used by the PV stress calculation.

    Args:
        pv_stress_com_opening_stock_percent_of_face: Scalar opening-stock percent of face that seeds the first time period of the discount schedule for every instrument.
        input3_old_debt_service: Typed input series over catalog coordinates whose TIME_PERIOD axis defines the projection horizon the discount periods are evaluated across.

    Returns:
        A typed series of discount periods indexed by instrument and time period, seeded once and then incremented by one per period, with None where no value is available.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(pv_stress_com_opening_stock_percent_of_face, 'int')
        elif _p_time_period == 1:
            return as_measure(xl_add(pv_stress_com_discount_period[instrument, axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        elif instrument == 'Eurobond' and _p_time_period >= 2:
            return as_measure(xl_add(pv_stress_com_discount_period['Eurobond', axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        elif instrument == 'Commecial Bank' and _p_time_period >= 2:
            return as_measure(xl_add(pv_stress_com_discount_period['Commecial Bank', axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        elif instrument == 'COM3' and _p_time_period >= 2:
            return as_measure(xl_add(pv_stress_com_discount_period['COM3', axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        elif instrument == 'COM4' and _p_time_period >= 2:
            return as_measure(xl_add(pv_stress_com_discount_period['COM4', axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        return as_measure(xl_add(pv_stress_com_discount_period['COM5', axis_step(_ax_time_period, time_period, -1)], 1), 'int')

    pv_stress_com_discount_period = CoordinateReader('pv_stress_com_discount_period', data.PV_STRESS_COM_DISCOUNT_PERIOD.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.PV_STRESS_COM_DISCOUNT_PERIOD.collect(((coord, pv_stress_com_discount_period[coord]) for coord in data.PV_STRESS_COM_DISCOUNT_PERIOD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_DISCOUNT_PERIOD.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_COM_GRACE.schema, cells=data.PV_STRESS_COM_GRACE.cells)
def pv_stress_com_grace(*, c4_mkt_fin_stressed_lending_terms: data.Series[float | str | None]) -> data.Series[int | str | None]:
    """Compute the PV stress commercial grace-period series from stressed market-financing lending terms.

    Lifts rounded Grace values from stressed lending terms into the COM grace coordinate space for LIC-DSF PV stress calculations.

    Args:
        c4_mkt_fin_stressed_lending_terms: Named-axis data.Series[float | str | None] of stressed lending-term values, covering the COM3, COM4, COM5, Commercial Bank, and Eurobond instruments, that provides the rounded Grace field consumed by the helper.

    Returns:
        Returns a data.Series[int | str | None] of rounded grace periods aligned to the PV_STRESS_COM_GRACE coordinates, preserving non-integer or missing entries as str or None.
    """
    def formula(instrument: str) -> int | str | None:
        return as_measure(c4_mkt_fin_stressed_lending_terms[instrument, 'Grace\n(rounded)'], 'int')

    return data.PV_STRESS_COM_GRACE.collect(evaluate(formula, data.PV_STRESS_COM_GRACE.required))

@publish(data.PV_STRESS_COM_MATURITY.schema, cells=data.PV_STRESS_COM_MATURITY.cells)
def pv_stress_com_maturity(*, c4_mkt_fin_stressed_lending_terms: data.Series[float | str | None]) -> data.Series[int | str | None]:
    """Computes the PV stress commercial maturity series from stressed lending terms.

    Derive rounded COM maturity values under PV stress using authored coordinate identities.

    Args:
        c4_mkt_fin_stressed_lending_terms: Stressed-lending-terms measure series over COM maturity instruments (COM3, COM4, COM5, Commercial Bank, Eurobond), carrying float, string, or None entries for the rounded-maturity coordinate.

    Returns:
        A typed data.Series of int, str, or None containing the rounded COM maturity values under PV stress.
    """
    def formula(instrument: str) -> int | str | None:
        return as_measure(c4_mkt_fin_stressed_lending_terms[instrument, 'Maturity\n(rounded)'], 'int')

    return data.PV_STRESS_COM_MATURITY.collect(evaluate(formula, data.PV_STRESS_COM_MATURITY.required))

@publish(data.PV_STRESS_COM_DISCOUNT_DEBT_STOCK.schema, cells=data.PV_STRESS_COM_DISCOUNT_DEBT_STOCK.cells)
def pv_stress_com_discount_debt_stock(*, pv_stress_com_opening_percent_of_face: data.Series[int | str | None], pv_stress_com_discount_amortization: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the outstanding discount debt stock for PV stress COM instruments over time.

    Rolls forward each instrument’s opening balance or prior-period debt stock and subtracts scheduled discount amortization to produce the debt-stock path.

    Args:
        pv_stress_com_opening_percent_of_face: Per-instrument opening percent of face by time period, represented as a named-axis series over catalog coordinates; scalar cells remain scalars.
        pv_stress_com_discount_amortization: Per-instrument discount amortization by time period, represented as a named-axis series over catalog coordinates; scalar cells remain scalars.
        input3_old_debt_service: Typed old-debt-service input containing the series and coordinates used to bind the time-period axis for the calculation.

    Returns:
        A named-axis series of floating-point debt-stock values, with string or null placeholders where applicable, aligned to the bound time-period and instrument coordinates.
    """
    data.PV_STRESS_COM_OPENING_PERCENT_OF_FACE.schema.validate(pv_stress_com_opening_percent_of_face)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond' and _p_time_period == 0:
            return as_measure(xl_sub(pv_stress_com_opening_percent_of_face[instrument], pv_stress_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Eurobond' and _p_time_period == 1:
            return as_measure(xl_sub(pv_stress_com_discount_debt_stock[instrument, axis_step(_ax_time_period, time_period, -1)], pv_stress_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and _p_time_period == 0:
            return as_measure(xl_sub(pv_stress_com_opening_percent_of_face[instrument], pv_stress_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'Commecial Bank' and _p_time_period == 1:
            return as_measure(xl_sub(pv_stress_com_discount_debt_stock[instrument, axis_step(_ax_time_period, time_period, -1)], pv_stress_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and _p_time_period == 0:
            return as_measure(xl_sub(pv_stress_com_opening_percent_of_face[instrument], pv_stress_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM3' and _p_time_period == 1:
            return as_measure(xl_sub(pv_stress_com_discount_debt_stock[instrument, axis_step(_ax_time_period, time_period, -1)], pv_stress_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM4' and _p_time_period == 0:
            return as_measure(xl_sub(pv_stress_com_opening_percent_of_face[instrument], pv_stress_com_discount_amortization['COM4', time_period]))
        elif instrument == 'COM4' and _p_time_period == 1:
            return as_measure(xl_sub(pv_stress_com_discount_debt_stock[instrument, axis_step(_ax_time_period, time_period, -1)], pv_stress_com_discount_amortization['COM4', time_period]))
        elif instrument == 'COM5' and _p_time_period == 0:
            return as_measure(xl_sub(pv_stress_com_opening_percent_of_face[instrument], pv_stress_com_discount_amortization['COM5', time_period]))
        elif instrument == 'COM5' and _p_time_period == 1:
            return as_measure(xl_sub(pv_stress_com_discount_debt_stock[instrument, axis_step(_ax_time_period, time_period, -1)], pv_stress_com_discount_amortization['COM5', time_period]))
        elif instrument == 'Eurobond' and 2 <= _p_time_period <= 38:
            return as_measure(xl_sub(pv_stress_com_discount_debt_stock['Eurobond', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and 2 <= _p_time_period <= 38:
            return as_measure(xl_sub(pv_stress_com_discount_debt_stock['Commecial Bank', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and 2 <= _p_time_period <= 38:
            return as_measure(xl_sub(pv_stress_com_discount_debt_stock['COM3', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM4' and 2 <= _p_time_period <= 38:
            return as_measure(xl_sub(pv_stress_com_discount_debt_stock['COM4', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_discount_amortization['COM4', time_period]))
        return as_measure(xl_sub(pv_stress_com_discount_debt_stock['COM5', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_discount_amortization['COM5', time_period]))

    pv_stress_com_discount_debt_stock = CoordinateReader('pv_stress_com_discount_debt_stock', data.PV_STRESS_COM_DISCOUNT_DEBT_STOCK.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.PV_STRESS_COM_DISCOUNT_DEBT_STOCK.collect(((coord, pv_stress_com_discount_debt_stock[coord]) for coord in data.PV_STRESS_COM_DISCOUNT_DEBT_STOCK.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_DISCOUNT_DEBT_STOCK.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_COM_DISCOUNT_INTEREST_RATE.schema, cells=data.PV_STRESS_COM_DISCOUNT_INTEREST_RATE.cells)
def pv_stress_com_discount_interest_rate(*, input4_interest_rate: data.Input4InterestRate, pv_stress_com_assumptions_increase_in_external_borrowing_costs: float | str) -> data.Series[float | str | None]:
    """Compute the PV stress COM discount interest rate series.

    Derives stressed discount rates by adding the scaled external borrowing cost shock to each instrument's Input 4 interest rate.

    Args:
        input4_interest_rate: A data.Input4InterestRate named-axis series over instrument coordinates (COM3, COM4, COM5, Commercial Bank, Eurobond) holding input interest rates.
        pv_stress_com_assumptions_increase_in_external_borrowing_costs: A scalar float or str assumption for the increase in external borrowing costs under PV stress COM.

    Returns:
        A data.Series[float | str | None] of stressed discount interest rates keyed by instrument coordinate, whose values may be float, str, or None.
    """
    data.INPUT4_INTEREST_RATE.schema.validate(input4_interest_rate)
    def formula(instrument: str) -> float | str | None:
        return as_measure(xl_add(input4_interest_rate[instrument], xl_div(xl_div(pv_stress_com_assumptions_increase_in_external_borrowing_costs, 100), 100)))

    return data.PV_STRESS_COM_DISCOUNT_INTEREST_RATE.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_INTEREST_RATE.required))

@publish(data.PV_STRESS_COM_DISCOUNT_AMORTIZATION.schema, cells=data.PV_STRESS_COM_DISCOUNT_AMORTIZATION.cells)
def pv_stress_com_discount_amortization(*, pv_stress_com_opening_percent_of_face: data.Series[int | str | None], pv_stress_com_discount_period: data.Series[int | str | None], pv_stress_com_grace: data.Series[int | str | None], pv_stress_com_maturity: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Computes per-instrument discount-schedule amortization for the five commercial external instruments.

    Derives straight-line amortization from opening percent-of-face across the grace-to-maturity window, returning zero outside that window, over the old-debt-service time axis.

    Args:
        pv_stress_com_opening_percent_of_face: Named-axis series of opening percent-of-face values per instrument (COM3, COM4, COM5, Commecial Bank, Eurobond), used as the numerator of straight-line amortization.
        pv_stress_com_discount_period: Named-axis series of discount-period positions per instrument; its first time-period key anchors the elapsed-period offset used to compare against grace and maturity.
        pv_stress_com_grace: Named-axis series of grace-period lengths per instrument; amortization is zero while elapsed discount periods remain below the grace threshold.
        pv_stress_com_maturity: Named-axis series of maturity-period lengths per instrument; straight-line amortization runs between grace end and maturity and is zero at or beyond maturity.
        input3_old_debt_service: Input 3 old-debt-service series supplying the TIME_PERIOD axis and domain over which the formula is evaluated and the result is bound.

    Returns:
        Series of float | str | None indexed by instrument and TIME_PERIOD, carrying the per-cell amortization amount, zero during grace or after maturity, or a blank/string passthrough where inputs are unavailable.
    """
    data.PV_STRESS_COM_OPENING_PERCENT_OF_FACE.schema.validate(pv_stress_com_opening_percent_of_face)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_com_discount_period['Eurobond', time_period], pv_stress_com_discount_period['Eurobond', _ax_time_period.keys[0]]), 1), pv_stress_com_grace['Eurobond'])) else (xl_div(pv_stress_com_opening_percent_of_face['Eurobond'], xl_sub(pv_stress_com_maturity['Eurobond'], pv_stress_com_grace['Eurobond'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_com_discount_period['Eurobond', time_period], pv_stress_com_discount_period['Eurobond', _ax_time_period.keys[0]]), 1), pv_stress_com_maturity['Eurobond'])) else 0)))
        elif instrument == 'Commecial Bank':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_com_discount_period['Commecial Bank', time_period], pv_stress_com_discount_period['Commecial Bank', _ax_time_period.keys[0]]), 1), pv_stress_com_grace['Commecial Bank'])) else (xl_div(pv_stress_com_opening_percent_of_face['Commecial Bank'], xl_sub(pv_stress_com_maturity['Commecial Bank'], pv_stress_com_grace['Commecial Bank'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_com_discount_period['Commecial Bank', time_period], pv_stress_com_discount_period['Commecial Bank', _ax_time_period.keys[0]]), 1), pv_stress_com_maturity['Commecial Bank'])) else 0)))
        elif instrument == 'COM3':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_com_discount_period['COM3', time_period], pv_stress_com_discount_period['COM3', _ax_time_period.keys[0]]), 1), pv_stress_com_grace['COM3'])) else (xl_div(pv_stress_com_opening_percent_of_face['COM3'], xl_sub(pv_stress_com_maturity['COM3'], pv_stress_com_grace['COM3'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_com_discount_period['COM3', time_period], pv_stress_com_discount_period['COM3', _ax_time_period.keys[0]]), 1), pv_stress_com_maturity['COM3'])) else 0)))
        elif instrument == 'COM4':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_com_discount_period['COM4', time_period], pv_stress_com_discount_period['COM4', _ax_time_period.keys[0]]), 1), pv_stress_com_grace['COM4'])) else (xl_div(pv_stress_com_opening_percent_of_face['COM4'], xl_sub(pv_stress_com_maturity['COM4'], pv_stress_com_grace['COM4'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_com_discount_period['COM4', time_period], pv_stress_com_discount_period['COM4', _ax_time_period.keys[0]]), 1), pv_stress_com_maturity['COM4'])) else 0)))
        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_com_discount_period['COM5', time_period], pv_stress_com_discount_period['COM5', _ax_time_period.keys[0]]), 1), pv_stress_com_grace['COM5'])) else (xl_div(pv_stress_com_opening_percent_of_face['COM5'], xl_sub(pv_stress_com_maturity['COM5'], pv_stress_com_grace['COM5'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_stress_com_discount_period['COM5', time_period], pv_stress_com_discount_period['COM5', _ax_time_period.keys[0]]), 1), pv_stress_com_maturity['COM5'])) else 0)))

    return data.PV_STRESS_COM_DISCOUNT_AMORTIZATION.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_AMORTIZATION.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_DISCOUNT_AMORTIZATION.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_COM_DISCOUNT_DISCOUNT_RATE.schema, cells=data.PV_STRESS_COM_DISCOUNT_DISCOUNT_RATE.cells)
def pv_stress_com_discount_discount_rate(*, input4_discount_rate: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """PV stress COM discount-rate series over instrument coordinates.

    Lift Input 4 discount-rate values into the PV stress COM terms discount-rate series.

    Args:
        input4_discount_rate: Discount-rate series over catalog coordinates for the five instruments COM3, COM4, COM5, Commercial Bank, and Eurobond; each value may be a float, string, or None.

    Returns:
        A data.Series of discount rates aligned to the PV stress COM discount-rate coordinates, preserving float, string, or None values.
    """
    def formula(instrument: str) -> float | str | None:
        return as_measure(input4_discount_rate[instrument])

    return data.PV_STRESS_COM_DISCOUNT_DISCOUNT_RATE.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_DISCOUNT_RATE.required))

@publish(data.PV_STRESS_COM_DISCOUNT_INTEREST.schema, cells=data.PV_STRESS_COM_DISCOUNT_INTEREST.cells)
def pv_stress_com_discount_interest(*, pv_stress_com_discount_debt_stock: data.Series[float | str | None], pv_stress_com_discount_interest_rate: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute interest expense on commercial discount-schedule instruments for the PV stress test.

    Multiplies each instrument's interest rate by its lagged debt stock (averaging prior and current stock for COM5) to produce the interest line of the discount schedule.

    Args:
        pv_stress_com_discount_debt_stock: Named-axis series of outstanding debt stock per instrument on the discount schedule, indexed over catalog coordinates; values are read one period back when forming interest.
        pv_stress_com_discount_interest_rate: Named-axis series of per-instrument interest rates on the discount schedule, indexed over catalog coordinates and aligned with the debt stock series.
        input3_old_debt_service: Debt-service input bundle whose TIME_PERIOD axis defines the projection grid the returned interest series is evaluated over.

    Returns:
        Named-axis series of computed interest amounts per instrument and time period, aligned to the discount-schedule coordinates.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['Eurobond'], pv_stress_com_discount_debt_stock['Eurobond', axis_step(_ax_time_period, time_period, -1)]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['Commecial Bank'], pv_stress_com_discount_debt_stock['Commecial Bank', axis_step(_ax_time_period, time_period, -1)]))
        elif instrument == 'COM3':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['COM3'], pv_stress_com_discount_debt_stock['COM3', axis_step(_ax_time_period, time_period, -1)]))
        elif instrument == 'COM4':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['COM4'], pv_stress_com_discount_debt_stock['COM4', axis_step(_ax_time_period, time_period, -1)]))
        return as_measure(xl_mul(pv_stress_com_discount_interest_rate['COM5'], xl_average(view(pv_stress_com_discount_debt_stock, rows=('COM5',), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, -1), time_period)))))

    return data.PV_STRESS_COM_DISCOUNT_INTEREST.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_INTEREST.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_DISCOUNT_INTEREST.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_COM_DISCOUNT_TOTAL_DEBT_SERVICE.schema, cells=data.PV_STRESS_COM_DISCOUNT_TOTAL_DEBT_SERVICE.cells)
def pv_stress_com_discount_total_debt_service(*, pv_stress_com_discount_amortization: data.Series[float | str | None], pv_stress_com_discount_interest: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute total debt service for the COM discount schedule by summing amortization and interest across the five instruments.

    Derive the total-debt-service series from paired amortization and interest components for each instrument and projection period.

    Args:
        pv_stress_com_discount_amortization: Typed per-instrument amortization series over catalog coordinates, supplying the amortization component for each instrument and time period.
        pv_stress_com_discount_interest: Typed per-instrument interest series over catalog coordinates, supplying the interest component to add to amortization for each instrument and time period.
        input3_old_debt_service: Structured old-debt-service input bundle whose time-period domain and values bind the result's projection grid.

    Returns:
        Typed series of total debt service values, with float, string, or null entries, over the instruments COM3, COM4, COM5, Commecial Bank, and Eurobond and the bound time periods.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure(xl_add(pv_stress_com_discount_amortization['Eurobond', time_period], pv_stress_com_discount_interest['Eurobond', time_period]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_add(pv_stress_com_discount_amortization['Commecial Bank', time_period], pv_stress_com_discount_interest['Commecial Bank', time_period]))
        elif instrument == 'COM3':
            return as_measure(xl_add(pv_stress_com_discount_amortization['COM3', time_period], pv_stress_com_discount_interest['COM3', time_period]))
        elif instrument == 'COM4':
            return as_measure(xl_add(pv_stress_com_discount_amortization['COM4', time_period], pv_stress_com_discount_interest['COM4', time_period]))
        return as_measure(xl_add(pv_stress_com_discount_amortization['COM5', time_period], pv_stress_com_discount_interest['COM5', time_period]))

    return data.PV_STRESS_COM_DISCOUNT_TOTAL_DEBT_SERVICE.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_TOTAL_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_DISCOUNT_TOTAL_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_COM_DISCOUNT_PV_OF_DEBT.schema, cells=data.PV_STRESS_COM_DISCOUNT_PV_OF_DEBT.cells)
def pv_stress_com_discount_pv_of_debt(*, pv_stress_com_discount_debt_stock: data.Series[float | str | None], pv_stress_com_discount_interest_rate: data.Series[float | str | None], pv_stress_com_discount_discount_rate: data.Series[float | str | None], pv_stress_com_discount_total_debt_service: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the present value of commercial debt for each instrument and projection year.

    Derive the discount-schedule PV of debt using either outstanding debt stock or the NPV of future total debt service, depending on the interest-rate versus discount-rate comparison.

    Args:
        pv_stress_com_discount_debt_stock: Instrument-by-time series of outstanding commercial debt stock used directly when the interest rate is at least the discount rate.
        pv_stress_com_discount_interest_rate: Instrument-level series of contractual interest rates compared with the discount rate to select the valuation branch.
        pv_stress_com_discount_discount_rate: Instrument-level series of discount rates used to compute the net present value of future debt service cash flows.
        pv_stress_com_discount_total_debt_service: Instrument-by-time series of total debt service cash flows discounted from the current period through the 40-year projection horizon.
        input3_old_debt_service: Macro-debt input series whose TIME_PERIOD domain defines the projection grid for the returned PV-of-debt series.

    Returns:
        A data.Series[float | str | None] of present values of debt indexed over commercial instruments and TIME_PERIOD, preserving text and missing values from the source series.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((pv_stress_com_discount_debt_stock[instrument, time_period] if xl_bool(xl_ge(pv_stress_com_discount_interest_rate[instrument], pv_stress_com_discount_discount_rate[instrument])) else xl_npv(pv_stress_com_discount_discount_rate[instrument], view(pv_stress_com_discount_total_debt_service, rows=(instrument,), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, 1), _ax_time_period.keys[39])))))

    return data.PV_STRESS_COM_DISCOUNT_PV_OF_DEBT.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_PV_OF_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_DISCOUNT_PV_OF_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_COM_DISCOUNT_T_G_0.schema, cells=data.PV_STRESS_COM_DISCOUNT_T_G_0.cells)
def pv_stress_com_discount_t_g_0(*, pv_stress_com_discount_period: data.Series[int | str | None], pv_stress_com_grace: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Computes per-instrument PV stress commercial discount periods where time exceeds grace (t-g>0).

    Derives the nonnegative t-g>0 discount schedule for COM3, COM4, COM5, Commercial Bank, and Eurobond from the PV stress commercial discount data.

    Args:
        pv_stress_com_discount_period: A named-axis series of discount periods by instrument and time period for the five commercial instruments.
        pv_stress_com_grace: A named-axis series of grace periods by instrument used to subtract from each discount period.
        input3_old_debt_service: A typed input3 old-debt-service series whose domain supplies the TIME_PERIOD axis used to evaluate the result.

    Returns:
        A named-axis series over instruments and time periods containing the nonnegative discount-period values, or zero when the period does not exceed grace.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure((xl_sub(pv_stress_com_discount_period['Eurobond', time_period], pv_stress_com_grace['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_stress_com_discount_period['Eurobond', time_period], pv_stress_com_grace['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank':
            return as_measure((xl_sub(pv_stress_com_discount_period['Commecial Bank', time_period], pv_stress_com_grace['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_stress_com_discount_period['Commecial Bank', time_period], pv_stress_com_grace['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3':
            return as_measure((xl_sub(pv_stress_com_discount_period['COM3', time_period], pv_stress_com_grace['COM3']) if xl_bool(xl_gt(xl_sub(pv_stress_com_discount_period['COM3', time_period], pv_stress_com_grace['COM3']), 0)) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_stress_com_discount_period['COM4', time_period], pv_stress_com_grace['COM4']) if xl_bool(xl_gt(xl_sub(pv_stress_com_discount_period['COM4', time_period], pv_stress_com_grace['COM4']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_stress_com_discount_period['COM5', time_period], pv_stress_com_grace['COM5']) if xl_bool(xl_gt(xl_sub(pv_stress_com_discount_period['COM5', time_period], pv_stress_com_grace['COM5']), 0)) else 0), 'int')

    return data.PV_STRESS_COM_DISCOUNT_T_G_0.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_DISCOUNT_T_G_0.required.bind(TIME_PERIOD=input3_old_debt_service))

