@publish(data.PV_STRESS_COM_DISCOUNT_T_M_CONDITION.schema, cells=data.PV_STRESS_COM_DISCOUNT_T_M_CONDITION.cells)
def pv_stress_com_discount_t_m_condition(*, pv_stress_com_discount_period: data.Series[int | str | None], pv_stress_com_maturity: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute the per-instrument, per-period t-minus-m maturity-gap condition on the commercial-external discount schedule.

    Derives the discount-schedule t-m condition for each of the five commercial instruments by subtracting maturity from discount period and clipping negatives to zero.

    Args:
        pv_stress_com_discount_period: Typed data.Series[int | str | None] indexed by instrument (COM3, COM4, COM5, Commecial Bank, Eurobond) and TIME_PERIOD, giving the discount period applied to each commercial external instrument.
        pv_stress_com_maturity: Typed data.Series[int | str | None] indexed by the same instrument axis, giving each instrument's maturity used as the subtrahend in the t-m gap.
        input3_old_debt_service: Typed data.Input3OldDebtService supplying the Input 3 old debt service series whose TIME_PERIOD axis defines the output domain and evaluation grid for the condition.

    Returns:
        A data.Series[int | str | None] over the instrument and TIME_PERIOD coordinates holding the clipped integer t-m condition for each instrument, zero where the discount period does not exceed maturity.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
