@publish(data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.schema, cells=data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.cells)
def pv_stress_com_discount_cumulative_selected_by_t_m_condition(*, pv_stress_com_discount_t_m_condition: data.Series[int | str | None], pv_stress_com_output_cumulative: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Select cumulative commercial discount values by t-m condition across five instruments.

    Builds the cumulative selected discount series used in the PV Stress commercial discount schedule from per-instrument condition selectors and cumulative outputs.

    Args:
        pv_stress_com_discount_t_m_condition: Per-instrument time-series of t-m condition selectors; a value of zero yields zero, otherwise the value indexes the instrument's cumulative discount schedule.
        pv_stress_com_output_cumulative: Per-instrument cumulative discount schedule series supplying the values selected by the t-m condition.
        input3_old_debt_service: Debt-service input series whose TIME_PERIOD axis defines the evaluation grid for the returned series.

    Returns:
        A data.Series[float | str | None] of selected cumulative discount values over the TIME_PERIOD grid, aligned to the five instruments.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_0 = view(pv_stress_com_output_cumulative, rows=('Eurobond',), cols=span(_ax_time_period, _ax_time_period.keys[0], _ax_time_period.keys[27]))
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_1 = view(pv_stress_com_output_cumulative, rows=('Commecial Bank',), cols=span(_ax_time_period, _ax_time_period.keys[0], _ax_time_period.keys[27]))
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_2 = view(pv_stress_com_output_cumulative, rows=('COM3',), cols=span(_ax_time_period, _ax_time_period.keys[0], _ax_time_period.keys[27]))
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_3 = view(pv_stress_com_output_cumulative, rows=('COM4',), cols=span(_ax_time_period, _ax_time_period.keys[0], _ax_time_period.keys[27]))
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_4 = view(pv_stress_com_output_cumulative, rows=('COM5',), cols=span(_ax_time_period, _ax_time_period.keys[0], _ax_time_period.keys[27]))
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure((0 if xl_bool(xl_eq(pv_stress_com_discount_t_m_condition['Eurobond', time_period], 0)) else xl_choose_range(pv_stress_com_discount_t_m_condition['Eurobond', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_0)))
        elif instrument == 'Commecial Bank':
            return as_measure((0 if xl_bool(xl_eq(pv_stress_com_discount_t_m_condition['Commecial Bank', time_period], 0)) else xl_choose_range(pv_stress_com_discount_t_m_condition['Commecial Bank', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_1)))
        elif instrument == 'COM3':
            return as_measure((0 if xl_bool(xl_eq(pv_stress_com_discount_t_m_condition['COM3', time_period], 0)) else xl_choose_range(pv_stress_com_discount_t_m_condition['COM3', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_2)))
        elif instrument == 'COM4':
            return as_measure((0 if xl_bool(xl_eq(pv_stress_com_discount_t_m_condition['COM4', time_period], 0)) else xl_choose_range(pv_stress_com_discount_t_m_condition['COM4', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_3)))
        return as_measure((0 if xl_bool(xl_eq(pv_stress_com_discount_t_m_condition['COM5', time_period], 0)) else xl_choose_range(pv_stress_com_discount_t_m_condition['COM5', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_4)))

    return data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.schema, cells=data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.cells)
def pv_stress_com_output_new_forex_borrowing_gross_usd(*, ext_debt_new_disbursements_external: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Builds the gross new forex borrowing series (USD) by instrument.

    Maps external new disbursements onto the five pv_stress_com.new_loan_output instruments to produce New forex borrowing (gross, USD).

    Args:
        ext_debt_new_disbursements_external: External debt new disbursements by instrument (COM3, COM4, COM5, Commercial Bank, Eurobond); each instrument's value is passed through as the gross forex borrowing measure.
        input3_old_debt_service: Input 3 old debt service series whose TIME_PERIOD domain supplies the time grid the output is evaluated over.

    Returns:
        A data.Series[float | str | None] of New forex borrowing (gross, USD) keyed by instrument and TIME_PERIOD.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond':
            return as_measure(ext_debt_new_disbursements_external['Eurobond', time_period])
        elif instrument == 'Commecial Bank':
            return as_measure(ext_debt_new_disbursements_external['Commecial Bank', time_period])
        elif instrument == 'COM3':
            return as_measure(ext_debt_new_disbursements_external['COM3', time_period])
        elif instrument == 'COM4':
            return as_measure(ext_debt_new_disbursements_external['COM4', time_period])
        return as_measure(ext_debt_new_disbursements_external['COM5', time_period])

    return data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.collect(evaluate(formula, data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.required.bind(TIME_PERIOD=input3_old_debt_service))

