@publish(data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.schema, cells=data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.cells)
def pv_stress_com_output_stock_of_new_forex_debt_in_usd(*, pv_stress_com_output_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_stress_com_output_amortization: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the projected stock of new foreign-currency debt in USD for each instrument under the PV stress commercial scenario.

    Roll forward prior-period debt stock by adding gross new forex borrowing and subtracting amortization, then collect the results as a catalog series.

    Args:
        pv_stress_com_output_new_forex_borrowing_gross_usd: Gross new foreign-currency borrowing in USD as a Keyword-only data.Series[float | str | None] over instrument (COM3, COM4, COM5, Commecial Bank, Eurobond) and TIME_PERIOD coordinates, added to prior stock in periods 1–3.
        pv_stress_com_output_amortization: Keyword-only data.Series[float | str | None] of amortization over the same instrument and TIME_PERIOD coordinates, subtracted in every period to reduce outstanding stock.
        input3_old_debt_service: Keyword-only data.Input3OldDebtService dataclass of series supplying the old debt service inputs; its TIME_PERIOD axis and domain determine the projection periods and instrument coordinates used to bind the output reader.

    Returns:
        A data.Series[float | str | None] over instrument and TIME_PERIOD giving the stock of new forex debt in USD, where period 0 is negative amortization, periods 1–3 add gross borrowing to prior stock, and later periods roll forward prior stock net of amortization; non-numeric results appear as str or None.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond' and 2 <= _p_time_period <= 3:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Eurobond', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_new_forex_borrowing_gross_usd['Eurobond', time_period]), pv_stress_com_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and 2 <= _p_time_period <= 3:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Commecial Bank', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period]), pv_stress_com_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and 2 <= _p_time_period <= 3:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM3', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_new_forex_borrowing_gross_usd['COM3', time_period]), pv_stress_com_output_amortization['COM3', time_period]))
        elif instrument == 'COM4' and 2 <= _p_time_period <= 3:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM4', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_new_forex_borrowing_gross_usd['COM4', time_period]), pv_stress_com_output_amortization['COM4', time_period]))
        elif instrument == 'COM5' and 2 <= _p_time_period <= 3:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM5', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_new_forex_borrowing_gross_usd['COM5', time_period]), pv_stress_com_output_amortization['COM5', time_period]))
        elif _p_time_period == 0:
            return as_measure(xl_sub(None, pv_stress_com_output_amortization[instrument, time_period]))
        elif _p_time_period == 1:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd[instrument, axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_new_forex_borrowing_gross_usd[instrument, time_period]), pv_stress_com_output_amortization[instrument, time_period]))
        elif instrument == 'Eurobond' and _p_time_period >= 4:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Eurobond', axis_step(_ax_time_period, time_period, -1)], None), pv_stress_com_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and _p_time_period >= 4:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Commecial Bank', axis_step(_ax_time_period, time_period, -1)], None), pv_stress_com_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and _p_time_period >= 4:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM3', axis_step(_ax_time_period, time_period, -1)], None), pv_stress_com_output_amortization['COM3', time_period]))
        elif instrument == 'COM4' and _p_time_period >= 4:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM4', axis_step(_ax_time_period, time_period, -1)], None), pv_stress_com_output_amortization['COM4', time_period]))
        return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM5', axis_step(_ax_time_period, time_period, -1)], None), pv_stress_com_output_amortization['COM5', time_period]))

    pv_stress_com_output_stock_of_new_forex_debt_in_usd = CoordinateReader('pv_stress_com_output_stock_of_new_forex_debt_in_usd', data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.collect(((coord, pv_stress_com_output_stock_of_new_forex_debt_in_usd[coord]) for coord in data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT.schema, cells=data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT.cells)
def pv_stress_com_output_pv_of_debt(*, pv_stress_com_discount_interest_rate: data.Series[float | str | None], pv_stress_com_discount_discount_rate: data.Series[float | str | None], pv_stress_com_discount_pv_of_debt: data.Series[float | str | None], pv_stress_com_output_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_stress_com_output_total_debt_service_in_usd: data.Series[float | str | None], pv_stress_com_output_amortization: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute the PV-of-debt recursion for the five commercial external-debt instruments over the projection horizon.

    Rebuilds each instrument's stressed PV path by rolling forward the prior period's PV with amortization, new foreign-currency borrowing, and total debt service, choosing a simple or compounded branch from the interest-versus-discount rate comparison.

    Args:
        pv_stress_com_discount_interest_rate: Named-axis series of per-instrument interest rates over catalog coordinates, compared against the discount rate to select the simple or compounded recursion branch.
        pv_stress_com_discount_discount_rate: Named-axis series of per-instrument discount rates over catalog coordinates, applied to the prior period's PV when compounding is selected.
        pv_stress_com_discount_pv_of_debt: Named-axis series of per-instrument PV of debt over catalog coordinates, read at the shifted-back period to seed each recursion step and at the first axis key for the borrowing valuation factor.
        pv_stress_com_output_new_forex_borrowing_gross_usd: Named-axis series of per-instrument gross new foreign-currency borrowing in USD, added to the PV in the early projection periods and dropped in later ones.
        pv_stress_com_output_total_debt_service_in_usd: Named-axis series of per-instrument total debt service in USD, subtracted from the grossed-up prior PV in the compounded branch.
        pv_stress_com_output_amortization: Named-axis series of per-instrument amortization, subtracted from the prior PV in the non-compounded branch.
        input3_old_debt_service: Input3OldDebtService dataclass of series whose TIME_PERIOD axis defines the projection grid, its first key, and the per-instrument coordinates the recursion is evaluated over.

    Returns:
        data.Series[float | str | None] of PV of debt indexed by instrument and time period, built from the bound PV_STRESS_COM_OUTPUT_PV_OF_DEBT domain; blanks propagate as None or text where the source formulas are undefined.
    """
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if instrument == 'Eurobond' and 2 <= _p_time_period <= 3:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Eurobond', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_amortization['Eurobond', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['Eurobond', time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['Eurobond'], pv_stress_com_discount_discount_rate['Eurobond'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Eurobond', axis_step(_ax_time_period, time_period, -1)], xl_add(1, pv_stress_com_discount_discount_rate['Eurobond'])), pv_stress_com_output_total_debt_service_in_usd['Eurobond', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['Eurobond', time_period], pv_stress_com_discount_pv_of_debt['Eurobond', _ax_time_period.keys[0]]), 100))))
        elif instrument == 'Commecial Bank' and 2 <= _p_time_period <= 3:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Commecial Bank', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_amortization['Commecial Bank', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['Commecial Bank'], pv_stress_com_discount_discount_rate['Commecial Bank'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Commecial Bank', axis_step(_ax_time_period, time_period, -1)], xl_add(1, pv_stress_com_discount_discount_rate['Commecial Bank'])), pv_stress_com_output_total_debt_service_in_usd['Commecial Bank', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period], pv_stress_com_discount_pv_of_debt['Commecial Bank', _ax_time_period.keys[0]]), 100))))
        elif instrument == 'COM3' and 2 <= _p_time_period <= 3:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM3', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_amortization['COM3', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['COM3', time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['COM3'], pv_stress_com_discount_discount_rate['COM3'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM3', axis_step(_ax_time_period, time_period, -1)], xl_add(1, pv_stress_com_discount_discount_rate['COM3'])), pv_stress_com_output_total_debt_service_in_usd['COM3', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['COM3', time_period], pv_stress_com_discount_pv_of_debt['COM3', _ax_time_period.keys[0]]), 100))))
        elif instrument == 'COM4' and 2 <= _p_time_period <= 3:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM4', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_amortization['COM4', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['COM4', time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['COM4'], pv_stress_com_discount_discount_rate['COM4'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM4', axis_step(_ax_time_period, time_period, -1)], xl_add(1, pv_stress_com_discount_discount_rate['COM4'])), pv_stress_com_output_total_debt_service_in_usd['COM4', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['COM4', time_period], pv_stress_com_discount_pv_of_debt['COM4', _ax_time_period.keys[0]]), 100))))
        elif instrument == 'COM5' and 2 <= _p_time_period <= 3:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM5', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_amortization['COM5', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['COM5', time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['COM5'], pv_stress_com_discount_discount_rate['COM5'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM5', axis_step(_ax_time_period, time_period, -1)], xl_add(1, pv_stress_com_discount_discount_rate['COM5'])), pv_stress_com_output_total_debt_service_in_usd['COM5', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['COM5', time_period], pv_stress_com_discount_pv_of_debt['COM5', _ax_time_period.keys[0]]), 100))))
        elif _p_time_period == 0:
            return as_measure((None if xl_bool(xl_ge(pv_stress_com_discount_interest_rate[instrument], pv_stress_com_discount_discount_rate[instrument])) else xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt[instrument, time_period]), 100)))
        elif _p_time_period == 1:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt[instrument, axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_amortization[instrument, time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd[instrument, time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate[instrument], pv_stress_com_discount_discount_rate[instrument])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt[instrument, axis_step(_ax_time_period, time_period, -1)], xl_add(1, pv_stress_com_discount_discount_rate[instrument])), pv_stress_com_output_total_debt_service_in_usd[instrument, time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd[instrument, time_period], pv_stress_com_discount_pv_of_debt[instrument, _ax_time_period.keys[0]]), 100))))
        elif instrument == 'Eurobond' and _p_time_period >= 4:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Eurobond', axis_step(_ax_time_period, time_period, -1)], pv_stress_com_output_amortization['Eurobond', time_period]), None) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['Eurobond'], pv_stress_com_discount_discount_rate['Eurobond'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Eurobond', axis_step(_ax_time_period, time_period, -1)], xl_add(1, pv_stress_com_discount_discount_rate['Eurobond'])), pv_stress_com_output_total_debt_service_in_usd['Eurobond', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['Eurobond', _ax_time_period.keys[0]]), 100))))
